 if(t.type==='personal_settlement'){let l=personalLoan(t.personalLoanId);if(l){let interest=fx(num(t.interest),t.currency);if(l.direction==='lent'){if(!t.cardId)cashIn+=v;income+=interest;incomeBy['Intereses personales']=(incomeBy['Intereses personales']||0)+interest}else{if(!t.cardId)cashOut+=v;expense+=interest;expenseBy['Deudas e intereses']=(expenseBy['Deudas e intereses']||0)+interest}}}
