ICONS.grid='<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>';
ICONS.apple='<path d="M12.4 6.2C10.1 4.9 7.8 5.5 6.3 7.5c-2.9 4-.5 11.7 2.2 12.9 1.4.6 2.3-.5 3.7-.5 1.6 0 2.5 1.1 3.9.5 1.4-.6 2.9-3.5 3.5-5.9-2.2-.5-3.3-2.2-3.1-4.3.1-1.8 1.3-3.2 2.5-4.1-1.7-1.7-3.2-2.1-5.6-1.1Z" fill="currentColor" stroke="none"/><path d="M12.2 5.9c.1-2.7 1.8-4.4 4.1-4.9-.1 2.1-1.2 4-4.1 4.9Z" fill="currentColor" stroke="none"/>';
/* V36 · Notificaciones internas, basadas exclusivamente en vencimientos registrados. */
function v36DueItems(){
 return upcoming().filter(o=>o.kind!=='personal_recv'&&Number(o.amount)>0&&/^\d{4}-\d{2}-\d{2}$/.test(String(o.date||'')));
}

/* V988 · Los avisos de pago de la campanita y del informe abren directamente el pago correspondiente */
document.addEventListener('click',e=>{
 const b=e.target.closest?.('.v988-notice[data-act],[data-v988-pay]');if(!b)return;
 const det=b.closest('details.v36-notifications');if(det)det.open=false;
 if(b.matches('[data-v988-pay]')){document.getElementById('v216-layer')?.remove();document.body.classList.remove('v216-modal-open');}
});
/* V994 · «Limpiar todo»: oculta (en este dispositivo) los avisos presentes; los nuevos reaparecen. */
const V994_KEY='vive.notif.cleared.v1';
function v994Cleared(){try{const x=JSON.parse(localStorage.getItem(V994_KEY)||'{}');return {d:new Set(x.d||[]),s:new Set(x.s||[]),r:new Set(x.r||[])}}catch(_){return {d:new Set(),s:new Set(),r:new Set()}}}
const v994DueKey=o=>[o.kind,o.ref||o.id,o.date].join('|');
const v994SpendKey=a=>[a.category,a.kind].join('|');
function v994ClearAll(){
 const c=v994Cleared();
 try{for(const o of v36DueItems())c.d.add(v994DueKey(o));}catch(_){}
 try{for(const a of v123CategoryAlerts())c.s.add(v994SpendKey(a));}catch(_){}
 try{for(const e of v246ReportEvents()){c.r.add(e.id);if(typeof v246MarkReportRead==='function')v246MarkReportRead(e.id);}}catch(_){}
 try{localStorage.setItem(V994_KEY,JSON.stringify({d:[...c.d].slice(-400),s:[...c.s].slice(-100),r:[...c.r].slice(-200)}))}catch(_){}
}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v994-clear]');if(!b)return;e.preventDefault();e.stopPropagation();v994ClearAll();render();toast('Notificaciones eliminadas.')},true);
function v36Bell(){
 const todayISO=today();
 const all=v36DueItems().sort((a,b)=>a.date.localeCompare(b.date));
 const v994=v994Cleared();
 const visibleAll=all.filter(o=>!v994.d.has(v994DueKey(o)));
 const notices=visibleAll.filter(o=>diffDays(o.date,todayISO)<=14);
 const urgent=visibleAll.filter(o=>diffDays(o.date,todayISO)<=7).length;
 const spendAlerts=v123CategoryAlerts().filter(a=>!v994.s.has(v994SpendKey(a)));
 const svg=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg>`;
 const items=notices.slice(0,9).map(o=>{
   const d=diffDays(o.date,todayISO),kind=o.kind==='card'?'Tarjeta':o.kind==='loan'?'Préstamo':o.kind==='personal'?'Entre personas':'Suscripción';
   const state=d<0?'Vencido · revisar':d===0?'Vence hoy':d===1?'Mañana':`En ${d} días`;
   const act=o.action?`data-act="${sanitize(o.action)}" data-id="${sanitize(String(o.ref||o.id))}" data-ccy="${sanitize(String(o.ccy||o.currency||''))}"`:'';
   return `<button type="button" class="v36-notice v988-notice ${d<0?'v36-expired':d<=3?'v36-urgent':''} v988-${o.kind}" ${act} aria-label="Pagar ${sanitize(o.name)}, ${kind}, ${state}"><span class="v988-nico" aria-hidden="true"></span><div><strong>${sanitize(o.name)}</strong><small>${kind} · ${state} · ${prettyDate(o.date)}</small></div><span class="v988-amt"><b>${money(o.amount,o.currency,2)}</b><em>Pagar</em></span></button>`;
 }).join('');
 const spendingItems=spendAlerts.map(a=>`<article class="v36-notice v123-bell-alert"><span class="v36-notice-dot"></span><div><strong>${sanitize(a.category)} · ${a.kind==='trend'?'Tendencia al alza':'Gasto elevado'}</strong><small>${sanitize(v123AlertText(a))}</small></div></article>`).join('');
 const v994Reports=(()=>{try{return v246ReportEvents()}catch(_){return []}})();const v994AllRead=v994Reports.length>0&&v994Reports.every(r=>v994.r.has(r.id));
 const totalAlerts=urgent+spendAlerts.length+(v994AllRead?0:v246UnreadReportCount());
 const v994HasAny=items||spendingItems||(!v994AllRead&&v994Reports.length>0);
 return `<details class="v36-notifications"><summary aria-label="Notificaciones: ${totalAlerts} avisos">${svg}${totalAlerts?`<span class="v36-notification-count">${totalAlerts>99?'99+':totalAlerts}</span>`:''}</summary><div class="v36-notice-pop"><div class="v36-notice-head"><div><strong>Notificaciones</strong><small>Los informes aparecen a medida que cierra cada período</small></div>${v994HasAny?'<button type="button" class="v994-clear" data-v994-clear="1">Limpiar todo</button>':''}</div>${v994AllRead?'':v216BellItems()}${spendingItems}${items}${v994HasAny?'':'<p class="v994-empty">No tienes notificaciones pendientes.</p>'}<button type="button" class="v36-notice-footer" data-act="navigate" data-id="pressure">Ver calendario de vencimientos →</button><p class="v36-notice-disclaimer">Los informes de la campanita se habilitan por fecha y hora; no equivalen a notificaciones push cuando la app está cerrada. Los recordatorios de vencimientos se configuran por separado.</p></div></details>`;
}
function mobileHeader(){
 const pageName={pressure:'Presión financiera',overview:'Inicio',cards:'Tarjetas',mobilehub:'Explorar',mobilesearch:'Buscar',settings:'Ajustes',banks:'Instituciones',accounts:'Cuentas',register:'Movimientos',payments:'Compromisos',income:'Ingresos',budget:'Presupuestos',recurring:'Suscripciones',personal:'Entre personas',loans:'Préstamos',certificates:'Certificados',benefits:'Beneficios',advanced:'Analítica',kpis:'Indicadores',patrimony:'Patrimonio',categories:'Categorías'};
 return `<header class="vive-mobile-top" aria-label="Encabezado móvil"><button class="vive-mobile-brand" type="button" data-v119-open="1" aria-label="vive el hoy · Abrir El costo de mañana" title="Abrir El costo de mañana"><span>${APP_BRAND}</span></button><span class="vive-mobile-location">${ui.page==='cards'?'Wallet':ui.page==='banks'?'Bancos':(ui.page==='wallet'?'Wallet':pageName[ui.page])||'Tus finanzas'}</span><span class="v146-mobile-date" title="${prettyDate(today())}" aria-label="Fecha: ${prettyDate(today())}">${prettyDate(today()).replace(/\s+de\s+\d{4}$/i,'')}</span><div class="v65-header-tools v146-mobile-actions">${v402SyncButton()}${v36Bell()}${window.VIVE_ENABLED===false?'':`<button type="button" class="vive-mobile-head-access" data-vive-open="mobile" aria-label="Abrir Vive" title="Vive"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19.414 14.414C21 12.828 22 11.5 22 9.5a5.5 5.5 0 0 0-9.591-3.676.6.6 0 0 1-.818.001A5.5 5.5 0 0 0 2 9.5c0 2.3 1.5 4 3 5.5l5.535 5.362a2 2 0 0 0 2.879.052 2.12 2.12 0 0 0-.004-3 2.124 2.124 0 1 0 3-3 2.124 2.124 0 0 0 3.004 0 2 2 0 0 0 0-2.828l-1.881-1.882a2.41 2.41 0 0 0-3.409 0l-1.71 1.71a2 2 0 0 1-2.828 0 2 2 0 0 1 0-2.828l2.823-2.762"/></svg></button>`}<button type="button" class="v65-settings-button v271-settings-access ${ui.page==='settings'?'active':''}" data-act="navigate" data-id="settings" aria-label="Abrir Configuración" title="Configuración"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-1.91 1.91-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.52V20h-3v-.08a1.65 1.65 0 0 0-1-1.52 1.65 1.65 0 0 0-1.82.33l-.06.06-1.91-1.91.06-.06A1.65 1.65 0 0 0 7.6 15a1.65 1.65 0 0 0-1.52-1H6v-3h.08A1.65 1.65 0 0 0 7.6 10a1.65 1.65 0 0 0-.33-1.82l-.06-.06 1.91-1.91.06.06A1.65 1.65 0 0 0 11 6.6a1.65 1.65 0 0 0 1-1.52V5h3v.08A1.65 1.65 0 0 0 16 6.6a1.65 1.65 0 0 0 1.82-.33l.06-.06 1.91 1.91-.06.06A1.65 1.65 0 0 0 19.4 10a1.65 1.65 0 0 0 1.52 1H21v3h-.08A1.65 1.65 0 0 0 19.4 15Z" transform="translate(-1.5 -0.5) scale(1.05)"/></svg></button></div></header>`;
}
function mobileBottomNavigation(){
 // Cada producto bancario pertenece al espacio Bancos; no debe marcar Explorar por error.
 const bankingPages=['banks','accounts','cards','loans','certificates','benefits'];
 const current=bankingPages.includes(ui.page)?'banks':(['overview','wallet','mobilehub','mobilesearch'].includes(ui.page)?ui.page:'mobilehub');
 const items=[['overview','Inicio','home'],['wallet','Wallet','card'],['banks','Bancos','landmark'],['mobilehub','Explorar','grid'],['mobilesearch','Buscar','search']];
 return `<nav class="vive-mobile-dock" aria-label="Navegación móvil">${items.map(([id,label,ic])=>`<button type="button" class="vive-mobile-dock-item ${current===id?'active':''}" data-act="navigate" data-id="${id}" ${current===id?'aria-current="page"':''} aria-label="${label}" title="${label}"><span class="vive-mobile-dock-icon">${icon(ic)}</span><span class="vive-mobile-dock-label">${label}</span></button>`).join('')}</nav><button type="button" class="v249-register-fab" data-act="newTransaction" aria-label="Registrar una operación" title="Registrar ingresos, egresos, transferencias y pagos"><span class="v249-fab-surface" aria-hidden="true">${icon('plus')}</span></button>`;
}

function mobileMiniTrend(){
 const ref=dateObj(ui.month+'-01');const months=Array.from({length:5},(_,i)=>{let d=new Date(ref.getFullYear(),ref.getMonth()-(4-i),1),x=monthlyTotals(d.getFullYear(),d.getMonth()+1);return {m:d.toLocaleDateString('es-DO',{month:'short'}).replace('.',''),income:x.income,expense:x.expense}});
 const max=Math.max(1,...months.flatMap(m=>[m.income,m.expense]));
 const current=monthlyTotals(ref.getFullYear(),ref.getMonth()+1);
 const monthName=ref.toLocaleDateString('es-DO',{month:'long',year:'numeric'});
 return `<div class="v348-trend-block"><div class="vive-mobile-mini-trend" role="img" aria-label="Comparación de ingresos y egresos de los últimos cinco meses">${months.map(m=>`<div class="vive-mobile-trend-group" title="${m.m}: Ingresos ${money(m.income)} · Egresos ${money(m.expense)}"><div class="vive-mobile-trend-bars"><span class="vive-mobile-trend-in" style="height:${Math.max(5,m.income/max*100)}%"></span><span class="vive-mobile-trend-out" style="height:${Math.max(5,m.expense/max*100)}%"></span></div><small>${m.m}</small></div>`).join('')}</div><div class="v348-trend-legend" aria-label="Resumen del mes seleccionado: ${sanitize(monthName)}"><span class="v348-trend-total"><i class="v348-trend-dot income" aria-hidden="true"></i><span>Ingresos</span><strong>${money(current.income)}</strong></span><span class="v348-trend-total"><i class="v348-trend-dot expense" aria-hidden="true"></i><span>Egresos</span><strong>${money(current.expense)}</strong></span></div></div>`;
}

/* V64 · Total de saldo por naturaleza: no confundir deuda íntegra con cuotas por vencer. */
function v64CommitmentTotals(){
 const cards=(db.cards||[]).reduce((sum,c)=>sum+fx(cardStatus(c,'DOP').debt,'DOP')+fx(cardStatus(c,'USD').debt,'USD'),0);
 const loans=(db.loans||[]).reduce((sum,l)=>sum+fx(loanAccounting(l).balance,l.currency),0);
 const personal=(db.personalLoans||[]).filter(l=>l.direction==='borrowed').reduce((sum,l)=>sum+fx(personalBalance(l),l.currency),0);
 const monthly=v80RecurringMonthly();
 return {card:rnd(cards),loan:rnd(loans),personal:rnd(personal),recurring:rnd(monthly)};
}
function v64DueSummary(kind,amount){
 return `${kind==='recurring'?'Costo mensual equivalente':'Saldo total pendiente'}: ${money(amount)}`;
}
/* V64 · Comparación con último mes cerrado hasta que exista base interanual en 2027. */
function v64PositionComparison(){
 const now=today(),year=Number(now.slice(0,4));
 const yoy=positionYearOverYear();
 if(year>=2027&&yoy.valid)return {prior:yoy.prior,position:yoy.position,valid:true,label:'año anterior',short:'vs. '+yoy.prior.slice(0,4)};
 const d=dateObj(now);const lastDay=new Date(d.getFullYear(),d.getMonth(),0);
 const prior=monthDay(lastDay.getFullYear(),lastDay.getMonth()+1,lastDay.getDate());
 const historical=[...(db.accounts||[]).map(a=>a.opened),...(db.cards||[]).map(c=>c.opened),...(db.loans||[]).map(l=>plusMonths(l.firstDue||today(),-1)),...(db.certificates||[]).map(c=>c.startDate),...(db.personalLoans||[]).map(l=>l.date),...(db.transactions||[]).map(t=>t.date)].filter(Boolean);
 const valid=historical.some(t=>t<=prior);
 return {prior,position:valid?historicalPosition(prior):null,valid,label:'mes anterior',short:'cambio mensual'};
}



