function v985Ring(pct,tone,label,small){
 const r=40,c=2*Math.PI*r,v=Math.max(0,Math.min(100,Number.isFinite(pct)?pct:0)),off=(c*(1-v/100)).toFixed(1);
 return `<div class="v985-ring v985-${tone}" role="img" aria-label="${sanitize(label)} ${Math.round(v)}%"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="${r}" class="v985-ring-bg"/><circle cx="50" cy="50" r="${r}" class="v985-ring-fg" stroke-dasharray="${c.toFixed(1)}" stroke-dashoffset="${off}" transform="rotate(-90 50 50)"/></svg><div><strong>${Math.round(v)}%</strong><small>${sanitize(small)}</small></div></div>`;
}
function v985SimplificationWidget(asKpi){
 if(!asKpi)return ''; // La Matriz Jobs solo existe como estilo del KPI principal.
 let liquid=0,debt=0,cert=0,recv=0;
 try{liquid=totalLiquid();debt=totalCardDebt()+totalLoanDebt()+personalTotals().payable;cert=totalCertificates();recv=personalTotals().receivable;}catch(e){console.warn('V985: posición no disponible',e);}
 const assets=liquid+cert+recv,net=assets-debt;
 // Tendencia: patrimonio neto al cierre de los últimos 6 meses
 const series=[];
 try{const now=new Date();for(let i=5;i>=0;i--){const d=new Date(now.getFullYear(),now.getMonth()-i,1);const end=periodEnd(d.getFullYear(),d.getMonth()+1);const day=end>today()?today():end;series.push(Number(historicalPosition(day).net)||0);}}catch(e){}
 let delta=null;
 try{const cmp=v64PositionComparison();const prev=cmp.valid?Number(cmp.position?.net):NaN;if(Number.isFinite(prev)&&Math.abs(prev)>.005)delta=100*(net-prev)/Math.abs(prev);}catch(e){}
 const deltaTxt=delta===null?'—':(delta>=0?'+':'')+delta.toLocaleString('es-DO',{maximumFractionDigits:1,minimumFractionDigits:1})+'%';
 let spark='';
 if(series.length>1){const mn=Math.min(...series),mx=Math.max(...series),span=mx-mn||1,W=240,H=60,pts=series.map((v,i)=>[6+i*(W-12)/(series.length-1),H-8-(v-mn)/span*(H-16)]);
  const line=pts.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join(' ');
  spark=`<svg class="v985-spark" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="v985sg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="currentColor" stop-opacity=".3"/><stop offset="1" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs><path d="${line} L${pts[pts.length-1][0].toFixed(1)} ${H} L${pts[0][0].toFixed(1)} ${H} Z" fill="url(#v985sg)"/><path d="${line}" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
 // Actuar: movimientos del mes seleccionado
 const period=ui.month||today().slice(0,7);
 let inc=0,exp=0,trf=0,pay=0;
 try{const [y,mo]=period.split('-').map(Number),mt=monthlyTotals(y,mo);inc=mt.income;exp=mt.expense;
  for(const t of db.transactions){if(!String(t.date||'').startsWith(period))continue;
   if(t.type==='transfer')trf+=fx(num(t.amount),account(t.accountId)?.currency||t.currency||'DOP');
   else if(t.type==='card_payment'||t.type==='loan_payment')pay+=fx(num(t.amount),t.currency||'DOP');}}catch(e){}
 // Anticipar / Decidir: mismo modelo que Capacidad de endeudamiento
 let d=null;try{d=v89DebtCapacity();}catch(e){}
 const sumKind=k=>d?d.lines.filter(x=>x.kind===k).reduce((t,x)=>t+v99MoneyInDop(x.amount,x.currency),0):0;
 const pending=d?d.monthly:0,full=d&&d.basis==='remaining'?d.fullMonthly:0;
 const paidShare=full>0?100*(1-Math.min(1,pending/full)):0;
 const ratio=d&&Number.isFinite(d.ratio)?d.ratio:null,health=ratio===null?0:Math.max(0,Math.min(100,100-ratio));
 const room=d&&d.balance!==null?d.balance:0;
 let budgetTxt=null;try{const bs=v290BudgetSnapshot(period);if(bs&&bs.allocated>0)budgetTxt=Math.round(bs.percent)+'% usado';}catch(e){}
 const mini=(ico,label,val,attrs,cls='')=>`<button type="button" class="v985-mini ${cls}" ${attrs}><span class="v985-mini-ico">${v985Svg(V985_ICO[ico],22)}</span><strong>${sanitize(label)}</strong>${val===null?'':`<small>${typeof val==='string'?sanitize(val):money(val)}</small>`}</button>`;
 const stat=(ico,label,val)=>`<div class="v985-stat"><span class="v985-stat-ico">${v985Svg(V985_ICO[ico],22)}</span><div><small>${sanitize(label)}</small><strong>${money(val)}</strong></div></div>`;
 const head=(tone,title,q,n,act)=>`<header class="v985-head"><div class="v985-head-copy"><div><h3>${title}</h3></div><p>${q}</p></div><button type="button" class="v985-go" ${act} aria-label="Abrir ${title}">${v985Svg(V985_ICO.chev,16)}</button></header>`;
 const row=(ico,label,val,attrs)=>`<button type="button" class="v985-row-item" ${attrs}><span class="v985-row-ico">${v985Svg(V985_ICO[ico],20)}</span><span class="v985-row-lbl">${sanitize(label)}</span><strong>${money(val)}</strong></button>`;
 const dotted=Math.round(paidShare);
 return `<section ${asKpi?'data-v1124-kpi="1"':'data-v105-widget="simplification"'} class="v985-matrix" aria-label="Matriz Jobs">
 <header class="v985-title"><h2>Matriz Jobs</h2></header>
 <div class="v985-grid">
  <article class="v985-card v985-green">${head('green','Entender','¿Cómo estoy financieramente?','01','data-act="navigate" data-id="patrimony"')}
   <div class="v985-body"><small class="v985-cap">Patrimonio neto</small><div class="v985-figure"><strong>${money(net)}</strong></div>${delta===null?'':`<span class="v985-delta ${delta<0?'down':'up'}">${delta>=0?'▲ ':'▼ '}${deltaTxt}</span>`}${spark}</div>
   <div class="v985-stats">${stat('layers','Activos',assets)}${stat('layers','Pasivos',debt)}</div></article>
  <article class="v985-card v985-blue">${head('blue','Actuar','¿Qué necesito registrar o pagar?','02','data-act="newTransaction"')}
   <div class="v985-list">${row('plusC','Ingresos',inc,'data-act="newTransaction" data-type="income"')}${row('minusC','Gastos',exp,'data-act="newTransaction" data-type="expense"')}${row('swap','Transferir',trf,'data-act="newTransaction" data-type="transfer"')}${row('card','Pagos',pay,'data-act="navigate" data-id="payments"')}</div></article>
  <article class="v985-card v985-orange">${head('orange','Anticipar','¿Qué viene y qué debo pagar?','03','data-act="navigate" data-id="payments"')}
   <div class="v985-body"><div class="v985-figure"><strong>${money(pending)}</strong></div><small class="v985-cap">Compromisos</small><div class="v985-bar" role="img" aria-label="Compromisos pagados ${dotted}%"><i style="width:${Math.max(0,Math.min(100,dotted))}%"></i><span>${dotted}% pagado</span></div></div>
   <div class="v985-list">${row('card','Tarjetas',sumKind('card'),'data-v1121-pay="card"')}${row('bank','Préstamos',sumKind('loan'),'data-v1121-pay="loan"')}${row('grid4','Suscripciones',sumKind('recurring'),'data-v1121-pay="recurring"')}${row('people','Personas',sumKind('personal'),'data-v1121-pay="personal"')}</div></article>
  <article class="v985-card v985-purple">${head('purple','Decidir','¿Qué puedo hacer con mi dinero?','04','data-act="navigate" data-id="projection"')}
   <div class="v985-body v985-row"><div class="v985-figure"><strong>${money(room)}</strong></div><div class="v985-duo"><div><small class="v985-cap">Endeudamiento</small>${ratio===null?'':`<span class="v985-delta up v985-soft">${ratio.toLocaleString('es-DO',{maximumFractionDigits:1})}% usado</span>`}</div>${v985Ring(health,'purple','Salud financiera','Salud financiera')}</div></div>
   <div class="v985-minis v985-minis-3 v985-flat">${mini('target','Presupuesto',budgetTxt,'data-act="navigate" data-id="budget"')}${mini('pie','Análisis',null,'data-act="navigate" data-id="analytics"')}${mini('trend','Recuperación',null,'data-act="navigate" data-id="settings" data-v985-pane="security"')}</div></article>
 </div></section>`;
}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v985-pane]');if(b)v242SettingsPane=b.dataset.v985Pane;},true);
/* V1121 · Anticipar: cada fila abre primero el selector de qué pagar y luego el flujo de pago existente. */
function v1121Go(act,id,ccy){const b=document.createElement('button');b.type='button';b.dataset.act=act;b.dataset.id=String(id);if(ccy)b.dataset.ccy=ccy;b.hidden=true;document.body.append(b);b.click();b.remove()}
function v1121Pay(kind){
 const nav=(page,msg)=>{toast(msg);ui.page=page;render()};
 try{
  if(kind==='card'){
   const cards=(db.cards||[]).filter(c=>c&&!c.archived&&!isHidden(c)&&!/debit|debito/.test(String([c.type,c.cardType,c.kind].join(' ')).toLowerCase()));
   if(!cards.length)return nav('cards','No tienes tarjetas de crédito registradas.');
   window.openRegisterProductPicker('Selecciona la tarjeta a pagar',cards.map(item=>({type:'cardId',item})),'',o=>v1121Go('payCard',o.value));
  }else if(kind==='loan'){
   const loans=(db.loans||[]).filter(l=>l&&!l.archived&&!isHidden(l));
   if(!loans.length)return nav('loans','No tienes préstamos activos.');
   window.openRegisterProductPicker('Selecciona el préstamo a pagar',loans.map(item=>({type:'loanId',item})),'',o=>v1121Go('payLoan',o.value));
  }else if(kind==='recurring'){
   const list=(typeof v339ActiveRecurring==='function'?v339ActiveRecurring():(db.recurring||[]).filter(r=>r.active!==false&&!r.archived));
   if(!list.length)return nav('recurring','No tienes suscripciones activas.');
   window.openItemPicker('Selecciona la suscripción a pagar',list.map(r=>({value:r.id,name:r.name,detail:[r.nextDue?prettyDate(r.nextDue):'',r.category].filter(Boolean).join(' · '),amount:money(num(r.amount),r.currency||'DOP',2)})),id=>v1121Go('payRecurring',id));
  }else{
   const list=(db.personalLoans||[]).filter(l=>l&&!l.archived&&personalBalance(l)>.005);
   if(!list.length)return nav('personal','No tienes saldos pendientes con personas.');
   window.openItemPicker('Selecciona la persona',list.map(l=>({value:l.id,name:l.person,detail:l.direction==='lent'?'Te debe':'Le debes',amount:money(personalBalance(l),l.currency||'DOP',2)})),id=>v1121Go('payPersonal',id));
  }
 }catch(err){console.warn('V1121',err);}
}
/* V1127 · Próximos vencimientos: tocar uno abre directamente su pago (tarjeta, préstamo, suscripción o persona). */
function v1127Target(key){
 const m=/^(?:debt|overdue):(card|loan|recurring|personal):(.+?)(?::(DOP|USD))?:(\d{4}-\d{2}-\d{2})$/.exec(String(key||''));
 if(!m)return null;
 const act={card:'payCard',loan:'payLoan',recurring:'payRecurring',personal:'payPersonal'}[m[1]];
 return act?{act,id:m[2],ccy:m[3]||''}:null;
}
document.addEventListener('click',e=>{const r=e.target.closest?.('[data-v1127-pay]');if(!r)return;const t=v1127Target(r.dataset.v1127Pay);if(!t)return;e.preventDefault();e.stopPropagation();document.getElementById('v361-pressure-day-dialog')?.remove();document.body.classList.remove('v361-pressure-open');v1121Go(t.act,t.id,t.ccy)},true);
/* V1126 · Radar: tocar un tramo (0–7, 8–15, 16–30 días) abre el desglose de sus vencimientos, igual que el calendario. */
function v1126OpenDueRange(i){
 const limits=[7,15,30],labels=['0–7 días','8–15 días','16–30 días'];
 const from=v119DateAfter(i?limits[i-1]+1:0),end=v119DateAfter(limits[i]);
 const events=(v119Baseline(30).events||[]).filter(e=>e.type==='expense'&&num(e.amount)>0&&e.date>=from&&e.date<=end).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
 const total=events.reduce((t,e)=>t+num(e.amount),0);
 document.getElementById('v361-pressure-day-dialog')?.remove();
 const rows=events.map(e=>{const pay=v1127Target(e.key);return `<article class="v361-pressure-item${pay?' v1127-payable':''}" ${pay?`data-v1127-pay="${sanitize(e.key)}" role="button" tabindex="0"`:''}><div><strong>${sanitize(e.name||'Compromiso')}</strong><span>${sanitize(prettyDate(e.date))}${pay?' · Toca para pagar':''}</span></div><b>${v318Money(num(e.amount))}</b></article>`}).join('');
 const dialog=document.createElement('div');dialog.id='v361-pressure-day-dialog';dialog.className='v361-pressure-overlay';
 dialog.innerHTML=`<div class="v361-pressure-backdrop" data-v361-pressure-close="1"></div><section role="dialog" aria-modal="true" aria-labelledby="v361-pressure-title" class="v361-pressure-sheet"><header><div><small>RADAR DE VENCIMIENTOS · ${labels[i]}</small><h2 id="v361-pressure-title">${labels[i]}</h2></div><button type="button" data-v361-pressure-close="1" aria-label="Cerrar desglose">×</button></header><div class="v361-pressure-main"><span>Compromisos previstos</span><strong>${v318Money(total)}</strong><small>${events.length} ${events.length===1?'compromiso':'compromisos'} en este tramo</small></div><div class="v361-pressure-list">${rows||'<p class="v360-pressure-empty">No hay obligaciones en este tramo.</p>'}</div><footer><button type="button" data-v361-pressure-close="1">Cerrar</button></footer></section>`;
 document.body.appendChild(dialog);document.body.classList.add('v361-pressure-open');dialog.querySelector('.v361-pressure-sheet header button')?.focus();
}
document.addEventListener('click',e=>{const c=e.target.closest?.('[data-v1126-bucket]');if(!c)return;e.preventDefault();e.stopPropagation();v361PressureLastFocus=c;v1126OpenDueRange(Number(c.dataset.v1126Bucket))},true);
document.addEventListener('keydown',e=>{const c=e.target.closest?.('[data-v1126-bucket]');if(c&&(e.key==='Enter'||e.key===' ')){e.preventDefault();v1126OpenDueRange(Number(c.dataset.v1126Bucket))}});
/* V1125 · Radar de vencimientos: el botón «Pagar» pregunta qué vencimiento pagar y abre el pago. */
function v1125PayUpcoming(){
 let list=[];try{list=(upcoming()||[]).filter(u=>u&&u.action&&u.ref).slice(0,40)}catch(e){}
 if(!list.length){toast('No tienes pagos próximos.');return}
 const map=new Map(list.map((u,i)=>[String(i),u]));
 window.openItemPicker('Selecciona qué pagar',list.map((u,i)=>({value:String(i),name:u.name,detail:prettyDate(u.date)+(u.kind==='card'?' · Tarjeta':u.kind==='loan'?' · Préstamo':u.kind==='recurring'?' · Suscripción':''),amount:money(num(u.amount),u.currency||'DOP',2)})),i=>{const u=map.get(String(i));if(u)v1121Go(u.action,u.ref,u.ccy)});
}
document.addEventListener('click',e=>{if(!e.target.closest?.('[data-v1125-pay]'))return;e.preventDefault();e.stopPropagation();v1125PayUpcoming()},true);
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v1121-pay]');if(!b)return;e.preventDefault();e.stopPropagation();v1121Pay(b.dataset.v1121Pay)},true);
/* V1129 · Widget «Salario anticipado»: registra desde Inicio el cobro de un ingreso recurrente (nómina) antes de su fecha. */
function v1129SalaryWidget(){
 let sources=[];
 try{v40Ensure();sources=(db.incomeSchedules||[]).filter(x=>x&&x.active!==false&&x.nextDue).sort((a,b)=>(a.kind==='formal'?0:1)-(b.kind==='formal'?0:1)||String(a.nextDue).localeCompare(String(b.nextDue))).slice(0,3)}catch(e){}
 const head='<div class="vive-mobile-card-head"><div><span class="vive-mobile-eyebrow">INGRESOS RECURRENTES</span><h2>Salario anticipado</h2></div><button type="button" class="vive-mobile-view-all" data-act="navigate" data-id="income">Ver ingresos '+icon('arrow')+'</button></div>';
 const rows=sources.map(s=>{let net=0;try{net=num(v40Payroll(s,s.nextDue).net)}catch(e){}
  const future=s.nextDue>today();const label=future?(s.kind==='formal'?'Registrar salario anticipado':'Registrar cobro anticipado'):(s.kind==='formal'?'Confirmar salario':'Confirmar cobro');
  return `<div class="v1129-income"><div class="v1129-income-info"><strong>${sanitize(s.name||'Ingreso')}</strong><small>${future?'Próximo cobro':'Cobro pendiente'} · ${sanitize(prettyDate(s.nextDue))}${s.postingMode==='auto'?' · automático':''}</small></div><b>${money(net,s.currency||'DOP')}</b><button type="button" class="v1129-income-btn" data-v40-action="${future?'v940Advance':'confirmIncome'}" data-id="${sanitize(String(s.id))}">${label}</button></div>`}).join('');
 const hint=rows?'<p class="v1129-hint">Si te pagan antes de la fecha prevista, regístralo aquí como salario anticipado; el cobro automático no se duplica.</p>':'';
 const body=rows?rows+hint:'<p class="v273-widget-empty">Para registrar un salario anticipado primero crea tu salario recurrente; luego podrás cobrarlo antes de su fecha desde aquí.</p><button type="button" class="v1129-income-btn v1129-add" data-v1129-start="1">Registrar salario anticipado</button>';
 return `<section data-v105-widget="salaryAdvance" class="v105-mobile-extra v273-overview-widget v1129-salary" aria-label="Salario anticipado">${head}${body}</section>`;
}
