/* V290 — Panel ejecutivo de presupuesto: lectura exclusiva de datos existentes.
   El porcentaje representa UTILIZACIÓN (gastado / límite), no una puntuación
   de cumplimiento; más de 100% significa que se sobrepasó el límite. */
function v290BudgetSnapshot(period=ui.month){
 const month=/^\d{4}-(0[1-9]|1[0-2])$/.test(String(period||''))?String(period):today().slice(0,7);
 const [year,mo]=month.split('-').map(Number),plan=budgetPlan(month),totals=monthlyTotals(year,mo);
 const allocated=Math.max(0,num(plan.total));
 const categories=plan.groups.map(g=>{
   const spent=g.global!==null?num(totals.expenseBy[g.category]):g.subs.reduce((v,b)=>v+num(totals.expenseSubBy[g.category+'||'+b.subcategory]),0);
   return {name:g.category,limit:Math.max(0,num(g.amount)),spent:Math.max(0,spent),percent:g.amount>0?100*spent/g.amount:0};
 }).sort((a,b)=>b.spent-a.spent);
 const spent=Math.max(0,budgetCoveredSpend(totals,month));
 const expense=Math.max(0,num(totals.expense));
 const uncovered=Math.max(0,expense-spent);
 const remaining=allocated-spent;
 const percent=allocated>0?100*spent/allocated:null;
 const days=new Date(year,mo,0).getDate(),now=today().slice(0,7);
 const elapsed=month<now?days:month===now?Math.min(days,Number(today().slice(8))):0;
 const expected=allocated*elapsed/days;
 const pace=allocated>0&&elapsed>0?spent-expected:null;
 const over=categories.filter(c=>c.spent>c.limit+.005).length;
 const state=percent===null?'Sin presupuesto':percent>100?'Límite superado':percent>=85?'Atención al límite':'Dentro del límite';
 return {month,allocated,spent,expense,uncovered,remaining,percent,elapsed,days,expected,pace,over,categories,state};
}
function v290BudgetPct(value){return value===null?'—':new Intl.NumberFormat('es-DO',{minimumFractionDigits:1,maximumFractionDigits:1}).format(value)+'%'}

function v290BudgetRing(p){
 const angle=p.percent===null?0:Math.max(0,Math.min(100,p.percent))*3.6;
 return `<div class="v290-ring ${p.percent!==null&&p.percent>100?'v290-ring-over':p.percent!==null&&p.percent>=85?'v290-ring-warn':''}" style="--v290-angle:${angle}deg" role="img" aria-label="Utilización del presupuesto: ${v290BudgetPct(p.percent)}"><div><strong>${v290BudgetPct(p.percent)}</strong><small>${p.percent===null?'Sin asignación':'utilizado'}</small></div></div>`;
}
/* V291 · Resumen web: presupuesto junto a Próximos pagos.
   Cuatro datos, sin categorías. Las métricas provienen del mismo snapshot
   que utiliza Ejecución, y no se modifica el Resumen móvil. */
function v290BudgetWeb(){
 const p=v290BudgetSnapshot();
 const remainingClass=p.remaining<-.005?'v290-negative':'';
 const remainingHint=p.remaining<-.005?'Presupuesto excedido': 'Importe por gastar';
 return `<section class="v290-budget-web v291-budget-compact ff-tile" aria-label="Presupuesto mensual: porcentaje utilizado, asignado, ejecutado y disponible" data-v105-widget="budget">
    <header class="v290-budget-head"><div><span class="v290-eyebrow">PRESUPUESTO · ${sanitize(p.month)}</span><h2>Cumplimiento del presupuesto</h2></div><button type="button" data-v290-budget-open="execution" aria-label="Abrir ejecución del presupuesto">Ver ejecución ${icon('arrow')}</button></header>
    <div class="v291-budget-content">
      ${v290BudgetRing(p)}
      <div class="v291-budget-metrics">
        <div class="v291-budget-line"><span>Asignado</span><strong title="Presupuesto asignado: ${money(p.allocated,'DOP',2)}">${money(p.allocated)}</strong></div>
        <div class="v291-budget-line"><span>Ejecutado</span><strong title="Gasto cubierto por presupuesto: ${money(p.spent,'DOP',2)}">${money(p.spent)}</strong></div>
        <div class="v291-budget-line"><span>Disponible</span><strong class="${remainingClass}" title="${remainingHint}: ${money(p.remaining,'DOP',2)}">${money(p.remaining)}</strong></div>
      </div>
    </div>
 </section>`;
}

function v290BudgetHistory(){
 const base=ui.month||today().slice(0,7);const months=[];
 for(let i=5;i>=0;i--){const date=dateObj(base+'-01');date.setMonth(date.getMonth()-i);
  const month=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');const p=v290BudgetSnapshot(month);
  months.push({month,p});
 }
 const any=months.some(x=>x.p.allocated>0),max=Math.max(100,...months.map(x=>x.p.percent||0));
 const bars=months.map(x=>`<div class="v290-history-month" tabindex="0" data-chart-tip="${sanitize(x.month)}|Asignado: ${money(x.p.allocated)}|Ejecutado: ${money(x.p.spent)}|Utilización: ${v290BudgetPct(x.p.percent)}"><div class="v290-history-column"><i class="${x.p.percent!==null&&x.p.percent>100?'over':''}" style="height:${x.p.percent===null?0:Math.max(2,Math.min(100,x.p.percent/max*100))}%"></i><span class="v290-history-target" aria-hidden="true" style="bottom:${100/max*100}%"></span></div><small>${sanitize(x.month.slice(5))}</small></div>`).join('');
 return `<section data-v105-widget="budgetTrend" class="v290-budget-trend" aria-label="Evolución histórica del presupuesto"><header class="v290-mobile-header"><div><span class="v290-eyebrow">PLANIFICACIÓN · HISTÓRICO</span><h2>Tu disciplina en seis meses</h2></div><button type="button" data-v290-budget-open="execution" aria-label="Abrir presupuesto">${icon('arrow')}</button></header>${any?`<div class="v290-history-chart" role="img" aria-label="Porcentaje de presupuesto utilizado en los últimos seis meses">${bars}</div><p class="v290-history-note">Cada barra es el porcentaje gastado respecto al límite de ese mes. La línea marca el 100%.</p>`:'<div class="v290-no-categories">Cuando definas un presupuesto, aquí verás cómo evoluciona mes a mes.</div>'}</section>`;
}

