let v243ExploreDestination=null;
// Paso 8: reuse the existing contextual breadcrumb for journeys originating in Buscar.
// No new router or alternate search engine is introduced.
let v8SearchDestination=null;
let v243ExploreScrollY=0;
function v243ExploreReturn(){
  if(v8SearchDestination===ui.page && ui.page!=='mobilesearch' && isMobileViewport()){
    return `<nav class="v243-explore-return" aria-label="Regresar a Buscar"><button type="button" data-v8-search-back="1" aria-label="Volver a resultados de Buscar">${icon('arrow')}<span>Buscar</span></button><span aria-hidden="true">/</span><strong>${sanitize(({'cards':'Tarjetas','banks':'Bancos','accounts':'Cuentas','loans':'Préstamos','register':'Movimientos','recurring':'Suscripciones','budget':'Presupuestos','payments':'Compromisos','patrimony':'Patrimonio','income':'Ingresos','expenses':'Egresos','personal':'Entre personas'})[ui.page]||'Resultado')}</strong></nav>`;
  }
  if(!v243ExploreDestination || v243ExploreDestination!==ui.page || ui.page==='mobilehub')return '';
 return `<nav class="v243-explore-return" aria-label="Volver a Explorar"><button type="button" data-v243-explore-back="1" aria-label="Volver a Explorar">${icon('arrow')}<span>Explorar</span></button><span aria-hidden="true">/</span><strong>${sanitize(({'income':'Ingresos','expenses':'Egresos','budget':'Presupuestos','categories':'Categorías','payments':'Visión global','vision':'Visión global','recurring':'Suscripciones','personal':'Entre personas','patrimony':'Patrimonio','analytics':'Visión global','advanced':'Analítica avanzada','pressure':'Presión financiera'})[ui.page]||'Módulo')}</strong></nav>`;
}
function mobileHub(){
 const period=ui.month||today().slice(0,7);
 const groups=[
  {eyebrow:'TU ACTIVIDAD',title:'Cada movimiento, en su lugar',subtitle:'Registros, análisis y planificación',entries:[
   ['income','Ingresos','Recibes','up'],['expenses','Egresos','Gastas','down'],
   ['budget','Presupuesto','Ejecución','chart'],['categories','Categorías','Organización','grid']]},
  {eyebrow:'TU VISIÓN',title:'Visión global',subtitle:'Tu panorama integral sin menús duplicados',entries:[
   ['payments','Visión global','Vencimientos y pagos','eye']]},
  {eyebrow:'MÁS PERSPECTIVA',title:'Tu inteligencia financiera',subtitle:'Información con profundidad, cuando la necesites',entries:[
   ['patrimony','Patrimonio','Activos y obligaciones','wallet'],
   ['advanced','Analítica avanzada','Tendencias y decisiones','chart']]},
  {eyebrow:'TU CALENDARIO',title:'Presión financiera',subtitle:'Tus próximos 30 días de un vistazo',entries:[['pressure','Presión financiera','Consultar calendario completo','calendar']]} 
 ];
 const link=([id,name,description,ic])=>`<button type="button" class="v205-explore-link" data-act="navigate" data-id="${id}" aria-label="Abrir ${name}"><span class="v205-explore-link-icon">${icon(ic)}</span><span class="v205-explore-link-copy"><strong>${name}</strong><small>${description}</small></span><span class="v205-explore-arrow" aria-hidden="true">${icon('arrow')}</span></button>`;
 return `<div class="vive-mobile-hub v205-explore v243-explore">
   <header class="v205-explore-header"><span class="v205-explore-kicker">vive el hoy · TU ESPACIO</span><h1>Explorar<span class="v205-explore-period">${dateObj(period+'-01').toLocaleDateString('es-DO',{month:'long',year:'numeric'})}</span></h1><p>Tu espacio financiero, organizado por lo que quieres hacer.</p></header>
   ${groups.map(g=>`<section class="v205-explore-group" aria-label="${g.title}"><div class="v205-explore-group-header"><span>${g.eyebrow}</span><h2>${g.title}</h2><p>${g.subtitle}</p></div><div class="v205-explore-links">${g.entries.filter(e=>!(typeof window!=='undefined'&&window.matchMedia('(max-width:790px)').matches&&e[0]==='advanced')).map(link).join('')}</div></section>`).join('')}
   <div class="v205-explore-end"><span>Tu información está organizada por decisiones, no por menús.</span></div>
 </div>`;
}






const V728_RECENT_SEARCH_STORAGE='vive-finanzas-search-history-v728';
function v728RecentSearchTerms(){
 try{const stored=JSON.parse(localStorage.getItem(V728_RECENT_SEARCH_STORAGE)||'[]');return Array.isArray(stored)?stored.filter(x=>typeof x==='string'&&x.trim()).slice(0,12):[]}catch(_){return []}
}
function v728StoreRecentSearch(value){
 const term=String(value||'').trim().slice(0,90);if(term.length<2)return;
 try{const rest=v728RecentSearchTerms().filter(x=>x.toLocaleLowerCase()!==term.toLocaleLowerCase());localStorage.setItem(V728_RECENT_SEARCH_STORAGE,JSON.stringify([term,...rest].slice(0,12)))}catch(_){}
}

function v728RecentSearchHtml(){
 const terms=v728RecentSearchTerms();return terms.length?terms.map((term,i)=>`<button type="button" class="v711-recent-pill" data-v711-search-term="${sanitize(term)}" ${i>3?'data-v728-recent-extra="1" hidden':''}>${sanitize(term)}</button>`).join(''):`<span class="v711-empty-inline">Todavía no has realizado búsquedas. Tus consultas aparecerán aquí.</span>`;
}
function v728UpdateRecentWidget(){
 const node=document.querySelector('.v721-recent-widget');if(!node)return;
 const list=node.querySelector('.v711-recent-row');if(!list)return;
 list.innerHTML=v728RecentSearchHtml();
 const btn=node.querySelector('[data-v728-recent-all]');if(btn){const n=v728RecentSearchTerms().length;btn.hidden=n<=4;btn.setAttribute('aria-expanded','false');btn.textContent='Ver todo';}
}

