/* V721 · Recent-search chips reuse existing client-side search, without new API calls. */
document.addEventListener('click',e=>{
 const chip=e.target.closest?.('[data-v711-search-term]');
 if(!chip)return;
 const input=document.getElementById('v154-mobile-search-input');
 if(!input)return;
 e.preventDefault();
 input.value=chip.dataset.v711SearchTerm||'';
 v154MobileCategory=null;
 v154SearchResultsUpdate();
 input.focus();
});


document.addEventListener('change',e=>{
 if(e.target?.id!=='v154-mobile-search-input')return;
 if(String(e.target.value||'').trim().length>=2){v728StoreRecentSearch(e.target.value);v728UpdateRecentWidget()}
});
document.addEventListener('click',e=>{
 const btn=e.target.closest?.('[data-v728-recent-all]');if(!btn)return;
 e.preventDefault();
 const pane=btn.closest('.v721-recent-widget');if(!pane)return;
 const expanded=btn.getAttribute('aria-expanded')==='true';
 pane.querySelectorAll('[data-v728-recent-extra]').forEach(x=>x.hidden=expanded);
 btn.setAttribute('aria-expanded',String(!expanded));btn.textContent=expanded?'Ver todo':'Ver menos';
});

/* V371 · Rentabilidad de tarjeta, lectura anual sin asientos duplicados.
   Beneficios = solo acreditaciones monetarias reales vinculadas a la tarjeta.
   Comparación = anualidad del año registrada, o contrato anual si aún no se cobró.
   No se agrega la anualidad a transacciones ni se valoran puntos / millas / perks. */
function v371CardReturn(c){
 const year=String(today()).slice(0,4), tx=(db.transactions||[]).filter(t=>t.cardId===c.id && String(t.date||'').startsWith(year));
 const configuredAmount=num(c.annualFeeAmount) || num(c.annualFeeDOP) || num(c.annualFeeUSD);
 const configuredCurrency=c.annualFeeCurrency || (num(c.annualFeeUSD)>0&&num(c.annualFeeDOP)<=0?'USD':'DOP');
 const feeRows=tx.filter(t=>['card_charge','expense'].includes(t.type) && (t.chargeKind==='annual_fee' || /anualidad|membres[ií]a/i.test(String(t.subcategory||''))));
 const rewardRows=tx.filter(t=>['card_reward','bank_reward'].includes(t.type));
 const rate=num(db.settings?.fx);
 const needsFx=(configuredAmount>0&&configuredCurrency==='USD')||[...feeRows,...rewardRows].some(t=>t.currency==='USD'&&num(t.amount)>0);
 const missingRate=needsFx&&!(rate>0);
 const asDop=t=>num(t.amount)*(t.currency==='USD'?rate:1);
 const feeActual=rnd(feeRows.reduce((sum,t)=>sum+asDop(t),0));
 const configured=rnd(configuredAmount*(configuredCurrency==='USD'?rate:1));
 // Si ya hubo un cargo real este año, se utiliza ese importe como costo de referencia.
 const annual=feeActual>0?feeActual:configured;
 const benefit=rnd(rewardRows.reduce((sum,t)=>sum+asDop(t),0));
 const net=rnd(benefit-annual);
 const roi=!missingRate&&annual>0?rnd(net/annual*100):null;
 return {year,annual,benefit,net,roi,missingRate,feeConfirmed:feeActual>0,hasAnnual:configuredAmount>0||feeActual>0};
}
function v371CardReturnWidget(c){
 const d=v371CardReturn(c);
 const cost=d.missingRate?'—':d.hasAnnual?money(d.annual,'DOP',2):'Sin definir';
 const benefit=d.missingRate?'—':money(d.benefit,'DOP',2);
 const net=d.missingRate||!d.hasAnnual?'—':`${d.net>0?'+':''}${money(d.net,'DOP',2)}`;
 const percentage=d.roi===null?'—':`${d.roi>0?'+':''}${new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(d.roi)}%`;
 const tone=d.missingRate||!d.hasAnnual?'':(d.net>0?'positive':d.net<0?'negative':'');
 return `<section class="v266-wallet-panel v371-card-return" aria-label="Retorno anual de beneficios de ${sanitize(c.name)}">
 <div class="v371-return-heading"><div><span class="v266-overline">BENEFICIOS · ${d.year}</span><h2>Beneficios y retorno</h2></div><button type="button" class="v371-return-action" data-v144-action="open-benefits" data-id="${sanitize(c.id)}" aria-label="Abrir beneficios de ${sanitize(c.name)}">${icon('arrow')}</button></div>
 <div class="v371-return-values">
 <div class="v371-return-tile"><small>Anualidad</small><strong>${cost}</strong></div>
 <div class="v371-return-tile"><small>Beneficios recibidos</small><strong>${benefit}</strong></div>
 <div class="v371-return-tile ${tone}"><small>Retorno</small><strong>${net}</strong></div>
 <div class="v371-return-tile ${tone}"><small>Retorno %</small><strong>${percentage}</strong></div>
 </div>
 <p class="v371-return-note">${d.missingRate?'Falta la tasa RD$/US$ para calcular el retorno.':!d.hasAnnual?'Configura la anualidad desde Gestionar para calcular el retorno.':d.feeConfirmed?'Retorno = beneficios monetarios acreditados − anualidad cobrada.':'Retorno estimado respecto a la anualidad configurada; no implica un cargo realizado.'}</p>
 </section>`;
}

/* V6 · Wallet móvil: ficha de transacción solo lectura, edición mediante el editor financiero existente. */
function v6WalletTransactionDetail(id){
 if(typeof window.v708OpenDetail==='function'&&(db.transactions||[]).some(r=>String(r.id)===String(id))){window.v708OpenDetail(id);return}
 const t=(db.transactions||[]).find(row=>String(row.id)===String(id));
 if(!t){toast('Este movimiento ya no está disponible.');return;}
 const c=t.cardId?card(t.cardId):null;
 const item=(label,value)=>`<div class="v6-wallet-detail-line"><span>${label}</span><strong>${value}</strong></div>`;
 const title=sanitize(transactionTitle(t));
 const category=sanitize(t.category||'Sin categoría');
 const subcategory=t.subcategory?` · ${sanitize(t.subcategory)}`:'';
 const editable=TRANSACTION_EDITABLE.has(t.type)||['personal_issue','personal_settlement','card_advance'].includes(t.type);
 const content=`<div class="v6-wallet-detail-amount"><small>${sanitize(TRANSL[t.type]||t.type)} ${v213ApplePayBadge(t)}</small><strong>${txDisplay(t)}</strong><span>${title}</span></div>
 <div class="v6-wallet-detail-lines">
 ${item('Fecha',sanitize(prettyDate(t.date)))}
 ${item('Producto / origen',sanitize(v922MovementProduct(t)))}${t.merchant||t.payee?item('Comercio',sanitize(t.merchant||t.payee)):''}${t.note||t.description?item('Descripción',sanitize(t.note||t.description)):''}
 ${item('Moneda',sanitize(t.currency||'DOP'))}
 ${item('Categoría',category)}${item('Subcategoría',sanitize(t.subcategory||'Sin subcategoría'))}
 ${item('Estado',t.reviewed===true?'Revisado':'Por revisar')}${v5NeedsAppleCategory(t)?item('Apple Pay','Pendiente de clasificar'):''}
 ${t.type==='card_advance'?item('Efectivo recibido',money(t.advanceNet,t.currency,2))+item('Comisión · '+num(t.advanceFeePct).toFixed(2)+'%',money(t.advanceFee,t.currency,2))+item('Deuda adicional',money(t.amount,t.currency,2))+item('Destino',sanitize(account(t.toAccountId)?.name||'Cuenta no encontrada')):''}
 ${t.paymentChannel?item('Canal',sanitize(String(t.paymentChannel))):''}
 </div><p class="v6-wallet-detail-hint">La consulta no cambia importes ni saldos. Al editar se utilizará el formulario de Movimientos.</p>`;
 document.querySelectorAll('.v36-notifications[open]').forEach(n=>n.open=false);
 const root=document.getElementById('modal-root');
 if(!root)return;
 root.innerHTML=`<div class="modal-layer v6-wallet-detail-layer" data-backdrop="true"><section class="modal v6-wallet-detail-modal" role="dialog" aria-modal="true" aria-label="Detalle del movimiento"><header class="modal-head"><h2>Detalle del movimiento</h2><button type="button" class="close" data-act="closeModal" aria-label="Cerrar">×</button></header><div class="v6-wallet-detail-content">${content}</div><footer class="v6-wallet-detail-actions"><button type="button" class="btn ghost" data-act="closeModal">Cerrar</button>${v5NeedsAppleCategory(t)?`<button type="button" class="btn v9-apple-classify" data-v7-apple-id="${sanitize(String(t.id))}">${icon('check')} Categorizar compra</button>`:''}${editable?`<button type="button" class="btn soft" data-act="v6WalletEditTransaction" data-id="${sanitize(String(t.id))}">${icon('edit')} Editar movimiento</button>`:''}</footer></section></div>`;
 root.querySelector('.v6-wallet-detail-modal .close')?.focus({preventScroll:true});
}
/* V68 — Wallet independiente y estrictamente visual. No genera movimientos por sí sola. */
function v68Wallet(){
 const cards=(db.cards||[]).filter(c=>ui.showHidden||!isHidden(c));
 if(!cards.length)return `<section class="v266-wallet v279-wallet" aria-label="Wallet móvil"><header class="v266-wallet-header"><div><span class="v266-overline">TU CARTERA</span><h1>Mis tarjetas</h1></div><button class="v266-wallet-add" data-act="addCard" aria-label="Añadir tarjeta">${icon('plus')}</button></header><div class="v266-empty"><strong>Tu Wallet comienza aquí.</strong><p>Agrega una tarjeta para consultar crédito, cortes, pagos y actividad.</p><button class="btn" data-act="addCard">Añadir tarjeta</button></div></section>`;
 const active=cards.find(c=>c.id===ui.v68WalletId)||cards[0];
 const dop=cardStatus(active,'DOP'),usd=cardStatus(active,'USD');
 const debt=dop.debt+fx(usd.debt,'USD');
 const totalLimit=num(active.limitDOP)+fx(num(active.limitUSD),'USD');
 const available=Math.max(0,totalLimit-debt);
 const availableDOP=Math.max(0,num(active.limitDOP)-num(dop.debt));
 const availableUSD=Math.max(0,num(active.limitUSD)-num(usd.debt));
 const usage=totalLimit>0?Math.min(100,Math.max(0,100*debt/totalLimit)):0;
 const last4=c=>String(c.last4||c.number||'').replace(/\D/g,'').slice(-4);
 const tierName=c=>CARD_TIER_NAMES[cardTierKey(c)]||'Tarjeta';
 const due=[{...dop,ccy:'DOP'},{...usd,ccy:'USD'}].filter(s=>s.nextDue&&num(s.billed)>0.005).sort((a,b)=>String(a.nextDue).localeCompare(String(b.nextDue)))[0];
 const history=recentTx().filter(t=>t.cardId===active.id).slice(0,4);
 const gallery=cards.map(c=>{
  const selected=c.id===active.id,bankName=bankOf(c),tier=cardTierKey(c);
  return `<button type="button" class="v68-wallet-face v266-wallet-face v277-wallet-face ${selected?'selected':''}" data-act="v68WalletSelect" data-id="${sanitize(c.id)}" aria-pressed="${selected}" aria-label="Seleccionar ${sanitize(c.name)}"><span class="v266-physical-card v277-physical-card tier-${sanitize(tier)}"><span class="v277-card-head"><span class="v277-card-bank">${bankLogoInline(c.bankId)}<b>${sanitize(bankName||c.name)}</b></span><small>${sanitize(tierName(c))}</small></span><strong class="v277-card-title">${sanitize(c.name)}</strong><span class="v277-card-number">•••• ${sanitize(last4(c)||'••••')}</span><span class="v277-card-footer"><small>CRÉDITO · ${num(c.limitDOP)>0?'RD$':''}${num(c.limitDOP)>0&&num(c.limitUSD)>0?' / ':''}${num(c.limitUSD)>0?'US$':''}${num(c.limitDOP)<=0&&num(c.limitUSD)<=0?'RD$ / US$':''}</small>${cardNetworkMark(c)}</span></span></button>`;
 }).join('');
 const rows=history.map(t=>`<button type="button" class="v266-activity-row v6-wallet-tx-trigger" data-act="v6WalletTransactionDetail" data-id="${sanitize(String(t.id))}" aria-label="Ver detalles de ${sanitize(transactionTitle(t))}, ${sanitize(String(txDisplay(t)).replace(/<[^>]*>/g,''))}"><span class="v266-activity-ico">${icon(['card_payment','card_refund','card_reward'].includes(t.type)?'up':'card')}</span><span class="v266-activity-info"><strong>${sanitize(transactionTitle(t))} ${v213ApplePayBadge(t)}</strong><small>${prettyDate(t.date)}</small></span><b>${txDisplay(t)}</b><span class="v6-wallet-tx-chevron" aria-hidden="true">${icon('arrow')}</span></button>`).join('');
 const metric=(label,value,sub='')=>`<div class="v266-metric"><small>${label}</small><strong>${value}</strong>${sub?`<span>${sub}</span>`:''}</div>`;
 const accent=String(bank(active.bankId)?.color||db.settings.paletteHex||'').trim();
 const walletAccent=/^#[0-9a-fA-F]{6}$/.test(accent)?accent:'#6964ea';
 return `<section class="v68-wallet v266-wallet v279-wallet" style="--v900-wallet-tone:${walletAccent}" aria-label="Wallet móvil"><header class="v266-wallet-header"><div><h1>Mis tarjetas</h1></div><button type="button" class="v266-wallet-add" data-act="addCard" aria-label="Agregar tarjeta">${icon('plus')}</button></header>
 <div class="v266-gallery" aria-label="Selecciona una tarjeta"><div class="v68-wallet-gallery v266-gallery-track">${gallery}</div><div class="v68-wallet-dots v266-dots">${cards.map(c=>`<button type="button" data-act="v68WalletSelect" data-id="${sanitize(c.id)}" class="${c.id===active.id?'active':''}" aria-label="Seleccionar ${sanitize(c.name)}"></button>`).join('')}</div></div>
 <div class="v266-selected-balance v550-currency-balance v565-credit-dashboard" aria-label="Resumen de crédito por moneda de la tarjeta seleccionada">
   <div class="v550-balance-column v565-primary"><span>CRÉDITO DISPONIBLE</span><strong>${money(available)}</strong><small>RD$ equivalentes</small>
    <div class="v550-currency-breakdown" aria-label="Disponible en pesos y dólares"><span><i>RD$</i><b>${num(availableDOP).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</b></span><span><i>US$</i><b>${num(availableUSD).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</b></span></div>
   </div>
   <div class="v266-selected-debt v550-balance-column v565-secondary"><small>DEUDA UTILIZADA</small><b>${money(debt)}</b><small>RD$ equivalentes</small>
    <div class="v550-currency-breakdown" aria-label="Deuda en pesos y dólares"><span><i>RD$</i><b>${num(dop.debt).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</b></span><span><i>US$</i><b>${num(usd.debt).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</b></span></div>
   </div>
  </div>
 <div class="v266-wallet-actions" aria-label="Acciones de tarjeta"><button type="button" data-act="payCard" data-id="${sanitize(active.id)}"><span>${icon('wallet')}</span><b>Pagar</b></button><button type="button" data-act="goCard" data-id="${sanitize(active.id)}"><span>${icon('calendar')}</span><b>Corte</b></button><button type="button" data-v900-action="advance" data-id="${sanitize(active.id)}" aria-label="Solicitar avance de efectivo"><span>${icon('cashAdvance')}</span><b>Avance</b></button><button type="button" data-act="editCard" data-id="${sanitize(active.id)}"><span>${icon('settings')}</span><b>Editar</b></button></div>
 <section class="v266-wallet-panel"><div class="v266-panel-heading"><div><span class="v266-overline">CONTROL DE CRÉDITO</span><h2>Estado de tu tarjeta</h2></div><button type="button" data-act="goCard" data-id="${sanitize(active.id)}" aria-label="Abrir detalles">${icon('arrow')}</button></div>
 <div class="v268-limit-row v565-limit-header"><span>Límite total</span><strong>${money(totalLimit)}</strong></div><div class="v565-limit-currencies" aria-label="Límites originales por moneda"><div><span>EN PESOS</span><strong>${money(num(active.limitDOP),'DOP',2)}</strong></div><div><span>EN DÓLARES</span><strong>${money(num(active.limitUSD),'USD',2)}</strong></div></div><div class="v266-credit-meter" role="meter" aria-label="Porcentaje utilizado del límite" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${usage.toFixed(1)}"><span style="width:${usage}%"></span></div><div class="v266-meter-foot"><span>Utilización del límite</span><b>${usage.toFixed(1)}%</b></div>${due?`<div class="v266-next-payment"><div><small>${due.nextDue<today()?'VENCIMIENTO ATRASADO':'PRÓXIMO VENCIMIENTO'}</small><strong>${prettyDate(due.nextDue)}</strong></div><b>${money(due.billed,due.ccy,2)}</b><button type="button" data-act="payCard" data-id="${sanitize(active.id)}" data-ccy="${due.ccy}">Pagar ${icon('arrow')}</button></div>`:''}</section>
 ${v371CardReturnWidget(active)}
 <details class="v266-wallet-detail v935-wallet-accordion"><summary><span>${icon('receipt')} Cortes por moneda <small>Pesos y dólares</small></span>${icon('arrow')}</summary><div class="v266-currency-row"><span>Facturado · RD$</span><b>${money(dop.billed,'DOP',2)}</b></div><div class="v266-currency-row"><span>Facturado · US$</span><b>${money(usd.billed,'USD',2)}</b></div><p>Los importes son registros internos. Consulta el estado oficial de tu entidad para conciliar.</p></details>
 ${v921WalletAdvanceDetails(active)}
 <section class="v266-wallet-panel v266-activity"><div class="v266-panel-heading"><div><span class="v266-overline">TUS ÚLTIMOS CONSUMOS</span><h2>Actividad reciente</h2></div><button type="button" data-act="goCard" data-id="${sanitize(active.id)}" aria-label="Ver todos los movimientos">${icon('arrow')}</button></div>${rows||'<p class="v266-empty-activity">Sin movimientos recientes en esta tarjeta.</p>'}</section>
 <p class="v266-wallet-note">Una compra con tarjeta aumenta tu deuda; pagarla reduce el saldo pendiente sin duplicar el gasto.</p></section>`;
}



