 window.__v847CardCurrencyMeta=Object.fromEntries((db.cards||[]).map(c=>[c.id,{currency:c.currency,dual:Number(c.usdLimit||c.limitUSD||c.limitUsd||0)>0&&Number(c.limit||c.limitDop||0)>0}]));
