function cardBenefitsBlock(c){
 const year=new Date().getFullYear(),dop=benefitBreakdown(c,'DOP',year),usd=benefitBreakdown(c,'USD',year);
 const date=annualMembershipDate(c);
 const perks=(db.perkUses||[]).filter(p=>p.cardId===c.id&&p.date.startsWith(String(year)));
 const actual=[...dop.realized,...usd.realized].map(t=>({date:t.date,label:t.note||'Cashback acreditado',value:money(t.amount,t.currency,2),type:'cash',id:t.id}));
 const extras=perks.map(p=>({date:p.date,label:p.name,value:p.kind==='points'?new Intl.NumberFormat('es-DO',{maximumFractionDigits:2}).format(num(p.value))+' puntos':num(p.value)?'Valor referencial '+money(p.value,p.currency,2):'Beneficio registrado',type:'other',kind:p.kind||'other',id:p.id}));
 const history=[...actual,...extras].sort((a,b)=>b.date.localeCompare(a.date));
 const allD=benefitBreakdown(c,'DOP'),allU=benefitBreakdown(c,'USD');
 const allBenefitD=allD.credited+fx(allU.credited,'USD');
 const allAnnualD=allD.fees+fx(allU.fees,'USD');
 const boxes=[['Beneficios monetarios · acumulados',money(allBenefitD,'DOP',2),'Cashback efectivo histórico · RD$ equivalente'],['Anualidades pagadas · acumuladas',money(allAnnualD,'DOP',2),'Solo cargos de anualidad confirmados'],['Retorno tras anualidades',money(allBenefitD-allAnnualD,'DOP',2),'Beneficios cobrados menos anualidades reales'],['Cashback RD$ · cobrado',money(dop.credited,'DOP',2),'Cuenta o tarjeta, realmente acreditado'],['Cashback US$ · cobrado',money(usd.credited,'USD',2),'Sin conversión automática'],['Costos reales · RD$',money(dop.costs,'DOP',2),'Anualidad, intereses y comisiones'],['Resultado neto RD$',money(dop.net,'DOP',2),'Cashback cobrado menos costos reales']].map(([t,note,desc])=>`<div class="benefit-simple-tile"><small>${sanitize(t)}</small><strong>${note}</strong><span>${sanitize(desc)}</span></div>`).join('');
 return `<section class="benefit-simple" aria-label="Beneficios manuales de la tarjeta"><div class="benefit-simple-header"><div><span class="summary-tag">BENEFICIOS REALES · ${year}</span><h3>Beneficios que registraste</h3><p>Sin puntos, millas, promociones ni estimaciones. Solo lo que recibiste o utilizaste.</p></div><button class="btn" data-act="manualBenefit" data-id="${c.id}">${icon('plus')} Registrar beneficio</button></div><div class="benefit-simple-kpis">${boxes}</div><div class="benefit-simple-info"><div><small>Anualidad de la tarjeta</small><b>${money(num(c.annualFeeAmount??(num(c.annualFeeDOP)||num(c.annualFeeUSD))),c.annualFeeCurrency||(num(c.annualFeeUSD)&&!num(c.annualFeeDOP)?'USD':'DOP'),2)}</b></div><div><small>Renovación indicada</small><b>${date?prettyDate(date):'Sin fecha declarada'}</b></div><div><small>Retorno neto US$</small><b class="${usd.net<0?'negative':'positive'}">${money(usd.net,'USD',2)}</b></div><button class="btn sm soft" data-act="annualFee" data-id="${c.id}">Registrar anualidad cobrada</button></div><div class="benefit-simple-list-title"><b>Historial de beneficios registrados</b><span>${history.length} en ${year}</span></div><div class="benefit-simple-list">${history.length?history.slice(0,12).map(h=>`<div class="benefit-simple-row"><div><strong>${sanitize(h.label)}</strong><small>${prettyDate(h.date)} · ${h.type==='cash'?'Cashback real':({discount:'Descuento confirmado',points:'Puntos recibidos',other:'Beneficio informativo'})[h.kind]||'Otro beneficio · no es ingreso'}</small></div><div class="benefit-simple-end"><b>${sanitize(h.value)}</b>${h.type==='other'?`<span><button data-act="editManualBenefit" data-id="${c.id}" data-entry="${h.id}" title="Editar beneficio">Editar</button><button data-act="removeManualBenefit" data-id="${c.id}" data-entry="${h.id}" title="Eliminar beneficio">Eliminar</button></span>`:`<button data-act="editTransaction" data-id="${h.id}" title="Editar cashback">Editar</button>`}</div></div>`).join(''):'<div class="benefit-empty">Todavía no has registrado beneficios para esta tarjeta.</div>'}</div><p class="footnote">Los beneficios distintos del cashback son informativos y no aumentan tu saldo. La anualidad configurada no es gasto hasta registrar su cobro. Los importes RD$ y US$ no se mezclan.</p></section>`;
}
/* PRÉSTAMOS ENTRE PERSONAS: módulo patrimonial, no cronograma financiero ni proyección */
function personal(){
 let records=(db.personalLoans||[]).filter(l=>ui.showHidden||!l.archived).slice().sort((a,b)=>(a.dueDate||'').localeCompare(b.dueDate||''));
 let receivable=records.filter(l=>l.direction==='lent').reduce((a,l)=>a+fx(personalBalance(l),l.currency),0);
 let payable=records.filter(l=>l.direction==='borrowed').reduce((a,l)=>a+fx(personalBalance(l),l.currency),0);
 let filter=ui.personalFilter||'all';let filtered=records.filter(l=>filter==='all'||l.direction===filter);
 let rows=filtered.map(l=>{let due=l.dueDate||'',bal=personalBalance(l),t=personalMovementInstrument(l),pct=l.principal?Math.min(100,100*(l.principal-bal)/l.principal):100;
  return `<tr><td><strong>${sanitize(l.person)}</strong><small class="today-row-muted">${sanitize(t)}</small></td><td><span class="pill ${l.forgiveness?.amount?'blue':l.direction==='lent'?'green':'orange'}">${l.forgiveness?.amount?'Perdonado':bal<.01?'Liquidado':l.direction==='lent'?'Me deben':'Yo debo'}</span></td><td class="right">${money(l.principal,l.currency,2)}</td><td class="right"><strong>${money(bal,l.currency,2)}</strong><div class="personal-progress"><span style="width:${pct.toFixed(1)}%"></span></div></td><td>${prettyDate(due)}<small class="today-row-muted">${l.forgiveness?.amount?'Perdonado · '+prettyDate(l.forgiveness.date):bal>0?whenTxt(due):'Liquidado'}</small></td><td class="right"><div class="v82-personal-actions"><button class="btn sm soft" data-act="payPersonal" data-id="${l.id}" ${bal<.01?'disabled':''}>Registrar abono</button>${l.direction==='lent'&&bal>.005?`<button class="btn sm ghost v82-forgive-btn" type="button" data-act="forgivePersonal" data-id="${l.id}">Perdonar deuda</button>`:''}</div>${l.forgiveness?.amount?`<small class="v82-forgiven-note" title="${sanitize(l.forgiveness.note||'Condonación voluntaria')}">${money(l.forgiveness.amount,l.currency,2)} perdonados · sin ingreso bancario</small>`:''}</td></tr>`;
 }).join('');
 let history=recentTx().filter(t=>['personal_issue','personal_settlement'].includes(t.type)).slice(0,24);
 return `<div class="personal-world"><header class="personal-world-hero"><div><span class="summary-tag">PERSONAS · SIN ENTIDAD PRESTAMISTA</span><h2>Dinero entre personas</h2><p>Registra a quién debes y quién te debe. El origen o destino del dinero es una cuenta o tarjeta, pero el acreedor es una persona.</p></div><button class="btn" data-act="addPersonal">${icon('plus')} Nueva relación</button></header>
 <div class="personal-ledger-head"><div class="personal-ledger-total"><span>Por cobrar</span><strong class="positive">${money(receivable)}</strong></div><div class="personal-ledger-total"><span>Por devolver</span><strong>${money(payable)}</strong></div><div class="personal-ledger-filter" role="group" aria-label="Filtrar préstamos personales"><button class="${filter==='all'?'selected':''}" data-act="personalFilter" data-id="all">Todos</button><button class="${filter==='lent'?'selected':''}" data-act="personalFilter" data-id="lent">Me deben</button><button class="${filter==='borrowed'?'selected':''}" data-act="personalFilter" data-id="borrowed">Yo debo</button></div></div>
 <section class="summary-glass personal-ledger"><div class="personal-ledger-title"><h3>Registro de relaciones</h3><small>${filtered.length} relación${filtered.length===1?'':'es'} · saldos por moneda, sin sumar divisas en cada fila</small></div><div class="table-wrap"><table class="personal-table"><thead><tr><th>Persona e instrumento</th><th>Situación</th><th class="right">Capital pactado</th><th class="right">Pendiente</th><th>Vencimiento</th><th class="right">Acción</th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="personal-no-items">No tienes relaciones de este tipo registradas.</td></tr>'}</tbody></table></div></section>
 <details class="personal-historical"><summary>Ver historial de entregas y abonos <span>${history.length} operaciones</span></summary><div class="summary-glass">${smallTxTable(history)}</div></details><p class="footnote">El capital recibido o prestado no es ingreso ni gasto. Solo los intereses realmente cobrados o pagados afectan el resultado. Si eliges tarjeta como medio de disposición o abono, su deuda se ajusta sin registrarse como consumo de compra.</p></div>`;
}
