 let benefitD=db.cards.reduce((v,c)=>v+benefitBreakdown(c,'DOP').credited,0),benefitU=db.cards.reduce((v,c)=>v+benefitBreakdown(c,'USD').credited,0);
 let netD=db.cards.reduce((v,c)=>v+v144CardStats(c,false).net,0),netU=0;
