 banks:[['banksCount','Instituciones registradas'],['banksWithProducts','Bancos con productos'],['bankFunds','Fondos en instituciones'],['bankDebt','Deuda bancaria']],
 cards:[['cardDebtTotal','Deuda total de tarjetas'],['cardDebtDOP','Tarjetas · RD$'],['cardDebtUSD','Tarjetas · US$'],['cardBilled','Pendiente facturado'],['cardUnused','Crédito disponible'],['cardOverdraft','Sobregiro utilizado'],['cardCount','Tarjetas registradas'],['cardAnnual','Anualidades pactadas']],
 loans:[['loanDebt','Capital pendiente'],['loanPaid','Capital amortizado'],['loanInterest','Intereses pagados'],['loanExtras','Abonos extraordinarios'],['loansCount','Préstamos registrados']],
 certs:[['certCapital','Capital en certificados'],['certCount','Certificados registrados'],['certInterest','Intereses cobrados este año']],
 benefits:[['cashback','Cashback recibido este año'],['benefitNet','Retorno neto realizado']],
 personal:[['personalReceivable','Me deben'],['personalPayable','Yo debo'],['personalNet','Posición personal neta'],['personalCount','Préstamos activos']],
 activity:[['income','Ingresos del mes'],['expense','Egresos del mes'],['net','Resultado neto del mes'],['subscriptions','Suscripciones activas'],['subscriptionsMonthly','Suscripciones / mes'],['upcoming30','Pagos próximos · 30 días']],
 wealth:[['registeredAssets','Activos registrados'],['registeredLiabilities','Pasivos registrados'],['registeredNet','Posición neta registrada']]
