 const body=`<div class="form-full form-section">EFECTIVO PERSONAL · DOS MONEDAS</div>
 ${formItem('openingDOP','Efectivo inicial en pesos · RD$',aD?.opening??0,'number','required min="0" step="0.01"')}
 ${formItem('openingUSD','Efectivo inicial en dólares · US$',aU?.opening??0,'number','required min="0" step="0.01"')}
 ${formItem('openedDOP','Fecha inicial del efectivo RD$',aD?.opened||today(),'date','required max="'+today()+'"')}
 ${formItem('openedUSD','Fecha inicial del efectivo US$',aU?.opened||today(),'date','required max="'+today()+'"')}
 ${para('Efectivo es permanente, independiente de cualquier banco y funciona en pesos y dólares. Modifica aquí únicamente el saldo de apertura: para registrar entradas o salidas, utiliza el Centro de operaciones. Cambiar un saldo inicial no crea ingresos ni gastos.')}`;
 modal(aD||aU?'Editar efectivo en RD$ y US$':'Registrar efectivo en RD$ y US$',body,'cashWalletForm',true);
