function widgetSize(id){const n=Number((db.settings.widgetSizes||{})[id]);return Number.isInteger(n)&&n>=1&&n<=4?n:(V317_FEATURE_GRAPHS.includes(id)?2:V105_WIDGETS.some(w=>w.id===id)?2:1)}
function widgetHeight(id){const n=Number((db.settings.widgetHeights||{})[id]);return Number.isFinite(n)&&n>=220&&n<=800?n:(id==='futureCalendar'?530:id==='futureCostKpi'?445:V317_FEATURE_GRAPHS.includes(id)?465:V105_WIDGETS.some(w=>w.id===id)?365:310)}




/* ━━━━━━━━━━━━━ vive el hoy · VALOR REAL / V12 ━━━━━━━━━━━━━ */
function v12Percent(now,previous,risk=false){
 const delta=now-previous,valid=Number.isFinite(previous)&&Math.abs(previous)>.005;
 if(!valid)return '<span class="v12-quiet">Sin base histórica</span>';
 const pct=delta/Math.abs(previous)*100;
 const cls=Math.abs(delta)<.005?'flat':(delta>=0?'good':'warn');
 return `<span class="v12-gap ${cls}" tabindex="0" data-chart-tip="Comparación vs. ${Number(ui.month.slice(0,4))-1}|Actual: ${money(now)}|Valor en ${Number(ui.month.slice(0,4))-1}: ${money(previous)}|Diferencia vs. ${Number(ui.month.slice(0,4))-1}: ${(delta>=0?'+':'')+money(delta)}|Diferencia: ${pct>0?'+':''}${pct.toFixed(1)}%"><small class="comparison-year">vs. ${Number(ui.month.slice(0,4))-1}</small>${comparisonInline(pct,delta)}</span>`;
}

function v12CardHistorical(c,cur,end){
 if((c.opened||today())>end)return 0;
 const opening=cur==='USD'?num(c.openingUSD):num(c.openingDOP);
 const change=db.transactions.filter(t=>t.cardId===c.id&&t.currency===cur&&t.date<=end).reduce((v,t)=>{
  const l=personalLoan(t.personalLoanId);
  const issue=t.type==='personal_issue',pay=t.type==='personal_settlement';
  const plus=['card_charge','card_advance'].includes(t.type)||(issue&&l?.direction==='lent')||(pay&&l?.direction==='borrowed');
  const minus=['card_payment','card_refund','card_reward'].includes(t.type)||(issue&&l?.direction==='borrowed')||(pay&&l?.direction==='lent');
  return v+(plus?num(t.amount):minus?-num(t.amount):0);
 },0);
 return Math.max(0,opening+change);
}

function v14HistoricalAvailable(date){
 const starts=[...db.accounts.map(x=>x.opened),...db.cards.map(x=>x.opened),...db.loans.map(x=>plusMonths(x.firstDue||today(),-1)),...db.certificates.map(x=>x.startDate),...db.personalLoans.map(x=>x.date),...db.transactions.map(x=>x.date)].filter(Boolean);
 return starts.some(x=>x<=date);
}
function v14ForecastBasis(){
 const now=dateObj(today()),prev=[];
 for(let step=3;step>=1;step--){const d=new Date(now.getFullYear(),now.getMonth()-step,1);prev.push({year:d.getFullYear(),month:d.getMonth()+1,...monthlyTotals(d.getFullYear(),d.getMonth()+1)});}
 const income=prev.reduce((a,x)=>a+num(x.income),0)/3,expense=prev.reduce((a,x)=>a+num(x.expense),0)/3;
 const sampleCount=prev.filter(x=>x.income||x.expense).length;
 return {income,expense,sampleCount,months:prev,baseNet:historicalPosition(today()).net};
}
function v14MonthlyScenario(model,scenario='base'){
 if(scenario==='conservative')return model.income*.9-model.expense*1.1;
 if(scenario==='optimistic')return model.income*1.1-model.expense*.9;
 return model.income-model.expense;
}

function v14ChartSvg(rows,defs){
 const W=960,H=320,L=103,R=25,T=26,B=53,plotH=H-T-B;
 const x=i=>L+i*(W-L-R)/Math.max(1,rows.length-1);
 const all=defs.flatMap(line=>line.values.filter(v=>v!==null&&Number.isFinite(v)));
 if(!all.length)return `<div class="empty">No hay historial suficiente para dibujar esta evolución.</div>`;
 const rawMax=Math.max(...all),rawMin=Math.min(...all);
 let roughSpan=rawMax-rawMin;
 if(roughSpan<1)roughSpan=Math.max(Math.abs(rawMax)*.22,100);
 const magnitude=10**Math.floor(Math.log10(roughSpan/4));
 const normalized=(roughSpan/4)/magnitude;
 let step=(normalized<=1?1:normalized<=2?2:normalized<=2.5?2.5:normalized<=5?5:10)*magnitude;
 let min=Math.floor((rawMin-roughSpan*.055)/step)*step;
 let max=Math.ceil((rawMax+roughSpan*.055)/step)*step;
 if(max<=min)max=min+step*4;
 let count=Math.round((max-min)/step);
 if(count>8){const widened=step*Math.ceil(count/5);min=Math.floor(min/widened)*widened;max=Math.ceil(max/widened)*widened;step=widened;count=Math.round((max-min)/step);}
 const y=value=>T+plotH*(max-value)/(max-min);
 const fmt=value=>{
  const abs=Math.abs(value),sign=value<0?'−':'';
  if(abs>=1e6)return sign+new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(abs/1e6)+'M';
  if(abs>=1e3)return sign+new Intl.NumberFormat('es-DO',{maximumFractionDigits:abs<1e4?1:0}).format(abs/1e3)+'K';
  return sign+new Intl.NumberFormat('es-DO',{maximumFractionDigits:0}).format(abs);
 };
 const ticks=Array.from({length:count+1},(_,i)=>min+step*i);
 const guides=ticks.map(v=>{const py=y(v);return `<line x1="${L}" x2="${W-R}" y1="${py.toFixed(1)}" y2="${py.toFixed(1)}" stroke="var(--border,#c8d6ea)" stroke-width="1" stroke-dasharray="4 7" opacity=".82"/><text x="${L-15}" y="${(py+4).toFixed(1)}" font-size="12" font-weight="650" fill="var(--muted,#7082a0)" text-anchor="end">${fmt(v)}</text>`}).join('');
 const segments=(values)=>{const sections=[];let section=[];values.forEach((v,i)=>{if(v===null||!Number.isFinite(v)){if(section.length)sections.push(section);section=[];}else section.push([x(i),y(v)]);});if(section.length)sections.push(section);return sections;};
 const smooth=coords=>coords.length===1?`M ${coords[0][0].toFixed(2)} ${coords[0][1].toFixed(2)}`:coords.reduce((d,point,i)=>{
  if(i===0)return `M ${point[0].toFixed(2)} ${point[1].toFixed(2)}`;
  const prev=coords[i-1];const midX=(prev[0]+point[0])/2,midY=(prev[1]+point[1])/2;
  return d+` Q ${prev[0].toFixed(2)} ${prev[1].toFixed(2)}, ${midX.toFixed(2)} ${midY.toFixed(2)}`+(i===coords.length-1?` T ${point[0].toFixed(2)} ${point[1].toFixed(2)}`:'');
 },'');
 const series=defs.map((line,index)=>{
  const drawn=segments(line.values).map(points=>`<path d="${smooth(points)}" fill="none" stroke="${line.color}" stroke-width="${line.width||3.6}" ${line.dash?'stroke-dasharray="8 7"':''} stroke-linecap="round" stroke-linejoin="round"/>`).join('');
  const dots=line.values.map((v,i)=>v===null||!Number.isFinite(v)?'':`<circle cx="${x(i).toFixed(2)}" cy="${y(v).toFixed(2)}" r="${line.dash?3.2:4.3}" fill="${line.color}" stroke="var(--panel,#fff)" stroke-width="2.3" tabindex="0" data-chart-tip="${sanitize(line.name)} · ${sanitize(rows[i])}|Patrimonio: ${money(v,'DOP',2)}"><title>${sanitize(line.name)} · ${sanitize(rows[i])}: ${money(v,'DOP',2)}</title></circle>`).join('');
  return drawn+dots;
 }).join('');
 return `<div class="v14-chart-scroll"><svg class="v14-timeline-svg v16-patrimony-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolución patrimonial por mes con escala de RD$ en el eje izquierdo"><text x="${L-15}" y="13" text-anchor="end" font-size="12" font-weight="750" fill="var(--muted,#7082a0)">RD$</text>${guides}${series}${rows.map((name,i)=>`<text x="${x(i).toFixed(2)}" y="${H-17}" text-anchor="middle" font-size="12" font-weight="650" fill="var(--muted,#7082a0)">${sanitize(name)}</text>`).join('')}</svg></div><div class="v14-chart-legend v16-chart-legend">${defs.map(line=>`<span><i style="background:${line.color};${line.dash?'outline:1px dashed #7abfb4;outline-offset:2px':''}"></i>${sanitize(line.name)}</span>`).join('')}</div>`;
}


/* Patrimonio: comparación histórica verdadera, no una simulación. */
function v23PatrimonyActualComparison(year=ui.year){
 const selected=Number(year),currentYear=Number(today().slice(0,4));
 const currentMonth=Number(today().slice(5,7));
 const labels=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
 const observed=(y,m)=>{
  const monthEnd=periodEnd(y,m);
  const cutoff=y===currentYear&&m===currentMonth?today():monthEnd;
  if(y>currentYear||(y===currentYear&&m>currentMonth)||!v14HistoricalAvailable(cutoff))return null;
  return historicalPosition(cutoff).net;
 };
 const previous=labels.map((_,i)=>observed(selected-1,i+1));
 const current=labels.map((_,i)=>observed(selected,i+1));
 return v14ChartSvg(labels,[
  {name:String(selected-1)+' · año anterior',color:'#93a9c7',values:previous,width:3.1},
  {name:String(selected)+' · registrado',color:'var(--v876-trend-main,#6366ef)',values:current,width:3.8}
 ]);
}
function patrimonyWorld(){
 const funds=totalLiquid(),cert=totalCertificates(),p=personalTotals(),cards=totalCardDebt(),loans=totalLoanDebt();
 const assets=funds+cert+p.receivable,liabilities=cards+loans+p.payable,net=assets-liabilities;
 const yoy=positionYearOverYear(),old=yoy.position||{},lastYear=ui.year-1;
 const model=v14ForecastBasis(),scenario=['base','conservative','optimistic'].includes(ui.forecastScenario)?ui.forecastScenario:'base';
 const delta=v14MonthlyScenario(model,scenario),canProject=model.sampleCount>0;
 const projected=canProject?rnd(net+delta*12):null;
 const difference=canProject?rnd(projected-net):null;
 const scenarioLabel=({base:'Base',conservative:'Conservador',optimistic:'Optimista'})[scenario];
 const tooltip=(title,amount,sub)=>` tabindex="0" data-chart-tip="${sanitize(title)}|Valor registrado: ${money(amount,'DOP',2)}|${sanitize(sub)}"`;
 const groups=[{name:'Cuentas y efectivo',value:funds,link:'accounts',icon:'wallet'},{name:'Certificados',value:cert,link:'certificates',icon:'analytics'},{name:'Préstamos por cobrar',value:p.receivable,link:'personal',icon:'up'}],owed=[{name:'Tarjetas de crédito',value:cards,link:'cards',icon:'card'},{name:'Préstamos bancarios',value:loans,link:'loans',icon:'receipt'},{name:'Préstamos entre personas',value:p.payable,link:'personal',icon:'wallet'}];
 const listed=(arr,heading)=>`<section class="panel v12-wealth-list"><div class="panel-head"><h3>${heading}</h3><span class="pill">${arr.length} componentes</span></div>${arr.map(item=>`<button class="v12-wealth-row" data-act="navigate" data-id="${item.link}"><span class="v12-row-icon">${icon(item.icon)}</span><span>${item.name}</span><b>${money(item.value)}</b>${icon('arrow')}</button>`).join('')}</section>`;
 const totalAll=Math.max(assets,liabilities,1),scenarioNote=`${scenarioLabel} · 12 meses`;
 return `<div class="v12-patrimony v14-patrimony v22-wealth">
  <header class="v12-wealth-hero v22-wealth-hero"><div><span class="summary-tag">vive el hoy / PATRIMONIO</span><h2>Lo que tienes. Lo que debes.<br><em>Lo que realmente es tuyo.</em></h2><p>Tu posición financiera y su evolución frente a ${lastYear}.</p></div></header>
  <div class="v12-wealth-metrics v22-wealth-metrics">
    <article class="v12-wealth-metric hero"><span>Patrimonio neto</span><strong${tooltip('Patrimonio neto',net,'Activos menos pasivos')}>${money(net)}</strong>${yoy.valid?v12Percent(net,old.net):`<small>Sin referencia de ${lastYear}</small>`}</article>
    <article class="v12-wealth-metric v22-forecast-kpi"><span>Patrimonio proyectado</span><strong tabindex="0" data-chart-tip="Estimación a 12 meses|${canProject?'Escenario: '+scenarioLabel:'Sin datos suficientes'}|${canProject?'Importe estimado: '+money(projected,'DOP',2):'Se requieren ingresos o gastos registrados en los últimos tres meses cerrados'}">${canProject?money(projected):'Sin datos'}</strong><small>${canProject?`12 meses · ${scenarioLabel} · ${signedCompactAmount(difference)} respecto a hoy`:'Necesita movimientos históricos'}</small></article>
  </div>
  <div class="v14-patrimony-main v22-wealth-main"><section class="panel v14-wealth-first v22-wealth-chart"><div class="panel-head"><div><h3>Evolución del patrimonio · ${ui.year} vs. ${lastYear}</h3><p>Patrimonio al cierre de cada mes · comparación entre ambos años</p></div><span class="pill">Valores en RD$</span></div>${v23PatrimonyActualComparison(ui.year)}<p class="footnote">La línea de ${lastYear} muestra los meses con historial disponible; la de ${ui.year} refleja solamente los cierres registrados. Sin valores futuros simulados.</p></section>
  <section class="panel v14-wealth-second v22-wealth-balance"><div class="panel-head"><h3>Balance de situación</h3><span class="pill">RD$ equivalente</span></div><div class="v12-balance-stack"><div class="v12-patrimony-line"><span>Activos</span><strong>${money(assets)}</strong></div><div class="v12-patrimony-track"><span style="width:${100*assets/totalAll}%"></span></div><div class="v12-patrimony-line"><span>Pasivos</span><strong>${money(liabilities)}</strong></div><div class="v12-patrimony-track debt"><span style="width:${100*liabilities/totalAll}%"></span></div><div class="v12-patrimony-net"><span>Patrimonio neto</span><strong>${money(net)}</strong></div></div><p class="footnote">Incluye los productos financieros registrados. No incluye bienes externos sin registrar.</p></section></div>
  <section class="v176-patrimony-readout" aria-label="Lectura estratégica del patrimonio"><div><small>POSICIÓN FINANCIERA REGISTRADA</small><h3>${net>=0?'Los activos registrados superan tus deudas':'Las obligaciones registradas superan tus activos'}</h3><p>${net>=0?'El saldo patrimonial neto es positivo.':'El saldo patrimonial neto es negativo.'} La liquidez en cuentas, los certificados y el dinero por cobrar se distinguen del capital adeudado. Los límites de crédito no se consideran activos.</p></div><button type="button" class="btn sm soft" data-act="navigate" data-id="banks">Explorar cada producto ${icon('arrow')}</button></section>
  <div class="grid columns equal section v14-patrimony-details">${listed(groups,'Composición de activos')}${listed(owed,'Composición de obligaciones')}</div>
 </div>`;
}
function annualSplitTables(){
 const y=ui.year,data=Array.from({length:12},(_,i)=>monthlyTotals(y,i+1)),hdr=['ENE','FEB','MAR','ABR','MAY','JUN','JUL','AGO','SEP','OCT','NOV','DIC'];
 const cells=(values)=>{let total=values.reduce((a,b)=>a+num(b),0);return `${values.map(v=>`<td class="num" title="${money(num(v))}">${v357AdvancedNumber(v)}</td>`).join('')}<td class="num v12-total" title="${money(total)}">${v357AdvancedNumber(total)}</td><td class="num" title="${money(total/12)}">${v357AdvancedNumber(total/12)}</td>`};
 const table=(kind)=>{
  const key=kind==='income'?'incomeBy':'expenseBy',subKey=kind==='income'?'incomeSubBy':'expenseSubBy';
  const names=[...new Set(data.flatMap(m=>Object.keys(m[key]||{})))].filter(cat=>data.some(m=>num(m[key]?.[cat])!==0)).sort((a,b)=>data.reduce((s,m)=>s+num(m[key]?.[b]),0)-data.reduce((s,m)=>s+num(m[key]?.[a]),0));
  const rows=names.map(cat=>{
   const subs=[...new Set(data.flatMap(m=>Object.keys(m[subKey]||{}).filter(v=>v.startsWith(cat+'||')).map(v=>v.split('||')[1])))];
   const expanded=!!ui.matrixExpanded?.[kind+':'+cat];
   const row=`<tr class="v12-split-main"><td class="v12-sticky">${subs.length?`<button type="button" class="matrix-expand" data-act="matrixCategory" data-kind="${kind}" data-cat="${sanitize(cat)}" aria-expanded="${expanded}"><span class="matrix-chevron">${expanded?'⌄':'›'}</span>${sanitize(cat)}</button>`:`<span>${sanitize(cat)}</span>`}</td>${cells(data.map(m=>m[key]?.[cat]||0))}</tr>`;
   return row+(expanded?subs.map(sub=>`<tr class="v12-split-sub"><td class="v12-sticky">↳ ${sanitize(sub)}</td>${cells(data.map(m=>m[subKey]?.[cat+'||'+sub]||0))}</tr>`).join(''):'');
  }).join('');
  const label=kind==='income'?'Ingresos':'Egresos',iconName=kind==='income'?'up':'down',vals=data.map(m=>m[kind]);
  return `<section class="panel v12-split-table v16-clean-table v16-${kind}"><div class="v12-split-head"><div><span class="summary-tag">${label.toUpperCase()} · ${y}</span><h3><span class="v19-table-trend v27-trend-${kind}" aria-hidden="true"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.15" stroke-linecap="round" stroke-linejoin="round">${kind==='income'?'<path d="m3 17 7-7 4 3 7-9"/><path d="M16 4h5v5"/>':'<path d="m3 6 7 7 4-3 7 9"/><path d="M16 19h5v-5"/>'}</svg></span>${label} por categoría <span class="v20-table-currency" title="Valores en pesos dominicanos" aria-label="Pesos dominicanos">RD$</span></h3><p>Pulsa una categoría para ver sus subcategorías · Valores expresados en RD$</p></div><strong class="v27-category-total v27-${kind}-total">${money(vals.reduce((a,b)=>a+b,0))}</strong></div><div class="v12-table-scroller v198-auto-category-scroll" tabindex="0" role="region" aria-label="Tabla anual de ${label.toLowerCase()} por categoría, valores compactos en K y M; selecciona cada cifra para conocer su importe completo"><table class="v12-year-table v198-category-year-table"><colgroup><col class="v198-category-col"/>${hdr.map(()=>'<col class="v198-month-col"/>').join('')}<col class="v198-total-col"/><col class="v198-average-col"/></colgroup><thead><tr><th class="v12-sticky">Categoría</th>${hdr.map(m=>`<th class="num">${m}</th>`).join('')}<th class="num">TOTAL</th><th class="num">PROM.</th></tr></thead><tbody>${rows||`<tr><td colspan="15" class="v14-empty-table">Sin ${label.toLowerCase()} registrados en ${y}.</td></tr>`}<tr class="v12-split-footer"><td class="v12-sticky">TOTAL ${label.toUpperCase()}</td>${cells(vals)}</tr></tbody></table></div></section>`;
 };
 return `<div class="v12-year-sections v14-year-sections">${table('income')}${table('expense')}</div>`;
}

function duplicateAlerts(){
 const key=t=>[t.date,t.type,t.currency||'DOP',num(t.amount).toFixed(2),t.accountId||'',t.cardId||'',(t.note||'').trim().toLocaleLowerCase('es')].join('|');
 const groups={};for(let t of db.transactions){if(['transfer','certificate_funding','certificate_redemption'].includes(t.type))continue;let id=key(t);(groups[id]??=[]).push(t)}
 const pairs=Object.values(groups).filter(list=>list.length>1),count=pairs.reduce((a,x)=>a+x.length,0);
 if(!pairs.length)return '';
 return `<aside class="v12-duplicate-warning panel" aria-label="Revisión de registros potencialmente repetidos"><span>${icon('receipt')}</span><div><strong>Revisa ${count} registros potencialmente repetidos</strong><p>Misma fecha, importe, producto y descripción. Pueden ser operaciones legítimas: revísalas antes de eliminar alguna.</p></div><button class="btn sm soft" data-act="movementTab" data-id="all">Abrir libro</button></aside>`;
}
