/* V117 · Etiquetas coherentes de las cuentas en TODOS los selectores móviles.
   Nunca cambia los identificadores, la moneda, los saldos ni las opciones disponibles. */
function v116AccountLabel(a){
 // Un formato único para web y móvil: sin banco, moneda ni nombre repetidos.
 const name=a.kind==='cash'?'Efectivo':String(a.name||'Cuenta').trim();
 return `${name} · ${money(getAccountBalance(a),a.currency,2)}`;
}
function sourceOptions(kind='account'){
 return kind==='card'?db.cards.filter(a=>!a.archived).map(a=>[a.id,`${a.name} · ${bankOf(a)} · RD$ / US$`]):db.accounts.filter(a=>!a.archived).map(a=>[a.id,v116AccountLabel(a)]);
}

/* V78 · registro verdaderamente móvil: tipo -> importe -> datos -> completar */
const MQR_MODES={
 income:{title:'Ingreso',hint:'Recibir',icon:'up'},
 spend:{title:'Gasto',hint:'Gastar',icon:'down'},
 transfer:{title:'Transferir',hint:'Mover dinero',icon:'wallet'}
};
const MQR_PRESETS={
 income:[['Salario y nómina','Nómina'],['Negocios y ventas','Ventas'],['Joseo e ingresos adicionales','Joseo']],
 spend:[['Alimentación','Comida'],['Transporte','Transporte'],['Servicios básicos','Servicios']]
};
function isMobileViewport(){return window.innerWidth<=790}
function mqrState(){
 if(!ui.mobileQuickRegister)ui.mobileQuickRegister={mode:'income',amount:'',preset:'Salario y nómina',transferKind:'own'};
 return ui.mobileQuickRegister;
}
function mqrAmountText(raw){
 const str=String(raw||'0'),parts=str.split('.');
 const v=(parts[0]||'0').replace(/^0+(?=\d)/,'').replace(/\B(?=(\d{3})+(?!\d))/g,',');
 return 'RD$ '+v+(parts.length>1?'.'+parts[1]:'');
}
function openMobileQuickRegister(mode='income',amount=''){
 const chosen=mode==='expense'?'spend':mode==='transfer'||mode==='outgoing'?'transfer':mode==='card_charge'?'spend':mode;
 const valid=MQR_MODES[chosen]?chosen:'income';
 ui.mobileQuickRegister={mode:valid,amount:String(amount||''),preset:MQR_PRESETS[valid]?.[0]?.[0]||'',transferKind:mode==='outgoing'?'outgoing':'own'};
 renderMobileQuickRegister();
}
function renderMobileQuickRegister(){
 const state=mqrState(),presets=MQR_PRESETS[state.mode]||[],isTransfer=state.mode==='transfer';
 const kinds=Object.entries(MQR_MODES).map(([id,c])=>`<button type="button" class="mqr-mode ${id===state.mode?'active':''}" data-mqr-act="mode" data-id="${id}" aria-pressed="${id===state.mode}"><span class="mqr-mode-icon">${icon(c.icon)}</span><strong>${c.title}</strong></button>`).join('');
 const sub=isTransfer?`<div class="mqr-transfer-kinds"><button type="button" class="${state.transferKind==='own'?'selected':''}" data-mqr-act="transferKind" data-id="own">Entre mis cuentas</button><button type="button" class="${state.transferKind==='outgoing'?'selected':''}" data-mqr-act="transferKind" data-id="outgoing">A terceros</button></div>`:'';
 const restCategory=state.mode==='income'?'ingreso':state.mode==='spend'?'gasto':null;
 const extra=restCategory?Object.keys(categoryMap(restCategory)).filter(k=>!presets.some(([id])=>id===k)):[];
 const chosenExtra=state.preset&&extra.includes(state.preset);
 const presetsHtml=presets.length?`<div class="mqr-presets">${presets.map(([k,t])=>`<button type="button" class="mqr-chip ${state.preset===k?'active':''}" data-mqr-act="preset" data-id="${sanitize(k)}">${t}</button>`).join('')}${chosenExtra?`<button type="button" class="mqr-chip active" data-mqr-act="moreCategories" aria-label="Elegir otra categoría">${sanitize(state.preset)}</button>`:`<button type="button" class="mqr-chip mqr-plus" data-mqr-act="moreCategories" aria-label="Más categorías">+</button>`}</div>`:'';
 const extraPanel=state.showCategories&&extra.length?`<div class="mqr-extra-categories" role="group" aria-label="Más categorías">${extra.map(k=>`<button type="button" class="mqr-extra-category ${state.preset===k?'active':''}" data-mqr-act="preset" data-id="${sanitize(k)}">${sanitize(k)}</button>`).join('')}</div>`:'';
 const keypad=['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(n=>`<button class="mqr-key ${n==='⌫'||n==='.'?'soft':''}" type="button" data-mqr-act="key" data-id="${n}" aria-label="${n==='⌫'?'Borrar último dígito':n}">${n}</button>`).join('');
 document.querySelectorAll('.v36-notifications[open]').forEach(el=>el.open=false);
 document.getElementById('modal-root').innerHTML=`<div class="modal-layer mqr-layer" data-backdrop="true"><section class="modal mqr-modal" role="dialog" aria-modal="true" aria-label="Registrar un movimiento"><header class="modal-head mqr-header"><h2>Nuevo movimiento</h2><button type="button" class="close" data-act="closeModal" aria-label="Cerrar">×</button></header><div class="mqr-scroll"><div class="mqr-shell"><div class="v141-quick-heading"><div class="mqr-step-caption">PASO 1 DE 3 · IMPORTE</div><details class="v141-quick-operations"><summary aria-label="Abrir más operaciones">Más operaciones <span aria-hidden="true">⌄</span></summary><div class="v141-quick-operations-menu" role="group" aria-label="Otros tipos de registro"><button type="button" data-act="guidedFlow" data-mode="service">${icon('receipt')}<span><strong>Pagar servicio</strong><small>Facturas y servicios</small></span>${icon('arrow')}</button><button type="button" data-act="guidedFlow" data-mode="cardpay">${icon('card')}<span><strong>Pagar tarjeta</strong><small>Corte, total o abono</small></span>${icon('arrow')}</button><button type="button" data-v354-act="open" data-v355="fast">${icon('users')}<span><strong>Movimiento rápido</strong><small>Compré para alguien · cuánto me dio</small></span>${icon('arrow')}</button></div></details></div><nav class="mqr-segment" aria-label="Qué deseas registrar">${kinds}</nav>${sub}<div class="mqr-display"><small>¿Cuánto ${state.mode==='income'?'recibiste':state.mode==='spend'?'gastaste':'vas a transferir'}?</small><strong id="mqrAmountValue" aria-live="polite">${mqrAmountText(state.amount)}</strong><span>Escribe el importe en el teclado</span></div>${state.mode==='spend'?'<div id="v80QuickAssessment" aria-live="polite"></div>':''}${presetsHtml}${extraPanel}<div class="mqr-keypad">${keypad}</div></div></div><footer class="mqr-bottom"><button class="mqr-primary" type="button" data-mqr-act="continue">Siguiente ${icon('arrow')}</button></footer></section></div>`;
 v80RefreshQuickAdvisor();
}
function mqrApplyKey(key){
 const st=mqrState(),current=String(st.amount||'');
 if(key==='⌫')st.amount=current.slice(0,-1);
 else if(key==='.') {if(!current.includes('.'))st.amount=(current||'0')+'.';}
 else if(/^\d$/.test(key)){
  const p=current.split('.');
  if((p.length===1||p[1].length<2)&&current.replace(/\D/g,'').length<10){st.amount=current==='0'?key:current+key;}
 }
 // Change only the number; don't rebuild the entire modal on every keystroke.
 const number=document.getElementById('mqrAmountValue');if(number)number.textContent=mqrAmountText(st.amount);
 v80RefreshQuickAdvisor();
}
/* V129 · Orden narrativo por operación, idéntico para la versión web y móvil.
   Solo reorganiza nodos del mismo formulario. Nunca recalcula importes ni crea registros. */
const V129_FIELD_ORDER=Object.freeze({
 income:['amount','category','subcategory','accountId','date','note','postingStatus','tags'],
 spend:['amount','category','subcategory','paymentSource','accountId','cardId','currency','paymentChannel','date','note','postingStatus','tags'],
 own:['amount','accountId','toAccountId','date','paymentChannel','fxRate','receiveMode','targetAmount','transferSpeed','note','postingStatus','tags'],
 outgoing:['amount','accountId','payee','date','paymentChannel','category','subcategory','transferSpeed','note','postingStatus','tags'],
 cardpay:['cardId','currency','accountId','cardPaymentMode','amount','date','paymentChannel','paymentFxRate','actualDebitMode','sourceAmount','note','postingStatus','tags']
});
function v129FieldName(el){
 if(!el||!el.querySelector)return '';
 return el.getAttribute('name')||el.querySelector('[name]')?.getAttribute('name')||'';
}
function v129ArrangeMobileDetails(container,mode){
 if(!container)return;
 const sequence=V129_FIELD_ORDER[mode]||V129_FIELD_ORDER.spend;
 const nodes=Array.from(container.children);
 const getPriority=el=>{
  if(el.classList.contains('mqr-detail-amount'))return -200;
  if(el.classList.contains('v80-advisor-slot'))return mode==='spend'?-90:80;
  if(el.id==='flowRoute')return mode==='own'?-55:80;
  if(el.id==='guidedReceipt')return 900;
  if(el.classList.contains('confirm-status'))return 950;
  if(el.matches('.flow-minor-details'))return 800;
  const name=v129FieldName(el);
  const order=sequence.indexOf(name);
  if(order>=0)return order*10;
  if(el.dataset.flowContext==='account'||el.dataset.flowContext==='card')return mode==='spend'?35:70;
  if(el.dataset.flowContext==='conversion')return 650;
  if(el.dataset.flowContext==='transferSpeedSection')return 700;
  if(el.classList.contains('flow-payment-preview'))return 600;
  return 750;
 };
 nodes.forEach((el,i)=>{el.style.setProperty('order',String(getPriority(el)*100+i),'important');});
 container.classList.add('v129-organized-details');
}
function v129OrderStudioFields(mode,steps){
 const order=V129_FIELD_ORDER[mode]||V129_FIELD_ORDER.own;
 steps.forEach((step,stepIndex)=>{
  const group=step.firstElementChild;
  const nodes=Array.from(group.children);
  nodes.sort((a,b)=>{
   const p=el=>{
    const n=v129FieldName(el),ix=order.indexOf(n);
    if(el.id==='flowRoute')return 28;
    if(el.classList.contains('flow-payment-preview'))return 800;
    if(el.matches('[data-segment="cardPaymentMode"]'))return 35;
    if(el.dataset.flowContext==='conversion')return 500;
    if(el.dataset.flowContext==='transferSpeedSection')return 520;
    return ix>=0?ix*10:700;
   };
   return p(a)-p(b);
  });
  nodes.forEach(el=>group.appendChild(el));
  group.dataset.v129Group=mode+'-'+(stepIndex+1);
 });
}

/* V134 · UX progresiva de registro: reutiliza los controles financieros originales.
   No modifica las reglas de contabilidad, Supabase ni la validación de datos. */
function v134NodeField(el){
 if(!el||el.nodeType!==1)return '';
 return el.getAttribute('name')||el.querySelector('[name]')?.getAttribute('name')||'';
}

function v134CreateGroup(title,subtitle,cls=''){
 const section=document.createElement('section');section.className='v134-section '+cls;
 section.innerHTML=`<header class="v134-section-heading"><strong>${title}</strong>${subtitle?`<small>${subtitle}</small>`:''}</header><div class="v134-group-fields"></div>`;
 return section;
}
function v134CreateMore(title){
 const details=document.createElement('details');details.className='v134-more';
 details.innerHTML=`<summary><span>${title}</span><span class="v134-more-chevron" aria-hidden="true">⌄</span></summary><div class="v134-more-body"></div>`;
 return details;
}
function v134ProgressiveMobileDetail(form,mode){
 const grid=form.querySelector(':scope > .form-grid');
 if(!grid||grid.classList.contains('v134-progressive-grid'))return;
 const nodes=[...grid.children];const used=new Set();
 const take=(predicate,dest)=>{
  for(const el of nodes){if(!used.has(el)&&predicate(el)){used.add(el);dest.appendChild(el)}}
 };
 const matches=(...names)=>(el)=>names.includes(v134NodeField(el));
 const block=(...keys)=>(el)=>keys.includes(el.dataset?.flowContext)||keys.includes(el.id)||keys.some(k=>el.classList?.contains(k));
 const heading=(el)=>el.classList?.contains('flow-section-heading')||el.classList?.contains('flow-hero');
 const hidden=(el)=>el.matches?.('input[type="hidden"]');
 const core=document.createDocumentFragment();
 const fields=document.createDocumentFragment();
 const choice=v134CreateGroup(mode==='income'?'Clasificación del ingreso':mode==='spend'?'¿En qué gastaste?':'Origen y destino',mode==='income'||mode==='spend'?'Categoría y subcategoría':'Cuentas y beneficiario','v134-choices');
 const source=v134CreateGroup(mode==='income'?'¿Dónde recibiste el dinero?':mode==='spend'?'¿Cómo pagaste?':'Movimiento entre cuentas',mode==='income'?'Elige tu cuenta de destino':mode==='spend'?'Selecciona cuenta o tarjeta':'Define de dónde sale y a dónde llega','v134-sources');
 const summary=v134CreateGroup('Resumen del movimiento','Revísalo antes de confirmar','v134-receipt');
 const more=v134CreateMore('Fecha, notas y opciones adicionales');
 const moreBody=more.querySelector('.v134-more-body');
 // Importe y, cuando corresponde, el indicador ya calculado de endeudamiento.
 take(el=>el.classList.contains('mqr-detail-amount'),core);
 take(el=>el.classList.contains('v80-advisor-slot'),core);
 // Etiquetas de ingreso/gasto o beneficiario de transferencia.
 if(mode==='income'||mode==='spend')take(matches('category','subcategory'),choice.querySelector('.v134-group-fields'));
 else take(matches('accountId','toAccountId','payee'),choice.querySelector('.v134-group-fields'));
 if(mode==='income')take(matches('accountId'),source.querySelector('.v134-group-fields'));
 else if(mode==='spend'){
  take(matches('paymentSource'),source.querySelector('.v134-group-fields'));
  take(block('account','card'),source.querySelector('.v134-group-fields'));
  take(matches('accountId','cardId','currency'),source.querySelector('.v134-group-fields'));
 } else {
  take(block('flowRoute'),source.querySelector('.v134-group-fields'));
  take(matches('accountId','toAccountId'),source.querySelector('.v134-group-fields'));
  take(block('transferSpeedSection'),source.querySelector('.v134-group-fields'));
  take(block('conversion'),source.querySelector('.v134-group-fields'));
 }
 // Mantener los resúmenes vivos; ninguna cifra se recalcula aquí.
 take(block('guidedReceipt','flow-payment-preview'),summary.querySelector('.v134-group-fields'));
 // Fechas editables, canales, notas, impuestos y estado: opcionales, sin perder valores.
 take(el=>hidden(el),moreBody);
 take(el=>heading(el),moreBody);
 take(el=>!used.has(el),moreBody);
 grid.replaceChildren(...core.childNodes);
 if(choice.querySelector('.v134-group-fields').childElementCount)grid.appendChild(choice);
 if(source.querySelector('.v134-group-fields').childElementCount)grid.appendChild(source);
 if(summary.querySelector('.v134-group-fields').childElementCount)grid.appendChild(summary);
 // Si hay campos obligatorios sin valor en extras, mostrarlos antes de guardar.
 if(moreBody.childElementCount)grid.appendChild(more);
 grid.classList.add('v134-progressive-grid');
 form.classList.add('v134-progressive-form');
 form.addEventListener('submit',ev=>{
  const invalid=[...form.elements].find(x=>x.willValidate&&!x.disabled&&!x.checkValidity());
  if(invalid&&more.contains(invalid))more.open=true;
 },true);
 // No ocultar los campos reales: se conservan por completo en el formulario.
}
function v134RefineExpress(f,mode){
 const grid=f.querySelector('.fastx-category-grid');const sec=f.querySelector('.fastx-category-section');
 if(!grid||!sec||sec.classList.contains('v134-express'))return;
 sec.classList.add('v134-express');
 const buttons=[...grid.querySelectorAll('button[data-fast-category]')];
 const extra=v134CreateMore('Todas las categorías');extra.classList.add('v134-category-more');
 const extraBody=extra.querySelector('.v134-more-body');
 buttons.slice(3).forEach(x=>extraBody.appendChild(x));
 const controls=sec.querySelector('.fastx-category-controls');
 const catLabel=controls?.querySelector('label:has([name="category"])');
 if(catLabel)extraBody.appendChild(catLabel);
 if(extraBody.childElementCount)grid.insertAdjacentElement('afterend',extra);
 // Fecha y canal tienen valores iniciales: disponibles sin ocupar la pantalla principal.
 const moreDetails=f.querySelector('.fastx-fold');
 const dateChannel=f.querySelector('.fastx-date-and-channel');
 const detailsBody=moreDetails?.querySelector('.fastx-fold-inner');
 if(!f.classList.contains('v700-express') && mode!=='income'&&dateChannel&&detailsBody)detailsBody.insertBefore(dateChannel,detailsBody.firstChild);
 const moreTitle=moreDetails?.querySelector('summary span:first-child');
 if(moreTitle)moreTitle.textContent=f.classList.contains('v700-express')?'Opciones adicionales · etiquetas y estado':mode==='income'?'Notas y opciones adicionales':'Fecha, notas y opciones adicionales';
 const selected=f.elements.category?.value;
 // Resaltar la categoría inicial sin abrir un catálogo voluminoso.
 const categoryTitle=extra.querySelector('summary span:first-child');
 const updateTitle=()=>{const value=f.elements.category?.value||'';if(categoryTitle)categoryTitle.textContent=value&&!buttons.slice(0,3).some(b=>b.dataset.fastCategory===value)?'Categoría · '+value:'Todas las categorías';};
 updateTitle();
 f.elements.category?.addEventListener('change',updateTitle);
 const amountInput=f.elements.amount;
 if(amountInput&&!amountInput.placeholder)amountInput.placeholder='0.00';
 // Mantener Subcategoría visible cuando el catálogo tenga opciones.
 const sublabel=controls?.querySelector('label:has([name="subcategory"])');
 if(sublabel&&controls)controls.appendChild(sublabel);
}
function v134RefineStudio(f,mode){
 if(!f||f.dataset.v134Studio==='yes')return;
 f.dataset.v134Studio='yes';f.classList.add('v134-studio-form');
 for(const step of f.querySelectorAll('.studio-step')){
  const container=step.querySelector('.studio-fields');if(!container)continue;
  const n=Number(step.dataset.step);
  const optional=[...container.children].filter(el=>{
   const name=v134NodeField(el);
   if(name==='paymentChannel'&&['cardpay','outgoing','own','service'].includes(mode))return false;
   if(['date','note','tags','postingStatus','paymentChannel'].includes(name))return true;
   if(el.classList.contains('flow-minor-details'))return true;
   if(el.classList.contains('confirm-status'))return true;
   return false;
  });
  if(!optional.length)continue;
  const fold=v134CreateMore(n===3?'Detalles del registro':'Fecha y opciones adicionales');
  fold.classList.add('v134-studio-more');const body=fold.querySelector('.v134-more-body');
  optional.forEach(x=>body.appendChild(x));container.appendChild(fold);
 }
 f.addEventListener('submit',()=>{
  for(const input of f.elements){
   if(!input.willValidate||input.disabled||input.checkValidity())continue;
   const details=input.closest('details.v134-more');if(details)details.open=true;
  }
 },true);
}

function mqrContinue(){
 const st=mqrState(),amount=Number(st.amount);
 if(!Number.isFinite(amount)||amount<=0){toast('Introduce un importe mayor que cero.');return;}
 const payload={amount,date:today()};
 if(st.mode==='income'){Object.assign(payload,{flowMode:'income',type:'income',category:st.preset||'Salario y nómina'});}
 else if(st.mode==='spend'){Object.assign(payload,{flowMode:'spend',type:'expense',category:st.preset||'Alimentación'});}
 else if(st.mode==='transfer'&&st.transferKind==='outgoing'){Object.assign(payload,{flowMode:'outgoing',type:'expense',paymentChannel:'internet_banking'});}
 else{Object.assign(payload,{flowMode:'own',type:'transfer'});}
 ui.mobileQuickInDetail=true;
 try{guidedTransactionForm(payload);}finally{ui.mobileQuickInDetail=false;}
 const f=document.getElementById('transactionForm');
 if(f){f.classList.add('mqr-detail-form');f.dataset.mqrMode=st.mode;
  const h=f.closest('.modal')?.querySelector('.modal-head');
  if(h){h.querySelector('h2').textContent='Completar '+(st.mode==='income'?'ingreso':st.mode==='spend'?'gasto':'transferencia');
  h.insertAdjacentHTML('afterbegin','<button type="button" class="mqr-back" data-mqr-act="back" aria-label="Volver al monto">←</button>');}
  const body=f.querySelector('.form-grid');
  if(body){
   body.insertAdjacentHTML('afterbegin',`<div class="mqr-detail-amount"><span>CONFIRMA LOS DETALLES</span><strong>${mqrAmountText(st.amount)}</strong><small>${st.mode==='income'?'Ingreso':st.mode==='spend'?'Gasto':st.transferKind==='outgoing'?'Transferencia a terceros':'Transferencia entre cuentas'}</small></div>`);
   // V101: el segundo paso prioriza categoría y capacidad, sin eliminar datos ni cambiar cálculos.
   // Mover nodos conserva valores, listeners y referencias del formulario original.
   const pick=(n)=>body.querySelector(`label:has([name="${n}"])`);
   const amount=pick('amount'),date=pick('date'),category=pick('category'),subcategory=pick('subcategory');
   for(const field of [date,amount,category,subcategory])if(field&&field.parentElement===body)field.classList.add('v101-inline-field');
   const afterAmount=amount&&amount.parentElement===body?amount:date;
   if(afterAmount&&category&&category.parentElement===body){
    afterAmount.after(category);
    if(subcategory&&subcategory.parentElement===body)category.after(subcategory);
   }
   const advisor=body.querySelector('.v80-advisor-slot');
   const last=body.querySelector('label:has([name="subcategory"])')||body.querySelector('label:has([name="category"])');
   if(advisor&&last&&last.parentElement===body)last.after(advisor);
   v129ArrangeMobileDetails(body, st.mode==='transfer'?(st.transferKind==='outgoing'?'outgoing':'own'):st.mode);
   v134ProgressiveMobileDetail(f,st.mode==='transfer'?(st.transferKind==='outgoing'?'outgoing':'own'):st.mode);
  }
 }
}
function flowPicker(){
 if(isMobileViewport()){openMobileQuickRegister();return}
 const groups=[{title:'RECIBIR',desc:'Entradas',modes:['income']},{title:'PAGAR',desc:'Salidas y obligaciones',modes:['spend','service','cardpay']},{title:'MOVER',desc:'Fondos y terceros',modes:['own','outgoing']}];
 const icons={income:'arrow-down-left',spend:'shopping-bag',service:'receipt',own:'repeat',outgoing:'send',cardpay:'credit-card'};
 modal('Nuevo movimiento',`<div class="vr-picker-head form-full"><span>✦ REGISTRO INTELIGENTE</span><h3>¿Qué vas a registrar?</h3><p>Elige la operación. Después te mostraré únicamente lo necesario.</p></div><div class="vr-picker-groups form-full">${groups.map(g=>`<section class="vr-picker-group"><div class="vr-picker-label">${g.title}<small>${g.desc}</small></div>${g.modes.map(mode=>`<button type="button" class="vr-picker-choice" data-act="guidedFlow" data-mode="${mode}"><span>${icon(icons[mode])}</span><span><strong>${FLOW_CATALOG[mode].name}</strong><small>${FLOW_CATALOG[mode].subtitle}</small></span>${icon('arrow')}</button>`).join('')}</section>`).join('')}</div>`,'operationPicker',true);
}
/* ================== ASISTENTE FINANCIERO CONTEXTUAL 4.0 ==================
  Efectivo RD$ + US$ permanente. Pago al instante: modalidad, NO comisión
  genérica. Impuesto bancario separado de la modalidad y de otros cargos.
  Solo hay cambio cuando las MONEDAS realmente son distintas.             */
const flowCurrencyLabel=c=>c==='USD'?'dólares · US$':'pesos · RD$';
// El medio de pago (cuenta, efectivo o tarjeta) NO es el canal.
// Se admiten códigos históricos al leer respaldos sin modificar registros antiguos.
const normalizePaymentChannel=c=>c==='presencial'||c==='efectivo'?'presencial':c==='internet_banking'||c==='web'||c==='debito'?'internet_banking':'';
const PAYMENT_CHANNEL_OPTIONS=[['internet_banking','Internet Banking'],['presencial','Presencial']];
const isBankPaymentSource=a=>Boolean(a&&a.kind!=='cash'&&!a.archived);
const isTaxableBankPayment=(a,channel,cardPurchase=false,ownTransfer=false)=>
 isBankPaymentSource(a)&&normalizePaymentChannel(channel)==='internet_banking'&&!cardPurchase&&!ownTransfer;
// V138 · Fuente única para pagos de tarjetas: tasa MANUAL guardada en Ajustes.
// Se respeta 0% si el usuario lo configura y no se infiere por la fecha del movimiento.
function cardPaymentSettingsTaxPct(){
 const raw=db.settings?.transferTaxPct, value=Number(raw);
 return raw!==undefined&&raw!==null&&raw!==''&&Number.isFinite(value)&&value>=0&&value<=100?value:0.20;
}

const flowRates=()=>Math.max(.0001,num(db.settings.fx)||60);
function flowWrap(key,html,extra=''){return `<div class="flow-context ${extra}" data-flow-context="${key}">${html}</div>`}
function flowSegment(name,choices,value){return `<div class="form-full flow-segment" data-segment="${name}">${choices.map(([id,title,desc])=>`<label class="flow-segment-option"><input type="radio" name="${name}" value="${id}" ${value===id?'checked':''}><span class="flow-segment-surface"><strong>${title}</strong><small>${desc}</small></span></label>`).join('')}</div>`}
function flowAmountField(label,amount){return formItem('amount',label,amount,'text','required inputmode="decimal" autocomplete="off" spellcheck="false" pattern="[0-9]+([.,][0-9]{1,2})?" id="flowAmount"')}
// V953: el importe acepta coma o punto. Se normaliza a punto (el formato que ya leen num()/los cálculos)
// y se mantiene la regla existente «mayor que cero» (antes min="0.01") con un mensaje junto al campo.
document.addEventListener('input',e=>{const f=e.target;if(f?.id!=='flowAmount')return;
 const clean=f.value.replace(/,/g,'.').replace(/[^0-9.]/g,'').replace(/(\..*)\./g,'$1');if(clean!==f.value)f.value=clean;
 f.setCustomValidity(f.value&&!(Number(f.value)>0)?'Introduce un importe mayor que cero.':'');},true);
document.addEventListener('invalid',e=>{const f=e.target;if(f?.id==='flowAmount'&&f.validity.valueMissing)f.setCustomValidity('Introduce el importe.');},true);
document.addEventListener('input',e=>{const f=e.target;if(f?.id==='flowAmount'&&f.validity.customError&&f.value&&Number(f.value)>0)f.setCustomValidity('');},true);
