 const hero=`<div class="form-full flow-hero flow-hero-v4 flow-hero-quick"><div class="flow-hero-body"><div class="flow-hero-glyph">${p.symbol}</div><div><span class="smart-kicker">${editing?'EDITAR OPERACIÓN':'REGISTRO RÁPIDO'}</span><h3>${p.name}</h3><p>${p.subtitle}</p></div></div></div>`;
 let body=hero+`<input type="hidden" name="type" value="${mode==='income'?'income':mode==='own'?'transfer':isPay?'card_payment':'expense'}"><input type="hidden" name="flowMode" value="${mode}">`;
