 // Mantener la barra nativa del navegador alineada con la apariencia existente.
 document.querySelector('meta[name="theme-color"]')?.setAttribute('content',db.settings.theme==='light'?'#f3f6fb':'#000000');
 document.body.classList.remove('vision-mode');
