(function(){
 const handlers={
 addCashWallet:el=>cashWalletForm(), editCashWallet:el=>cashWalletForm(),
 widgetEditor:()=>{if(!ui.widgetEditor){ui.widgetCatalogFilter='all';ui.widgetSearch=''}ui.widgetEditor=!ui.widgetEditor;render()},
  v197CompareMode:el=>{ui.v197CompareMode=el.dataset.id||'net';render()},
  widgetReferencePreset:()=>{const refs=['referenceBalance','referenceCredit','referenceCashflow','referenceComparison'];const old=widgetsState();const rest=old.filter(x=>!refs.includes(x));saveWidgets([...refs,...rest]);toast('Cuatro gráficos incorporados a tu tablero.');render()},
 widgetToggle:el=>{let list=widgetsState(),id=el.dataset.id;if(list.includes(id))list=list.filter(x=>x!==id);else list.push(id);saveWidgets(list);render()},
 widgetRemove:el=>{saveWidgets(widgetsState().filter(x=>x!==el.dataset.id));render()},
 widgetMoveUp:el=>{let list=widgetsState(),i=list.indexOf(el.dataset.id);if(i>0){[list[i-1],list[i]]=[list[i],list[i-1]];saveWidgets(list);render()}},
 widgetMoveDown:el=>{let list=widgetsState(),i=list.indexOf(el.dataset.id);if(i>=0&&i<list.length-1){[list[i+1],list[i]]=[list[i],list[i+1]];saveWidgets(list);render()}},
 widgetPreset:()=>{if(widgetsState().length&& !confirm('¿Vaciar tu tablero personal? Tus registros financieros no se eliminarán.'))return;saveWidgets([]);render()},
 widgetCatalogFilter:el=>{ui.widgetCatalogFilter=el.dataset.id||'all';render()},
 v332AddAll:()=>{saveWidgets(widgetCatalog().map(x=>x[0]));toast('Todos los elementos de Personalización están en el tablero.');render()},
 v332SyncOrder:()=>{const chosen=new Set(widgetsState());saveWidgets(widgetCatalog().map(x=>x[0]).filter(id=>chosen.has(id)));toast('Orden actualizado desde Personalización.');render()},
 widgetSize:el=>{db.settings.widgetSizes??={};let id=el.dataset.id;db.settings.widgetSizes[id]=widgetSize(id)>=2?1:2;persist();render()}
 };
 document.addEventListener('click',e=>{let b=e.target.closest?.('[data-act]');if(b&&handlers[b.dataset.act]){e.preventDefault();e.stopImmediatePropagation();handlers[b.dataset.act](b)}},true);
 let draggedWidget='';
 document.addEventListener('dragstart',e=>{const item=e.target.closest?.('.ws-tile[draggable="true"]');if(!item)return;draggedWidget=item.dataset.widget||'';e.dataTransfer?.setData('text/plain',draggedWidget);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';item.classList.add('ws-dragging')});
 document.addEventListener('dragover',e=>{const dest=e.target.closest?.('.ws-tile');if(!dest||!draggedWidget||dest.dataset.widget===draggedWidget)return;e.preventDefault();dest.classList.add('ws-drop-target')});
 document.addEventListener('dragleave',e=>e.target.closest?.('.ws-tile')?.classList.remove('ws-drop-target'));
 document.addEventListener('drop',e=>{let dest=e.target.closest?.('.ws-tile');if(!dest||!draggedWidget)return;e.preventDefault();const items=widgetsState(),src=items.indexOf(draggedWidget),dst=items.indexOf(dest.dataset.widget);if(src>=0&&dst>=0&&src!==dst){const [it]=items.splice(src,1);items.splice(dst,0,it);saveWidgets(items);render()}draggedWidget='';});
 document.addEventListener('dragend',()=>{draggedWidget='';document.querySelectorAll('.ws-drop-target,.ws-dragging').forEach(x=>x.classList.remove('ws-drop-target','ws-dragging'))});

 document.addEventListener('submit',e=>{if(e.target.id!=='cashWalletForm')return;e.preventDefault();e.stopImmediatePropagation();try{
  const v=Object.fromEntries(new FormData(e.target).entries());
  const vals=[['DOP',Number(v.openingDOP),v.openedDOP],['USD',Number(v.openingUSD),v.openedUSD]];
  if(vals.some(([c,amt,date])=>!Number.isFinite(amt)||amt<0||!date||date>today()))throw Error('Revisa los dos importes y sus fechas iniciales.');
  for(const [currency,amount,opened] of vals){
   const existing=db.accounts.find(a=>a.kind==='cash'&&a.currency===currency);
   if(existing){existing.opening=rnd(amount);existing.opened=opened;existing.bankId='';existing.bank='';existing.archived=false;existing.systemCash=true;}
   else db.accounts.push({...defaultCashAccounts().find(a=>a.currency===currency),opening:rnd(amount),opened});
  }
  persist();closeModal();ui.page='accounts';render();toast('Efectivo RD$ / US$ actualizado sin duplicar movimientos.');
 }catch(err){showError(err.message||'No se pudo guardar el efectivo.')}},true);

})();

(function(){
 const actions={
  manualBenefit:el=>manualBenefitForm(el.dataset.id,el.dataset.ccy||'DOP'),
  editManualBenefit:el=>manualBenefitForm(el.dataset.id,'DOP',el.dataset.entry),
  removeManualBenefit:el=>{const id=el.dataset.entry;const p=(db.perkUses||[]).find(x=>x.id===id&&x.cardId===el.dataset.id);if(!p||!confirm('¿Eliminar este beneficio registrado? No se modifican cuentas ni deudas.'))return;db.perkUses=db.perkUses.filter(x=>x.id!==id);persist();render();toast('Beneficio eliminado.');}
 };
 document.addEventListener('click',e=>{const btn=e.target.closest?.('[data-act]');if(!btn||!actions[btn.dataset.act])return;e.preventDefault();e.stopImmediatePropagation();actions[btn.dataset.act](btn)},true);
 document.addEventListener('change',e=>{const el=e.target;if(el?.name==='kind'&&el.form?.id==='manualBenefitForm'){el.form.dataset.kind=el.value;}},true);
 document.addEventListener('submit',e=>{
  const f=e.target;if(f?.id!=='manualBenefitForm')return;e.preventDefault();e.stopImmediatePropagation();
   const priorTransactions=db.transactions.slice(),priorPerks=(db.perkUses||[]).map(p=>({...p}));
   try{
   const v=Object.fromEntries(new FormData(f).entries());const c=card(v.cardId),amt=Number(v.amount),date=v.date;
   if(!c||c.archived||!['cashback','discount','points','other'].includes(v.kind)||!['DOP','USD'].includes(v.currency)||!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today()||!Number.isFinite(amt)||amt<0||!String(v.name||'').trim())throw Error('Revisa tipo, nombre, moneda, importe y fecha.');
   if(v.kind==='cashback'){
     if(db.transactions.some(t=>t.cardId===c.id&&['card_reward','bank_reward'].includes(t.type)&&t.date===date&&t.currency===v.currency&&Math.abs(num(t.amount)-rnd(amt))<.005&&String(t.note||'').startsWith(String(v.name||'').trim())))throw Error('Este cashback ya figura registrado para esta tarjeta. Revisa el historial antes de volver a guardarlo.');
     if(v.entryId)throw Error('Para cambiar el tipo de un beneficio existente, crea un registro nuevo.');
    if(amt<=0)throw Error('El cashback acreditado debe ser mayor que cero.');
    if(!['card','account'].includes(v.destination))throw Error('Selecciona a dónde llegó el cashback.');
    const a=v.destination==='account'?account(v.accountId):null;
    if(v.destination==='account'&&(!a||a.archived||a.currency!==v.currency))throw Error('Selecciona una cuenta activa de la misma moneda del cashback.');
    db.transactions.push({id:uuid(),created:new Date().toISOString(),type:v.destination==='account'?'bank_reward':'card_reward',cardId:c.id,accountId:a?.id||'',currency:v.currency,date,amount:rnd(amt),category:'Beneficios bancarios',subcategory:'Cashback acreditado',note:String(v.name||'Cashback recibido').trim().slice(0,85)+(v.note?' · '+String(v.note).trim().slice(0,120):'')});
   }else{
    const entry={id:v.entryId||uuid(),cardId:c.id,date,kind:v.kind,status:'received',name:String(v.name).trim().slice(0,85),currency:v.currency,value:rnd(amt),note:String(v.note||'').trim().slice(0,150)};
    const old=(db.perkUses||[]).find(x=>x.id===entry.id);
    if(old){if(old.cardId!==c.id)throw Error('El registro no pertenece a esta tarjeta.');Object.assign(old,entry)}else{db.perkUses??=[];db.perkUses.push(entry)}
   }
   if(!persist())throw Error('No se pudo preparar el guardado en Supabase. Revisa tu sesión y conexión antes de continuar.');closeModal();render();toast(v.kind==='cashback'?'Cashback incorporado; verifica su sincronización en Tarjetas.':'Beneficio incorporado a Tarjetas; verifica la sincronización.');
  }catch(err){db.transactions=priorTransactions;db.perkUses=priorPerks;showError(err.message||'No fue posible guardar el beneficio.');}
 },true);
})();

/* Menús internos V5. UX/UI exterior y navegación original conservadas literalmente. */
