/* Traza de cambios: participa solo cuando el almacenamiento existente persiste modificaciones. */
let v31AuditBaseline={};
function v31Tracked(){const parts={};for(const [key,collection] of [['tx',db.transactions],['accounts',db.accounts],['cards',db.cards],['loans',db.loans],['budgets',db.budgets],['recurring',db.recurring]]){const m={};for(const o of collection||[])if(o&&o.id)m[o.id]=JSON.stringify(o);parts[key]=m;}return parts}
v31AuditBaseline=v31Tracked();
function v31LogAudit(action,subject,description){const s=v31Ensure();s.audit.unshift({id:uuid(),at:new Date().toISOString(),action,subject:String(subject||''),description:String(description||'').slice(0,200)});if(s.audit.length>500)s.audit.length=500;}
function v31BeforePersist(){const s=v31Ensure(),now=v31Tracked(),events=[];for(const k of Object.keys(now)){const old=v31AuditBaseline[k]||{},cur=now[k]||{};for(const id of Object.keys(cur))if(!(id in old))events.push(['Creación',k,id]);else if(cur[id]!==old[id])events.push(['Modificación',k,id]);for(const id of Object.keys(old))if(!(id in cur))events.push(['Eliminación',k,id]);}if(events.length>35){v31LogAudit('Actualización masiva','Datos',events.length+' registros cambiaron. Revisar un punto de recuperación si no era esperado.')}else for(const [action,k,id] of events)v31LogAudit(action,k,id);v31AuditBaseline=now;}

/* Impacto bancario real por movimiento: no contabilizar dos veces capital, impuestos ni cargos. */
function v31BankImpact(t,a){if(!t||!a)return 0;if(t.type==='card_advance')return t.toAccountId===a.id?num(t.advanceNet):0;let v=num(t.amount),src=num(t.sourceAmount||t.amount),id=a.id,fee=num(t.paymentTax)+num(t.paymentFee);if(t.accountId===id){switch(t.type){case 'income':case 'bank_reward':return v;case 'adjustment':return v;case 'certificate_funding':return -v;case 'certificate_redemption':return v;case 'expense':return -(v+fee);case 'card_payment':case 'loan_payment':return -(src+fee);case 'transfer':return -(v+num(t.transferFee));case 'personal_issue':{let l=personalLoan(t.personalLoanId);return l?(l.direction==='borrowed'?v:-v):0;}case 'personal_settlement':{let l=personalLoan(t.personalLoanId);return l?(l.direction==='lent'?v:-v):0;}}}
 if(t.type==='transfer'&&t.toAccountId===id)return num(t.targetAmount||v);
 return 0;
}
function v31PossibleMatches(row,includeLinked=false){const a=account(row.accountId);if(!a)return [];
 let booked=new Set(v31Ensure().bankRows.filter(r=>r.status==='matched'&&r.id!==row.id).map(r=>r.txId));
 return db.transactions.map(t=>({t,impact:v31BankImpact(t,a)})).filter(x=>Math.abs(x.impact)>0.005&&Math.abs(x.impact-num(row.amount))<=.06&&Math.abs(v31Days(x.t.date,row.date))<=3&&(includeLinked||!booked.has(x.t.id))).sort((x,y)=>Math.abs(v31Days(x.t.date,row.date))-Math.abs(v31Days(y.t.date,row.date)));
}


function v31MatchDialog(rowId){const row=v31Ensure().bankRows.find(r=>r.id===rowId);if(!row)return;const a=account(row.accountId),matches=v31PossibleMatches(row,true).slice(0,30),opts=matches.map(({t,impact})=>[t.id,`${t.date} · ${v31Title(t)} · ${v31Fmt(impact,a.currency)}`]);modal('Conciliar movimiento',`<div class="form-full v31-form-note"><strong>${v31E(row.description)}</strong><p>${row.date} · ${v31Fmt(row.amount,row.currency)} · ${v31E(a?.name||'')}</p></div>${formSelect('txId','Movimiento en la aplicación',[['','Seleccionar coincidencia'],...opts],'','required')}${para('Vincular no cambia saldos ni crea transacciones. La coincidencia debe validarse contra el comprobante.')}`,'v31MatchForm');document.getElementById('v31MatchForm').dataset.rowId=row.id}
function v31ParseCSV(data){const text=String(data).replace(/^\uFEFF/,'');const first=(text.split(/\r?\n/).find(Boolean)||'');const delimiters=[';',',','\t'];const d=delimiters.map(d=>[d,(first.match(new RegExp(d==='\t'?'\\t':d===';'?';':',','g'))||[]).length]).sort((a,b)=>b[1]-a[1])[0][0];let rows=[],row=[],field='',quote=false;
 for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++;}else quote=!quote;}else if(c===d&&!quote){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';}else field+=c;}
 if(quote)throw Error('El CSV tiene comillas sin cerrar.');row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows;
}
function v31NormalizeHeader(h){return String(h||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ' ).trim()}
function v31Num(s){let x=String(s??'').trim().replace(/(?:rd\$|us\$|usd|dop|\$)/gi,'').replace(/\s/g,'');if(!x)return 0;let neg=x.includes('(')||x.startsWith('-');x=x.replace(/[()−-]/g,'');let comma=x.lastIndexOf(','),dot=x.lastIndexOf('.');if(comma>=0&&dot>=0){if(comma>dot)x=x.replace(/\./g,'').replace(',','.');else x=x.replace(/,/g,'');}else if(comma>=0){let digits=x.length-comma-1;x=digits===3?x.replace(/,/g,''):x.replace(',','.');}else if(dot>=0&&x.length-dot-1===3&&/^\d{1,3}(\.\d{3})+$/.test(x))x=x.replace(/\./g,'');let n=Number(x);if(!Number.isFinite(n))throw Error('Importe no válido: '+s);return neg?-n:n}
function v31NormalizeDate(value){let s=String(value||'').trim();if(/^\d{4}-\d\d-\d\d/.test(s))return s.slice(0,10);let d=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})$/);if(d){let year=Number(d[3]);if(year<100)year+=2000;let a=Number(d[1]),b=Number(d[2]);const month=a>12?b:b>12?a:b,day=a>12?a:b>12?b:a;let out=`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;if(!Number.isNaN(dateObj(out).getTime()))return out;}let serial=Number(s);if(Number.isFinite(serial)&&serial>30000&&serial<90000)return new Date(Date.UTC(1899,11,30)+serial*86400000).toISOString().slice(0,10);return ''}
function v31RowsFromMatrix(matrix,accountId){const ac=account(accountId);if(!ac)throw Error('Selecciona una cuenta bancaria.');if(matrix.length<2)throw Error('El archivo no tiene filas de datos.');const headers=matrix[0].map(v31NormalizeHeader);const col=(patterns)=>headers.findIndex(h=>patterns.some(x=>h===x||h.includes(x)));
 const date=col(['fecha','date','posting date','transaction date']),desc=col(['descripcion','concepto','detalle','description','merchant','comercio','referencia']),amount=col(['importe','monto','amount','valor','total']),debit=col(['debito','cargo','debe','withdrawal']),credit=col(['credito','abono','haber','deposit']);if(date<0||desc<0||(amount<0&&debit<0&&credit<0))throw Error('Columnas requeridas: fecha, descripción y monto (o débito/crédito).');
 const out=[];for(const row of matrix.slice(1)){let raw=row[date],dt=v31NormalizeDate(raw),description=String(row[desc]||'').trim();if(!dt||!description)continue;let v=0;if(debit>=0||credit>=0){v=v31Num(row[credit]||0)-Math.abs(v31Num(row[debit]||0));}else v=v31Num(row[amount]);if(Math.abs(v)<.005)continue;out.push({id:uuid(),accountId,description:description.slice(0,160),date:dt,amount:rnd(v),currency:ac.currency,status:'pending',txId:'',created:new Date().toISOString()});}return out;
}
/* Lectura XLSX local: ZIP Office Open XML, sin servicios externos. */
async function v31UnzipXml(file){const buffer=await file.arrayBuffer(),dv=new DataView(buffer),bytes=new Uint8Array(buffer);let eocd=-1;for(let p=bytes.length-22;p>=Math.max(0,bytes.length-65558);p--)if(dv.getUint32(p,true)===0x06054b50){eocd=p;break;}if(eocd<0)throw Error('El archivo XLSX no es un ZIP válido.');const count=dv.getUint16(eocd+10,true),offset=dv.getUint32(eocd+16,true);let p=offset,entries={};for(let i=0;i<count;i++){if(dv.getUint32(p,true)!==0x02014b50)throw Error('Estructura XLSX no reconocida.');let method=dv.getUint16(p+10,true),csize=dv.getUint32(p+20,true),nlen=dv.getUint16(p+28,true),elen=dv.getUint16(p+30,true),clen=dv.getUint16(p+32,true),local=dv.getUint32(p+42,true);let name=new TextDecoder().decode(bytes.slice(p+46,p+46+nlen));if(name.endsWith('.xml')||name.endsWith('.rels'))entries[name]={method,csize,local};p+=46+nlen+elen+clen;}
 async function get(name){let e=entries[name];if(!e)return '';let pos=e.local;let nlen=dv.getUint16(pos+26,true),elen=dv.getUint16(pos+28,true),start=pos+30+nlen+elen;let compressed=bytes.slice(start,start+e.csize);if(e.method===0)return new TextDecoder().decode(compressed);if(e.method!==8||typeof DecompressionStream==='undefined')throw Error('Este navegador no admite la compresión XLSX. Guarda el Excel como CSV.');let stream=new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return await new Response(stream).text()}
 const shares=await get('xl/sharedStrings.xml'),sharedDoc=new DOMParser().parseFromString(shares||'<sst/>','text/xml'),shared=[...sharedDoc.getElementsByTagName('si')].map(node=>[...node.getElementsByTagName('t')].map(x=>x.textContent||'').join(''));
 let sheet=await get('xl/worksheets/sheet1.xml');if(!sheet){let paths=Object.keys(entries).filter(n=>/^xl\/worksheets\/sheet\d+\.xml$/.test(n));if(paths.length)sheet=await get(paths[0]);}if(!sheet)throw Error('El Excel no tiene una primera hoja reconocible.');const doc=new DOMParser().parseFromString(sheet,'text/xml'),rows=[];for(let r of doc.getElementsByTagName('row')){let out=[];for(let c of r.getElementsByTagName('c')){const ref=c.getAttribute('r')||'A1',letters=(ref.match(/[A-Z]+/)||[])[0]||'A';let idx=0;for(const letter of letters)idx=idx*26+letter.charCodeAt(0)-64;idx--;let val=c.getElementsByTagName('v')[0]?.textContent||'',type=c.getAttribute('t');if(type==='s')val=shared[Number(val)]||'';else if(type==='inlineStr')val=[...c.getElementsByTagName('t')].map(x=>x.textContent||'').join('');out[idx]=val;}rows.push(out);}return rows;
}
async function v31ImportBankFile(file){if(!file)return;const accountId=ui.v31Account;if(!account(accountId)){toast('Selecciona la cuenta que corresponde al extracto.');return}try{if(file.size>12*1024*1024)throw Error('El extracto excede 12 MB.');let mat=file.name.toLowerCase().endsWith('.xlsx')?await v31UnzipXml(file):v31ParseCSV(await file.text());let incoming=v31RowsFromMatrix(mat,accountId),s=v31Ensure(),known=new Set(s.bankRows.map(r=>[r.accountId,r.date,r.description.toLowerCase(),r.amount].join('|'))),added=0;for(let r of incoming){let key=[r.accountId,r.date,r.description.toLowerCase(),r.amount].join('|');if(!known.has(key)){s.bankRows.push(r);known.add(key);added++}}v31LogAudit('Importación de extracto','Conciliación',file.name+' · '+added+' filas nuevas');persist();render();toast(`Extracto leído: ${added} movimientos nuevos; ${incoming.length-added} repetidos omitidos.`)}catch(e){toast('No se pudo importar: '+e.message)}}
function v31AutoMatch(){let assigned=0;const s=v31Ensure();for(const row of s.bankRows.filter(x=>x.status==='pending')){let candidates=v31PossibleMatches(row);if(candidates.length===1){row.status='matched';row.txId=candidates[0].t.id;candidates[0].t.reviewed=true;assigned++;}}v31LogAudit('Conciliación automática','Extractos',assigned+' coincidencias únicas');persist();render();toast(`${assigned} coincidencias únicas vinculadas. Revisa el resultado.`)}
function v31ReconcileAction(action,id){const s=v31Ensure(),r=s.bankRows.find(x=>x.id===id);if(!r)return;switch(action){case 'v31Ignore':r.status='ignored';r.txId='';break;case 'v31Unmatch':r.status='pending';r.txId='';break;case 'v31PostBank':if(!confirm('El importe del extracto puede incluir impuesto y cargos. Revisa y separa el principal y los costos antes de guardar; después vuelve a conciliar.'))return;transactionForm({type:r.amount>=0?'income':'expense',accountId:r.accountId,date:r.date,amount:Math.abs(r.amount),note:r.description,category:r.amount>=0?'Otros ingresos':'Otros gastos'});return;}v31LogAudit('Revisión de extracto','Movimiento bancario',r.description+' · '+r.status);persist();render()}









const V31_DOCS_DB='vive-el-hoy-360-comprobantes';
function v31OpenDocs(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(Error('Este navegador no ofrece almacenamiento documental.'));let req=indexedDB.open(V31_DOCS_DB,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('files'))req.result.createObjectStore('files',{keyPath:'id'})};req.onerror=()=>reject(req.error||Error('No se pudo abrir la base documental.'));req.onsuccess=()=>resolve(req.result);});}
const V31_DOC_FALLBACK='vivehoy360.doc.';
async function v31PutDoc(id,blob){try{let dbi=await v31OpenDocs();return await new Promise((resolve,reject)=>{let tr=dbi.transaction('files','readwrite'),req=tr.objectStore('files').put({id,blob});tr.oncomplete=()=>{dbi.close();resolve(true)};tr.onerror=()=>{dbi.close();reject(tr.error)};req.onerror=()=>reject(req.error)});}catch(err){if(blob.size>512*1024)throw Error('El navegador no permite guardar este comprobante en IndexedDB. Para documentos de más de 512 KB utiliza un navegador que permita almacenamiento local.');let data=v31DataString(await blob.arrayBuffer());localStorage.setItem(V31_DOC_FALLBACK+id,JSON.stringify({type:blob.type,data}));return true;}}
async function v31GetDoc(id){try{let dbi=await v31OpenDocs();let blob=await new Promise((resolve,reject)=>{let tr=dbi.transaction('files','readonly'),req=tr.objectStore('files').get(id);req.onsuccess=()=>{dbi.close();resolve(req.result?.blob||null)};req.onerror=()=>{dbi.close();reject(req.error)}});if(blob)return blob;}catch(err){}let raw=localStorage.getItem(V31_DOC_FALLBACK+id);if(!raw)return null;let item=JSON.parse(raw);return new Blob([v31FromB64(item.data)],{type:item.type||'application/octet-stream'});}
async function v31DeleteDoc(id){try{let dbi=await v31OpenDocs();await new Promise((resolve,reject)=>{let tr=dbi.transaction('files','readwrite'),req=tr.objectStore('files').delete(id);tr.oncomplete=()=>{dbi.close();resolve()};tr.onerror=()=>{dbi.close();reject(tr.error)}});}catch(err){}localStorage.removeItem(V31_DOC_FALLBACK+id);}
function v31DataString(bytes){const u=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);let chunks=[];for(let i=0;i<u.length;i+=16384)chunks.push(String.fromCharCode(...u.subarray(i,i+16384)));return btoa(chunks.join(''))}
function v31FromB64(input){let txt=atob(String(input)),out=new Uint8Array(txt.length);for(let i=0;i<out.length;i++)out[i]=txt.charCodeAt(i);return out}
async function v31Sha(blob){if(!crypto?.subtle)return '';return [...new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('')}

async function v31SaveReceipt(form){try{const file=form.elements.file.files[0],txId=form.elements.txId.value,title=String(form.elements.title.value||'').trim();if(!file||!db.transactions.some(t=>t.id===txId))throw Error('Selecciona un movimiento existente y un archivo.');if(file.size>8*1024*1024)throw Error('Máximo 8 MB por comprobante.');if(!/\.(pdf|png|jpe?g|webp|txt)$/i.test(file.name))throw Error('Tipo de archivo no permitido.');if(!['application/pdf','image/jpeg','image/png','image/webp','text/plain',''].includes(file.type))throw Error('Formato de archivo no admitido.');const id=uuid(),sha=await v31Sha(file);await v31PutDoc(id,file);v31Ensure().docs.push({id,txId,title,filename:file.name,size:file.size,mime:file.type||'application/octet-stream',sha,date:new Date().toISOString()});v31LogAudit('Adjunto','Comprobante',title);if(!persist()){v31Ensure().docs=v31Ensure().docs.filter(x=>x.id!==id);await v31DeleteDoc(id);throw Error('Almacenamiento insuficiente para guardar los metadatos.');}render();toast('Comprobante asociado al movimiento.')}catch(e){toast('No se pudo adjuntar: '+e.message)}}
async function v31OpenReceipt(id){try{const meta=v31Ensure().docs.find(x=>x.id===id);if(!meta)throw Error('Comprobante no encontrado.');const blob=await v31GetDoc(id);if(!blob)throw Error('El archivo no está en este navegador. Restaura un respaldo que incluya comprobantes.');if(meta.sha&&await v31Sha(blob)!==meta.sha)throw Error('El archivo no supera la verificación de integridad.');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=meta.filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(e){toast(e.message)}}
async function v31RemoveReceipt(id){let meta=v31Ensure().docs.find(x=>x.id===id);if(!meta||!confirm('¿Eliminar este comprobante? Esta acción no modifica el movimiento asociado.'))return;try{await v31DeleteDoc(id);v31Ensure().docs=v31Ensure().docs.filter(x=>x.id!==id);v31LogAudit('Eliminación','Comprobante',meta.title);persist();render();toast('Comprobante eliminado.')}catch(e){toast('No pudo eliminarse el archivo: '+e.message)}}

function v31CipherForm(mode){modal(mode==='export'?'Crear respaldo cifrado':'Restaurar respaldo cifrado',`<div class="form-full v31-form-note"><strong>Contraseña de protección</strong><p>Mínimo 10 caracteres. No la guardes en una nota pública; si la pierdes, no será posible descifrar el respaldo.</p></div>${mode==='import'?`<label class="form-full"><span class="filter-label">Archivo cifrado V31</span><input type="file" class="field" name="file" required accept=".v360,.json,application/json"></label>`:''}${formItem('password','Contraseña','','password','required minlength="10" autocomplete="new-password"')}${mode==='export'?formItem('confirmPassword','Repetir contraseña','','password','required minlength="10" autocomplete="new-password"'):''}<p class="form-full v31-note">${mode==='export'?'Se guardarán tus productos, movimientos y adjuntos que estén disponibles en este dispositivo.':'Se creará un punto de recuperación antes de sustituir la información. Comprueba que el archivo proviene de una fuente confiable.'}</p>`,mode==='export'?'v31EncryptedExportForm':'v31EncryptedImportForm',true)}
function v31SecureSupported(){if(!crypto||!crypto.subtle||!crypto.getRandomValues)throw Error('El navegador no ofrece criptografía segura en este contexto. Abre la aplicación en un navegador actualizado.')}
async function v31AesKey(password,salt){let material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function v31Bundle(){const files=[],docs=v31Ensure().docs;let total=0;for(const meta of docs){const blob=await v31GetDoc(meta.id);if(!blob)continue;total+=blob.size;if(total>28*1024*1024)throw Error('Los comprobantes exceden 28 MB. Exporta los documentos por separado antes de continuar.');files.push({id:meta.id,mime:blob.type,bytes:v31DataString(await blob.arrayBuffer())})}return {format:'vivehoy360-bundle-v31',at:new Date().toISOString(),finance:db,files}}
async function v31CreateEncrypted(form){try{v31SecureSupported();const pwd=String(form.elements.password.value),conf=String(form.elements.confirmPassword.value);if(pwd.length<10||pwd!==conf)throw Error('Las contraseñas no coinciden o son demasiado cortas.');let payload=await v31Bundle(),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await v31AesKey(pwd,salt);let content=new TextEncoder().encode(JSON.stringify(payload)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,content),output={format:'vivehoy360-encrypted-v1',kdf:'PBKDF2-SHA256',iterations:310000,cipher:'AES-256-GCM',salt:v31DataString(salt),iv:v31DataString(iv),data:v31DataString(cipher)};download(JSON.stringify(output),`vive-el-hoy-seguro-${today()}.v360`,'application/json');closeModal();toast('Respaldo cifrado creado. Conserva la contraseña en un lugar seguro.')}catch(e){toast('No se pudo cifrar: '+e.message)}}
async function v31RestoreEncrypted(form){try{v31SecureSupported();let file=form.elements.file.files[0],password=String(form.elements.password.value);if(!file)throw Error('Selecciona el archivo cifrado.');if(file.size>48*1024*1024)throw Error('El archivo supera el límite de 48 MB.');let o=JSON.parse(await file.text());if(o.format!=='vivehoy360-encrypted-v1'||o.cipher!=='AES-256-GCM'||o.iterations!==310000)throw Error('Formato cifrado no reconocido.');let key=await v31AesKey(password,v31FromB64(o.salt)),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:v31FromB64(o.iv)},key,v31FromB64(o.data));let pack=JSON.parse(new TextDecoder().decode(plain));if(pack.format!=='vivehoy360-bundle-v31')throw Error('Contenido cifrado inválido.');v30ValidateImport(pack.finance);if(!confirm('Este respaldo REEMPLAZARÁ los datos financieros actuales. ¿Confirmar?'))return;if(!v30SavePoint('Antes de restaurar respaldo cifrado V31'))throw Error('No se pudo crear el punto de recuperación. Exporta primero un JSON.');const before=db;try{db=migrateData({...init(),...pack.finance,settings:{...init().settings,...(pack.finance.settings||{})}});v31Ensure();if(!persist())throw Error('No se pudo guardar el respaldo restaurado.');for(const d of pack.files||[]){if(!d.id||!d.bytes)continue;let blob=new Blob([v31FromB64(d.bytes)],{type:d.mime||'application/octet-stream'});await v31PutDoc(d.id,blob);}v31AuditBaseline=v31Tracked();v31LogAudit('Restauración','Respaldo cifrado',file.name);persist();closeModal();ui.page='settings';ui.v32Tools.settings='audit';render();toast('Respaldo descifrado y restaurado. Verifica documentos y saldos.')}catch(e){db=before;persist();throw e;}}
 catch(e){toast('No se pudo restaurar (contraseña o archivo): '+e.message)}}
