 if(typeof f33Active==='undefined'||!f33Active){mode='pending';}
 else if(!navigator.onLine){mode='error';}
 else if(f33Conflict||v10ManualConflict){mode='error';}
 else if(f33Dirty||f33Saving){mode=f33Saving?'syncing':'pending';}
 else if(v402Busy){mode='syncing';}
 else if(f34SyncState==='error'&&f33Dirty){mode='error';}
 else if(f34SyncState==='saving'){mode='syncing';}
 if(mode==='synced'&&(!v402Realtime||v403GetAppleQueue().length))mode='pending';
 document.querySelectorAll('[data-v402-sync]').forEach(el=>{
  el.dataset.status=mode;
  const label=mode==='synced'?'Sincronizado con Supabase':mode==='syncing'?'Sincronizando con Supabase':mode==='error'?'No se pudo sincronizar':'Comprobar sincronización';
  el.title=label+' · tocar para actualizar';el.setAttribute('aria-label',label+', tocar para actualizar');
  el.setAttribute('aria-busy',String(mode==='syncing'));
 });
