  const subEl=[...document.querySelectorAll('.topbar-intro .top-sub')].find(e=>{const b=e.getBoundingClientRect();return b.width>8&&b.height>6});
  let dst2=[];const subPrev=subEl&&subEl.style.opacity!=='0'?subEl.style.opacity:'';
  let subPts=[];
