  if(Array.isArray(data)){
   data.forEach((value,i)=>result.set(collection+'\u0000'+v405Id(value,i),{collection,id:v405Id(value,i),position:i,data:value}));
  }else result.set(collection+'\u0000__root__',{collection,id:'__root__',position:0,data});
