 if(!bank(v.institutionId)||!v.name?.trim()||num(v.value)<0||v.validUntil&&v.validUntil<v.validFrom)throw Error('Indica institución, nombre y fechas válidas.');
 const entry={id:id||uuid(),institutionId:v.institutionId,name:v.name.trim().slice(0,90),kind:v.kind,monetary:v.monetary==='true',value:rnd(v.value),currency:v.currency,validFrom:v.validFrom,validUntil:v.validUntil||'',notes:(v.notes||'').slice(0,160),active:prev?.active!==false};
