function deletePersonalLoan(id){
 const l=personalLoan(id);if(!l)return;
 const related=db.transactions.filter(t=>t.personalLoanId===id&&['personal_issue','personal_settlement'].includes(t.type));
 const question='¿Eliminar definitivamente el acuerdo «'+loanCategory(l)+'» con '+(contactFor(l)?fullName(contactFor(l)):l.person)+'? Se quitarán exclusivamente sus '+related.length+' entregas/abonos vinculados y se recalcularán los saldos bancarios, deudas e indicadores. Los demás acuerdos y movimientos permanecerán intactos. Se guardará un punto de recuperación.';
 if(!confirm(question))return;
 try{
  v233PersonalMutation('Eliminar acuerdo · '+loanCategory(l),()=>{
   v403RegisterDeletedTransactions(related);
   db.personalLoans=db.personalLoans.filter(x=>x.id!==id);
   db.transactions=db.transactions.filter(t=>!(t.personalLoanId===id&&['personal_issue','personal_settlement'].includes(t.type)));
   db.pendingOperations=(db.pendingOperations||[]).filter(o=>o.values?.personalLoanId!==id);
   db.deletedMovements=(db.deletedMovements||[]).filter(o=>o.tx?.personalLoanId!==id);
  });
  ui.v56LoanId='';ui.v56ContactId=l.contactId||'';render();toast('Acuerdo y movimientos vinculados eliminados; saldos recalculados.');
 }catch(err){showError(err.message||'No se pudo eliminar el acuerdo.');}
}
