 const footnav=oldActions.cloneNode(false);oldActions.replaceWith(footnav);footnav.classList.add('v87-nav');
 const modalBox=form.closest('.modal');if(modalBox)modalBox.classList.add('v87-loan-dialog');
 const footer=form.querySelector('.form-foot');const submit=footer?.querySelector('[type="submit"]');
 if(submit)submit.innerHTML=`${icon('check')} Guardar préstamo`;
 const footerBack=footer?.querySelector('.btn.ghost');
