 // 01 — Identificación, tasa y cobertura. El seguro siempre se ve desde el principio.
 append(panels[0],stepIntro('01 / 03','CONDICIONES DEL CONTRATO','Primero, las condiciones.','Indica con quién tienes el préstamo, el interés y si incluye seguro.'));
 const identity=section('01','Identificación','Los datos para reconocer correctamente el contrato.');
 append(identity,row(name,bank),row(currency,acquired));append(panels[0],identity);
 const interest=section('02','Tasa de interés','La tasa anual es parte fundamental del contrato.');
 if(rate?.querySelector('.filter-label'))rate.querySelector('.filter-label').textContent='Tasa anual pactada (%)';
 if(currentRate?.querySelector('.filter-label'))currentRate.querySelector('.filter-label').textContent='Tasa anual vigente (%)';
 // Una única tasa contractual visible; los campos heredados se mantienen ocultos para compatibilidad.
 const rateLegacy=node('div','v94-hidden-legacy');rateLegacy.hidden=true;
 append(rateLegacy,currentRate,rateEffective);
 append(interest,row(rateType,rate),rateLegacy);append(panels[0],interest);
 const coverage=section('03','Seguro del préstamo','Primero confirma si el contrato incluye una cobertura.');
 if(!previous&&form.elements.insuranceKind){form.elements.insuranceKind.value='none';form.elements.insuranceMonthly.value='0'}
 const coverageCallout=node('div','v87-inline-note','El seguro y los cargos se añaden a cada pago según su periodicidad; no aumentan el capital original.');
 const extraCosts=node('details','v87-optional-costs',`<summary>¿Hay otros cargos mensuales? <span>Opcional</span></summary><div class="v87-extra-body"></div>`);
 append(extraCosts.querySelector('.v87-extra-body'),monthlyFee);
 append(coverage,row(insuranceKind,insuranceMonthly),extraCosts,coverageCallout);append(panels[0],coverage);
 // 02 — Capital, situación actual, calendario, cuota y cómo se registrarán pagos.
 append(panels[1],stepIntro('02 / 03','SALDO Y CALENDARIO','Ahora, el capital y las cuotas.','Registra el capital original y cómo se comportan los vencimientos.'));
 const balanceSection=section('04','Capital y estado del préstamo','Calculamos cada cuota e interés del contrato desde su origen y conciliamos con el saldo actual informado.');
 if(principal?.querySelector('.filter-label'))principal.querySelector('.filter-label').textContent='Capital original del contrato';
 append(balanceSection,principal,opening);append(panels[1],balanceSection);
 const datesSection=section('05','Plazo y vencimientos','Selecciona la frecuencia y ajusta la cuota. El sistema determina los días 15 y 30 y ajusta automáticamente los meses cortos.');
