 const quotaBox=node('div','v97-quota-box');
 append(quotaBox,installment,node('small','v97-quota-hint','Se utiliza el importe exacto de tu contrato. Si el banco cobra RD$1,501.99, escribe 1501.99; la tabla, los compromisos y la proyección usarán ese importe. Deja 0 para calcular.'));
 append(datesSection,term,row(freq),quotaBox,planned);append(panels[1],datesSection);
 const paymentSection=section('06','Registro de pagos','Define cómo se registran los pagos en la aplicación.');
