 if(posting?.querySelector('.filter-label'))posting.querySelector('.filter-label').textContent='Cómo registrar cada pago';
 if(autoAccount?.querySelector('.filter-label'))autoAccount.querySelector('.filter-label').textContent='Cuenta prevista para pagar';
