/* Apply after render; do not interfere with existing observers, event delegation or Supabase. */
const v105OldRender=render;
render=function(...args){const value=v105OldRender.apply(this,args);v105ApplyWidgetPreferences();return value;};

/* V119 · EL COSTO DEL MAÑANA
   Simulaciones en memoria: no crean transacciones ni realizan llamadas de red.
   Se parte del saldo líquido confirmado hoy y se separan ingresos programados
   de cargos pendientes con fecha. Nunca se infieren ingresos no programados. */
const v119DecisionState={amount:'10000',scenario:'today',horizon:30};
function v119DateAfter(n,from=today()){const d=dateObj(from);d.setDate(d.getDate()+n);return dateStr(d)}
function v119ForecastEvents(horizon=90){
 const start=today(),end=v119DateAfter(horizon),events=[],seen=new Set();
 const add=(key,date,amount,type,name,quality='scheduled')=>{
  if(!date||date<start||date>end||!(amount>.005)||seen.has(key))return;
  seen.add(key);events.push({key,date,amount:rnd(amount),type,name,quality});
 };
 const linked=new Set((db.transactions||[]).map(t=>t.scheduleKey).filter(Boolean));
 for(const s of db.incomeSchedules||[]){
  if(s.active===false||num(s.grossMonthly)<=0||!s.nextDue)continue;
  let d=String(s.nextDue),tries=0;
  while(d<=end&&tries++<520){
   if(d>=start&&!linked.has(`income:${s.id}:${d}`)){
    try{add(`income:${s.id}:${d}`,d,fx(Math.max(0,v40Payroll(s,d).net),s.currency||'DOP'),'income',s.name||'Ingreso programado')}
    catch(err){console.warn('V119: nómina sin cálculo disponible',s.id,err)}
   }
   const next=v40IncomeNext(d,s.frequency||'monthly');if(!next||next<=d)break;d=next;
  }
 }
 // El motor mensual es la misma fuente utilizada por Compromisos, no una segunda tabla.
 const periods=new Set();for(let offset=0;offset<=horizon;offset+=1){const p=v119DateAfter(offset).slice(0,7);periods.add(p)}
 for(const period of periods){
  let lines=[];try{lines=v99DebtMonth(period).lines||[]}catch(err){console.warn('V119: periodo no proyectable',period,err)}
  for(const l of lines){
   let date=l.date;
   if(!date||date<start||date>end)continue;
   // La cuota contractual histórica ya pagada no se convierte en salida futura.
   if(l.kind==='loan'&&l.previous)continue;
   // Evitar duplicar suscripciones pagadas, aunque se abonaron unos días antes.
   if(l.kind==='recurring'&&(db.transactions||[]).some(t=>t.recurringId===l.id&&['expense','card_charge'].includes(t.type)&&Math.abs(diffDays(t.date,date))<=4))continue;
   const identifier=[l.kind,l.id,l.currency||'DOP',date].join(':');
   add('debt:'+identifier,date,fx(Math.max(0,num(l.amount)),l.currency||'DOP'),'expense',l.name||'Compromiso','estimated');
  }
 }
 // Previsiones manuales: incluyen ingresos expresamente programados por la persona.
 // No se infiere una nómina nueva a partir de ingresos pasados, ni se duplican
 // los importes ya presentes en el calendario de nómina o de compromisos.
 try{
  for(const plan of db.smart360?.planned||[]){
   if(!['income','expense'].includes(plan.kind)||!(num(plan.amount)>0)||!plan.date)continue;
   let date=String(plan.date),attempts=0;
   while(date<=end&&attempts++<18){
    if(date>=start){
     const amount=v99MoneyInDop(plan.amount,plan.currency||'DOP'),type=plan.kind;
     const repeated=events.some(e=>e.date===date&&e.type===type&&Math.abs(e.amount-amount)<.02);
     if(!repeated)add(`plan:${plan.id||'manual'}:${date}`,date,amount,type,plan.name||'Previsión manual','manual');
    }
    if(plan.frequency!=='monthly')break;
    const next=plusMonths(date,1);if(!next||next<=date)break;date=next;
   }
  }
 }catch(err){console.warn('V143: previsiones manuales omitidas',err)}
 // Los vencidos aún pendientes se consideran obligación inmediata, sin contarlos dos veces.
 try{for(const p of v99PendingForPeriod(start.slice(0,7))){
   if(!p.date||p.date>=start||!['loan','card','recurring','personal'].includes(p.kind))continue;
   add('overdue:'+p.kind+':'+p.ref+':'+p.date,start,fx(num(p.amount),p.currency||'DOP'),'expense','Vencido · '+(p.name||'Compromiso'),'overdue');
 }}catch(err){console.warn('V119: vencidos incompletos',err)}
 return events.sort((a,b)=>a.date.localeCompare(b.date)||(a.type==='expense'?-1:1));
}
function v119AvailableToday(){
 let total=0;
 for(const a of db.accounts||[]){
  // Las cuentas archivadas conservan saldo real; no son límites de crédito.
  try{total+=fx(getAccountBalance(a),a.currency||'DOP')}catch(err){console.warn('V119: saldo omitido',a.id,err)}
 }
 return rnd(total);
}
function v119BaselineRaw(horizon=30){
 const events=v119ForecastEvents(horizon),initial=v119AvailableToday();
 let balance=initial,minimum=initial,critical=null,dayByDay=[],missingDays=0;
 let cursor=0;
 for(let day=0;day<=horizon;day++){
  const date=v119DateAfter(day);let incoming=0,outgoing=0;
  while(cursor<events.length&&events[cursor].date===date){const x=events[cursor++];if(x.type==='income')incoming+=x.amount;else outgoing+=x.amount}
  // Se presenta el fin del día tras todas las obligaciones, sin inferir el orden intradía.
  balance=rnd(balance+incoming-outgoing);
  if(balance<minimum)minimum=balance;
  if(balance<0){missingDays++;if(!critical)critical=date}
  dayByDay.push({date,balance,incoming:rnd(incoming),outgoing:rnd(outgoing)});
 }
 return {initial,ending:balance,minimum:rnd(minimum),critical,missingDays,events,dayByDay,horizon,
  incomes:rnd(events.filter(e=>e.type==='income').reduce((a,e)=>a+e.amount,0)),
  dues:rnd(events.filter(e=>e.type==='expense').reduce((a,e)=>a+e.amount,0))};
}
function v119Baseline(horizon=30){return v99Memo('v119:baseline:'+today()+':'+horizon,()=>v119BaselineRaw(horizon))}
function v119Decision(amount,scenario,horizon=30){
 const baseline=v119Baseline(horizon),value=Math.max(0,rnd(amount)),start=today();
 const nextIncome=baseline.events.find(e=>e.type==='income'&&e.date>start)?.date||null;
 let allocations=[],note='';
 if(scenario==='next'){
  if(nextIncome)allocations=[{date:nextIncome,amount:value}];
  else note='No hay un próximo ingreso programado verificable; no se puede simular la espera.';
 }else if(scenario==='split'){
  if(nextIncome){const first=rnd(value/2);allocations=[{date:start,amount:first},{date:nextIncome,amount:rnd(value-first)}]}
  else note='No hay próximo ingreso programado para dividir el pago.';
 }else allocations=[{date:start,amount:value}];
 if(note)return {...baseline,valid:false,note,nextIncome,amount:value,scenario};
 const extra=new Map();for(const x of allocations)extra.set(x.date,rnd((extra.get(x.date)||0)+x.amount));
 let minimum=baseline.initial,ending=baseline.initial,critical=null,missingDays=0;const points=[];
 for(const p of baseline.dayByDay){ending=rnd(p.balance-allocations.filter(x=>x.date<=p.date).reduce((sum,x)=>sum+x.amount,0));
  if(ending<minimum)minimum=ending;
  if(ending<0){missingDays++;if(!critical)critical=p.date}
  points.push({...p,balance:ending,decision:extra.get(p.date)||0});
 }
 const extraRisk=rnd(Math.max(0,-minimum)-Math.max(0,-baseline.minimum));
 return {...baseline,valid:true,note:'',nextIncome,amount:value,scenario,
   projectedEnding:ending,projectedMinimum:rnd(minimum),projectedCritical:critical,
   projectedMissingDays:missingDays,extraRisk,points};
}


/* V143: transparencia para El costo de mañana. Las deudas totales son
   un stock informativo; solo los vencimientos previstos salen del saldo. */
function v143TomorrowOutstanding(){
 const personal=personalTotals();
 return {cards:rnd(totalCardDebt()),loans:rnd(totalLoanDebt()),people:rnd(Math.max(0,num(personal.payable))),
  total:rnd(totalCardDebt()+totalLoanDebt()+Math.max(0,num(personal.payable)))};
}


/* V159 · Motor de escenarios no persistentes, basado en el calendario real.
   La ruta de gasto utiliza v119Decision sin modificar su regla histórica.
   El ingreso se agrega exactamente una vez a partir de la fecha elegida. */


/* V169 · El costo de mañana: sólo ingresos y gastos, vista compacta. */
/* V174 — Radiografía antes/después basada en saldos y compromisos reales.
   La pro forma es una variación patrimonial derivada de una decisión nueva.
   NO se interpreta una salida por gasto como pago de deuda; las cuotas no
   se descuentan de nuevo al construir el snapshot patrimonial. */



/* V178 · El costo de mañana: ingreso/gasto y cuatro KPIs compactos.
   Se reutilizan los saldos de la aplicación sin crear ni guardar transacciones. */
function v178Data(){
 const kind=v119DecisionState.kind==='income'?'income':'expense';
 const amount=Math.max(0,rnd(Number(v119DecisionState.amount)||0));
 const impact=rnd((kind==='income'?1:-1)*amount);
 const liquid=rnd(v119AvailableToday());
 const debt=rnd(v143TomorrowOutstanding().total);
 // Misma fuente de Compromisos → Total programado, mes vigente: nunca mezclar
 // liquidez de hoy con obligaciones de un mes histórico filtrado.
 const commitments=rnd(v89DebtCapacity(today().slice(0,7)).monthly);
 const personal=personalTotals();
 const net=rnd(liquid+totalCertificates()+Math.max(0,num(personal.receivable))-debt);
 return {kind,amount,liquid,debt,commitments,net,liquidAfter:rnd(liquid+impact),debtAfter:debt,commitmentsAfter:commitments,netAfter:rnd(net+impact)};
}
function v178Kpi(label,before,after,className){
 const beforeLong=money(before).length>=15?' v708-money-long':'';
 const afterLong=money(after).length>=15?' v708-money-long':'';
 const change=rnd(after-before);
 const movement=change>0?'is-positive':change<0?'is-negative':'is-steady';
 const ico=className.includes('liquid')?'wallet':className.includes('debt')?'card':className.includes('commit')?'cal':'trend';
 return `<article class="v178-kpi v708-impact-card v986-kpi ${className} ${movement}" aria-label="${sanitize(label)}: antes ${money(before)}, después ${money(after)}">
  <div class="v708-card-top"><span class="v986-kico" aria-hidden="true">${v985Svg(V985_ICO[ico],20)}</span><span class="v178-kpi-name">${sanitize(label)}</span><span class="v708-card-indicator" aria-hidden="true">${change===0?'—':change>0?'↗':'↘'}</span></div>
  <div class="v986-flow">
   <div class="v708-card-before"><small>ANTES</small><strong class="${beforeLong}">${money(before)}</strong></div>
   <div class="v708-card-divider" aria-hidden="true"><span>→</span></div>
   <div class="v178-kpi-new v708-card-after"><small>DESPUÉS</small><strong class="${afterLong} ${after<0?'v178-value-negative':''}">${money(after)}</strong></div>
  </div>
  <div class="v708-card-delta ${movement}">${change===0?'Sin variación':`${change>0?'+':'−'}${money(Math.abs(change))}`}</div>
 </article>`;
}
function v178Kpis(){
 const d=v178Data();
 return `${v178Kpi('Liquidez',d.liquid,d.liquidAfter,'v178-liquid')}
 ${v178Kpi('Deudas totales',d.debt,d.debtAfter,'v178-debt')}
 ${v178Kpi('Compromisos',d.commitments,d.commitmentsAfter,'v178-commitments')}
 ${v178Kpi('Posición financiera',d.net,d.netAfter,'v178-net')}`;
}
function v183TomorrowInsight(){
 const d=v178Data();
 if(!(d.amount>0))return '<span>Escribe un importe para visualizar su efecto inmediato, sin registrar ninguna operación.</span>';
 if(d.kind==='expense'){
  if(d.liquid<d.amount)return `<span>Este gasto superaría tu liquidez actual por <b>${money(d.amount-d.liquid)}</b>. Deudas y compromisos permanecen iguales.</span>`;
  const pct=d.liquid>0?d.amount/d.liquid*100:0;
  return `<span>El gasto representa <b>${pct.toFixed(1)}%</b> de la liquidez actual y reduciría tu posición financiera en <b>${money(d.amount)}</b>.</span>`;
 }
 if(d.commitments>0)return `<span>Este ingreso equivaldría al <b>${(d.amount/d.commitments*100).toFixed(1)}%</b> de tus compromisos actuales. No se contabiliza como recibido.</span>`;
 return `<span>El ingreso incrementaría tu liquidez en <b>${money(d.amount)}</b>, sin aumentar tus deudas ni compromisos.</span>`;
}

function v119Markup(){
 const kind=v119DecisionState.kind==='income'?'income':'expense';
 return `<div class="v119-content v159-tomorrow v169-simple-tomorrow v178-tomorrow v315-tomorrow v986-tomorrow is-${kind}">
  <section class="v986-hero" aria-label="Simulación">
   <span class="v986-eyebrow">SIMULADOR · NO REGISTRA NINGÚN MOVIMIENTO</span>
   <div class="v169-choice v986-seg" role="group" aria-label="Tipo de simulación">
    <button type="button" data-v159-kind="expense" class="${kind==='expense'?'active is-expense':''}" aria-pressed="${kind==='expense'}">${icon('down')} Gasto</button>
    <button type="button" data-v159-kind="income" class="${kind==='income'?'active is-income':''}" aria-pressed="${kind==='income'}">${icon('up')} Ingreso</button>
   </div>
   <label class="v169-amount v178-amount v986-amount"><span>${kind==='income'?'¿Cuánto recibirías?':'¿Cuánto gastarías?'}</span>
    <div><small>RD$</small><input id="v119-amount" type="number" inputmode="decimal" min="0" step="0.01" value="${sanitize(String(v119DecisionState.amount||''))}" placeholder="0.00" aria-label="Importe que ${kind==='income'?'recibirías':'gastarías'}"></div>
   </label>
   <p class="v986-insight" id="v986-insight" role="status" aria-live="polite">${v183TomorrowInsight()}</p>
  </section>
  <section class="v708-impact-section v986-impact" aria-label="Impacto financiero de la decisión">
   <div class="v708-impact-heading"><div><span class="v708-eyebrow">ANTES Y DESPUÉS</span><h3>El impacto de tu decisión</h3></div><span class="v708-live-label">${kind==='income'?'Ingreso simulado':'Gasto simulado'}</span></div>
   <div class="v178-kpi-grid" id="v178-kpis" role="group" aria-label="Liquidez, deudas totales, compromisos y posición financiera antes y después">${v178Kpis()}</div>
   <p class="v708-impact-foot">Las obligaciones solo varían si la operación realmente las modifica. Esta simulación no altera tus saldos.</p>
  </section>
 </div>`;
}



function v119Open(){
 v119DecisionState.kind='expense';v119DecisionState.amount='';
 const root=document.getElementById('modal-root');if(!root)return;
 root.innerHTML=`<div class="modal-layer" data-backdrop="true"><section class="modal wide v119-modal" role="dialog" aria-modal="true" aria-label="El costo de mañana"><div class="modal-head"><h2>El costo de mañana</h2><button type="button" class="close" data-act="closeModal" aria-label="Cerrar">×</button></div><div id="v119-results">${v119Markup()}</div></section></div>`;
}
function v119Refresh(){const node=document.getElementById('v119-results');if(node)node.innerHTML=v119Markup()}
document.addEventListener('click',event=>{
 const open=event.target.closest?.('[data-v119-open]');if(open){event.preventDefault();if(document.getElementById('v71-search-overlay'))v71SearchClose(false);v119Open();return}
 const kind=event.target.closest?.('[data-v159-kind]');if(kind){v119DecisionState.amount=document.getElementById('v119-amount')?.value??v119DecisionState.amount;v119DecisionState.kind=kind.dataset.v159Kind==='income'?'income':'expense';v119Refresh();return}
 const timing=event.target.closest?.('[data-v159-timing]');if(timing){v119DecisionState.amount=document.getElementById('v119-amount')?.value??v119DecisionState.amount;if(v119DecisionState.kind==='income')v119DecisionState.incomeTiming=timing.dataset.v159Timing;else v119DecisionState.scenario=timing.dataset.v159Timing;v119Refresh();return}
 const horizon=event.target.closest?.('[data-v119-horizon]');if(horizon){v119DecisionState.amount=document.getElementById('v119-amount')?.value??v119DecisionState.amount;v119DecisionState.horizon=Number(horizon.dataset.v119Horizon);v119Refresh();return}
});
document.addEventListener('change',event=>{
 if(event.target.id!=='v167-target')return;
 v119DecisionState.amount=document.getElementById('v119-amount')?.value??v119DecisionState.amount;
 if(v119DecisionState.kind==='debt')v119DecisionState.debtTarget=event.target.value;
 if(v119DecisionState.kind==='commitment')v119DecisionState.commitmentTarget=event.target.value;
 v119Refresh();
});
document.addEventListener('input',event=>{
 if(event.target.id!=='v119-amount')return;
 v119DecisionState.amount=event.target.value;
 const grid=document.getElementById('v178-kpis');
 if(grid)grid.innerHTML=v178Kpis();
 const ins=document.getElementById('v986-insight');if(ins)ins.innerHTML=v183TomorrowInsight();
});
/* Reutiliza el Resumen existente, sin reestructurar las demás vistas. */
/* V123 · Alertas de gasto por categoría, exclusivamente desde datos locales.
   Las tres referencias son meses completos anteriores al mes actual.
   No se cuentan pagos de tarjeta, préstamos ni transferencias como compras nuevas. */
function v123CategoryAlertsFromTransactions(transactions,cutoff,rate){
 const m=String(cutoff||'').slice(0,7);
 if(!/^\d{4}-\d{2}$/.test(m))return [];
 const baselineMonths=[];for(let offset=3;offset>=1;offset--){
  const d=new Date(Number(m.slice(0,4)),Number(m.slice(5,7))-1-offset,1);
  baselineMonths.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
 }
 const wanted=new Set([...baselineMonths,m]);
 const sums=new Map();const observed=new Set();
 const conversion=(tx)=>tx.currency==='USD'?Math.max(0,num(tx.fxRateSnapshot||rate)):1;
 for(const tx of transactions||[]){
  const day=String(tx.date||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||day>cutoff)continue;
  const period=day.slice(0,7);if(!wanted.has(period))continue;
  // Es una sola compra, aunque el pago de la tarjeta ocurra semanas después.
  if(!['expense','card_charge','card_refund'].includes(tx.type))continue;
  const category=String(tx.category||'Sin categoría').trim()||'Sin categoría';
  const amount=num(tx.amount)*conversion(tx)*(tx.type==='card_refund'?-1:1);
  if(!Number.isFinite(amount)||!amount)continue;
  const key=category+'\u0000'+period;
  sums.set(key,(sums.get(key)||0)+amount);
  observed.add(period);
 }
 const results=[];
 for(const category of new Set([...sums.keys()].map(k=>k.split('\u0000')[0]))){
  const previous=baselineMonths.map(period=>Math.max(0,sums.get(category+'\u0000'+period)||0));
  // La ausencia de gastos en un mes concreto no es un valor histórico fiable
  // si el usuario no registró ninguna operación en ese mes.
  if(baselineMonths.some(period=>!observed.has(period)))continue;
  const active=previous.filter(v=>v>0);
  if(active.length<2)continue;
  const avg=previous.reduce((sum,x)=>sum+x,0)/3;
  const current=Math.max(0,sums.get(category+'\u0000'+m)||0);
  if(avg<500)continue;
  const over=current-avg,ratio=avg>0?current/avg:0;
  if(current>=avg*1.5&&over>=1000){
   results.push({category,kind:'spike',average:rnd(avg),current:rnd(current),extra:rnd(over),pct:rnd((ratio-1)*100),history:previous.map(rnd)});
  }else if(previous.every(v=>v>=500)&&previous[1]>=previous[0]*1.15&&previous[2]>=previous[1]*1.15&&previous[2]>=previous[0]*1.5){
   results.push({category,kind:'trend',average:rnd(avg),current:rnd(current),extra:rnd(previous[2]-previous[0]),pct:rnd((previous[2]/previous[0]-1)*100),history:previous.map(rnd)});
  }
 }
 return results.sort((a,b)=>(a.kind==='spike'?-1:0)-(b.kind==='spike'?-1:0)||b.extra-a.extra).slice(0,5);
}
function v123CategoryAlerts(){return v99Memo('v123:category-alerts:'+today(),()=>v123CategoryAlertsFromTransactions(db.transactions,today(),db.settings.fx));}
function v123AlertText(a){
 if(a.kind==='trend')return `Subió en los últimos tres meses: ${money(a.history[0])} → ${money(a.history[2])}.`;
 return `Promedio: ${money(a.average)} · Este mes: ${money(a.current)} · ${a.pct.toFixed(0)}% por encima de lo habitual.`;
}
function v123AlertWidget(){
 const alerts=v123CategoryAlerts();if(!alerts.length)return '';
 return `<section class="v123-spending-panel" aria-label="Alertas de gastos fuera de lo habitual"><div class="v123-spending-head"><span class="v123-spending-symbol">${icon('chart')}</span><div><small>TUS HÁBITOS · ANÁLISIS PREVENTIVO</small><h2>Gastos fuera de lo habitual</h2><p>Comparación con los últimos tres meses completos.</p></div></div><div class="v123-spending-list">${alerts.slice(0,3).map(a=>`<div class="v123-spending-item"><div><strong>${sanitize(a.category)}</strong><small>${sanitize(v123AlertText(a))}</small></div><span class="v123-spending-percent">${a.kind==='trend'?'Tendencia al alza':`+${a.pct.toFixed(0)}%`}</span></div>`).join('')}</div><p class="v123-spending-disclaimer">Avisos orientativos según los gastos registrados. No incluyen abonos de tarjetas como nuevas compras.</p></section>`;
}
const v119PreviousOverview=pages.overview;
pages.overview=function(){return v123AlertWidget()+v119PreviousOverview()};


/* V144 · Centro de tarjetas y beneficios: interfaz contextual, sin duplicar el libro.
   Guarda únicamente referencias de beneficios previstos; los saldos reales siempre
   provienen de db.transactions y sus identificadores existentes. */
function v144Ready(){
 if(!Array.isArray(db.v144PendingBenefits))db.v144PendingBenefits=[];
 if(!Array.isArray(db.v144ScheduledCosts))db.v144ScheduledCosts=[];
}
function v144CurrentFx(t){return txDop(t)}
function v144AmountDOP(amount,currency){return rnd(num(amount)*(currency==='USD'?num(db.settings.fx)||0:1))}
function v144Value(value,currency='DOP'){return money(value,currency,2)}
function v144PeriodMatch(date){const y=String(ui.v144BenefitYear||new Date().getFullYear()),m=String(ui.v144BenefitMonth||'all');return String(date||'').startsWith(y)&&(m==='all'||String(date||'').slice(5,7)===m)}
function v144AllCosts(c){return db.transactions.filter(t=>t.cardId===c.id&&(
 ((t.type==='card_charge'||t.type==='expense')&&(
  t.v144CardCost===true||['annual_fee','commission','insurance','issuance','renewal'].includes(t.chargeKind)||
  (t.type==='card_charge'&&t.category==='Deudas e intereses'&&/anualidad|membres[ií]a|seguro|comisi[oó]n/i.test(t.subcategory||''))
 ))));}
function v144CostPaid(t){
 if(t.type==='expense')return true;
 if(t.type!=='card_charge'||!t.v144SettledVia)return false;
 const pay=db.transactions.find(p=>p.id===t.v144SettledVia&&p.type==='card_payment'&&p.cardId===t.cardId&&p.currency===t.currency&&p.date>=t.date);
 if(!pay)return false;
 const linked=db.transactions.filter(x=>x.v144SettledVia===pay.id);
 return linked.every(x=>x.cardId===pay.cardId&&x.currency===pay.currency&&x.date<=pay.date)
   &&linked.reduce((sum,x)=>sum+num(x.amount),0)<=num(pay.amount)+.01;
}
function v144CostPaidDate(t){const p=db.transactions.find(p=>p.id===t.v144SettledVia);return t.type==='card_charge'&&v144CostPaid(t)?p.date:t.date;}
function v144CardStats(c,period=true){
 v144Ready();
 const match=date=>!period||v144PeriodMatch(date);
 const rewards=db.transactions.filter(t=>t.cardId===c.id&&['card_reward','bank_reward'].includes(t.type)&&match(t.date));
 const realizedCashback=rnd(rewards.filter(t=>t.v144BenefitKind!=='other').reduce((s,t)=>s+v144CurrentFx(t),0));
 const realizedOther=rnd(rewards.filter(t=>t.v144BenefitKind==='other').reduce((s,t)=>s+v144CurrentFx(t),0));
 const costs=v144AllCosts(c);
 const paid=costs.filter(t=>v144CostPaid(t)&&match(v144CostPaidDate(t)));
 const billed=costs.filter(t=>!v144CostPaid(t)&&match(t.date));
 const feePaid=rnd(paid.filter(t=>t.chargeKind==='annual_fee'||/anualidad|membres[ií]a/i.test(t.subcategory||'')).reduce((s,t)=>s+v144CurrentFx(t),0));
 const paidAmount=rnd(paid.reduce((s,t)=>s+v144CurrentFx(t),0));
 const billedAmount=rnd(billed.reduce((s,t)=>s+v144CurrentFx(t),0));
 const pending=db.v144PendingBenefits.filter(x=>x.cardId===c.id&&match(x.date));
 const expected=rnd(pending.reduce((s,x)=>s+v144AmountDOP(x.amount,x.currency),0));
 const planned=db.v144ScheduledCosts.filter(x=>x.cardId===c.id&&match(x.date));
 const plannedSum=rnd(planned.reduce((s,x)=>s+v144AmountDOP(x.amount,x.currency),0));
 const gross=rnd(realizedCashback+realizedOther),net=rnd(gross-paidAmount);
 return {rewards,paid,billed,pending,planned,realizedCashback,realizedOther,gross,paidAmount,billedAmount,feePaid,expected,plannedSum,net,roi:paidAmount>0?rnd(net/paidAmount*100):null};
}
function v144RoiText(value){return value===null?'No aplica':`${value>=0?'+':''}${new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(value)}%`}
function v144CardDue(c){const due=annualMembershipDate(c);const configured=num(c.annualFeeAmount)>0?num(c.annualFeeAmount):(num(c.annualFeeDOP)||num(c.annualFeeUSD));const cur=c.annualFeeCurrency||(num(c.annualFeeUSD)&&!num(c.annualFeeDOP)?'USD':'DOP');return {date:due,currency:cur,amount:configured};}
function v144CardKpis(c,small=false){
 const z=v144CardStats(c),d=cardStatus(c,'DOP'),u=cardStatus(c,'USD'),debt=rnd(d.debt+v144AmountDOP(u.debt,'USD'));
 const items=[['Deuda total',v144Value(debt),'RD$ + US$ equivalentes',''],['Cashback cobrado',v144Value(z.realizedCashback),'Solo acreditaciones confirmadas','good'],['Costo pagado',v144Value(z.paidAmount),'No incluye cargos sin conciliar','cost'],['Beneficio neto',v144Value(z.net),'Cashback + otros beneficios − costos pagados',z.net>=0?'good':'cost']];
 return `<div class="v144-kpis ${small?'compact':''}">${items.map(([label,val,note,kind])=>`<div class="v144-kpi ${kind}"><small>${sanitize(label)}</small><strong>${val}</strong><span>${sanitize(note)}</span></div>`).join('')}</div>`;
}
function v144ReceivedBenefits(c){
 const seen=new Set();
 const rows=[...(db.transactions||[]).filter(t=>t.cardId===c.id&&['card_reward','bank_reward'].includes(t.type)).map(t=>({key:'tx:'+t.id,date:t.date,label:t.note||'Cashback acreditado',value:money(t.amount,t.currency,2),detail:t.type==='bank_reward'?'Acreditado en cuenta':'Acreditado en tarjeta'})),...(db.perkUses||[]).filter(p=>p.cardId===c.id).map(p=>({key:'perk:'+p.id,date:p.date,label:p.name||'Beneficio recibido',value:p.kind==='points'?new Intl.NumberFormat('es-DO',{maximumFractionDigits:2}).format(num(p.value))+' puntos':num(p.value)?money(p.value,p.currency,2):'Registrado',detail:(({discount:'Descuento confirmado',points:'Puntos del programa',other:'Valor referencial'})[p.kind]||'Beneficio informativo')+' · no modifica saldos'}))].filter(r=>{if(seen.has(r.key))return false;seen.add(r.key);return true}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 return `<details class="v144-received-benefits" open><summary>Beneficios recibidos · ${rows.length}</summary>${rows.length?`<ul>${rows.slice(0,12).map(r=>`<li><div><strong>${sanitize(r.label)}</strong><small>${prettyDate(r.date)} · ${sanitize(r.detail)}</small></div><b>${sanitize(r.value)}</b></li>`).join('')}</ul>${rows.length>12?'<small>Últimos 12 registros. Consulta Análisis para filtrar el historial.</small>':''}`:'<small>Aún no hay beneficios registrados para esta tarjeta.</small>'}</details>`;
}
function v144CardExecutive(c,opts={}){
 const z=v144CardStats(c),due=v144CardDue(c),annual=(due.amount>0&&due.date)?`${v144Value(due.amount,due.currency)} · ${prettyDate(due.date)}`:due.amount>0?v144Value(due.amount,due.currency):'Sin configurar';
 return `<section class="v144-executive ${opts.mobile?'mobile':''}" aria-label="Beneficios y costos de ${sanitize(c.name)}">
 <div class="v144-section-head"><div><small>VALOR REAL DE TU TARJETA</small><h3>Beneficios y costos</h3><p>Ganancias confirmadas frente a dinero efectivamente pagado.</p></div><button type="button" class="v144-link" data-v144-action="open-benefits" data-id="${sanitize(c.id)}">Ver análisis ${icon('arrow')}</button></div>
 ${v144CardKpis(c,true)}
 <div class="v144-executive-strip"><span>Rentabilidad <b>${v144RoiText(z.roi)}</b></span><span>Costos cargados no conciliados <b>${v144Value(z.billedAmount)}</b></span><span>Anualidad prevista <b>${sanitize(annual)}</b></span></div>
 <div class="v144-actions"><button type="button" data-v144-action="new-cashback" data-id="${sanitize(c.id)}">${icon('plus')} Cashback</button><button type="button" data-v144-action="new-cost" data-id="${sanitize(c.id)}">${icon('receipt')} Costo de la tarjeta</button><button type="button" data-v144-action="open-benefits" data-id="${sanitize(c.id)}">${icon('chart')} Análisis</button></div>
 ${v144ReceivedBenefits(c)}
 </section>`;
}


function v144BenefitOptionsCards(){return [['all','Todas mis tarjetas'],...db.cards.filter(c=>ui.showHidden||!isHidden(c)).map(c=>[c.id,c.name])];}
function v144CardFilterUI(){const year=String(ui.v144BenefitYear||new Date().getFullYear()),month=ui.v144BenefitMonth||'all',selected=ui.v144BenefitsCard||'all';
 const months=[['all','Año completo'],...['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'].map((x,i)=>[String(i+1).padStart(2,'0'),x])];
 return `<div class="v144-filter-row"><label>Tarjeta<select data-v144-filter="card">${v144BenefitOptionsCards().map(([v,t])=>`<option value="${sanitize(v)}" ${selected===v?'selected':''}>${sanitize(t)}</option>`).join('')}</select></label><label>Año<select data-v144-filter="year">${Array.from({length:6},(_,i)=>new Date().getFullYear()+1-i).map(y=>`<option value="${y}" ${year===String(y)?'selected':''}>${y}</option>`).join('')}</select></label><label>Período<select data-v144-filter="month">${months.map(([v,t])=>`<option value="${v}" ${month===v?'selected':''}>${t}</option>`).join('')}</select></label></div>`;
}
/* V183 · Consistencia anual: solo beneficios confirmados y costos pagados.
   La anualidad configurada es informativa; no se mezcla con pagos reales. */
function v183YearBenefitMetrics(cards,year){
 const cardIds=new Set(cards.map(c=>c.id));
 const months=Array.from({length:12},(_,i)=>({month:i+1,earned:0,paid:0}));
 for(const t of db.transactions||[]){
  if(!cardIds.has(t.cardId)||!['card_reward','bank_reward'].includes(t.type))continue;
  const date=String(t.date||'');
  if(!date.startsWith(String(year)))continue;
  const m=Number(date.slice(5,7));if(m<1||m>12)continue;
  months[m-1].earned+=v144CurrentFx(t);
 }
 for(const c of cards){
  for(const t of v144AllCosts(c)){
   if(!v144CostPaid(t))continue;
   const date=String(v144CostPaidDate(t)||'');
   if(!date.startsWith(String(year)))continue;
   const m=Number(date.slice(5,7));if(m<1||m>12)continue;
   months[m-1].paid+=v144CurrentFx(t);
  }
 }
 let earn=0,paid=0;
 for(const m of months){
  m.earned=rnd(m.earned);m.paid=rnd(m.paid);
  earn=rnd(earn+m.earned);paid=rnd(paid+m.paid);
  m.accumulatedEarned=earn;
  m.accumulatedPaid=paid;
  m.accumulatedNet=rnd(earn-paid);
 }
 const feeConfigured=rnd(cards.reduce((sum,c)=>{
  const fee=v144CardDue(c);return sum+(fee.amount>0?v144AmountDOP(fee.amount,fee.currency):0);
 },0));
 return {months,earned:earn,paid,net:rnd(earn-paid),feeConfigured};
}

function v144BenefitsTable(cards){
 return `<div class="v144-table-wrap"><table class="v144-profit-table v183-profit-table"><thead><tr>
  <th>Tarjeta</th><th>Beneficios cobrados</th><th>Costos pagados</th><th>Cargos por conciliar</th><th>Anualidad configurada</th><th>Resultado neto</th><th>Detalle</th>
 </tr></thead><tbody>${cards.map(c=>{
  const z=v144CardStats(c),fee=v144CardDue(c);
  const feeText=fee.amount>0?v144Value(fee.amount,fee.currency):'Sin configurar';
  return `<tr><td data-label="Tarjeta"><strong>${sanitize(c.name)}</strong><small>${sanitize(bankOf(c))}</small></td>
   <td data-label="Beneficios cobrados">${v144Value(z.gross)}</td>
   <td data-label="Costos pagados">${v144Value(z.paidAmount)}</td>
   <td data-label="Cargos sin conciliar">${v144Value(z.billedAmount)}</td>
   <td data-label="Anualidad configurada">${feeText}<small>No es un pago registrado</small></td>
   <td data-label="Resultado neto" class="${z.net>=0?'positive':'negative'}">${v144Value(z.net)}</td>
   <td data-label="Detalle"><button type="button" class="v144-link" data-v144-action="open-benefits" data-id="${sanitize(c.id)}">Ver detalles</button></td>
  </tr>`;
 }).join('')}</tbody></table></div>`;
}



/* V187 — Beneficios solo con su KPI y la tabla principal; sin secciones redundantes. */
function v389BenefitsKPIs(cards){
 const year=Number(ui.v144BenefitYear)||new Date().getFullYear();
 const cardIds=new Set(cards.map(c=>c.id));
 const benefits=(db.transactions||[]).filter(t=>cardIds.has(t.cardId)&&['card_reward','bank_reward'].includes(t.type)&&String(t.date||'').startsWith(String(year)));
 const credited=rnd(benefits.reduce((sum,t)=>sum+v144CurrentFx(t),0));
 const annualFees=rnd(cards.reduce((sum,c)=>sum+v144AllCosts(c).filter(t=>v144CostPaid(t)&&String(v144CostPaidDate(t)||'').startsWith(String(year))&&(t.chargeKind==='annual_fee'||/anualidad|membres[ií]a/i.test(t.subcategory||''))).reduce((v,t)=>v+v144CurrentFx(t),0),0));
 const net=rnd(credited-annualFees);
 const ratio=annualFees>0?(net/annualFees*100):null;
 const fmtRatio=ratio===null?'—':new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(ratio)+' %';
 return `<section class="v389-benefit-kpis" aria-label="Resumen de beneficios reales de ${year}">
   <div><small>ANUALIDADES PAGADAS</small><strong>${v144Value(annualFees)}</strong></div>
   <div><small>BENEFICIOS RECIBIDOS</small><strong>${v144Value(credited)}</strong></div>
   <div><small>RETORNO</small><strong class="${net>=0?'positive':'negative'}">${v144Value(net)}</strong></div>
   <div><small>RETORNO %</small><strong class="${net>=0?'positive':'negative'}">${fmtRatio}</strong></div>
 </section><p class="v389-benefit-definition">${year} · Retorno = beneficios monetarios recibidos − anualidades pagadas. Porcentaje = retorno ÷ anualidades pagadas. Si no hay anualidades pagadas, el porcentaje no aplica. No incluye beneficios pendientes ni puntos.</p>`;
}
