document.addEventListener('click',function(event){const el=event.target.closest?.('[data-v144-action]');if(!el)return;event.preventDefault();event.stopImmediatePropagation();v144RunAction(el.dataset.v144Action,el)},true);
document.addEventListener('change',function(event){const select=event.target.closest?.('[data-v144-filter]');if(!select)return;const k=select.dataset.v144Filter;if(k==='card')ui.v144BenefitsCard=select.value;else if(k==='year')ui.v144BenefitYear=Number(select.value);else if(k==='month')ui.v144BenefitMonth=select.value;render()},true);
document.addEventListener('submit',function(event){const f=event.target;if(!['v144CashbackForm','v144CostForm','v144SettleForm'].includes(f.id))return;event.preventDefault();event.stopImmediatePropagation();try{if(f.id==='v144CashbackForm')v144SaveCashback(f);else if(f.id==='v144CostForm')v144SaveCost(f);else v144SaveSettlement(f)}catch(error){const spot=f.querySelector('#formError');if(spot)spot.textContent=error.message||String(error);toast(error.message||String(error))}},true);
// Gesture of return to the stack: only if the page has not scrolled vertically.
let v144GestureStart=null;
document.addEventListener('touchstart',ev=>{const node=ev.target.closest?.('.v144-wallet-shell .v68-wallet-face.selected');if(!node||!ev.touches?.[0])return;v144GestureStart={x:ev.touches[0].clientX,y:ev.touches[0].clientY,scroll:window.scrollY};},{passive:true});
document.addEventListener('touchend',ev=>{if(!v144GestureStart||!ev.changedTouches?.[0])return;const p=ev.changedTouches[0],dx=p.clientX-v144GestureStart.x,dy=p.clientY-v144GestureStart.y;if(dy>85&&Math.abs(dx)<32&&Math.abs(window.scrollY-v144GestureStart.scroll)<8&&ui.v144WalletExpanded!==false){ui.v144WalletExpanded=false;render()}v144GestureStart=null;},{passive:true});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&document.activeElement?.closest('.v144-wallet-shell .v68-wallet-gallery')){ui.v144WalletExpanded=false;render()}},true);



/* Selección de servicios desde el mismo motor de Próximos pagos.
   Reutiliza payRecurring/guideTransactionForm, nunca crea operaciones paralelas. */
function v146ServiceChooser(){ return v923ServiceChooser(); }

document.addEventListener('click',function(event){
 // V929: one entry to the same service confirmation for subscription / commitment payments.
 // Intercept before the old wizard and before any other delegated click listener.
 const specific=event.target.closest?.('[data-act="payRecurring"][data-id], [data-v146-pay-service], [data-v261-bill], [data-v261-continue], [data-act="quickPaySpecific"][data-kind="payRecurring"]');
 if(specific){
  event.preventDefault();event.stopImmediatePropagation();
  const serviceId=specific.dataset.id||specific.dataset.v146PayService||specific.dataset.v261Bill||specific.dataset.v261Continue;
  if(serviceId)v917BillDetail(serviceId);
  return;
 }
 const opening=event.target.closest?.('[data-act="guidedFlow"][data-mode="service"]');
 if(opening){event.preventDefault();event.stopImmediatePropagation();v146ServiceChooser();return}
 const occasional=event.target.closest?.('[data-v146-service-occasional]');
 if(occasional){event.preventDefault();event.stopImmediatePropagation();closeModal();guidedTransactionForm({type:'expense',flowMode:'service',servicePreset:'other'});return}
},true);



