/* V261 · Pago de servicios: catálogo, facturas próximas y detalle nativo.
   No registra operaciones por sí solo: delega a payRecurring y guidedTransactionForm. */
const V261_SERVICE_CATALOG=[
 ['electricity','Electricidad','bolt2'],['internet','Internet y TV','wifi2'],['water','Agua','droplet2'],
 ['mobile','Telefonía','smartphone'],['streaming','Streaming','play'],['insurance','Seguros','shield3'],
 ['education','Educación','graduation'],['app','Aplicaciones','monitor2'],['other','Otros','receipt']
];
function v261PendingServices(){
 const current=v99Period(today().slice(0,7));
 const recurring=new Map((db.recurring||[]).filter(r=>r&&r.active!==false).map(r=>[r.id,r]));
 const due=[...v99PendingForPeriod(current),...upcoming()].filter(x=>x.kind==='recurring');
 // A recurring service is not a separate payment form. Its nextDue is the source
 // even when the financial calendar does not include that future date yet.
 for(const r of recurring.values()){
  if(r.archived||!r.nextDue||!r.currency)continue;
  const key=`recurring:${r.id}:${r.nextDue}`;
  if(db.transactions.some(t=>t.scheduleKey===key))continue;
  if(!due.some(x=>String(x.ref)===String(r.id)))due.push({kind:'recurring',ref:r.id,date:r.nextDue,amount:num(r.amount),currency:r.currency});
 }
 const seen=new Set();
 return due.sort((a,b)=>String(a.date).localeCompare(String(b.date))).filter(x=>{
  if(!recurring.has(x.ref)||seen.has(x.ref))return false;
  const r=recurring.get(x.ref);
  if(r.archived||db.transactions.some(t=>t.scheduleKey===`recurring:${r.id}:${r.nextDue}`))return false;
  seen.add(x.ref);return true;
 }).map(x=>({r:recurring.get(x.ref),x}));
}
function v261ServiceStatus(date){
 const days=diffDays(date,today());
 if(days<0)return {name:`Venció hace ${Math.abs(days)} d`,kind:'overdue'};
 if(days===0)return {name:'Vence hoy',kind:'due'};
 if(days<=7)return {name:`En ${days} ${days===1?'día':'días'}`,kind:'near'};
 return {name:prettyDate(date),kind:'later'};
}
