const v212State={links:[],events:[],secret:'',webhook:'',lastLinkId:'',selectedCard:'',currency:'DOP',busy:false,loaded:false,error:'',syncError:'',lastSync:'',health:'unverified',healthMessage:'El vínculo y la recepción son pasos separados.'};
let v212Busy=false;
