    const inCur=visible.filter(a=>a.currency===cur), bankSum=inCur.filter(a=>!cash(a)).reduce((v,a)=>v+num(getAccountBalance(a)),0), cashSum=inCur.filter(cash).reduce((v,a)=>v+num(getAccountBalance(a)),0);
