/* V250 · Control exclusivo de intensidad Liquid Glass de la barra móvil.
   No aplica opacidad a la interfaz entera, ni al botón Registrar. */
function v250DockGlassValue(raw){
 const n=Number(raw);
 return Number.isFinite(n)?Math.min(100,Math.max(0,Math.round(n))):50;
}
function v250DockGlassApply(raw){
 const n=v250DockGlassValue(raw), ratio=n/100, style=document.documentElement.style;
 style.setProperty('--v250-dock-opacity',(0.12+0.50*ratio).toFixed(3));
 style.setProperty('--v250-dock-dark-opacity',(0.28+0.57*ratio).toFixed(3));
 style.setProperty('--v250-dock-blur',(12+40*ratio).toFixed(1)+'px');
 style.setProperty('--v250-dock-saturation',Math.round(140+90*ratio)+'%');
 style.setProperty('--v250-glass-meter',n+'%');
 return n;
}
function v250DockGlassPanel(){
 const value=v250DockGlassValue(db.settings.mobileDockGlassLevel ?? 50);
 return `<section class="v250-dock-settings panel" aria-labelledby="v250-dock-title">
  <div class="v250-dock-head"><div><span class="v250-dock-kicker">NAVEGACIÓN · SOLO MÓVIL</span><h3 id="v250-dock-title">Intensidad de Liquid Glass</h3><p>Regula cuánto se difumina el fondo detrás de la barra inferior. No cambia los demás paneles ni el botón Registrar.</p></div><output id="v250-dock-value" for="v250-dock-slider">${value}%</output></div>
  <div class="v250-dock-preview" aria-hidden="true"><span class="v250-dock-preview-shape"></span><span class="v250-dock-preview-shape second"></span><div class="v250-dock-preview-bar"><span>${icon('home')}</span><span>${icon('card')}</span><span>${icon('building')}</span><span>${icon('grid')}</span><span>${icon('search')}</span></div></div>
  <label class="v250-dock-range-label" for="v250-dock-slider">Nivel de efecto</label>
  <input id="v250-dock-slider" type="range" min="0" max="100" step="1" value="${value}" aria-label="Intensidad Liquid Glass de la barra inferior" aria-valuetext="${value} por ciento" style="--v250-slider-progress:${value}%">
  <div class="v250-dock-extremes"><span>Más transparente</span><span>Más esmerilado</span></div>
  <p class="v250-dock-foot">El cambio se ve al instante y se guarda al soltar el control.</p>
 </section>`;
}
document.addEventListener('input',event=>{
 const slider=event.target;
 if(slider?.id!=='v250-dock-slider')return;
 const n=v250DockGlassApply(slider.value);
 slider.style.setProperty('--v250-slider-progress',n+'%');
 slider.setAttribute('aria-valuetext',n+' por ciento');
 const output=document.getElementById('v250-dock-value');if(output)output.textContent=n+'%';
});
document.addEventListener('change',event=>{
 const slider=event.target;
 if(slider?.id!=='v250-dock-slider')return;
 const prev=v250DockGlassValue(db.settings.mobileDockGlassLevel ?? 50);
 const next=v250DockGlassValue(slider.value);
 if(next===prev)return;
 db.settings.mobileDockGlassLevel=next;
 if(!persist()){
  db.settings.mobileDockGlassLevel=prev;
  slider.value=String(prev);slider.style.setProperty('--v250-slider-progress',prev+'%');
  slider.setAttribute('aria-valuetext',prev+' por ciento');
  const output=document.getElementById('v250-dock-value');if(output)output.textContent=prev+'%';
  v250DockGlassApply(prev);
  toast('No se pudo guardar la intensidad. Comprueba la sincronización.');
 }
});

/* V443 · Control separado para intensidad de barras de navegación web. */
function v443NavLevel(raw){
 const n=Number(raw);
 return Number.isFinite(n)?Math.min(100,Math.max(0,Math.round(n))):18;
}
function v443NavTone(n){
 if(n<=8)return 'apagada';
 if(n<=28)return 'suave';
 if(n<=58)return 'media';
 if(n<=82)return 'marcada';
 return 'alta';
}
function v443NavApply(raw){
 const n=v443NavLevel(raw),ratio=n/100,style=document.documentElement.style;
 document.documentElement.dataset.v443NavIntensity=n===0?'off':n<=28?'soft':n<=58?'medium':'strong';
 style.setProperty('--v443-nav-level',String(n));
 style.setProperty('--v443-nav-preview-alpha',(0.09+0.32*ratio).toFixed(3));
 style.setProperty('--v443-nav-preview-border-alpha',(0.04+0.70*ratio).toFixed(3));
 style.setProperty('--v443-nav-pill-idle-alpha',(0.02+0.16*ratio).toFixed(3));
 style.setProperty('--v443-nav-shell-alpha',(0.40*ratio).toFixed(3));
 style.setProperty('--v443-nav-shell-border-alpha',(0.75*ratio).toFixed(3));
 style.setProperty('--v443-nav-shell-inner-alpha',(0.68*ratio).toFixed(3));
 style.setProperty('--v443-nav-shell-shadow-alpha',(0.09*ratio).toFixed(3));
 style.setProperty('--v443-nav-shell-blur',(26*ratio).toFixed(1)+'px');
 style.setProperty('--v444-dark-alpha',(0.50*ratio).toFixed(3));
 style.setProperty('--v444-dark-border',(0.28*ratio).toFixed(3));
 style.setProperty('--v443-nav-shell-sat',Math.round(104+76*ratio)+'%');
 style.setProperty('--v443-nav-idle-hover-alpha',(0.08+0.58*ratio).toFixed(3));
 style.setProperty('--v443-nav-active-alpha',(0.86+0.11*ratio).toFixed(3));
 style.setProperty('--v443-nav-active-shadow-alpha',(0.05+0.10*ratio).toFixed(3));
 document.documentElement.style.setProperty('--v443-nav-meter',`"${v443NavTone(n)}"`);
 return n;
}
function v443NavPanel(){
 const value=v443NavLevel(db.settings.webNavGlassLevel ?? 0), tone=v443NavTone(value);
 return `<section class="v443-nav-settings panel" aria-labelledby="v443-nav-title">
  <div class="v443-nav-head"><div><span class="v443-nav-kicker">NAVEGACIÓN WEB</span><h3 id="v443-nav-title">Intensidad de barras superiores</h3><p>Controla por separado la presencia visual de las cápsulas horizontales. En bajo nivel casi desaparece la barra y destaca sobre todo el botón activo.</p></div><output id="v443-nav-value" for="v443-nav-slider" class="v443-nav-meter">${tone}</output></div>
  <div class="v443-nav-preview" aria-hidden="true"><div class="v443-nav-preview-bar"><span class="v443-nav-pill active">${icon('home')} Resumen</span><span class="v443-nav-pill">${icon('chart')} Analítica avanzada</span><span class="v443-nav-pill">${icon('card')} Patrimonio</span><span class="v443-nav-pill">${icon('calendar')} Suscripciones</span></div></div>
  <label class="v443-nav-range-label" for="v443-nav-slider"><span>Solo resalta el activo</span><span>Barra más visible</span></label>
  <input id="v443-nav-slider" type="range" min="0" max="100" step="1" value="${value}" aria-label="Intensidad de barras de navegación web" aria-valuetext="${tone}" style="--v443-slider-progress:${value}%">
  <div class="v443-nav-extremes"><span>0% · casi apagada</span><span>100% · presencia alta</span></div>
  <div class="v443-nav-presets" role="group" aria-label="Niveles sugeridos"><button type="button" data-v443-nav-preset="0">Apagada</button><button type="button" data-v443-nav-preset="18">Suave</button><button type="button" data-v443-nav-preset="45">Media</button><button type="button" data-v443-nav-preset="72">Marcada</button></div>
 </section>`;
}
document.addEventListener('input',event=>{
 const slider=event.target;
 if(slider?.id!=='v443-nav-slider')return;
 const n=v443NavApply(slider.value), tone=v443NavTone(n);
 slider.style.setProperty('--v443-slider-progress',n+'%');
 slider.setAttribute('aria-valuetext',tone);
 const output=document.getElementById('v443-nav-value'); if(output) output.textContent=tone;
});
document.addEventListener('click',event=>{
 const btn=event.target.closest('[data-v443-nav-preset]');
 if(!btn)return;
 const slider=document.getElementById('v443-nav-slider'); if(!slider)return;
 slider.value=btn.dataset.v443NavPreset;
 const n=v443NavApply(slider.value), tone=v443NavTone(n);
 slider.style.setProperty('--v443-slider-progress',n+'%');
 slider.setAttribute('aria-valuetext',tone);
 const output=document.getElementById('v443-nav-value'); if(output) output.textContent=tone;
 const prev=v443NavLevel(db.settings.webNavGlassLevel ?? 0);
 if(n!==prev){db.settings.webNavGlassLevel=n; if(!persist()){db.settings.webNavGlassLevel=prev; v443NavApply(prev); slider.value=String(prev); slider.style.setProperty('--v443-slider-progress',prev+'%'); if(output)output.textContent=v443NavTone(prev); toast('No se pudo guardar la intensidad de navegación.');}}
});
document.addEventListener('change',event=>{
 const slider=event.target;
 if(slider?.id!=='v443-nav-slider')return;
 const prev=v443NavLevel(db.settings.webNavGlassLevel ?? 0);
 const next=v443NavLevel(slider.value);
 if(next===prev)return;
 db.settings.webNavGlassLevel=next;
 if(!persist()){
  db.settings.webNavGlassLevel=prev;
  slider.value=String(prev); slider.style.setProperty('--v443-slider-progress',prev+'%');
  slider.setAttribute('aria-valuetext',v443NavTone(prev));
  const output=document.getElementById('v443-nav-value'); if(output) output.textContent=v443NavTone(prev);
  v443NavApply(prev);
  toast('No se pudo guardar la intensidad de navegación.');
 }
});


