 <linearGradient id="${g}-pink" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ffb5ff"/><stop offset=".45" stop-color="#9f69f9"/><stop offset="1" stop-color="#5842b4"/></linearGradient>
