/* V726 · Perfil y cuentas registradas. Fuente: estado financiero de sesión
   recuperado de Supabase; no añade lecturas, tablas ni conexiones. */
let v726LinkedFilter='all';
let v726ProfileEditing=false;
const v726CleanText=(v,max=110)=>String(v??'').trim().slice(0,max);
function v726AccentColor(){const s=db?.settings||{};const predefined={original:'#6866f3',emerald:'#087f75',coral:'#bd4f70'};return s.paletteChoice==='custom'&&/^#[0-9a-f]{6}$/i.test(s.paletteHex||'')?s.paletteHex:(predefined[s.paletteChoice]||predefined.original)}
function v726ProfileInfo(){
 const user=(typeof f33User!=='undefined'&&f33User)||null;
 const m=user?.user_metadata||{};
 const preferred=[m.full_name,m.name,m.display_name,db?.settings?.userName,db?.settings?.ownerName].find(x=>typeof x==='string'&&x.trim());
 const name=preferred?v726CleanText(preferred,75):(user?.email?v726CleanText(user.email,75):'Mi perfil');
 const avatar=String(m.avatar_url||m.picture||'').trim();
 return {name,email:v726CleanText(user?.email||'',110),avatar:/^https:\/\//i.test(avatar)&&avatar.length<1700?avatar:'',connected:!!f33Active};
}
function v726Initials(v){return (String(v||'').split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('')||'VF').toUpperCase()}
function v726ProfileCard(){
 const p=v726ProfileInfo(),banks=(db.banks||[]).filter(x=>!x.archived).length;
 const products=['accounts','cards','loans','certificates'].reduce((n,k)=>n+(db[k]||[]).filter(x=>!x.archived).length,0);
 // Reutiliza el cálculo financiero existente; nunca muestra metas inventadas.
 let patrimonio='—';
 try { const v=widgetPicture('netPosition'); if(v&&v.value) patrimonio=String(v.value); }catch(err){console.warn('Patrimonio temporalmente no disponible',err)}
 return `<section class="v726-profile-card" aria-label="Mi perfil financiero">
  <div class="v726-profile-head"><div class="v726-avatar-wrap"><span class="v726-profile-avatar"><span aria-hidden="true" class="v726-avatar-initial">${sanitize(v726Initials(p.name))}</span>${p.avatar?`<img src="${sanitize(p.avatar)}" alt="Foto de perfil" referrerpolicy="no-referrer" loading="lazy" onerror="this.remove()">`:``}</span><i class="v726-online ${p.connected?'is-connected':''}" aria-label="${p.connected?'Sesión conectada':'Conexión pendiente'}"></i></div>
  <div class="v726-profile-copy"><strong>${sanitize(p.name)}</strong><small>${p.email?sanitize(p.email):'Cuenta personal'}</small><span class="v726-profile-state">${icon('shield')} ${p.connected?'Sesión protegida':'Verificando conexión'}</span></div>
  <button type="button" class="v726-profile-edit" data-v726-profile-edit="1" aria-label="Editar perfil">${icon('edit')}</button></div>
  <div class="v726-profile-stats"><div><small>Patrimonio</small><strong>${sanitize(patrimonio)}</strong></div><div><small>Cuentas vinculadas</small><strong>${banks}</strong></div><div><small>Productos activos</small><strong>${products}</strong></div></div>
 </section>`;
}
function v726LinkedRecords(){
 const source=[['banks','bank','Institución','building'],['accounts','account','Cuenta','wallet'],['cards','card','Tarjeta','card'],['loans','loan','Préstamo','chart'],['certificates','certificate','Certificado','receipt']];
 const rows=[];
 for(const [collection,kind,type,ico] of source)for(const p of db[collection]||[]){
  if(!p||!p.id)continue;
  if(kind==='account'&&p.kind==='cash')continue; // Efectivo del sistema no es una cuenta bancaria vinculada
  rows.push({id:String(p.id),kind,collection,type,ico,archived:!!p.archived,name:v726CleanText(p.name||p.title||type,120),bank:kind==='bank'?'Institución registrada':bankOf(p)});
 }
 return rows.sort((a,b)=>Number(a.archived)-Number(b.archived)||a.name.localeCompare(b.name,'es'));
}
function v726LinkedStrip(){
 const rows=v726LinkedRecords(),count=rows.filter(x=>!x.archived).length;
 const institutions=(db.banks||[]).filter(x=>!x.archived).slice(0,5);
 return `<section class="v726-linked-section" aria-label="Cuentas vinculadas"><div class="v726-section-line"><span class="v242-group-caption">CUENTAS VINCULADAS</span><button type="button" class="v726-manage-link" data-v242-section="linked">Gestionar ${icon('arrow')}</button></div>
 <div class="v726-linked-strip"><button type="button" class="v726-linked-mini v730-apple-mini" data-v726-open-apple-pay="1" aria-label="Abrir configuración de Apple Pay"><span class="v730-apple-wordmark" aria-hidden="true"><svg viewBox="0 0 26 32" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><path d="M16.68 10.55c-2.53 0-4.14 1.52-6.29 1.52-2.19 0-3.43-1.47-6.15-1.21C.88 11.55-.26 15.94.26 20.18c.74 5.16 3.98 11.5 7.67 11.5 1.96 0 2.75-1.22 5.16-1.22 2.23 0 3.14 1.22 5.16 1.22 3.28 0 5.59-4.13 7.17-8.16-3.95-1.43-5.24-6.62-1.4-9.46-1.58-2.39-4.05-3.41-7.34-3.51Z"/><path d="M13.59 8.68c.09-4.14 2.8-6.88 6.87-7.8.31 4.03-2.47 7.28-6.87 7.8Z"/></svg><span>Pay</span></span><small>Apple Pay</small><span class="v730-mini-arrow" aria-hidden="true">›</span></button>${institutions.length?institutions.map(x=>`<button type="button" class="v726-linked-mini" data-v726-linked-open="bank" data-v726-id="${sanitize(x.id)}"><span class="v726-bank-mark">${bankLogoMark(x,'v726-mini-logo')}</span><small>${sanitize(v726CleanText(x.name,26))}</small><span class="v726-mini-dot" title="Registrada, no necesariamente conectada al banco"></span></button>`).join(''):`<div class="v726-empty-mini">Todavía no hay instituciones activas registradas.</div>`}</div>
 <p class="v726-linked-meta">${count} registros activos · ${rows.length-count} ${rows.length-count===1?'archivado':'archivados'}. Los productos se muestran desde tus datos financieros, sin conexión bancaria automática.</p></section>`;
}
function v726LinkedPage(){
 const rows=v726LinkedRecords(),filter=v726LinkedFilter;
 const visible=rows.filter(x=>filter==='all'||(filter==='active'?!x.archived:x.archived));
 const countActive=rows.filter(x=>!x.archived).length;
 return `<div class="v726-linked-page" aria-label="Gestión de cuentas vinculadas"><div class="v726-linked-intro"><span class="v726-kicker">TUS REGISTROS FINANCIEROS</span><h2>Productos registrados</h2><p>Consulta tus instituciones y productos registrados. Archivar conserva movimientos, pagos e historial.</p></div>
 <div class="v730-apple-access"><button type="button" data-v726-open-apple-pay="1"><span class="v730-apple-wordmark" aria-hidden="true"><svg viewBox="0 0 26 32" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><path d="M16.68 10.55c-2.53 0-4.14 1.52-6.29 1.52-2.19 0-3.43-1.47-6.15-1.21C.88 11.55-.26 15.94.26 20.18c.74 5.16 3.98 11.5 7.67 11.5 1.96 0 2.75-1.22 5.16-1.22 2.23 0 3.14 1.22 5.16 1.22 3.28 0 5.59-4.13 7.17-8.16-3.95-1.43-5.24-6.62-1.4-9.46-1.58-2.39-4.05-3.41-7.34-3.51Z"/><path d="M13.59 8.68c.09-4.14 2.8-6.88 6.87-7.8.31 4.03-2.47 7.28-6.87 7.8Z"/></svg><span>Pay</span></span><span><strong>Apple Pay</strong><small>Gestionar integración y tarjetas asociadas</small></span><span aria-hidden="true">›</span></button></div>
 <div class="v726-linked-tabs" role="group" aria-label="Estado de productos">${[['all','Todas',rows.length],['active','Activas',countActive],['archived','Archivadas',rows.length-countActive]].map(([v,label,n])=>`<button type="button" class="${filter===v?'is-active':''}" data-v726-linked-filter="${v}" aria-pressed="${filter===v}">${label} <small>${n}</small></button>`).join('')}</div>
 <div class="v726-linked-list">${visible.length?visible.map(x=>`<article class="v726-linked-record"><span class="v726-linked-icon">${x.kind==='bank'?bankLogoMark((db.banks||[]).find(b=>String(b.id)===x.id),'v726-record-logo'):icon(x.ico)}</span><div class="v726-linked-detail"><strong>${sanitize(x.name)}</strong><small>${sanitize(x.type)} · ${sanitize(v726CleanText(x.bank,70))}</small><span class="v726-linked-status ${x.archived?'is-archived':''}">${x.archived?'Archivada':'Activa'}</span></div><div class="v726-linked-actions"><button type="button" data-v726-linked-open="${x.kind}" data-v726-id="${sanitize(x.id)}" aria-label="Consultar ${sanitize(x.name)}">Ver</button><button type="button" data-v726-linked-toggle="${x.kind}" data-v726-id="${sanitize(x.id)}">${x.archived?'Reactivar':'Archivar'}</button></div></article>`).join(''):`<div class="v726-linked-empty">No hay productos en esta categoría.</div>`}</div>
 <p class="v726-linked-note">«Vinculadas» significa registradas en tus finanzas. No implica que exista una conexión bancaria o sincronización bancaria automática.</p></div>`;
}
function v726NotificationsPane(){return `<section class="v726-notifications-panel"><div class="v726-kicker">AVISOS DE LA APLICACIÓN</div><h2>Notificaciones</h2><p>Las alertas de vencimientos y compromisos se muestran dentro de la aplicación. No se reactivará el sistema antiguo de notificaciones push.</p><button type="button" class="btn soft" data-v726-open-bell="1">${icon('receipt')} Consultar avisos de la campanita</button></section>`}
function v726ProfilePane(){
 const p=v726ProfileInfo();
 return `<div class="v726-profile-pane">${v726ProfileCard()}${v726ProfileEditing?`<form id="v726ProfileForm" class="v726-profile-form"><label>Nombre para mostrar<input name="name" type="text" maxlength="75" required value="${sanitize(p.name)}" autocomplete="name"></label><label>Foto de perfil (URL HTTPS, opcional)<input name="avatar" type="url" maxlength="1700" placeholder="https://..." value="${sanitize(p.avatar)}"></label><div class="v726-profile-form-actions"><button type="submit" class="btn">Guardar perfil</button><button type="button" class="btn soft" data-v726-profile-cancel="1">Cancelar</button></div><p>Los datos de perfil se guardan en tu cuenta de Supabase Auth; no alteran movimientos ni saldos.</p></form>`:`<div class="v726-profile-quick"><button type="button" data-v726-profile-edit="1">${icon('edit')} Editar nombre y fotografía</button><button type="button" data-v242-section="linked">${icon('building')} Gestionar productos registrados</button></div>`}${f34CloudPanel()}</div>`;
}

function v242Settings(){
 const s=db.settings,pane=V242_PANES.some(x=>x[0]===v242SettingsPane)?v242SettingsPane:'home';
 const desktopSettings=!isMobileViewport();
 const activeDesktopPane=desktopSettings&&pane==='home'?'appearance':pane;
 const paneInfo=V242_PANES.find(x=>x[0]===activeDesktopPane);
 const tile=(entry)=>`<button class="v242-settings-row" type="button" data-v242-section="${entry[0]}"><span class="v242-settings-symbol v242-symbol-${entry[0]}">${icon(entry[3])}</span><span class="v242-settings-row-copy"><strong>${entry[1]}</strong><small>${entry[2]}</small></span><span class="v242-settings-chevron" aria-hidden="true">›</span></button>`;
 const content={
  appearance:()=>`${v300AppearancePane()}`,
  profile:()=>`${v726ProfilePane()}`,
  notifications:()=>`${v726NotificationsPane()}`,
  linked:()=>`${v726LinkedPage()}`,
  integrations:()=>`${v212SettingsPanel()}`,
  financial:()=>`<div class="settings-group-title" id="v176-setting-04"><div><span class="summary-tag">04 / REGLAS FINANCIERAS</span><h3>Tasas, transferencias y cargos</h3></div></div>
${f34FxPanel()}<div class="panel settings-finance"><form id="settingsForm"><div class="form-grid">${formItem('fx','RD$ por cada US$1 · tasa de referencia',s.fx,'number','required min="0.001" step="0.0001"')}${formItem('transferTaxPct','Impuesto de transferencias y pagos bancarios (%)',num(s.transferTaxPct),'number','required min="0" max="100" step="0.001"')}</div><div class="settings-explain">El impuesto general a determinadas transferencias es <b>0.20% desde el 3 de julio de 2026</b> (era 0.15%); no todas las operaciones están gravadas. Las transferencias entre cuentas propias y los consumos con tarjeta pueden estar exentos. Para pagos de tarjeta desde cuenta bancaria, Internet Banking utiliza la tasa manual de este ajuste y Presencial no genera este impuesto en la aplicación; verifica posibles excepciones según el banco. No existe una comisión fija general. <b>Pago al instante</b> es una modalidad que puedes elegir en cada transferencia y agrega RD$100 solamente cuando la seleccionas. Ejemplo: una transferencia gravada de RD$10,000 con Pago al instante suma RD$20 de impuesto y RD$100 por esa modalidad, totalizando RD$10,120. La tasa USD/DOP se consulta automáticamente y solo se usa para valoración y nuevas conversiones. Los movimientos históricos conservan la tasa registrada en cada operación.</div><div class="form-foot"><button class="btn" type="submit">Guardar configuración financiera</button></div></form></div>
`,
  security:()=>`<div class="settings-group-title" id="v176-setting-05"><div><span class="summary-tag">05 / CENTRO DE REVISIÓN</span><h3>Protección y coherencia financiera</h3></div></div>${v30ReviewContent(true)}${v30RecoveryContent()}
<div class="settings-group-title" id="v176-setting-06"><div><span class="summary-tag">06 / HISTORIAL Y PRIVACIDAD</span><h3>Control de productos y registros</h3></div></div>
<div class="grid columns equal"><div class="panel"><div class="panel-head"><h3>Productos archivados</h3></div><p class="form-note">Desactivar una relación financiera no debe eliminar sus transacciones. Los productos archivados permanecen en cálculos históricos, aunque se oculten de los listados habituales.</p>${visibilityControl()}<p class="form-note">Archivados: ${[...db.banks,...db.accounts,...db.cards,...db.loans,...db.certificates].filter(x=>x.archived).length}. La eliminación definitiva solo se permite cuando no hay operaciones ni saldos iniciales o dependencias.</p></div><div class="panel"><div class="panel-head"><h3>Protección y respaldo</h3></div><p class="form-note">Respalda tus datos JSON antes de modificar contratos o importar versiones nuevas. El respaldo local no está cifrado.</p><div class="hstack"><button class="btn soft" data-act="export" title="Descargar una copia de seguridad de todos tus registros en JSON">${icon('download')} Descargar respaldo JSON</button><button class="btn ghost" data-act="import">${icon('upload')} Importar JSON</button></div><div class="mini-divider"></div><div class="hstack"><button class="btn ghost" data-act="demo">Demostración</button><button class="btn danger" data-act="clear">Eliminar todos los datos</button></div><input id="importFile" type="file" accept="application/json,.json" class="hidden" /></div></div>
`,
  about:()=>`<div class="panel section v1300-milestone"><span class="v1300-milestone-date">14 de noviembre de 2026</span><strong>Hoy se marcó un gran cambio</strong></div><div class="panel section"><div class="panel-head"><h3>Información guardada</h3></div><div class="settings-counts">${[['Instituciones',db.banks.length],['Cuentas',db.accounts.length],['Tarjetas',db.cards.length],['Préstamos',db.loans.length],['Certificados',db.certificates.length],['Movimientos',db.transactions.length],['Suscripciones',db.recurring.length]].map(([l,n])=>`<div><span>${l}</span><strong>${n}</strong></div>`).join('')}</div><div class="notification warning">vive el hoy es local: no consulta bancos en tiempo real, no ejecuta pagos ni comprueba automáticamente impuestos. No guardes CVV, PIN, contraseñas ni números completos.</div></div>`
 };
 let sectionBody='';
 try{ sectionBody=(content[activeDesktopPane]||(()=>''))(); }
 catch(error){
  console.error('Error al mostrar la sección de Configuración:',pane,error);
  sectionBody='<section class="panel section v3-settings-recovery" role="alert"><h3>No fue posible cargar esta sección</h3><p>Las demás opciones siguen disponibles. Vuelve al menú de Configuración e intenta nuevamente.</p><button type="button" class="btn soft" data-v242-back="1">Volver a Configuración</button></section>';
 }
 const title=paneInfo?.[1]||'Configuración';
 if(desktopSettings){
  const desktopTile=(entry)=>`<button type="button" class="v439-mac-item ${activeDesktopPane===entry[0]?'is-active':''}" data-v242-section="${entry[0]}" aria-current="${activeDesktopPane===entry[0]?'page':'false'}"><span class="v439-mac-item-icon v242-settings-symbol v242-symbol-${entry[0]}">${icon(entry[3])}</span><span class="v439-mac-item-copy"><strong>${entry[1]}</strong><small>${entry[4]}</small></span><span class="v439-mac-item-arrow" aria-hidden="true">›</span></button>`;
  const groups=[['CUENTA',['profile']],['PERSONALIZACIÓN',['appearance','notifications']],['SERVICIOS',['integrations','financial']],['PRIVACIDAD Y AYUDA',['security','about']],['CUENTAS VINCULADAS',['linked']]];
  return `<div class="settings-layout v242-ios-settings v439-macos-settings" style="--v726-accent:${v726AccentColor()}" data-v242-settings="${activeDesktopPane}">
    <header class="v439-mac-top"><div><span class="v439-mac-eyebrow">vive el hoy</span><h1>Configuración</h1><p>Tus preferencias, organizadas en un solo lugar.</p></div></header>
    <div class="v439-mac-workspace"><aside class="v439-mac-sidebar" aria-label="Secciones de Configuración"><div class="v439-mac-sidehead"><span class="v439-mac-avatar">${icon('wallet')}</span><span><strong>${sanitize(v726ProfileInfo().name)}</strong><small>Ajustes y preferencias</small></span></div><nav aria-label="Categorías de Configuración">${groups.map(([label,ids])=>`<div class="v439-mac-group"><p>${label}</p>${V242_PANES.filter(x=>ids.includes(x[0])).map(desktopTile).join('')}</div>`).join('')}</nav><div class="v439-mac-sidefoot">${icon('shield')} Datos vinculados a tu sesión</div></aside>
    <main class="v439-mac-detail" id="v439-settings-detail" tabindex="-1" aria-label="${title}"><header class="v439-mac-detail-head"><span class="v439-mac-eyebrow">${paneInfo?.[4]||'Preferencias'}</span><h2>${title}</h2><p>${paneInfo?.[2]||''}</p></header><div class="v242-settings-inner v439-mac-detail-body">${sectionBody}</div></main></div>
  </div>`;
 }
 return `<div class="settings-layout v242-ios-settings" style="--v726-accent:${v726AccentColor()}" data-v242-settings="${pane}">
 ${pane==='home'?`<div class="v242-settings-home"><header class="v242-settings-intro"><span class="v242-settings-eyebrow">vive el hoy</span><h1>Configuración</h1><p>Todo a tu manera, con la claridad de Ajustes de iPhone.</p></header>${v726ProfileCard()}<div class="v242-settings-section"><span class="v242-group-caption">APARIENCIA</span><div class="v242-settings-rows">${V242_PANES.filter(x=>x[0]==='appearance').map(tile).join('')}</div></div><div class="v242-settings-section"><span class="v242-group-caption">NOTIFICACIONES</span><div class="v242-settings-rows">${V242_PANES.filter(x=>x[0]==='notifications').map(tile).join('')}</div></div><div class="v242-settings-section"><span class="v242-group-caption">CONEXIONES Y FINANZAS</span><div class="v242-settings-rows">${V242_PANES.filter(x=>['integrations','financial'].includes(x[0])).map(tile).join('')}</div></div><div class="v242-settings-section"><span class="v242-group-caption">PRIVACIDAD Y SOPORTE</span><div class="v242-settings-rows">${V242_PANES.filter(x=>['security','about'].includes(x[0])).map(tile).join('')}</div></div>${v726LinkedStrip()}<p class="v242-settings-footer">Tus registros y operaciones financieras se mantienen protegidos por las reglas actuales de la aplicación.</p></div>`:
 `<div class="v242-settings-subpage"><header class="v242-settings-subhead"><button type="button" class="v242-settings-back" data-v242-back="1">‹ <span>Configuración</span></button><span class="v242-settings-eyebrow">${paneInfo?.[4]||'Preferencias'}</span><h1>${title}</h1><p>${paneInfo?.[2]||''}</p></header><div class="v242-settings-inner">${sectionBody}</div></div>`}
 </div>`;
}

document.addEventListener('click',event=>{
 const opener=event.target.closest('[data-v273-open-personalization]');
 const toggle=event.target.closest('[data-v273-toggle]');
 const move=event.target.closest('[data-v273-move]');
 const reset=event.target.closest('[data-v273-reset]');
 const resetAll=event.target.closest('[data-v883-reset-all]');
 if(!opener&&!toggle&&!move&&!reset&&!resetAll)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(opener){ui.page=isMobileViewport()?'personalize':'settings';ui.mobile=false;if(!isMobileViewport())v242SettingsPane='appearance';render();window.scrollTo(0,0);return}
 const cfg=v105Config();
 if(toggle){const id=toggle.dataset.v273Toggle;if(!cfg.order.includes(id))return;cfg.visible=cfg.visible.includes(id)?cfg.visible.filter(x=>x!==id):[...cfg.visible,id]}
 else if(move){const id=move.dataset.id,i=cfg.order.indexOf(id),j=i+(move.dataset.v273Move==='up'?-1:1);if(i<0||j<0||j>=cfg.order.length)return;[cfg.order[i],cfg.order[j]]=[cfg.order[j],cfg.order[i]]}
 else if(reset){const ids=V105_WIDGETS.map(x=>x.id);cfg.order=[...ids.filter(id=>cfg.order.includes(id)),...cfg.order.filter(id=>!ids.includes(id))]}
 else if(resetAll){const ids=V105_WIDGETS.map(x=>x.id);cfg.order=['applePayInbox',...v316OrderDefaults(ids).filter(id=>id!=='applePayInbox')];cfg.visible=ids.slice()}
 const old=db.settings.v105OverviewWidgets;
 db.settings.v105OverviewWidgets={order:cfg.order.slice(),visible:cfg.visible.slice()};
 if(!persist()){db.settings.v105OverviewWidgets=old;toast('No se pudieron guardar los cambios de personalización.');return}
 render();
 if(resetAll)toast('Restaurados todos los indicadores y su orden inicial.');
},true);


/* V294 · PERSONALIZACIÓN FINANCIERA + DESTINO VISIÓN
   Presentación y navegación solamente. No se modifica el almacén de movimientos,
   contratos, saldos, fórmulas, Supabase ni los procesos de pago. */
function v294BankingWidgets(){
 const active=x=>Array.isArray(x)?x.filter(p=>p&&!p.archived&&!isHidden(p)):[];
 const banks=active(db.banks),accounts=active(db.accounts),cards=active(db.cards),loans=active(db.loans),certificates=active(db.certificates);
 const amount=a=>{try{return Number(getAccountBalance(a))||0}catch(_){return 0}};
 const cardDebt=c=>{try{return Math.max(0,Number(cardStatus(c,'DOP').debt)||0)+Math.max(0,fx(Number(cardStatus(c,'USD').debt)||0,'USD'))}catch(_){return 0}};
 const loanBalance=l=>{try{return Math.max(0,fx(Number(loanStatus(l).balance)||0,l.currency||'DOP'))}catch(_){return 0}};
 const accountTotal=accounts.reduce((sum,a)=>sum+fx(amount(a),a.currency||'DOP'),0);
 const cardTotal=cards.reduce((sum,c)=>sum+cardDebt(c),0);
 const loanTotal=loans.reduce((sum,l)=>sum+loanBalance(l),0);
 const certificateTotal=totalCertificates();
 const linked=banks.reduce((sum,b)=>sum+accounts.filter(a=>a.bankId===b.id).length+cards.filter(c=>c.bankId===b.id).length+loans.filter(l=>l.bankId===b.id).length,0);
 const layouts=[
  {id:'banks',title:'Bancos e instituciones',eyebrow:'TU ECOSISTEMA',page:'banks',icon:'building',count:banks.length,amount:String(banks.length),unit:'instituciones activas',hint:`${linked} productos vinculados · posición neta por banco`,items:banks.map(b=>({name:b.name||'Institución',value:money(accounts.filter(a=>a.bankId===b.id).reduce((v,a)=>v+fx(amount(a),a.currency||'DOP'),0)+certificates.filter(c=>c.bankId===b.id).reduce((v,c)=>v+fx(num(certProjection(c).capital),c.currency||'DOP'),0)-cards.filter(c=>c.bankId===b.id).reduce((v,c)=>v+cardDebt(c),0)-loans.filter(l=>l.bankId===b.id).reduce((v,l)=>v+loanBalance(l),0))}))},
  {id:'accounts',title:'Cuentas y efectivo',eyebrow:'DISPONIBILIDAD',page:'accounts',icon:'wallet',count:accounts.length,amount:money(accountTotal),unit:'saldo en RD$ equivalentes',hint:`${accounts.length} cuentas y efectivos`,items:accounts.slice(0,3).map(a=>({name:a.name||'Cuenta',value:money(amount(a),a.currency||'DOP')}))},
  {id:'cards',title:'Mis tarjetas',eyebrow:'CRÉDITO',page:'cards',icon:'card',count:cards.length,amount:money(cardTotal),unit:'deuda utilizada',hint:`${cards.length} tarjetas registradas`,items:cards.slice(0,3).map(c=>({name:c.name||'Tarjeta',value:money(cardDebt(c))}))},
  {id:'loans',title:'Préstamos bancarios',eyebrow:'FINANCIAMIENTO',page:'loans',icon:'receipt',count:loans.length,amount:money(loanTotal),unit:'saldo pendiente equivalente',hint:`${loans.length} contratos activos`,items:loans.slice(0,3).map(l=>({name:l.name||'Préstamo',value:money(loanBalance(l))}))},
  {id:'certificates',title:'Certificados',eyebrow:'AHORRO E INVERSIÓN',page:'certificates',icon:'analytics',count:certificates.length,amount:money(certificateTotal),unit:'capital registrado equivalente',hint:`${certificates.length} certificados activos`,items:certificates.slice(0,3).map(c=>({name:c.name||'Certificado',value:'Activo'}))}
 ];
 return layouts.filter(w=>w.id!=='cards').map(w=>`<section class="v105-mobile-extra v273-overview-widget v294-finance-widget" data-v105-widget="${w.id}" aria-label="${w.title}">
  <div class="vive-mobile-card-head v294-widget-head"><div><span class="vive-mobile-eyebrow">${w.eyebrow}</span><h2>${w.title}</h2></div><button type="button" class="vive-mobile-view-all" data-act="navigate" data-id="${w.page}" aria-label="Abrir ${w.title}">${icon('arrow')}</button></div>
  <div class="v294-widget-amount"><span class="v294-widget-ico">${icon(w.icon)}</span><div><strong>${w.amount}</strong><small>${w.unit}</small></div></div>
  <span class="v294-widget-count">${w.hint}</span>
  ${w.id==='banks'?'<span class="v309-bank-note">Posición neta = saldos + activos vinculados − deudas. Cifras en RD$ equivalentes.</span>':''}${w.items.length?`<div class="v294-widget-list">${w.items.map(r=>`<div><span>${sanitize(r.name)}</span><b>${r.value}</b></div>`).join('')}</div>`:`<p class="v273-widget-empty">No hay productos activos de este tipo.</p>`}
 </section>`).join('');
}

/* V315 — Solo dos gráficos útiles en el Resumen móvil.
   Los cálculos toman saldos y límites reales, no importes de demostración.
   La serie patrimonial usa el mismo cierre histórico que la vista Patrimonio. */
function v309ExtraCharts(){
 const active=v=>(Array.isArray(v)?v:[]).filter(x=>x&&!x.archived&&!isHidden(x));
 const cards=active(db.cards);
 const safe=v=>Number.isFinite(Number(v))?Number(v):0;
 const debt=c=>Math.max(0,safe(cardStatus(c,'DOP').debt))+Math.max(0,fx(safe(cardStatus(c,'USD').debt),'USD'));
 const limit=c=>Math.max(0,safe(c.limitDOP))+Math.max(0,fx(safe(c.limitUSD),'USD'));
 const details=cards.map(c=>({name:c.name||'Tarjeta',used:debt(c),max:limit(c)}));
 const totalLimit=details.reduce((t,c)=>t+c.max,0);
 const totalUsed=details.reduce((t,c)=>t+c.used,0);
 const available=Math.max(0,totalLimit-totalUsed);
 const pct=totalLimit>0?totalUsed/totalLimit*100:null;
 const pctText=n=>n===null?'—':new Intl.NumberFormat('es-DO',{minimumFractionDigits:1,maximumFractionDigits:1}).format(n)+'%';
 const fill=n=>Math.max(0,Math.min(100,n||0));
 const displayMoney=n=>money(n,'DOP',0);
 const creditHTML=totalLimit<=0?'<p class="v315-empty">Registra los límites de tus tarjetas para conocer la utilización real del crédito.</p>':`
  <div class="v315-credit-hero">
   <div><small>LÍMITE TOTAL</small><strong>${displayMoney(totalLimit)}</strong></div>
   <div><small>UTILIZADO</small><strong>${displayMoney(totalUsed)}</strong></div>
   <div><small>DISPONIBLE</small><strong>${displayMoney(available)}</strong></div>
  </div>
  <div class="v315-credit-overall"><div><span>Utilización conjunta</span><strong class="${pct>100?'v315-warn':''}">${pctText(pct)}</strong></div><div class="v315-credit-track"><i style="width:${fill(pct)}%" class="${pct>100?'v315-credit-over':''}"></i></div></div>
  <div class="v315-credit-rows">${details.map(c=>{
    const ratio=c.max>0?100*c.used/c.max:null;
    return `<div class="v315-credit-row" title="${sanitize(c.name)} · límite ${displayMoney(c.max)} · utilizado ${displayMoney(c.used)}">
     <div class="v315-credit-row-head"><span>${sanitize(c.name)}</span><strong class="${ratio!==null&&ratio>100?'v315-warn':''}">${pctText(ratio)}</strong></div>
     <div class="v315-credit-track"><i style="width:${fill(ratio)}%" class="${ratio!==null&&ratio>100?'v315-credit-over':''}"></i></div>
     <div class="v315-credit-row-foot"><span>Usado ${displayMoney(c.used)}</span><span>Límite ${displayMoney(c.max)}</span></div>
    </div>`}).join('')}</div>`;
 const cardSection=`<section class="v105-mobile-extra v273-overview-widget v309-graph-widget v315-chart-widget" data-v105-widget="creditUtil" aria-label="Utilización total y por tarjeta">
  <div class="vive-mobile-card-head"><div><span class="vive-mobile-eyebrow">CRÉDITO · UTILIZACIÓN</span><h2>Utilización por tarjeta</h2></div><button type="button" class="vive-mobile-view-all" data-act="navigate" data-id="cards" aria-label="Ver detalles de tarjetas">Ver tarjetas ${icon('arrow')}</button></div>${creditHTML}
 </section>`;
 // Máximo 6 cierres recientes; un mes sin histórico real queda sin punto.
 const now=today();const [y,m]=now.slice(0,7).split('-').map(Number);
 const labels=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
 const months=Array.from({length:6},(_,i)=>{const d=new Date(y,m-1-(5-i),1);return {p:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'),label:labels[d.getMonth()]}});
 const series=months.map(x=>({label:x.label,period:x.p,snapshot:v134WealthMonth(x.p).snapshot}));
 const observed=series.filter(x=>x.snapshot&&Number.isFinite(x.snapshot.net));
 const last=observed.at(-1),prev=observed.length>1?observed.at(-2):null;
 let historyHTML='';
 if(!last){historyHTML='<p class="v315-empty">Todavía no hay cierres registrados suficientes para trazar el patrimonio.</p>'}
 else{
  const delta=prev?last.snapshot.net-prev.snapshot.net:null;
  const percentage=delta!==null&&Math.abs(prev.snapshot.net)>.005?delta/Math.abs(prev.snapshot.net)*100:null;
  const vals=observed.map(x=>x.snapshot.net);
  const low=Math.min(...vals),high=Math.max(...vals),spread=Math.max(1,high-low);
  const W=330,H=125,pad=14;
  const xy=(r,i)=>({x:pad+i*(W-2*pad)/(series.length-1),y:pad+(high-r.snapshot.net)/spread*(H-2*pad)});
  const coords=series.map((r,i)=>r.snapshot&&Number.isFinite(r.snapshot.net)?xy(r,i):null);
  // No unir meses sin información; evita interpretar huecos como meses de cero.
  const runs=[];let current=[];
  for(const c of coords){if(c)current.push(c);else if(current.length){runs.push(current);current=[]}}
  if(current.length)runs.push(current);
  const path=runs.map(run=>'<polyline points="'+run.map(p=>p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ')+'"/>').join('');
  const circles=coords.map((p,i)=>p?`<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3.7"><title>${series[i].period}: ${displayMoney(series[i].snapshot.net)}</title></circle>`:'').join('');
  const dClass=delta===null?'':delta>=0?'v315-positive':'v315-negative';
  historyHTML=`<div class="v315-wealth-summary"><div><small>PATRIMONIO NETO · ${last.period}</small><strong class="${last.snapshot.net<0?'v315-warn':''}">${displayMoney(last.snapshot.net)}</strong></div><span class="v315-wealth-delta ${dClass}">${delta===null?'Sin comparación':(delta>0?'+':'')+displayMoney(delta)}${percentage===null?'':' · '+(percentage>0?'+':'')+pctText(percentage)}</span></div>
  <div class="v315-wealth-chart" role="img" aria-label="Tendencia patrimonial de los últimos seis cierres disponibles. Último patrimonio ${displayMoney(last.snapshot.net)}"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><line x1="14" x2="316" y1="111" y2="111" class="v315-wealth-axis"/><g class="v315-wealth-path">${path}</g><g class="v315-wealth-dots">${circles}</g></svg><div class="v315-wealth-labels">${months.map(x=>`<span>${x.label}</span>`).join('')}</div></div>
  <p class="v315-small-note">Cierres de activos menos obligaciones registrados; no incluye límites disponibles como patrimonio.${observed.some(x=>x.snapshot.estimatedLoan)?' Algún préstamo histórico es estimado.':''}</p>`;
 }
 const wealthSection=`<section class="v105-mobile-extra v273-overview-widget v309-graph-widget v315-chart-widget" data-v105-widget="patrimonyTrend" aria-label="Tendencia de patrimonio neto"><div class="vive-mobile-card-head"><div><span class="vive-mobile-eyebrow">PATRIMONIO · EVOLUCIÓN</span><h2>Tendencia de patrimonio</h2></div><button type="button" class="vive-mobile-view-all" data-act="navigate" data-id="patrimony" aria-label="Abrir detalle del patrimonio">Ver detalle ${icon('arrow')}</button></div>${historyHTML}</section>`;
 /* V316 · Gráfico 03/04 — El costo de mañana.
    No equivale a la deuda total: solamente cobros y vencimientos calendarizados. */
 const forecast=v119Baseline(30);
 const fMin=Number.isFinite(forecast.minimum)?forecast.minimum:0;
 const fEnd=Number.isFinite(forecast.ending)?forecast.ending:0;
 const fStart=Number.isFinite(forecast.initial)?forecast.initial:0;
 const fCritical=forecast.critical;
 const fMinLabel=fMin<0?'Faltante máximo':'Mínimo previsto';
 const dayValues=(forecast.dayByDay||[]).filter((r,i)=>i===0||i%3===0||i===forecast.dayByDay.length-1);
 const values=[fStart,...dayValues.map(x=>x.balance)],vLo=Math.min(...values,0),vHi=Math.max(...values,0),vRange=Math.max(1,vHi-vLo);
 const FW=332,FH=90,FP=12;
 const fY=v=>FP+(vHi-v)/vRange*(FH-2*FP);
 const fPoints=dayValues.map((d,i)=>({x:FP+i*(FW-2*FP)/Math.max(1,dayValues.length-1),y:fY(d.balance)}));
 const cashLine=fPoints.map(p=>p.x.toFixed(2)+','+p.y.toFixed(2)).join(' ');
 const zeroY=fY(0).toFixed(2);
 const fLast=fPoints.at(-1);
 const fTimeline=dayValues.length?`<div class="v316-cash-chart"><svg viewBox="0 0 ${FW} ${FH}" preserveAspectRatio="none" role="img" aria-label="Proyección de liquidez diaria a 30 días, desde ${displayMoney(fStart)} hasta ${displayMoney(fEnd)}"><line class="v316-cash-zero" x1="12" x2="320" y1="${zeroY}" y2="${zeroY}"/><polyline class="v316-cash-path ${fMin<0?'at-risk':''}" points="${cashLine}"/><circle class="v316-cash-point" cx="${fLast.x.toFixed(2)}" cy="${fLast.y.toFixed(2)}" r="4"/></svg><div class="v316-cash-axis"><span>Hoy</span><span>+15 días</span><span>+30 días</span></div></div>`:'';
 const tomorrowSection=`<section class="v105-mobile-extra v273-overview-widget v309-graph-widget v315-chart-widget v316-chart-widget v316-tomorrow" data-v105-widget="tomorrowInsight" aria-label="El costo de mañana: proyección de liquidez a 30 días">
  <div class="vive-mobile-card-head"><div><span class="vive-mobile-eyebrow">PROYECCIÓN · 30 DÍAS</span><h2>El costo de mañana</h2></div><button type="button" class="vive-mobile-view-all" data-v119-open="1" aria-label="Abrir simulador del costo de mañana">Simular ${icon('arrow')}</button></div>
  <div class="v316-tomorrow-pair"><div><small>HOY · DISPONIBLE</small><strong>${displayMoney(fStart)}</strong></div><span class="v316-tomorrow-arrow" aria-hidden="true">→</span><div><small>EN 30 DÍAS · ESTIMADO</small><strong class="${fEnd<0?'v316-negative':''}">${displayMoney(fEnd)}</strong></div></div>
  ${fTimeline}
  <div class="v316-tomorrow-foot"><span>${fMinLabel} <b class="${fMin<0?'v316-negative':''}">${displayMoney(Math.abs(fMin))}</b></span><span>${fCritical?'Primer día crítico: '+prettyDate(fCritical):'Sin días críticos previstos'}</span></div>
  <p class="v315-small-note">Proyección, no saldo garantizado: solo incluye cobros y pagos con fecha registrada. Simular no crea movimientos.</p>
 </section>`;

 /* V316 · Gráfico 04/04 — Pulso de ejecución presupuestaria.
    A diferencia de una puntuación, más de 100% indica límite superado. */
 const budget=v290BudgetSnapshot();
 const bPct=budget.percent;
 const angle=bPct===null?0:Math.min(100,Math.max(0,bPct))*3.6;
 const bOver=bPct!==null&&bPct>100;
 const bWarn=bPct!==null&&bPct>=85;
 const bTone=bOver?'over':bWarn?'warn':'calm';
 const bPace=budget.pace===null?'Sin ritmo comparable':budget.pace>0?'Por encima del ritmo esperado':'Dentro del ritmo esperado';
 const bTop=budget.categories.filter(c=>c.limit>0).slice(0,3);
 const bRows=bTop.map(c=>`<div class="v316-budget-category"><div><span>${sanitize(c.name)}</span><b class="${c.percent>100?'v316-negative':''}">${pctText(c.percent)}</b></div><div class="v316-budget-track"><i class="${c.percent>100?'is-over':''}" style="width:${fill(c.percent)}%"></i></div></div>`).join('');
 const budgetSection=`<section class="v105-mobile-extra v273-overview-widget v309-graph-widget v315-chart-widget v316-chart-widget v316-budget" data-v105-widget="budgetPulse" aria-label="Cumplimiento del presupuesto y distribución por categoría">
  <div class="vive-mobile-card-head"><div><span class="vive-mobile-eyebrow">PRESUPUESTO · ${sanitize(budget.month)}</span><h2>Tu pulso presupuestario</h2></div><button type="button" class="vive-mobile-view-all" data-v290-budget-open="execution" aria-label="Ver ejecución del presupuesto">Detalles ${icon('arrow')}</button></div>
  <div class="v316-budget-display"><div class="v316-budget-orbit ${bTone}" style="--v316-angle:${angle}deg" role="img" aria-label="Presupuesto utilizado: ${pctText(bPct)}"><div><small>UTILIZADO</small><strong>${pctText(bPct)}</strong><span>${budget.state}</span></div></div>
   <div class="v316-budget-money"><div><small>ASIGNADO</small><strong>${displayMoney(budget.allocated)}</strong></div><div><small>EJECUTADO</small><strong>${displayMoney(budget.spent)}</strong></div><div><small>${budget.remaining<0?'EXCESO':'DISPONIBLE'}</small><strong class="${budget.remaining<0?'v316-negative':''}">${displayMoney(Math.abs(budget.remaining))}</strong></div></div></div>
  <div class="v316-budget-pace"><span class="v316-pace-dot ${bTone}" aria-hidden="true"></span><span>${bPace}${budget.pace!==null?' · '+displayMoney(Math.abs(budget.pace))+' de diferencia':''}</span></div>
  ${bRows?`<div class="v316-budget-categories"><div class="v316-mini-eyebrow">CATEGORÍAS CON MAYOR CONSUMO</div>${bRows}</div>`:'<p class="v315-empty">Define un presupuesto para ver cómo se distribuye tu gasto.</p>'}
  <p class="v315-small-note">El porcentaje representa gasto / límite asignado. Los gastos sin presupuesto quedan fuera del porcentaje; no se duplican subcategorías.</p>
 </section>`;
 /* V317 · NUEVOS GRÁFICOS: radar de vencimientos y huella de gasto registrado.
    Se calculan en el dispositivo a partir de las mismas fuentes de la app. */
 const v317DueEvents=(forecast.events||[]).filter(e=>e.type==='expense'&&e.amount>0);
 const v317Limits=[7,15,30];
 const v317Buckets=v317Limits.map((limit,i)=>{
  const start=i? v317Limits[i-1]+1:0;
  const end=v119DateAfter(limit),from=v119DateAfter(start);
  const arr=v317DueEvents.filter(e=>e.date>=from&&e.date<=end);
  return {label:i===0?'0–7 días':i===1?'8–15 días':'16–30 días',start,end,total:arr.reduce((sum,e)=>sum+e.amount,0),count:arr.length};
 });
 const v317DueTotal=v317Buckets.reduce((a,b)=>a+b.total,0);
 const v317MaxDue=Math.max(1,...v317Buckets.map(x=>x.total));
 const v317DueBars=v317Buckets.map((d,i)=>`<div class="v317-due-col" data-v1126-bucket="${i}" role="button" tabindex="0" aria-label="Ver desglose de ${d.label}"><div class="v317-due-value">${displayMoney(d.total)}</div><div class="v317-due-tower"><i style="height:${d.total>0?Math.max(5,100*d.total/v317MaxDue):0}%" class="${i===0?'is-urgent':''}"></i></div><b>${d.label}</b><span>${d.count} ${d.count===1?'cargo':'cargos'}</span></div>`).join('');
 const v317Upcoming=v317DueEvents.slice(0,3).map(e=>{const pay=v1127Target(e.key);return pay?`<button type="button" class="v317-next-pay v1127-payable" data-v1127-pay="${sanitize(e.key)}" aria-label="Pagar ${sanitize(e.name||'compromiso')}"><span>${sanitize(prettyDate(e.date))} · ${sanitize(e.name||'Compromiso')}</span><strong>${displayMoney(e.amount)}</strong></button>`:`<div class="v317-next-pay"><span>${sanitize(prettyDate(e.date))} · ${sanitize(e.name||'Compromiso')}</span><strong>${displayMoney(e.amount)}</strong></div>`}).join('');
 const dueSection=`<section class="v105-mobile-extra v273-overview-widget v315-chart-widget v317-chart-widget" data-v105-widget="cashPressure" aria-label="Radar de compromisos con vencimiento en los próximos treinta días">
  <div class="vive-mobile-card-head"><div><span class="vive-mobile-eyebrow">VENCIMIENTOS · 30 DÍAS</span><h2>Radar de vencimientos</h2></div><button class="vive-mobile-view-all" type="button" data-v1125-pay="1" aria-label="Elegir qué pago registrar">Pagar ${icon('arrow')}</button></div>
  <div class="v317-due-overview"><span>COMPROMETIDO PRÓXIMOS 30 DÍAS</span><strong>${displayMoney(v317DueTotal)}</strong><small>Incluye únicamente cargos calendarizados y pendientes conocidos.</small></div>
  <div class="v317-due-chart" role="img" aria-label="Vencimientos previstos por periodos: ${v317Buckets.map(d=>d.label+' '+displayMoney(d.total)).join(', ')}">${v317DueBars}</div>
  ${v317Upcoming?`<div class="v317-next-pays"><span class="v316-mini-eyebrow">PRÓXIMOS VENCIMIENTOS</span>${v317Upcoming}</div>`:'<p class="v315-empty">No se han registrado obligaciones futuras en este periodo.</p>'}
  <p class="v315-small-note">Montos por fecha de vencimiento; no equivale a deuda total. Pueden incluir estimaciones y no duplica pagos ya conciliados por el motor.</p>
 </section>`;
 const v317Today=today();
 const v317Start=v119DateAfter(-27);
 const v317DayTotals=new Map();
 for(const t of db.transactions||[]){
  if(!t||!t.date||t.date<v317Start||t.date>v317Today||!['expense','card_charge','card_refund'].includes(t.type))continue;
  const base=num(t.amount)*(t.currency==='USD'?num(t.fxRateSnapshot||db.settings.fx):1);
  if(!Number.isFinite(base)||base<=0)continue;
  v317DayTotals.set(t.date,(v317DayTotals.get(t.date)||0)+(t.type==='card_refund'?-base:base));
 }
 const v317Days=Array.from({length:28},(_,i)=>v119DateAfter(i-27)).map(date=>({date,amount:Math.max(0,v317DayTotals.get(date)||0)}));
 const v317Spent=v317Days.reduce((a,d)=>a+d.amount,0);
 const v317MaxDay=Math.max(1,...v317Days.map(d=>d.amount));
 const v317ActiveDays=v317Days.filter(d=>d.amount>.005).length;
 const v317Peak=v317Days.reduce((best,d)=>d.amount>best.amount?d:best,v317Days[0]);
 const v317Cells=v317Days.map(d=>{
  const n=d.amount/v317MaxDay;
  const level=d.amount<.005?0:n<=.25?1:n<=.50?2:n<=.75?3:4;
  return `<button type="button" class="v317-heat-cell heat-${level}" data-v705-spend-day="${d.date}" ${v318Tip(prettyDate(d.date),'Gasto neto: '+money(d.amount,'DOP',2),'Tocar para ver cada movimiento')} aria-label="Ver movimientos del ${sanitize(prettyDate(d.date))}; gasto neto ${money(d.amount,'DOP',2)}"><span>${Number(d.date.slice(-2))}</span></button>`;
 }).join('');
 const fingerprintSection=`<section class="v105-mobile-extra v273-overview-widget v315-chart-widget v317-chart-widget" data-v105-widget="spendingFingerprint" aria-label="Huella del gasto registrado durante veintiocho días">
  <div class="vive-mobile-card-head"><div><span class="vive-mobile-eyebrow">PANORAMA · PATRÓN · 28 DÍAS</span><h2>Huella de tus gastos</h2></div><button type="button" class="vive-mobile-view-all" data-act="navigate" data-id="register" aria-label="Ver movimientos">Movimientos ${icon('arrow')}</button></div>
  <div class="v317-heat-summary"><div><small>TOTAL REGISTRADO · 28 DÍAS</small><strong>${displayMoney(v317Spent)}</strong></div><div><small>DÍAS CON GASTOS</small><strong>${v317ActiveDays} / 28</strong></div></div>
  <div class="v317-heat-label"><span>${sanitize(prettyDate(v317Start))}</span><span>${sanitize(prettyDate(v317Today))}</span></div>
  <div class="v317-heat-grid" aria-label="Gastos diarios. Toca un día para ver los movimientos">${v317Cells}</div>
  <div class="v317-heat-foot"><span>Sin gasto registrado</span><div class="v317-heat-legend"><i class="heat-0"></i><i class="heat-1"></i><i class="heat-2"></i><i class="heat-3"></i><i class="heat-4"></i></div><span>Mayor gasto</span></div>
  ${v317ActiveDays?`<div class="v317-peak"><span>Día de mayor consumo · ${sanitize(prettyDate(v317Peak.date))}</span><strong>${displayMoney(v317Peak.amount)}</strong></div>`:''}
  <p class="v315-small-note">Solo movimientos de gasto y compras registrados; reembolsos reducen el importe del día. Excluye transferencias y pagos de tarjeta para no contabilizar dos veces. No registra actividad nueva.</p>
 </section>`;
 return cardSection+wealthSection+tomorrowSection+budgetSection+dueSection+fingerprintSection;
}

/* V318 · El costo de mañana — 10 visualizaciones analíticas vinculadas al motor real.
   Solo presentación. Ningún gráfico registra gastos, ingresos, pagos ni modifica Supabase.
   La cartera contractual se proyecta únicamente donde existe amortización verificable. */
const V318_GRAPH_META=[
 ['futureCostKpi','Costo del mañana','Compromisos del próximo mes, presión y carga futura','decisions'],
 ['futureCalendar','Calendario de presión financiera','Mapa de vencimientos diarios en los próximos 30 días','decisions'],
 ['futureFlow','El río de tu dinero','Origen, obligaciones y saldo previsto en 30 días','activity'],
 ['futureWaterfall','Dinero comprometido · 30 días','Cascada de liquidez, ingresos y compromisos','decisions'],
 ['futureMap','Mapa de compromisos','Peso relativo por tipo de obligación mensual','breakdown'],
 ['futureBubbles','Matriz de importes y urgencia','Relación entre importe y días hasta vencer','decisions'],
];
const V318_GRAPH_IDS=new Set(V318_GRAPH_META.map(x=>x[0]));
const V318_LEGACY_MAP={creditUtil:'Utilización por tarjeta',patrimonyTrend:'Tendencia de patrimonio',budgetPulse:'Pulso presupuestario',cashPressure:'Radar de vencimientos',spendingFingerprint:'Huella de gastos · 28 días',futureCostKpi:'Costo del mañana',futureCalendar:'Calendario de presión financiera'};
const V318_ALL_CHART_IDS=[...Object.keys(V318_LEGACY_MAP),...V318_GRAPH_META.map(x=>x[0])];

function v318IsoMonth(offset){const d=dateObj(today());const t=new Date(d.getFullYear(),d.getMonth()+offset,1);return t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')}
function v318MonthEnd(offset){const d=dateObj(today());const t=new Date(d.getFullYear(),d.getMonth()+offset+1,0);return dateStr(t)}
function v318Context(){return v99Memo('v318:models:'+today(),()=>{
 const thirty=v119Baseline(30),year=v119Baseline(365),reference=v89DebtCapacity(today().slice(0,7));
 const recurring=v339ActiveRecurring();
 const subTotal=v80RecurringMonthly();
 const monthly=Array.from({length:12},(_,i)=>{const period=v318IsoMonth(i);return {period,label:new Date(+period.slice(0,4),+period.slice(5,7)-1,1).toLocaleDateString('es-DO',{month:'short'}).replace('.',''),income:0,due:0}});
 const monthLookup=new Map(monthly.map(row=>[row.period,row]));
 for(const event of year.events||[]){const row=monthLookup.get(String(event.date||'').slice(0,7));if(!row)continue;if(event.type==='income')row.income+=event.amount;else if(event.type==='expense')row.due+=event.amount;}
 const contractual=[];
 for(const l of db.loans||[]){if(l.archived)continue;try{const a=loanAccounting(l);if(a.settled||!(a.balance>0))continue;const forecast=loanForecast(l,a,{amount:0});contractual.push({name:l.name||'Préstamo',currency:l.currency||'DOP',balance:fx(a.balance,l.currency||'DOP'),rows:forecast.rows||[],error:forecast.error||null})}catch(err){console.warn('V318: préstamo sin curva verificable',l.id,err)}}
 const otherDebt=Math.max(0,totalCardDebt()+num(personalTotals().payable));
 const loans=Array.from({length:13},(_,i)=>{
  const close=i===0?today():v318MonthEnd(i);return contractual.reduce((sum,l)=>{let balance=l.balance;for(const row of l.rows){if(row.date>close)break;balance=fx(row.balance,l.currency)}return sum+balance},0)
 });
 const dueEvents=year.events.filter(x=>x.type==='expense'&&x.amount>.005);
 return {thirty,year,reference,subTotal,monthly,contractual,loans,otherDebt,dueEvents};
})}
function v318Empty(message){return `<div class="v318-no-data"><span class="v318-empty-mark" aria-hidden="true">ⓘ</span><span>${sanitize(message)}</span></div>`}
function v318Money(n){return money(Number.isFinite(n)?n:0,'DOP',0)}
function v318N(n){return Math.max(0,Number.isFinite(n)?n:0)}
function v318Pct(n){return Number.isFinite(n)?new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(n)+'%':'Sin datos'}
function v318Tip(name,...facts){return `data-chart-tip="${sanitize([name,...facts].join('|'))}" tabindex="0"`}

/* V360 — Inicio: enlaces de acceso directo sin alterar Visión global. */
function v360HomeLinks(){
 if(isMobileViewport())return ''; // V370: ocultar ÚNICAMENTE los tres accesos de Inicio en móvil.
 return `<nav class="v360-home-links" aria-label="Inicio: accesos directos"><button type="button" class="active" aria-current="page" data-act="navigate" data-id="overview">${icon('home')}Inicio</button><button type="button" data-act="navigate" data-id="recurring">${icon('cycle')}Suscripciones</button><button type="button" data-act="navigate" data-id="personal">${icon('wallet')}Entre personas</button></nav>`;
}
/* V362: month selection uses the SAME forecast events and pressure levels as the small widget. */
let v362PressureMonthOffset=0;
function v360PressurePage(){
 const now=dateObj(today());
 const offset=Math.min(11,Math.max(0,v362PressureMonthOffset));
 const first=new Date(now.getFullYear(),now.getMonth()+offset,1);
 const last=new Date(first.getFullYear(),first.getMonth()+1,0);
 const monthStart=dateStr(first),monthEnd=dateStr(last);
 const ctx=v318Context();
 // One calendar, one source of forecast events. No new accounting methodology.
 const source=ctx.year.events||[];
 const next30Start=today(),next30End=addDays(next30Start,29);
 const next30Events=source.filter(e=>e.type==='expense'&&Number(e.amount)>0&&e.date>=next30Start&&e.date<=next30End);
 const next30Total=next30Events.reduce((sum,e)=>sum+Number(e.amount),0);
 const next30Days=new Set(next30Events.map(e=>e.date)).size;
 const daily=new Map(),grouped=new Map();
 for(const e of source){
  if(e.type!=='expense'||!(Number(e.amount)>0)||e.date<monthStart||e.date>monthEnd)continue;
  daily.set(e.date,(daily.get(e.date)||0)+Number(e.amount));
  if(!grouped.has(e.date))grouped.set(e.date,[]);
  grouped.get(e.date).push(e);
 }
 const amounts=Array.from(daily.values());const max=Math.max(1,...amounts);
 const dayCount=last.getDate(),lead=(first.getDay()+6)%7;
 const weekdays=['L','M','X','J','V','S','D'].map(x=>`<span class="v362-pressure-weekday">${x}</span>`).join('');
 let cells='';
 for(let i=0;i<lead;i++)cells+='<span class="v362-pressure-spacer" aria-hidden="true"></span>';
 for(let day=1;day<=dayCount;day++){
  const d=dateStr(new Date(first.getFullYear(),first.getMonth(),day));
  const amount=daily.get(d)||0;
  const level=amount<=0?0:Math.max(1,Math.ceil(amount/max*4));
  const isPast=d<today();
  cells+=`<button type="button" class="v322-cal-cell v362-pressure-day level-${level}${isPast?' v362-pressure-past':''}" data-v360-pressure-day="${d}" aria-label="${sanitize(prettyDate(d))}: ${sanitize(v318Money(amount))} en compromisos" title="${sanitize(prettyDate(d)+' · '+v318Money(amount))}"><span>${day}</span></button>`;
 }
 const total=Array.from(daily.values()).reduce((a,b)=>a+b,0);
 const label=first.toLocaleDateString('es-DO',{month:'long',year:'numeric'});
 return `<div class="v360-pressure-page v361-pressure-compact v362-pressure-month" aria-label="Calendario de presión financiera completo"><section class="v360-pressure-calendar" aria-label="Calendario ampliado de ${sanitize(label)}"><header class="v362-pressure-toolbar"><div class="v362-pressure-heading"><small>PRESIÓN FINANCIERA</small><h1>Presión financiera</h1></div><nav aria-label="Cambiar mes" class="v362-pressure-month-nav"><button type="button" data-v362-month="-1" aria-label="Mes anterior" ${offset===0?'disabled':''}>‹</button><strong aria-live="polite">${sanitize(label)}</strong><button type="button" data-v362-month="1" aria-label="Mes siguiente" ${offset===11?'disabled':''}>›</button></nav></header>${offset===0?`<div class="v942-next30-summary" aria-label="Compromisos de los próximos 30 días"><div><span>PRÓXIMOS 30 DÍAS · ${next30Days} días con obligaciones</span><br><strong>${v318Money(next30Total)}</strong></div><span>Del ${sanitize(prettyDate(next30Start))} al ${sanitize(prettyDate(next30End))} · previsión, no pago registrado</span></div>`:''}<div class="v362-pressure-summary"><span><b>${Array.from(daily.values()).filter(x=>x>0).length}</b> días con compromisos</span><span><b>${v318Money(total)}</b> previstos en el mes</span></div><div class="v362-pressure-grid" role="group" aria-label="Días del mes">${weekdays}${cells}</div>${v705ScaleLegend(total>0?max:0)}<p class="v362-pressure-disclaimer">${offset===0?'Este mes: compromisos previstos desde la fecha actual.':'Proyección de compromisos registrados; no incluye gastos futuros sin programar.'}</p></section></div>`;
}
/* V361: la selección abre el detalle en una vista superpuesta, sin reducir el calendario. */
let v361PressureLastFocus=null;
function v361ClosePressureDay(){const el=document.getElementById('v361-pressure-day-dialog');if(el)el.remove();document.body.classList.remove('v361-pressure-open');v361PressureLastFocus?.focus?.();v361PressureLastFocus=null;}
function v361OpenPressureDay(date){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(String(date||'')))return;
 document.getElementById('v361-pressure-day-dialog')?.remove();
 const events=(v318Context().year.events||[]).filter(e=>e.date===date&&e.type==='expense'&&num(e.amount)>0);
 const total=events.reduce((sum,e)=>sum+num(e.amount),0);
 const rows=events.map(e=>`<article class="v361-pressure-item"><div><strong>${sanitize(e.name||'Compromiso')}</strong><span>${sanitize(e.kind||e.type||'Obligación')}</span></div><b>${v318Money(num(e.amount))}</b></article>`).join('');
 const dialog=document.createElement('div');dialog.id='v361-pressure-day-dialog';dialog.className='v361-pressure-overlay';dialog.innerHTML=`<div class="v361-pressure-backdrop" data-v361-pressure-close="1"></div><section role="dialog" aria-modal="true" aria-labelledby="v361-pressure-title" class="v361-pressure-sheet"><header><div><small>PRESIÓN FINANCIERA · DETALLE DEL DÍA</small><h2 id="v361-pressure-title">${prettyDate(date)}</h2></div><button type="button" data-v361-pressure-close="1" aria-label="Cerrar detalle del día">×</button></header><div class="v361-pressure-main"><span>Compromisos previstos</span><strong>${v318Money(total)}</strong><small>${events.length} ${events.length===1?'compromiso':'compromisos'} en esta fecha</small></div><div class="v361-pressure-list">${rows||'<p class="v360-pressure-empty">No hay obligaciones registradas para esta fecha.</p>'}</div><footer><button type="button" data-v361-pressure-close="1">Volver al calendario</button></footer></section>`;
 document.body.appendChild(dialog);document.body.classList.add('v361-pressure-open');dialog.querySelector('.v361-pressure-sheet header button')?.focus();
}
document.addEventListener('click',e=>{
 const close=e.target.closest('[data-v361-pressure-close]');if(close){e.preventDefault();v361ClosePressureDay();return}
 const monthBtn=e.target.closest('[data-v362-month]');if(monthBtn){e.preventDefault();v362PressureMonthOffset=Math.max(0,Math.min(11,v362PressureMonthOffset+Number(monthBtn.dataset.v362Month)));const parent=document.querySelector('.v360-pressure-page');if(parent){const holder=document.createElement('div');holder.innerHTML=v360PressurePage();parent.replaceWith(holder.firstElementChild);document.querySelector('.v362-pressure-month-nav [data-v362-month="'+monthBtn.dataset.v362Month+'"]')?.focus({preventScroll:true})}return;}
 const b=e.target.closest('[data-v360-pressure-day]');if(!b)return;
 e.preventDefault();v361PressureLastFocus=b;v361OpenPressureDay(b.dataset.v360PressureDay);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('v361-pressure-day-dialog')){e.preventDefault();v361ClosePressureDay();}});

function v318ChartFrame(body,foot=''){return `<div class="v318-chart-content">${body}${foot?`<p class="v318-chart-note">${foot}</p>`:''}</div>`}
function v318Curve(values,width=600,height=175,pad=16,range=null){
 const finite=values.map(x=>Number.isFinite(x)?x:null);const known=finite.filter(x=>x!==null);
 if(!known.length)return '';
 const min=range?range[0]:Math.min(0,...known),max=range?range[1]:Math.max(1,...known),span=Math.max(1,max-min);
 let output='',open=false;
 finite.forEach((val,i)=>{if(val===null){open=false;return}const x=pad+i*(width-pad*2)/Math.max(1,finite.length-1),y=height-pad-(val-min)/span*(height-2*pad);output+=(open?' L ':'M ')+x.toFixed(2)+' '+y.toFixed(2);open=true});return output;
}
function v318SmallStats(items){return `<div class="v318-stat-row">${items.map(([name,value,tone])=>`<div><small>${sanitize(name)}</small><strong class="${tone||''}">${value}</strong></div>`).join('')}</div>`}
function v318LoanRoadmap(c){const current=c.loans[0]+c.otherDebt;const last=c.loans.at(-1)+c.otherDebt;const range=Math.max(1,...c.loans.map(v=>v+c.otherDebt));const W=600,H=175;
 const path=v318Curve(c.loans.map(x=>x+c.otherDebt),W,H,18,[0,range]);const capital=v318Curve(c.loans,W,H,18,[0,range]);
 const markers=c.loans.map((v,i)=>`<circle cx="${(18+i*(W-36)/12).toFixed(1)}" cy="${(H-18-(v+c.otherDebt)/range*(H-36)).toFixed(1)}" r="3"><title>Mes ${i}: ${v318Money(v+c.otherDebt)}</title></circle>`).join('');
 return {current,last,markup:`<svg class="v318-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Capital de préstamos previsto y deudas no amortizadas a 12 meses"><path d="${path}" class="v318-blue-stroke"/><path d="${capital}" class="v318-green-stroke"/>${markers}</svg><div class="v318-inline-legend"><span><i class="blue"></i> Deuda total de referencia*</span><span><i class="green"></i> Capital bancario previsto</span></div>`,hasLoan:c.contractual.length>0};
}
function v318Graph(id){const c=v318Context(),t=c.thirty,Y=c.year;


 if(id==='futureCoverage'){
  const available=Math.max(0,v318N(t.initial)+v318N(t.incomes));
  const due=Math.max(0,v318N(t.dues));
  const total=Math.max(1,available,due);
  const cover=due>0?available/due:null;
  const row=(label,value,cls)=>`<div class="v343-compare-row"><div><span>${sanitize(label)}</span><strong>${v318Money(value)}</strong></div><div class="v343-compare-track"><i class="${cls}" style="width:${Math.max(0,Math.min(100,value/total*100)).toFixed(2)}%"></i></div></div>`;
  return v318ChartFrame(`<div class="v343-coverage">${row('Disponible y cobros previstos',available,'is-funds')}${row('Obligaciones previstas',due,'is-due')}</div>`+v318SmallStats([['Cobertura',cover===null?'Sin vencimientos':v318Pct(cover*100)],['Margen estimado',v318Money(available-due),available<due?'v318-danger':'v318-good']]),'30 días. Solo incluye saldos y pagos identificados; no anticipa gastos que todavía no se registraron.');
 }
 if(id==='futurePulse'){
  const bins=Array.from({length:4},(_,i)=>({name:`Semana ${i+1}`,income:0,due:0}));
  const anchor=dateObj(today());
  for(const event of t.events||[]){const date=dateObj(event.date);const diff=Math.round((date-anchor)/(24*60*60*1000));if(!Number.isFinite(diff)||diff<0||diff>=28)continue;const b=bins[Math.floor(diff/7)];if(event.type==='income')b.income+=v318N(event.amount);else if(event.type==='expense')b.due+=v318N(event.amount)}
  const max=Math.max(1,...bins.flatMap(b=>[b.income,b.due]));
  return v318ChartFrame(`<div class="v343-pulse">${bins.map(b=>`<div class="v343-pulse-week"><small>${b.name}</small><div class="v343-pulse-bars"><span title="Cobros ${v318Money(b.income)}" style="height:${Math.max(2,b.income/max*100)}%"></span><i title="Obligaciones ${v318Money(b.due)}" style="height:${Math.max(2,b.due/max*100)}%"></i></div></div>`).join('')}</div><div class="v343-chart-key"><span><i class="is-income"></i>Cobros programados</span><span><i class="is-due"></i>Pagos calendarizados</span></div>`,'Cuatro semanas desde hoy. Se usan solamente fechas e importes identificados por el motor de proyección.');
 }
 if(id==='futureBuffer'){
  const safeSigned=x=>Number.isFinite(x)?x:0;const start=safeSigned(t.initial),minimum=safeSigned(t.minimum),ending=safeSigned(t.ending);
  const range=Math.max(1,Math.abs(start),Math.abs(minimum),Math.abs(ending));
  const bars=[['Hoy',start],['Mínimo previsto',minimum],['Día 30',ending]];
  return v318ChartFrame(`<div class="v343-buffer">${bars.map(([label,value])=>`<div class="v343-buffer-item"><span>${label}</span><strong>${v318Money(value)}</strong><div class="v343-buffer-track"><i class="${value<0?'is-negative':''}" style="width:${Math.max(2,Math.min(100,Math.abs(value)/range*100)).toFixed(2)}%"></i></div></div>`).join('')}</div>`+v318SmallStats([['Caída máxima estimada',v318Money(Math.max(0,start-minimum))],['Saldo al final',v318Money(ending),ending<0?'v318-danger':'']]),'Escenario de 30 días. No incluye ingresos o consumos no programados.');
 }
 if(id==='futureCostKpi'){
  const activeRecurring=v339ActiveRecurring();
  const monthlyRecurring=v80RecurringMonthly();
  const monthlyDue=c.monthly?.[0]?.due||0;
  const totalMonthly=Math.max(monthlyDue,monthlyRecurring);
  const pressure=Number.isFinite(c.reference?.ratio)?c.reference.ratio:null;
  const recurringCount=activeRecurring.length;
  return `<div class="v324-cost-design"><div class="v324-cost-top"><div class="v324-cost-text"><span class="v324-cost-eyebrow">COSTO DEL MAÑANA</span><div class="v324-cost-price"><strong>${v318Money(totalMonthly)}</strong><span>/ mes</span></div><p>Lo que ya está comprometido para tu próximo mes (suscripciones, servicios y pagos de deuda).</p></div><span class="v324-cost-calendar" aria-hidden="true">${icon('calendar')}</span></div><div class="v324-cost-three"><div class="v324-cost-metric"><span class="v324-cost-metric-icon">${icon('layers')}</span><div><strong>${recurringCount}</strong><small>Compromisos recurrentes</small></div></div><div class="v324-cost-metric"><span class="v324-cost-metric-icon">${icon('clock')}</span><div><strong>${pressure===null?'—':v318Pct(pressure)}</strong><small>Presión de deuda</small></div></div><div class="v324-cost-metric"><span class="v324-cost-metric-icon">${icon('calendar')}</span><div><strong>${v318Money(monthlyDue||totalMonthly)}</strong><small>Carga mensual futura</small></div></div></div></div>`;
 }
 if(id==='futureCalendar'){
  const start=dateObj(today());
  const events=(c.thirty.events||[]).filter(x=>x.type==='expense'&&x.amount>.005);
  const daily=new Map();
  for(const ev of events)daily.set(ev.date,(daily.get(ev.date)||0)+ev.amount);
  const days=Array.from({length:30},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);const iso=dateStr(d);return {date:iso,day:d.getDate(),amount:daily.get(iso)||0}});
  const max=Math.max(1,...days.map(x=>x.amount));
  const active=days.filter(x=>x.amount>0);
  const total=active.reduce((s,x)=>s+x.amount,0);
  const cells=days.map(d=>{const level=d.amount<=0?0:Math.max(1,Math.ceil(d.amount/max*4));return `<button type="button" class="v322-cal-cell level-${level}" data-v705-due-day="${d.date}" ${v318Tip(prettyDate(d.date),'Compromisos: '+money(d.amount,'DOP',2),'Tocar para ver obligaciones del día')} aria-label="Ver compromisos del ${sanitize(prettyDate(d.date))}; ${money(d.amount,'DOP',2)}"><span>${d.day}</span></button>`}).join('');
  return v318ChartFrame(v318SmallStats([['Días con vencimientos',`${active.length} / 30`],['Obligaciones',v318Money(total)]])+`<div class="v322-cal-grid">${cells}</div>${v705ScaleLegend(total>0?max:0)}`,`Cada cuadrícula corresponde a un día futuro. Se excluyen movimientos ya pagados según el motor de compromisos.`);
 }
 if(id==='futureFlow'){
  const funds=v318N(t.initial),inc=v318N(t.incomes),dues=v318N(t.dues),net=t.ending,base=Math.max(1,funds+inc,dues),th=x=>Math.max(5,Math.min(41,40*x/base));
  const body=`<svg class="v318-svg" viewBox="0 0 620 190" role="img" aria-label="Flujo de liquidez inicial, ingresos calendarizados, vencimientos y saldo estimado"><path d="M116 49 C215 49 218 89 314 89" stroke="#60a5fa" stroke-width="${th(funds)}" fill="none" stroke-opacity=".74"/><path d="M116 139 C214 139 221 98 314 98" stroke="#3dd6bc" stroke-width="${th(inc)}" fill="none" stroke-opacity=".74"/><path d="M342 90 C430 90 436 50 498 50" stroke="#ff6c84" stroke-width="${th(dues)}" fill="none" stroke-opacity=".75"/><path d="M342 98 C430 98 438 143 498 143" stroke="#60a5fa" stroke-width="${th(v318N(net))}" fill="none" stroke-opacity=".75"/><rect x="6" y="24" width="114" height="54" rx="10"/><rect x="6" y="115" width="114" height="54" rx="10"/><rect x="287" y="67" width="67" height="55" rx="12"/><rect x="497" y="24" width="119" height="54" rx="10"/><rect x="497" y="115" width="119" height="54" rx="10"/><g class="v318-svg-caption"><text x="14" y="41">LIQUIDEZ HOY</text><text x="14" y="57">${sanitize(v318Money(funds))}</text><text x="14" y="132">COBROS PREVISTOS</text><text x="14" y="148">${sanitize(v318Money(inc))}</text><text x="297" y="90">30 DÍAS</text><text x="505" y="41">VENCIMIENTOS</text><text x="505" y="57">${sanitize(v318Money(dues))}</text><text x="505" y="132">SALDO PREVISTO</text><text x="505" y="148">${sanitize(v318Money(net))}</text></g></svg>`;
  return v318ChartFrame(body+v318SmallStats([['Disponible inicial',v318Money(funds)],['Déficit máximo',v318Money(Math.max(0,-t.minimum)),t.minimum<0?'v318-danger':'']]),'30 días · Solo cobros y obligaciones con fechas verificables. El ancho de cada flujo representa su magnitud relativa.');
 }
 if(id==='futureWaterfall'){
  const first=t.initial,after=t.initial+t.incomes,last=t.ending,low=Math.min(0,first,after,last),high=Math.max(1,first,after,last),span=high-low||1;
  const y=n=>164-(n-low)/span*142;
  const rect=(x,a,b,cls)=>{const y1=y(a),y2=y(b);return `<rect class="${cls}" x="${x}" y="${Math.min(y1,y2)}" width="74" height="${Math.max(2,Math.abs(y1-y2))}" rx="6"/>`};
  const svg=`<svg viewBox="0 0 540 205" class="v318-svg v318-waterfall" role="img" aria-label="Cascada del saldo de hoy a los cobros, compromisos y saldo previsto"><line x1="20" y1="${y(0)}" x2="523" y2="${y(0)}" stroke="#5c6682" stroke-dasharray="4 5"/>${rect(26,0,first,'v318-blue-fill')}${rect(158,first,after,'v318-green-fill')}${rect(290,after,last,'v318-amber-fill')}${rect(422,0,last,last<0?'v318-red-fill':'v318-blue-fill')}<path d="M100 ${y(first)} H158 M232 ${y(after)} H290 M364 ${y(last)} H422" fill="none" stroke="#7b8ca8" stroke-dasharray="4 4"/><g class="v318-waterfall-labels"><text x="63" y="191">AHORA</text><text x="195" y="191">+ INGRESOS</text><text x="327" y="191">− PAGOS</text><text x="459" y="191">FINAL</text></g></svg>`;
  const detailStats=`<div class="v318-stat-row v362-detail-stats">   <button type="button" class="v362-detail-stat" data-v362-flow-detail="1" data-stage="ahora" data-title="Ahora" data-value="${sanitize(v318Money(first))}" data-summary="Liquidez identificada al iniciar el escenario de 30 días." data-line1="Saldo base" data-value1="${sanitize(v318Money(first))}" data-line2="Interpretación" data-value2="Punto de partida de la cascada"><small>Ahora</small><strong>${v318Money(first)}</strong></button>   <button type="button" class="v362-detail-stat" data-v362-flow-detail="1" data-stage="ingresos" data-title="Cobros previstos" data-value="${sanitize('+'+v318Money(t.incomes))}" data-summary="Ingresos calendarizados que el motor identifica para los próximos 30 días." data-line1="Cobros previstos" data-value1="${sanitize(v318Money(t.incomes))}" data-line2="Después de sumar" data-value2="${sanitize(v318Money(after))}"><small>Cobros previstos</small><strong class="v318-good">+${v318Money(t.incomes)}</strong></button>   <button type="button" class="v362-detail-stat" data-v362-flow-detail="1" data-stage="pagos" data-title="Compromisos" data-value="${sanitize('−'+v318Money(t.dues))}" data-summary="Pagos y obligaciones futuras registradas dentro de la ventana de 30 días." data-line1="Compromisos" data-value1="${sanitize(v318Money(t.dues))}" data-line2="Salida estimada" data-value2="${sanitize(v318Money(last-after))}"><small>Compromisos</small><strong class="v318-danger">−${v318Money(t.dues)}</strong></button>   <button type="button" class="v362-detail-stat" data-v362-flow-detail="1" data-stage="final" data-title="Saldo estimado" data-value="${sanitize(v318Money(last))}" data-summary="Resultado estimado al terminar el horizonte, después de cobros y compromisos identificados." data-line1="Saldo final" data-value1="${sanitize(v318Money(last))}" data-line2="Lectura" data-value2="${sanitize(last<0?'Déficit estimado':'Liquidez estimada')}"><small>Saldo estimado</small><strong class="${last<0?'v318-danger':''}">${v318Money(last)}</strong></button>  </div>`;  return v318ChartFrame(svg+detailStats,'Cascada de 30 días: el saldo final no es dinero garantizado. Se omiten gastos que todavía no están programados.');
 }
 if(id==='futureDebt'){
  const road=v318LoanRoadmap(c);if(!road.hasLoan&&!c.otherDebt)return v318Empty('Agrega tarjetas, deudas personales o préstamos para analizar tu saldo pendiente.');
  return v318ChartFrame(v318SmallStats([['Deuda de referencia',v318Money(road.current)],['En 12 meses*',v318Money(road.last)],['Cambio estimado',v318Money(road.last-road.current),(road.last-road.current)<0?'v318-good':'']])+road.markup,'*Solo los préstamos con plan contractual se amortizan. Se mantiene constante la deuda actual de tarjetas y personas; no se anticipan compras nuevas.');
 }
 if(id==='futureMap'){
  const a=c.reference.a,types=[['Tarjetas',v318N(a.cards),'blue'],['Préstamos',v318N(a.loans),'cyan'],['Suscripciones',v318N(a.recurring),'amber'],['Entre personas',v318N(a.personal),'rose']];const total=types.reduce((s,x)=>s+x[1],0);
  if(!(total>0))return v318Empty('No hay compromisos cuantificados para el mes actual.');
  return v318ChartFrame(`<div class="v318-treemap">${types.filter(x=>x[1]>0).map(([name,amount,color])=>`<div class="v318-tree-cell ${color}" style="flex-grow:${Math.max(.04,amount/total).toFixed(4)}" ${v318Tip(name,'Cuota mensual: '+v318Money(amount),'Peso: '+v318Pct(amount/total*100))}><span>${sanitize(name)}</span><strong>${v318Pct(amount/total*100)}</strong><small>${v318Money(amount)}</small></div>`).join('')}</div>`+v318SmallStats([['Total mes',v318Money(total)],['Grupos activos',types.filter(x=>x[1]>0).length+'']]),'Cada bloque representa el peso relativo de una categoría en las obligaciones del mes. Se usan cuotas, no capital total.');
 }
 if(id==='futureBubbles'){
  const first=new Map();for(const e of c.dueEvents){const name=e.name||'Compromiso';if(!first.has(name))first.set(name,e)}
  const events=[...first.values()].filter(e=>e.date<=v119DateAfter(90)).sort((a,b)=>b.amount-a.amount).slice(0,12);
  if(!events.length)return v318Empty('No existen vencimientos próximos con fecha e importe para construir la matriz.');
  const upper=Math.max(1,...events.map(x=>x.amount));
  const bubbles=events.map((x,i)=>{const days=Math.max(0,diffDays(x.date,today()));const cx=35+days/90*520,cy=172-(x.amount/upper)*138,r=7+Math.sqrt(x.amount/upper)*13;return `<circle cx="${cx.toFixed(1)}" cy="${cy.toFixed(1)}" r="${r.toFixed(1)}" class="${days<=7?'is-urgent':''}" ${v318Tip(x.name,prettyDate(x.date),'Importe: '+v318Money(x.amount),'En '+days+' días')}><title>${sanitize(x.name)} · ${v318Money(x.amount)} · ${days} días</title></circle>`}).join('');
  return v318ChartFrame(`<svg viewBox="0 0 600 215" class="v318-svg v318-bubbles" role="img" aria-label="Matriz de fechas próximas e importes pendientes"><line x1="35" y1="22" x2="35" y2="172"/><line x1="35" y1="172" x2="565" y2="172"/><rect x="35" y="22" width="42" height="150" class="v318-bubble-urgent"/><g class="v318-bubble-label"><text x="43" y="12">Mayor importe</text><text x="35" y="193">Hoy</text><text x="288" y="193">45 días</text><text x="516" y="193">90 días</text></g>${bubbles}</svg>`+v318SmallStats([['Obligaciones distintas',String(events.length)],['Mayor importe',v318Money(events[0].amount)]]),'Cada burbuja es un compromiso identificado; a la izquierda vence antes, más arriba tiene mayor importe. Naranja = 7 días o menos.');
 }
 if(id==='futureFreedom'){
  const balances=[v119AvailableToday()],months=Array.from({length:12},(_,i)=>v318MonthEnd(i));
  for(const end of months){const days=Y.dayByDay.filter(row=>row.date<=end);balances.push(days.length?days.at(-1).balance:Y.ending)}
  const debt=c.loans.map(x=>x+c.otherDebt);const all=[...balances,...debt],low=Math.min(0,...all),high=Math.max(1,...all),range=[low,high];
  const ending=balances.at(-1),future=debt.at(-1);
  return v318ChartFrame(`<svg class="v318-svg" viewBox="0 0 600 180" role="img" aria-label="Liquidez futura identificada y deuda contractual proyectada a doce meses"><path d="${v318Curve(balances,600,180,16,range)}" class="v318-green-stroke"/><path d="${v318Curve(debt,600,180,16,range)}" class="v318-amber-stroke"/></svg><div class="v318-inline-legend"><span><i class="green"></i>Liquidez prevista</span><span><i class="amber"></i>Deudas de referencia</span></div>`+v318SmallStats([['Liquidez al final*',v318Money(ending),ending<0?'v318-danger':''],['Deuda estimada*',v318Money(future)],['Diferencia',v318Money(ending-future),(ending-future)<0?'v318-danger':'v318-good']]),'*Visualización orientativa: ingresos sin programación no se incluyen; tarjetas/personas se conservan al saldo actual si no hay amortización contractual.');
 }
 return v318Empty('El gráfico solicitado no está disponible.');
}
