/* V726 · Controls with existing in-memory Supabase-backed state. */
document.addEventListener('click',function(event){
 const target=event.target.closest?.('[data-v726-linked-filter],[data-v726-linked-open],[data-v726-linked-toggle],[data-v726-profile-edit],[data-v726-profile-cancel],[data-v726-open-bell],[data-v726-open-apple-pay]');
 if(!target)return;
 event.preventDefault();event.stopImmediatePropagation();
 if(target.hasAttribute('data-v726-linked-filter')){const v=target.dataset.v726LinkedFilter;if(['all','active','archived'].includes(v)){v726LinkedFilter=v;render()}return}
 if(target.hasAttribute('data-v726-profile-edit')){v726ProfileEditing=true;v242SettingsPane='profile';render();if(isMobileViewport())window.scrollTo(0,0);return}
 if(target.hasAttribute('data-v726-profile-cancel')){v726ProfileEditing=false;render();return}
 if(target.hasAttribute('data-v726-open-apple-pay')){v242SettingsPane='integrations';ui.page='settings';render();window.scrollTo(0,0);return}
 if(target.hasAttribute('data-v726-open-bell')){
   const bell=document.querySelector('.v36-notifications');
   if(bell&&bell.tagName.toLowerCase()==='details'){bell.open=true;bell.querySelector('summary')?.focus()}
   else toast('Consulta tus avisos desde la campanita del encabezado.');
   return;
 }
 const kind=target.dataset.v726LinkedOpen||target.dataset.v726LinkedToggle;
 const collection={bank:'banks',account:'accounts',card:'cards',loan:'loans',certificate:'certificates'}[kind];
 const id=target.dataset.v726Id;
 if(!collection||!id||!db[collection]?.some(x=>String(x.id)===id))return;
 if(target.hasAttribute('data-v726-linked-toggle')){manageProduct(kind,id,'toggle');return}
 ui.showHidden=true;
 ui.page={bank:'banks',account:'accounts',card:'cards',loan:'loans',certificate:'certificates'}[kind];
 if(kind==='bank'){ui.bankId=id;if(typeof v202ShowBankDetail!=='undefined')v202ShowBankDetail=true}
 if(kind==='account')ui.accountId=id;
 if(kind==='card')ui.cardId=id;
 if(kind==='loan')ui.loanId=id;
 if(kind==='certificate')ui.v239CertificateId=id;
 render();window.scrollTo(0,0);
},true);
document.addEventListener('submit',async function(event){
 if(event.target?.id!=='v726ProfileForm')return;
 event.preventDefault();event.stopImmediatePropagation();
 const form=event.target,btn=form.querySelector('[type="submit"]');
 const name=String(new FormData(form).get('name')||'').trim().slice(0,75);
 const avatar=String(new FormData(form).get('avatar')||'').trim();
 if(!name){toast('Indica un nombre.');return}
 if(avatar&&(!/^https:\/\/[^\s]+$/i.test(avatar)||avatar.length>1700)){toast('La foto requiere una URL HTTPS válida.');return}
 if(!f33Api||!f33User){toast('Inicia sesión para actualizar el perfil.');return}
 if(btn)btn.disabled=true;
 try{
   const metadata={...f33User.user_metadata,full_name:name,avatar_url:avatar||null};
   const {data,error}=await f33Api.auth.updateUser({data:metadata});
   if(error)throw error;
   if(data?.user)f33User=data.user;
   v726ProfileEditing=false;render();toast('Perfil actualizado en tu cuenta.');
 }catch(err){console.warn('No se pudo guardar el perfil',err);toast('No se pudo guardar. Comprueba la conexión y vuelve a intentar.');if(btn)btn.disabled=false}
},true);

