const antOrigSearchEntries=v71SearchEntries;
v71SearchEntries=function(){return antOrigSearchEntries().filter(entry=>entry.page!=='antExpenses');};
// Enable mobile Explore contextual return route.
const antOrigExploreReturn=v243ExploreReturn;
v243ExploreReturn=function(){return ui.page==='antExpenses'&&v243ExploreDestination==='antExpenses'?`<nav class="v243-explore-return"><button type="button" data-v243-explore-back="1">${icon('arrow')} Explorar</button><span>/</span><strong>Gastos hormiga</strong></nav>`:antOrigExploreReturn();};
// User actions are delegated to a small scope and do not modify transaction logic.
document.addEventListener('click',function(event){
 const button=event.target.closest('[data-ant]');if(!button)return;
 event.preventDefault();event.stopImmediatePropagation();
 const action=button.dataset.ant,key=button.dataset.key;
 if(action==='rules'){antUi.showRules=!antUi.showRules;render();return;}
 if(action==='tab'){antUi.tab=button.dataset.value==='ignored'?'ignored':'habits';antUi.selected=null;render();return;}
 if(action==='detail'){antUi.selected=antUi.selected===key?null:key;render();document.getElementById('ant-detail')?.scrollIntoView({block:'nearest',behavior:'smooth'});return;}
 if(action==='close'){antUi.selected=null;render();return;}
 if(action==='export'){
  const model=antModel();const groups=(antUi.tab==='ignored'?model.ignored:model.active).filter(g=>(g.label+' '+g.origin).toLocaleLowerCase('es').includes(antUi.search.toLocaleLowerCase('es')));
  const fields=['Hábito','Origen','Compras en 90 días','Frecuencia en días','Real del mes RD$','Participación %','Ritmo mensual RD$','Estimación anual RD$','Fiabilidad','Estado'];
  const rows=[fields,...groups.map(g=>[g.label,g.origin,g.number,g.frequency===null?'':g.frequency,g.real,g.share===null?'':g.share,g.projected,g.annual,g.confidence,g.ignored?'Ignorado':'Detectado'])];
  const quote=value=>'"'+String(value??'').replace(/"/g,'""')+'"';
  download('\ufeff'+rows.map(row=>row.map(quote).join(',')).join('\r\n'),`gastos-hormiga-${model.key}.csv`,'text/csv;charset=utf-8');return;
 }
 if(action==='save-rules'){
  const p=antPrefs(),maxUnitDop=Number(document.getElementById('ant-amount')?.value),minRepetitions=Number(document.getElementById('ant-repeat')?.value);
  if(!Number.isFinite(maxUnitDop)||maxUnitDop<1||maxUnitDop>100000||!Number.isInteger(minRepetitions)||minRepetitions<2||minRepetitions>30){toast('Introduce valores válidos: importe 1–100,000 y repeticiones 2–30.');return;}
  p.maxUnitDop=maxUnitDop;p.minRepetitions=minRepetitions;antRemember();render();return;
 }
 if(action==='ignore'||action==='restore'){
  if(!key)return;
  const p=antPrefs();p.excluded=action==='ignore'?[...new Set([...p.excluded,key])]:p.excluded.filter(x=>x!==key);
  antUi.selected=null;antRemember();render();return;
 }
},true);
document.addEventListener('change',function(event){
 if(event.target?.id==='ant-month'){
  const value=String(event.target.value||'');if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(value)||value>today().slice(0,7))return;
  ui.month=value;ui.year=Number(value.slice(0,4));antUi.selected=null;render();
 }
 if(event.target?.id==='ant-sort'){antUi.sort=event.target.value;render();}
});
document.addEventListener('input',function(event){
 if(event.target?.id!=='ant-search')return;
 const query=String(event.target.value||'').trim().toLocaleLowerCase('es');antUi.search=event.target.value||'';
 document.querySelectorAll('.ant-directory [data-ant-search]').forEach(el=>{el.hidden=!el.dataset.antSearch?.includes(query);});
});


/* V264 · La UI de Suscripciones debe compartir el ámbito de db/render */

(function(){
  'use strict';
  function $make(tag,cls,html){const e=document.createElement(tag);if(cls)e.className=cls;if(html!==undefined)e.innerHTML=html;return e;}
  function factor(freq){return freq==='annual'?12:freq==='quarterly'?3:freq==='weekly'?(7/30.4375):1;}
  function monthlyEq(r){return fx(num(r.amount),r.currency)/factor(r.frequency);}
  function calc(){
    const active=(db.recurring||[]).filter(r=>r&&r.active!==false);
    const monthlyTotal=active.reduce((s,r)=>s+monthlyEq(r),0);
    const yearTotal=monthlyTotal*12;
    const next=active.filter(r=>r.nextDue&&r.nextDue>=today()&&r.nextDue<=addDays(today(),30)).slice().sort((a,b)=>String(a.nextDue).localeCompare(String(b.nextDue)));
    const upcomingVal=next.reduce((s,r)=>s+fx(num(r.amount),r.currency),0);
    const month=String(ui.month||today().slice(0,7)).slice(0,7);
    const paid=(db.transactions||[]).filter(t=>t&&t.recurringId&&['expense','card_charge'].includes(t.type)&&String(t.date||'').startsWith(month));
    const paidVal=paid.reduce((s,t)=>s+fx(num(t.amount),t.currency),0);
    return {active,monthlyTotal,yearTotal,next,upcomingVal,paidVal};
  }
  function ensureKpi(root,body,data){
    let kpi=body.querySelector(':scope > .v264-subs-kpi');
    if(!kpi){kpi=$make('section','v264-subs-kpi');body.insertBefore(kpi,body.firstChild);}
    kpi.innerHTML='';
    const copy=$make('div','v264-kpi-copy');
    copy.innerHTML=`<span class="v264-kicker">SUSCRIPCIONES / COSTO RECURRENTE</span><h3>Lo que mantienes activo,<br><em>tiene un costo.</em></h3><p>Vista ejecutiva del gasto recurrente: costo mensual equivalente, próximos cargos, pagos del período y servicios activos, sin perder la profundidad analítica.</p>`;
    const actions=$make('div','v264-kpi-actions');
    actions.innerHTML=`<button type="button" class="btn" data-act="navigate" data-id="recurring" data-tab="overview">Ver servicios ${icon('arrow')}</button><button type="button" class="btn soft" data-act="navigate" data-id="recurring" data-tab="next">Próximos cargos ${icon('arrow')}</button>`;
    copy.append(actions,$make('div','v264-kpi-note','Distingue el costo mensual equivalente de los cargos reales del período. Las cifras se mantienen sincronizadas con tus servicios y con sus pagos registrados.'));
    const grid=$make('div','v264-kpi-grid');
    const cards=[
      ['COSTO MENSUAL EQUIVALENTE',money(data.monthlyTotal),'Solo suscripciones activas'],
      ['COMPROMISO ANUALIZADO',money(data.yearTotal),'12 meses de referencia'],
      ['PRÓXIMOS 30 DÍAS',money(data.upcomingVal),`${data.next.length} renovaciones registradas`],
      ['PAGADO EN EL MES',money(data.paidVal),(typeof fmtMonth==='function'?fmtMonth(String(ui.month||today().slice(0,7)).slice(0,7)):String(ui.month||today().slice(0,7)))],
      ['SERVICIOS ACTIVOS',String(data.active.length),'Con cargo programado']
    ];
    const primary=cards.slice(1,5); // leave monthly total as headline? no, also in grid? user wants KPI with main plus 4 support.
    primary.forEach(([label,val,sub])=>{const c=$make('article','v264-kpi-card',`<small>${label}</small><strong>${val}</strong><span>${sub}</span>`);grid.append(c);});
    // Add monthly equivalent first, replacing first card if needed, move before annualized.
    grid.prepend($make('article','v264-kpi-card',`<small>${cards[0][0]}</small><strong>${cards[0][1]}</strong><span>${cards[0][2]}</span>`));
    // keep only first 4 cards in 2x2 layout, but we still need servicios activos; replace annualized? maintain 4 indicators main. We'll trim below.
    while(grid.children.length>4)grid.removeChild(grid.lastElementChild);
    copy.querySelector('.btn[data-tab="overview"]')?.setAttribute('data-v264-link','overview');
    copy.querySelector('.btn[data-tab="next"]')?.setAttribute('data-v264-link','next');
    kpi.append(copy,grid);
  }
  function block(headEyebrow,title,desc,extraClass){
    const section=$make('section','v264-block '+(extraClass||''));
    section.innerHTML=`<header class="v264-block-head"><div class="copy"><span class="eyebrow">${headEyebrow}</span><h3>${title}</h3><p>${desc}</p></div></header>`;
    return section;
  }
  function build(){
    if(ui.page!=='recurring')return;
    const root=document.querySelector('#page .v26-internal[data-module="recurring"]');
    if(!root)return;
    const body=root.querySelector(':scope > .v26-body');
    if(!body)return;
    root.classList.add('v264-recurring');
    const data=calc();
    body.querySelectorAll(':scope > .v252-hero,:scope > .v252-additional-metrics,:scope > .section-title,:scope > .grid.kpis,:scope > .v149-rec-unified').forEach(el=>el.classList.add('v264-hide'));
    ensureKpi(root,body,data);
    const panel=body.querySelector('.v46-subs-panel');
    if(panel){
      let wrap=panel.closest('.v264-services-block');
      if(!wrap){wrap=block('TUS SERVICIOS','Tus servicios','Nombre, importe, frecuencia, próximo cargo y acciones de cada suscripción, en una presentación compacta y uniforme.','v264-services-block v264-services-card');panel.parentNode.insertBefore(wrap,panel);wrap.append(panel);} 
      const h=panel.querySelector('.v46-subs-head h3');if(h)h.textContent='Tus servicios';
      const p=panel.querySelector('.v46-subs-head p');if(p)p.textContent='Importe, frecuencia y próximo cargo por servicio. El nombre, el monto y la próxima renovación se priorizan visualmente.';
    }
    const intel=body.querySelector('.subscription-world');
    if(intel){
      let wrap=intel.closest('.v264-intelligence-block');
      if(!wrap){wrap=block('INTELIGENCIA DE SUSCRIPCIONES','Tu inteligencia de suscripciones','Indicadores, ranking Pareto y distribución por categoría con una lectura más ejecutiva, manteniendo todos los datos y cálculos dinámicos.','v264-intelligence-block v264-intelligence-card');intel.parentNode.insertBefore(wrap,intel);wrap.append(intel);} 
      const foot=wrap.querySelector('.v264-block-head .copy p');if(foot)foot.textContent='Equivalente mensual, gasto anual, concentración 80/20, mayor suscripción, ranking y distribución por categoría, sin eliminar profundidad analítica.';
    }
  }
  const previous=render;
  render=function(){const result=previous.apply(this,arguments);requestAnimationFrame(build);return result;};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>requestAnimationFrame(build),{once:true});
  else requestAnimationFrame(build);
})();



/* Registro de compra realizada para un tercero. Reutiliza el motor existente:
   personal_issue(lent,card) => cargo patrimonial a tarjeta, no gasto propio.
   personal_settlement(lent,account/card) => anticipo recibido, no ingreso propio.
   card_payment(account,card) => solo si realmente se pagó a la tarjeta.
   No se modifica el importe histórico del corte. */
(function(){
 'use strict';
 let draft=null,processing=false;
 const $=s=>document.querySelector(s), esc=s=>sanitize(String(s??''));
 const moneyIn=(n,c)=>money(Math.max(0,Math.round((Number(n)||0)*100)/100),c,2);
 const fmt=(n,c)=>moneyIn(n,c||'DOP');
 const activeCards=()=>db.cards.filter(c=>!c.archived);
 const activeAccounts=ccy=>db.accounts.filter(a=>!a.archived&&a.currency===ccy);
 const rows=x=>x.map(([key,value])=>'<div class="v354-review-row"><span>'+esc(key)+'</span><strong>'+esc(value)+'</strong></div>').join('');
 /* Ley 30-26: tasa referencial 0.20% desde 03/07/2026; antes 0.15%.
    El impuesto corresponde al emisor de la transferencia; no se carga al receptor.
    No se crea ningún egreso ni se altera el pendiente de corte por esta estimación. */
 const v356TaxInfo=(channel,received,currency,date)=>{
  const applicable=channel==='internet'&&Number(received)>0;
  const rate=String(date||'')>='2026-07-03'?0.002:0.0015;
  if(!applicable)return {applicable:false,amount:0,rate,estimable:true};
  const estimable=currency==='DOP';
  const amount=estimable?Math.round(Number(received)*rate*100)/100:0;
  return {applicable:true,amount,rate,estimable};
 };

 const root=()=>document.getElementById('modal-root');
 const makeShell=(title,step,amount,inner,footer)=>{
  const dark=document.body.classList.contains('theme-black')||document.body.classList.contains('theme-dark');
  const mobile=matchMedia('(max-width:790px)').matches;
  const modalStyle='background:'+ (dark?'#000000':'#f6f8fc')+'!important;padding:0!important;'+(mobile?'height:100dvh!important;max-height:100dvh!important;min-height:100dvh!important;width:100vw!important;':'');
  root().innerHTML='<div class="modal-layer v354-layer" data-backdrop="true"><section class="modal v354-dialog" style="'+modalStyle+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><header class="v354-top"><div><span class="v354-eyebrow">vive el hoy · MOVIMIENTO RÁPIDO</span><h2>'+esc(title)+'</h2></div><button type="button" class="v354-close" data-v354-act="close" aria-label="Cerrar">×</button></header><div class="v354-scroll"><div class="v354-progress"><small>'+esc(step)+'</small><strong>'+esc(amount)+'</strong></div>'+inner+'</div><footer class="v354-foot">'+footer+'</footer></section></div>';
 };
 const close=()=>{draft=null;processing=false;closeModal()};
 const selectOptions=(arr,selected)=>arr.map(([id,name])=>'<option value="'+esc(id)+'" '+(String(selected)===String(id)?'selected':'')+'>'+esc(name)+'</option>').join('');
 function formScreen(initial={}){
  if(!activeCards().length){toast('Primero registra una tarjeta de crédito en Bancos.');return;}
  const c=activeCards().find(x=>x.id===initial.cardId)||activeCards()[0], cc=initial.currency||'DOP';
  const ac=activeAccounts(cc),accountId=ac.some(a=>a.id===initial.accountId)?initial.accountId:(ac[0]?.id||'');
  const personOptions=[...new Set([...(db.personalContacts||[]).map(x=>[x.firstName,x.lastName].filter(Boolean).join(' ').trim()),...(db.personalLoans||[]).map(x=>x.person)].filter(Boolean))];
  const datalist='<datalist id="v354-people">'+personOptions.map(x=>'<option value="'+esc(x)+'"></option>').join('')+'</datalist>';
  const content='<div class="v355-intro"><strong>Una compra para alguien</strong><span>Cuánto usaste de tu tarjeta y cuánto te entregaron.</span></div>'+
   '<div id="v354-error" class="v354-error" role="alert" aria-live="polite"></div>'+
   '<form id="v354-form" class="v354-fields v355-fast-form" autocomplete="off">'+datalist+
   '<label class="v355-person">¿Para quién fue?<input name="person" list="v354-people" maxlength="85" required placeholder="Ej. Mi hermano" value="'+esc(initial.person||'')+'"></label>'+
   '<div class="v355-sums"><label>Compra total<input name="purchase" type="number" inputmode="decimal" step="0.01" min="0.01" required value="'+esc(initial.purchase??'')+'" placeholder="6000"></label><label>Me entregó<input name="received" type="number" inputmode="decimal" step="0.01" min="0" value="'+esc(initial.received??'')+'" placeholder="5000"></label></div>'+
   '<div class="v355-result" aria-live="polite"><span>Me debe · Otros</span><strong id="v354-owed-preview">—</strong></div>'+
   '<label>¿Qué pasó con el dinero?<select name="receiptMode" required><option value="">Selecciona lo que ocurrió</option><option value="card">Abonó directamente a mi tarjeta</option><option value="account">Lo recibí en cuenta o efectivo</option><option value="account_and_paid">Lo recibí y ya pagué la tarjeta</option><option value="none">Aún no me ha entregado dinero</option></select></label>'+
   '<label class="v356-channel">Canal del dinero<select name="channel" required><option value="presencial" '+((initial.channel||'presencial')==='presencial'?'selected':'')+'>Presencial</option><option value="internet" '+(initial.channel==='internet'?'selected':'')+'>Internet Banking</option></select></label>'+ 
   '<div class="v356-tax-indicator" id="v356-tax-indicator" aria-live="polite"><div><span>Impuesto de transferencia</span><strong id="v356-tax-amount">No aplica</strong></div><small id="v356-tax-explainer">No se añaden impuestos a esta operación.</small></div>'+ 
   '<div class="v355-compact-note" id="v354-cut-note">Si el dinero no llegó a la tarjeta, el pendiente del corte no disminuye.</div>'+
   '<details class="v355-extra" '+(initial.showExtra?'open':'')+'><summary><span>Tarjeta: <strong id="v355-card-label">'+esc(c.name)+'</strong></span><span aria-hidden="true">Editar ⌄</span></summary><div class="v354-fields v355-extra-fields">'+
   '<label>Tarjeta utilizada<select name="cardId" required>'+selectOptions(activeCards().map(x=>[x.id,x.name+' · '+bankOf(x)]),c.id)+'</select></label>'+
   '<label>Moneda<select name="currency"><option value="DOP" '+(cc==='DOP'?'selected':'')+'>RD$ · Pesos</option><option value="USD" '+(cc==='USD'?'selected':'')+'>US$ · Dólares</option></select></label>'+
   '<label id="v354-account-label" hidden>Cuenta en la que recibiste el dinero<select name="accountId">'+selectOptions(ac.map(a=>[a.id,a.name+' · '+fmt(getAccountBalance(a),cc)]),accountId)+'</select></label>'+
   '<label>Fecha de la compra<input type="date" name="date" max="'+esc(today())+'" required value="'+esc(initial.date||today())+'"></label>'+
   '<label>Fecha para cobrar la diferencia<input type="date" name="dueDate" required value="'+esc(initial.dueDate||plusMonths(today(),1))+'"></label>'+
   '<label>Nota opcional<input name="note" maxlength="120" placeholder="Ej. Compra de supermercado" value="'+esc(initial.note||'')+'"></label></div></details></form>';
  const footer='<button type="button" data-v354-act="close">Cancelar</button><button class="primary" type="submit" form="v354-form">Revisar →</button>';
  makeShell('Movimiento rápido','PASO 1 DE 2 · DATOS',fmt(initial.purchase,cc),content,footer);
  const f=$('#v354-form');f.elements.receiptMode.value=initial.receiptMode||'';
  recalc(f);f.elements.person.focus({preventScroll:true});
 }
 function recalc(form){
  if(!form)return;
  const v=Object.fromEntries(new FormData(form).entries()),p=Number(v.purchase)||0,r=Number(v.received)||0,cc=v.currency||'DOP';
  const mode=v.receiptMode||'',needAcc=mode==='account'||mode==='account_and_paid';
  const label=$('#v354-account-label');if(label)label.hidden=!needAcc;
  if(needAcc)form.querySelector('.v355-extra')?.setAttribute('open','');
  const owed=$('#v354-owed-preview'),hint=$('#v354-cut-note'),amountLabel=$('.v354-progress strong'),cardLabel=$('#v355-card-label');
  if(cardLabel)cardLabel.textContent=card(v.cardId)?.name||'Seleccionar tarjeta';
  if(amountLabel)amountLabel.textContent=p>0?fmt(p,cc):fmt(0,cc);
  if(owed)owed.textContent=p>0?fmt(Math.max(0,p-r),cc):'—';
  const modeHint={
   card:'El abono a la tarjeta reduce el corte pendiente cuando el banco lo aplicó.',
   account:'El dinero llegó a tu cuenta; el corte sigue pendiente hasta pagar la tarjeta.',
   account_and_paid:'El dinero entró en tu cuenta y ya hiciste un pago real a la tarjeta.',
   none:'Aún no has recibido dinero; quedará por cobrar a esta persona.'
  };
  if(hint)hint.textContent=modeHint[mode]||'No se registran ingresos ni gastos personales por esta compra.';
  const tax=v356TaxInfo(v.channel,r,cc,v.date);
  const taxAmount=$('#v356-tax-amount'),taxExplain=$('#v356-tax-explainer');
  if(taxAmount)taxAmount.textContent=!tax.applicable?(r>0&&v.channel==='presencial'?'Sin estimar':'No aplica'):!tax.estimable?'Verifica en tu banco':fmt(tax.amount,'DOP')+' estimados';
  if(taxExplain)taxExplain.textContent=!tax.applicable?'No se estima por este canal. Si hubo transferencia bancaria presencial, verifica el impuesto real con el banco.':
   !tax.estimable?'Transferencia en dólares: se necesita la tasa del banco para estimar el impuesto en pesos.':'Referencia '+(tax.rate*100).toFixed(2)+'%. Normalmente lo paga quien envía. No se descontará de tus cuentas.';
 }
 function validated(raw){
  const person=String(raw.person||'').trim().replace(/\s+/g,' '),ccy=String(raw.currency||''),c=card(raw.cardId),p=Number(raw.purchase),r=Number(raw.received),mode=raw.receiptMode,date=String(raw.date||''),dueDate=String(raw.dueDate||''),channel=String(raw.channel||'');
  if(!person||person.length>85)throw Error('Indica quién te debe el dinero.');
  if(!c||c.archived)throw Error('Selecciona una tarjeta activa.');
  if(!['DOP','USD'].includes(ccy))throw Error('Selecciona una moneda válida.');
  if(!['presencial','internet'].includes(channel))throw Error('Selecciona Presencial o Internet Banking.');
  if(!Number.isFinite(p)||p<=0||Math.round(p*100)/100!==Number(p.toFixed(2)))throw Error('La compra debe ser mayor que cero y tener como máximo dos decimales.');
  if(!Number.isFinite(r)||r<0||r>p+0.00001||Math.round(r*100)/100!==Number(r.toFixed(2)))throw Error('El dinero recibido debe estar entre cero y el valor de la compra.');
  if(!['card','account','account_and_paid','none'].includes(mode))throw Error('Indica qué pasó con el dinero: tu tarjeta, tu cuenta o pendiente.');
  if(mode==='none'&&r>0.00001)throw Error('Si no has recibido dinero, escribe RD$0 o selecciona su destino real.');
  if(mode!=='none'&&r<.005)throw Error('Si todavía no ha entregado dinero, selecciona «Todavía no recibido».');
  const a=['account','account_and_paid'].includes(mode)?account(raw.accountId):null;
  if(['account','account_and_paid'].includes(mode)&&(!a||a.archived||a.currency!==ccy))throw Error('Elige una cuenta o efectivo activo en la misma moneda.');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>today())throw Error('Indica la fecha real de la compra.');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(dueDate)||dueDate<date)throw Error('La fecha para cobrarle debe ser igual o posterior a la compra.');
  const tax=v356TaxInfo(channel,r,ccy,date);
  return {person,cardId:c.id,cardName:c.name,currency:ccy,purchase:Math.round(p*100)/100,received:Math.round(r*100)/100,receiptMode:mode,channel,transferTaxEstimate:tax.amount,transferTaxRate:tax.applicable?tax.rate:0,transferTaxEstimable:tax.estimable,accountId:a?.id||'',accountName:a?.name||'',date,dueDate,note:String(raw.note||'').trim().slice(0,120)};
 }
 function review(v){
  draft={...v};
  const cardPayment=v.received>0&&['card','account_and_paid'].includes(v.receiptMode),due=Math.max(0,Math.round((v.purchase-v.received)*100)/100);
  const payLabel=v.receiptMode==='card'?'Abono directo a tarjeta':v.receiptMode==='account_and_paid'?'Recibido y pagado a tarjeta':v.receiptMode==='account'?'Recibido en '+v.accountName:'Todavía no recibido';
  const summary='<div class="v355-review-hero"><span>Por cobrar · Me deben</span><strong>'+fmt(due,v.currency)+'</strong><small>'+esc(v.person)+'</small></div>'+
   '<div class="v354-panel v355-review-panel"><h3>Revisa el movimiento</h3>'+rows([['Compra con tarjeta',fmt(v.purchase,v.currency)],['Me entregó',fmt(v.received,v.currency)],['Tarjeta',v.cardName],['Dinero',payLabel],['Canal',v.channel==='internet'?'Internet Banking':'Presencial'],['Impuesto de transferencia',v.channel==='internet'&&v.received>0?(v.transferTaxEstimable?fmt(v.transferTaxEstimate,'DOP')+' · estimado':'No calculable · verificar con banco'):(v.received>0?'Sin estimar':'No aplica')]])+'</div>'+
   '<div class="v355-compact-note">Revisa y pulsa <strong>Confirmar y guardar</strong>. El impuesto mostrado es informativo, normalmente corresponde a quien envía y no se debita de tu cuenta. El corte solo baja con un pago real.</div>';
  makeShell('Revisar movimiento','PASO 2 DE 2 · REVISIÓN',fmt(v.purchase,v.currency),summary,'<button type="button" data-v354-act="back">Editar</button><button class="primary" type="button" data-v354-act="confirm">Confirmar y guardar</button>');
 }
 function save(v){
  if(processing)return;processing=true;
  const button=$('[data-v354-act="confirm"]');if(button)button.disabled=true;
  try{
   const x=validated(v),now=new Date().toISOString(),relationId=uuid();
   const relation={id:relationId,person:x.person,direction:'lent',principal:x.purchase,currency:x.currency,cardId:x.cardId,accountId:'',date:x.date,dueDate:x.dueDate,note:'Compra para tercero · Canal: '+(x.channel==='internet'?'Internet Banking':'Presencial')+(x.note?' · '+x.note:''),openingMode:'new',source:'third_party_card_purchase',quickChannel:x.channel,estimatedTransferTax:x.transferTaxEstimate,taxRate:x.transferTaxRate,taxOwner:'sender',createdAt:now};
   const common={created:now,date:x.date,currency:x.currency,personalLoanId:relationId,thirdPartyPurchase:true,quickChannel:x.channel,estimatedTransferTax:x.transferTaxEstimate,taxRate:x.transferTaxRate,taxOwner:'sender'};
   const entries=[{...common,id:uuid(),type:'personal_issue',cardId:x.cardId,amount:x.purchase,category:'Movimiento patrimonial',note:'Compra para '+x.person+' · '+(x.channel==='internet'?'Internet Banking':'Presencial')+(x.note?' · '+x.note:'')}];
   if(x.received>.005){entries.push({...common,id:uuid(),type:'personal_settlement',cardId:x.receiptMode==='card'?x.cardId:'',accountId:x.receiptMode==='card'?'':x.accountId,principal:x.received,interest:0,amount:x.received,category:'Movimiento patrimonial',note:'Dinero recibido de '+x.person+' · '+(x.channel==='internet'?'Internet Banking':'Presencial')});}
   if(x.received>.005&&x.receiptMode==='account_and_paid')entries.push({id:uuid(),created:now,type:'card_payment',date:x.date,cardId:x.cardId,accountId:x.accountId,currency:x.currency,amount:x.received,sourceAmount:x.received,paymentTax:0,paymentFee:0,category:'Movimiento patrimonial',thirdPartyPurchase:true,thirdPartyRelationId:relationId,note:'Pago real a tarjeta con dinero de '+x.person});
   // All local changes and their source link are appended together. No duplicate expense/income.
   db.personalLoans.push(relation);db.transactions.push(...entries);
   const saved=persist();
   if(saved===false){db.transactions.splice(db.transactions.length-entries.length,entries.length);db.personalLoans.pop();if(typeof v99Invalidate==='function')v99Invalidate();throw Error('No se pudo guardar. Inicia sesión y vuelve a intentarlo; no se registró ningún movimiento.');}
   draft=null;closeModal();render();toast('Movimiento rápido guardado. Te deben '+fmt(Math.max(0,x.purchase-x.received),x.currency)+'.');
  }catch(e){processing=false;if(button)button.disabled=false;toast(e.message||'No se pudo registrar la compra.');}
 }
 document.addEventListener('click',function(e){
  const b=e.target.closest?.('[data-v354-act]');if(!b)return;
  e.preventDefault();e.stopPropagation();const action=b.dataset.v354Act;
  if(action==='open'){draft=null;formScreen({cardId:b.dataset.cardId||''});}
  else if(action==='close'){close();}
  else if(action==='back'){const v=draft;draft=null;formScreen(v||{});}
  else if(action==='confirm'){if(draft)save(draft);}
 },true);
 document.addEventListener('submit',function(e){
  const f=e.target;if(f.id!=='v354-form')return;
  e.preventDefault();e.stopPropagation();
  try{const x=validated(Object.fromEntries(new FormData(f).entries()));x.showExtra=!!f.querySelector('.v355-extra')?.open;review(x)}
  catch(err){const el=$('#v354-error');if(el){el.textContent=err.message;el.scrollIntoView({behavior:'smooth',block:'nearest'});}else toast(err.message);}
 },true);
 document.addEventListener('input',function(e){const f=e.target.closest?.('#v354-form');if(f)recalc(f)},true);
 document.addEventListener('change',function(e){const f=e.target.closest?.('#v354-form');if(!f)return;
  if(e.target.name==='currency'){
   const cc=f.elements.currency.value,a=activeAccounts(cc),select=f.elements.accountId;
   select.innerHTML=selectOptions(a.map(x=>[x.id,x.name+' · '+fmt(getAccountBalance(x),cc)]),a[0]?.id||'');
  }
  recalc(f);
 },true);
})();


/* V411: Integrated inside original application IIFE. Presentational integration only. No credentials, local copies, seed data, or mutations here. */
(function(){
  'use strict';
  const fmt=(n)=>money(Number(n)||0,'DOP',0);
  const esc=v=>sanitize(String(v??''));
  const number=n=>Number.isFinite(Number(n))?Number(n):0;
  const monthText=()=>dateObj((ui.month||today().slice(0,7))+'-01').toLocaleDateString('es-DO',{month:'long',year:'numeric'});
  const monthKey=()=>String(ui.month||today().slice(0,7));
  const normalizedMonthly=r=>v339MonthlyEquivalent(r.amount,r.currency,r.frequency);
  const activeRecurring=()=>v339ActiveRecurring();

  // Image 4 is the exact visual/structural reference: two groups, 6 + 4 entries.
  mobileHub=function(){
    const totals=monthStats();
    const plan=v290BudgetSnapshot(monthKey());
    const people=personalTotals();
    const subs=activeRecurring();
    const cards=(db.cards||[]).filter(c=>!c.archived&&!isHidden(c));
    const cats=new Set((db.transactions||[]).filter(t=>String(t.date||'').startsWith(monthKey()) && t.category).map(t=>String(t.category)));
    const kpiBudget=plan.percent===null||!Number.isFinite(plan.percent)?'Sin presupuesto':v85Pct(plan.percent)+' utilizado';
    const previousMonth=dateObj(monthKey()+'-01');
    previousMonth.setMonth(previousMonth.getMonth()-1);
    const prevTotals=monthlyTotals(previousMonth.getFullYear(),previousMonth.getMonth()+1);
    const variation=(current,prior)=>{
      if(!Number.isFinite(current)||!Number.isFinite(prior)||prior<=0)return null;
      const v=(current-prior)/prior*100;
      return {pct:(v>=0?'+':'')+new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(v)+'%',dir:v>0?'up':v<0?'down':'flat'};
    };
    const incomeChange=variation(totals.income,prevTotals.income);
    const expenseChange=variation(totals.expense,prevTotals.expense);
    const pendingPersonal=Math.max(0,people.payable)+Math.max(0,people.receivable);
    const fmtShort=n=>{const x=Number(n)||0;return Math.abs(x)<10000?fmt(x):'RD$'+new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(x/1000)+'K';};
    const personalLabel=pendingPersonal<=.005?'RD$0 pendiente':fmtShort(pendingPersonal)+' pendiente';

    const coverMonths=v89DebtCapacity(monthKey()).monthly>0?totalLiquid()/v89DebtCapacity(monthKey()).monthly:null;
    const pressureState=(()=>{const cap=v89DebtCapacity(monthKey());const ratio=cap.ratio;if(!Number.isFinite(cap.monthly)||cap.monthly<=0)return 'Sin presión';if(ratio!==null&&ratio>=100)return 'Presión alta';if((coverMonths!==null&&coverMonths>=2)||(ratio!==null&&ratio<60))return 'Presión baja';if((coverMonths!==null&&coverMonths>=1)||(ratio!==null&&ratio<85))return 'Presión estable';return 'Presión activa';})();
    const sections=[
      {tag:'TU ACTIVIDAD',heading:'Gestiona los movimientos de tu dinero',desc:'Registra, analiza y mantén el control de tu día a día financiero.',items:[
       ['income','Ingresos','Lo que recibes','up','green',fmt(totals.income),false,incomeChange],
       ['expenses','Egresos','Lo que utilizas','down','rose',fmt(totals.expense),false,expenseChange],
       ['budget','Presupuesto','Límites y ejecución','chart','blue',kpiBudget],
       ['categories','Categorías','Organización','grid','violet',cats.size+' categorías'],
       ['recurring','Suscripciones','Recurrencia','calendar','blue',subs.length+' activas · '+fmtShort(v80RecurringMonthly())],
       ['personal','Entre personas','Cobros y pagos','users','violet',personalLabel]
      ]},
      {tag:'TU VISIÓN',heading:'Planifica y mantén el control integral',desc:'Una mirada completa de tus finanzas, compromisos y próximos pasos.',items:[
       ['payments','Visión global','Estrategia','eye','blue','',true],
       ['pressure','Presión financiera','Próximos 30 días','calendar','violet',fmtShort(v89DebtCapacity(monthKey()).monthly)],
       ['cards','Tarjetas','Créditos','card','blue',cards.filter(c=>num(cardStatus(c,'DOP').debt)>0.005||num(cardStatus(c,'USD').debt)>0.005).length+' de '+cards.length+' con balance'],
       ['projection','Planificación','Escenarios','analytics','violet','']
      ]}
    ];
    const tile=([id,name,desc,ic,tone,val,featured,change])=>{
      const isCompare=id==='income'||id==='expenses';
      const isBudget=id==='budget';
      const isCategory=id==='categories';
      const isPeople=id==='personal';
      const isCard=id==='cards';
      const isCommitment=id==='pressure';
      const indicator=val?`<span class="v431-value" title="${esc(id==='recurring'?subs.length+' suscripciones activas · '+fmt(v80RecurringMonthly())+' por mes':val)}">${esc(val)}</span>`:'';
      const variance=isCompare?`<span class="v431-compare ${change?'v431-compare-'+change.dir:'v431-compare-neutral'}" aria-label="${change?'Variación '+esc(change.pct):'Sin datos comparables'} frente al mes anterior"><span class="v431-compare-chip"><span aria-hidden="true">${change?(change.dir==='up'?'↗':change.dir==='down'?'↘':'→'):'—'}</span> ${change?esc(change.pct):'—'}</span><span class="v431-compare-label">vs. mes anterior</span></span>`:'';
      const budgetBar=isBudget&&Number.isFinite(plan.percent)?`<span class="v431-progress" role="progressbar" aria-label="Presupuesto utilizado" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.max(0,Math.min(100,plan.percent))}"><i style="width:${Math.max(0,Math.min(100,plan.percent))}%"></i></span>`:'';
      const categoryBar=isCategory?`<span class="v431-category-spectrum" aria-hidden="true"></span>`:'';
      const statusClass=isPeople?'v431-status-people':isCard?'v431-status-card':isCommitment?'v431-status-commitment':'';
      return `<button type="button" class="v431-tile ${featured?'v431-tile-featured':''} v431-${esc(id)}" data-act="navigate" data-id="${esc(id)}" data-tone="${esc(tone)}" aria-label="Abrir ${esc(name)}. ${esc(desc)}${val?'. '+esc(val):''}${isCompare?'. '+(change?'Variación '+esc(change.pct):'Sin base comparable')+' frente al mes anterior':''}">
        <span class="v431-tile-icon" aria-hidden="true">${icon(ic)}</span>
        <span class="v431-tile-body"><strong class="v431-tile-name">${esc(name)}</strong><span class="v431-tile-description">${esc(desc)}</span>${indicator?`<span class="v431-tile-stat ${statusClass}">${indicator}</span>`:''}${variance}${budgetBar}${categoryBar}</span>
        <span class="v431-tile-arrow" aria-hidden="true">${icon('arrow')}</span>
        ${featured?'<span class="v431-feature-bars" aria-hidden="true"><i></i><i></i><i></i><i></i></span>':''}
        ${id==='projection'?`<span class="v434-planning-spark" aria-hidden="true"><svg viewBox="0 0 120 40" preserveAspectRatio="xMaxYMax meet"><defs><linearGradient id="v434Spark" x1="0" y1="0" x2="1" y2="0"><stop offset="0" class="v984-s0"/><stop offset="1" class="v984-s1"/></linearGradient><linearGradient id="v984Area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" class="v984-a0"/><stop offset="1" class="v984-a1"/></linearGradient></defs><path class="v984-area" d="M4 34 C18 33 22 24 34 25 C46 26 50 16 62 18 C74 20 78 9 92 10 C102 11 108 6 116 4 L116 38 L4 38 Z" fill="url(#v984Area)"/><path class="v984-line" d="M4 34 C18 33 22 24 34 25 C46 26 50 16 62 18 C74 20 78 9 92 10 C102 11 108 6 116 4" fill="none" stroke="url(#v434Spark)" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/><circle class="v984-dot" cx="116" cy="4" r="3.6"/></svg></span>`:''}
      </button>`;
    };
    return `<div class="v410-explore v431-explore" aria-label="Explorar módulos financieros"><header class="v410-explore-head"><div><h1>Explorar</h1><p>Organiza y potencia tu espacio financiero.</p></div><label class="v410-date v990-month"><span>${esc(monthText())}</span><input id="monthFilter" type="month" value="${esc(ui.month||today().slice(0,7))}" aria-label="Período de análisis"></label></header>${sections.map(s=>`<section class="v410-explore-sec"><header><span class="v410-kicker">${s.tag}</span><h2>${s.heading}</h2><p>${s.desc}</p></header><div class="v410-explore-grid">${s.items.map(tile).join('')}</div></section>`).join('')}</div>`;
  };

  // Image 1 supplies *behavior* only; existing app style controls all layout.
  const originalRecurring=pages.recurring;
  let categoryFilter='__all__';
  pages.recurring=function(){
    // V416: La experiencia móvil utiliza íntegra la vista original de Suscripciones.
    // El rediseño por categorías se aplica únicamente a la versión web de escritorio.
    if(isMobileViewport()) return originalRecurring();
    const records=(db.recurring||[]).filter(Boolean);
    const active=activeRecurring();
    const monthly=v80RecurringMonthly();
    const todayDate=today();
    const next7=active.filter(r=>r.nextDue&&r.nextDue>=todayDate&&r.nextDue<=addDays(todayDate,7));
    const dueSoon=active.filter(r=>r.nextDue&&r.nextDue>=todayDate).slice().sort((a,b)=>a.nextDue.localeCompare(b.nextDue))[0];
    const largest=active.slice().sort((a,b)=>normalizedMonthly(b)-normalizedMonthly(a))[0];
    const groupOf=r=>String(r.category||'Sin categoría').trim()||'Sin categoría';
    const byCategory=new Map();
    for(const r of records){const cat=groupOf(r);if(!byCategory.has(cat))byCategory.set(cat,[]);byCategory.get(cat).push(r)}
    const categories=[...byCategory.keys()].sort((a,b)=>a.localeCompare(b,'es'));
    if(categoryFilter!=='__all__'&&!byCategory.has(categoryFilter))categoryFilter='__all__';
    const selectedCategories=categories.filter(c=>categoryFilter==='__all__'||categoryFilter===c);
    const rankedCategory=categories.map(c=>({cat:c,cost:byCategory.get(c).filter(r=>r.active!==false&&!r.archived).reduce((a,r)=>a+normalizedMonthly(r),0)})).sort((a,b)=>b.cost-a.cost)[0];
    const frequency=f=>({monthly:'Mensual',weekly:'Semanal',semi_monthly:'Quincenal',quarterly:'Trimestral',semiannual:'Semestral',annual:'Anual',yearly:'Anual'})[f]||String(f||'Periódico');
    const source=r=>{let card=(db.cards||[]).find(c=>c.id===r.cardId);let account=(db.accounts||[]).find(a=>a.id===r.accountId);return card?card.name:account?account.name:r.paymentMethod||r.paymentSource||'No indicada'};
    const activeCount=active.length;
    const firstMoney=(v,cur)=>money(v,cur||'DOP',2);
    const line=(r)=>{const state=r.archived?'Archivada':r.active===false?'Pausada':'Activa';return `<tr>
     <td data-label="Servicio"><span class="v410-servicename">${v45SubIcon(r,'small')}<strong>${esc(r.name||'Servicio')}</strong></span></td>
     <td data-label="Categoría">${esc(groupOf(r))}</td>
     <td data-label="Próximo pago">${r.nextDue?esc(prettyDate(r.nextDue)):'Sin fecha'}</td>
     <td data-label="Monto"><b>${firstMoney(r.amount,r.currency)}</b></td>
     <td data-label="Ciclo">${esc(frequency(r.frequency))}</td>
     <td data-label="Estado"><span class="v410-service-status ${r.archived?'archived':r.active===false?'paused':''}">${state}</span></td>
     <td data-label="Fuente de pago">${esc(source(r))}</td>
     <td><div class="v410-rowactions"><button type="button" data-act="editRecurring" data-id="${esc(r.id)}">Editar</button>${!r.archived?`<button type="button" data-act="toggleRecurring" data-id="${esc(r.id)}">${r.active===false?'Reactivar':'Pausar'}</button>`:''}${r.active!==false&&!r.archived?`<button type="button" data-act="payRecurring" data-id="${esc(r.id)}">Registrar pago</button>`:''}</div></td>
    </tr>`};
    const group=(cat)=>{const list=byCategory.get(cat);const subtotal=list.filter(r=>r.active!==false&&!r.archived).reduce((sum,r)=>sum+normalizedMonthly(r),0);return `<details class="v410-subgroup" open><summary><span class="v410-category-icon">${icon('cycle')}</span><span><strong>${esc(cat)} · ${list.length}</strong><small>${list.filter(r=>r.active!==false&&!r.archived).length} activas · agrupación por categoría</small></span><b class="v410-subtotal">${fmt(subtotal)} / mes</b><span class="v410-drop" aria-hidden="true">⌄</span></summary><div class="v410-subtable"><table><thead><tr><th>Servicio</th><th>Categoría</th><th>Próximo pago</th><th>Monto</th><th>Ciclo</th><th>Estado</th><th>Fuente de pago</th><th>Acciones</th></tr></thead><tbody>${list.map(line).join('')}</tbody></table></div></details>`};
    return `<div class="v410-subs"><header class="v410-subs-head"><div><span class="v410-kicker">vive el hoy · PAGOS RECURRENTES</span><h1>Suscripciones</h1><p>Gestiona tus servicios, categorías, renovaciones y pagos con tus registros reales.</p></div><button type="button" class="v410-primary" data-act="addRecurring">${icon('plus')} Agregar suscripción</button></header>
      <div class="v410-subs-stats"><article class="v410-substat"><small>Equivalente mensual</small><strong>${fmt(monthly)}</strong><span>Servicios activos · RD$ al cambio configurado</span></article><article class="v410-substat"><small>Suscripciones activas</small><strong>${activeCount}</strong><span>De ${records.length} registradas</span></article><article class="v410-substat"><small>Renovaciones próximas</small><strong>${next7.length}</strong><span>En los próximos siete días</span></article><article class="v410-substat"><small>Promedio por servicio activo</small><strong>${activeCount?fmt(monthly/activeCount):'—'}</strong><span>Equivalente mensual</span></article></div>
      <section class="v410-insight" aria-label="Análisis de suscripciones"><div class="v410-insight-title"><span class="v410-kicker">LECTURA EJECUTIVA</span><h2>Sobre tus pagos recurrentes</h2><p>Un resumen calculado únicamente con los servicios registrados.</p></div><article><small>Mayor gasto mensual</small><strong>${largest?esc(largest.name):'Sin servicios activos'}</strong><span>${largest?fmt(normalizedMonthly(largest))+' / mes':'—'}</span></article><article><small>Próxima renovación</small><strong>${dueSoon?esc(dueSoon.name):'Sin renovación próxima'}</strong><span>${dueSoon?esc(prettyDate(dueSoon.nextDue))+' · '+firstMoney(dueSoon.amount,dueSoon.currency):'—'}</span></article><article><small>Categoría de mayor costo</small><strong>${rankedCategory?.cost>0?esc(rankedCategory.cat):'Sin datos de gasto'}</strong><span>${rankedCategory?.cost>0?fmt(rankedCategory.cost)+' / mes':'—'}</span></article></section>
      <div class="v410-subfilters" role="group" aria-label="Filtrar por categoría"><button type="button" data-v410-category="__all__" aria-pressed="${categoryFilter==='__all__'}">Todas (${records.length})</button>${categories.map(c=>`<button type="button" data-v410-category="${esc(c)}" aria-pressed="${categoryFilter===c}">${esc(c)} (${byCategory.get(c).length})</button>`).join('')}</div>
      ${selectedCategories.length?selectedCategories.map(group).join(''):'<div class="panel empty">No hay suscripciones registradas.</div>'}
      <div class="v417-subscriptions-analytics" aria-label="Análisis de gasto recurrente mensual y anual">${subscriptionAnalysis()}</div>
    </div>`;
  };
  document.addEventListener('click',ev=>{const btn=ev.target.closest?.('[data-v410-category]');if(!btn)return;ev.preventDefault();ev.stopImmediatePropagation();categoryFilter=btn.dataset.v410Category||'__all__';render()},true);

  // Image 2: reuse the existing fully dynamic financial map/handlers.
  const creativeMap=v342CreativePositionMobile;
  v342CreativePositionMobile=function(...args){return creativeMap(...args).replace('v344-creative v342-creative-position','v344-creative v342-creative-position v410-financial-map')};
  // V417: El Inicio de escritorio conserva íntegra su vista nativa.
  // El diseño de mapa móvil solo funciona dentro del Inicio móvil original.


  // V412: the premium credit and commitment designs are managed only by Personalización.
})();
