// Preserve existing generic entry: only show pending bills (no category catalogue).
function v923ServiceChooser(){
 const all=v261PendingServices();
 // Prioritize overdue/today and the nearest due dates. No categories or independent card/loan actions.
 const ranked=all.slice().sort((a,b)=>String(a.x.date).localeCompare(String(b.x.date)));
 const pending=ranked.filter(({x})=>diffDays(x.date,today())<=7).slice(0,6);
 const taken=new Set(pending.map(({r})=>String(r.id)));
 const extraPending=ranked.filter(({r,x})=>!taken.has(String(r.id))&&diffDays(x.date,today())<=7);
 const future=ranked.filter(({x})=>diffDays(x.date,today())>7);
 const group=(title,detail,items)=>`<section class="v261-group v923-service-group"><div class="v261-group-head"><div><h3>${title}</h3><small>${detail}</small></div><span class="v261-number">${items.length}</span></div><div class="v261-bill-list">${items.length?items.map(({r,x})=>v261BillRow(r,x)).join(''):'<div class="v261-none"><strong>Sin pagos en este grupo</strong><small>Los vencimientos se mostrarán cuando estén pendientes.</small></div>'}</div></section>`;
 const pendingOverflow=extraPending.length?`<p class="v923-pending-overflow" role="status">Hay ${extraPending.length} compromiso${extraPending.length===1?'':'s'} pendiente${extraPending.length===1?'':'s'} adicional${extraPending.length===1?'':'es'}; la lista muestra los seis más próximos. <button type="button" data-act="navigate" data-id="recurring" data-tab="next">Ver todos en Suscripciones →</button></p>`:'';
 const body=`${group('Pendientes','Hasta seis cargos vencidos o próximos, por fecha',pending)}${pendingOverflow}${group('Próximos pagos y programados','Otros compromisos futuros',future)}`;
 v261ServiceFrame('Pagar servicios','Selecciona un compromiso pendiente para confirmar el pago',body);
};
v261OpenBill=v917BillDetail;
payRecurring=function(id){return v917BillDetail(id)};
document.addEventListener('submit',function(e){
 const form=e.target;if(form?.id!=='v917ServiceConfirm')return;
 e.preventDefault();e.stopImmediatePropagation();
 const error=form.querySelector('#v917ServiceError');error.textContent='';
 const submit=document.querySelector('.v917-submit');if(submit?.disabled)return;
 try{
  const id=form.dataset.recurring,r=(db.recurring||[]).find(x=>String(x.id)===id),pair=v261PendingServices().find(({r:x})=>String(x.id)===id);
  if(!r||r.archived||r.active===false||!pair)throw Error('La factura ya no está pendiente o fue modificada. Actualiza la lista.');
  const amount=Number(form.elements.amount.value),kind=form.dataset.kind,currency=pair.x.currency;
  if(!Number.isFinite(amount)||amount<=0)throw Error('Introduce un importe mayor que cero.');
  if(db.transactions.some(t=>t.scheduleKey===`recurring:${id}:${r.nextDue}`))throw Error('Este vencimiento ya está registrado; consulta el historial.');
  if(!['card','account'].includes(kind))throw Error('Selecciona una cuenta o tarjeta.');
  const a=account(form.elements.accountId.value),c=card(form.elements.cardId.value);
  if(kind==='account'&&(!a||a.archived||a.currency!==currency||bank(a.bankId)?.archived))throw Error('Selecciona una cuenta activa de la misma moneda.');
  if(kind==='card'&&(!c||c.archived||bank(c.bankId)?.archived))throw Error('Selecciona una tarjeta activa.');
  const src=kind==='card'?'card':'account';
  const channel=v918ChannelPolicy(kind,a,form.dataset.channel).channel;
  const debit=v918ServiceDebit(amount,kind,a,channel);
  const taxable=debit.taxable;
  const pct=debit.pct;
  // The financial engine owns the posting, scheduleKey, historical balance and persistence.
  // No duplicate second transaction or new database table is introduced here.
  if(submit){submit.disabled=true;submit.textContent='Registrando…'}
  saveTx({type:kind==='card'?'card_charge':'expense',flowMode:'service',date:today(),amount,currency,
   paymentSource:src,accountId:kind==='account'?a.id:'',cardId:kind==='card'?c.id:'',
   paymentChannel:channel,paymentTaxable:taxable?'yes':'no',paymentTaxPct:pct,paymentFee:0,
   category:r.category||'Servicios básicos',subcategory:r.subcategory||'',
   servicePreset:'other',note:r.name,recurringId:r.id,cardOnly:'no'});
 }catch(ex){error.textContent=ex.message||String(ex);if(submit){submit.disabled=false;submit.innerHTML=`${icon('check')} Registrar pago`}}
},true);


