/* ==== script: v342-reorder-script ==== */
(function(){
 let active=null,timer=null;
 function clear(){if(timer)clearTimeout(timer);timer=null;if(active){active.node?.classList.remove('v342-dragging');document.querySelectorAll('.v342-drop-target').forEach(x=>x.classList.remove('v342-drop-target'));active=null}}
 function saveMove(from,to){if(!from||!to||from===to)return;const cfg=v105Config();const a=cfg.order.indexOf(from),b=cfg.order.indexOf(to);if(a<0||b<0)return;
  const old=db.settings.v105OverviewWidgets;cfg.order.splice(a,1);cfg.order.splice(b,0,from);db.settings.v105OverviewWidgets={order:cfg.order.slice(),visible:cfg.visible.slice()};
  if(!persist()){db.settings.v105OverviewWidgets=old;toast('No se pudo guardar el orden.');return}render();toast('Orden actualizado en Personalización.');}
 document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-v342-drag]');if(!handle||e.button>0)return;clear();const node=handle.closest('[data-v316-row]');if(!node)return;
  active={id:handle.dataset.v342Drag,node,ready:false,pointer:e.pointerId,x:e.clientX,y:e.clientY,target:null};
  timer=setTimeout(()=>{if(active){active.ready=true;active.node.classList.add('v342-dragging');}},420);
 },{passive:true});
 document.addEventListener('pointermove',e=>{if(!active||active.pointer!==e.pointerId)return;
  if(!active.ready){if(Math.hypot(e.clientX-active.x,e.clientY-active.y)>14)clear();return;}
  document.querySelectorAll('.v342-drop-target').forEach(x=>x.classList.remove('v342-drop-target'));
  const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-v316-row]');
  if(target&&target!==active.node){active.target=target;target.classList.add('v342-drop-target')}
 },{passive:true});
 document.addEventListener('pointerup',e=>{if(!active||active.pointer!==e.pointerId)return;const from=active.id,ready=active.ready,target=active.target?.dataset.v316Row;clear();if(ready&&target)saveMove(from,target)},true);
 document.addEventListener('pointercancel',clear,true);
})();
/* Do not navigate backwards when swiping a horizontal card gallery. */
(function(){
 let touch=null,blockUntil=0;
 const railSelector='.v266-gallery-track,.v68-wallet-gallery,.v144-card-rail,.v58m-cardrail';
 document.addEventListener('pointerdown',e=>{const rail=e.target.closest(railSelector);touch=rail?{rail,x:e.clientX,y:e.clientY,moved:false}:null},{passive:true,capture:true});
 document.addEventListener('pointermove',e=>{if(!touch)return;const dx=Math.abs(e.clientX-touch.x),dy=Math.abs(e.clientY-touch.y);if(dx>18&&dx>dy*1.3)touch.moved=true},{passive:true,capture:true});
 document.addEventListener('pointerup',()=>{if(touch?.moved)blockUntil=performance.now()+350;touch=null},{passive:true,capture:true});
 document.addEventListener('pointercancel',()=>{touch=null},{passive:true,capture:true});
 document.addEventListener('click',e=>{if(performance.now()<blockUntil&&e.target.closest(railSelector)){e.preventDefault();e.stopImmediatePropagation();blockUntil=0}},true);
})();
;
/* ==== script: v381-transfer-controller ==== */
(function(){
 'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 const read=(form,key)=>{const x=form.elements.namedItem(key);return x&&typeof x.value==='string'?x.value:''};
 const val=x=>{const v=Number(x);return Number.isFinite(v)?v:NaN};
 const cash=(n,c)=>{if(!Number.isFinite(n))return '—';return (n<0?'-':'')+(c==='USD'?'US$':'RD$')+Math.abs(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});};
 const accountOf=id=>typeof account==='function'?account(id):null;
 const currentDate=()=>typeof today==='function'?today():'';
 const fmt=(n)=>Math.round((Number(n)||0)*100)/100;
 const safeDate=(f)=>!read(f,'date')||read(f,'date')===currentDate();
 const currentBalance=a=>{try{return typeof getAccountBalance==='function'?Number(getAccountBalance(a)):NaN}catch(_){return NaN}};
 function detect(f){const mode=f.dataset.mode||read(f,'flowMode');return mode==='own'||mode==='outgoing'?mode:null;}
 function render(f,box){
  if(!f.isConnected||!box.isConnected)return;
  const mode=detect(f),own=mode==='own';if(!mode)return;
  const a=accountOf(read(f,'accountId')),b=own?accountOf(read(f,'toAccountId')):null;
  const ac=a?.currency||'DOP',bc=b?.currency||ac;
  const amount=val(read(f,'amount')),positive=Number.isFinite(amount)&&amount>0;
  const rate=val(read(f,'fxRate'));
  const fx=own&&a&&b&&ac!==bc;
  const manual=fx&&read(f,'receiveMode')==='manual';
  const validRate=Number.isFinite(rate)&&rate>0;
  const expected=fx?(validRate&&positive?(ac==='USD'?amount*rate:amount/rate):NaN):amount;
  const receive=manual?val(read(f,'targetAmount')):expected;
  const fixed=own?val(read(f,'transferFixedFee')):val(read(f,'paymentFee'));
  const pct=own?0:(read(f,'paymentTaxable')==='yes'?val(read(f,'paymentTaxPct')):0);
  const tax=own?0:(Number.isFinite(pct)&&positive?fmt(amount*pct/100):NaN);
  const charges=Number.isFinite(fixed)&&Number.isFinite(tax)?fmt(fixed+tax):NaN;
  const total=positive&&Number.isFinite(charges)?fmt(amount+charges):NaN;
  const edit=!!f.dataset.id;
  const safe=!edit&&safeDate(f);
  const escape=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const line=(l,r)=>'<div><span>'+escape(l)+'</span><strong>'+escape(r)+'</strong></div>';
  const original=(!a||!b&&own)?'':a?.name||'';
  let warnings=[];
  if(!a||a.archived)warnings.push('Selecciona una cuenta de origen activa.');
  if(own&&(!b||b.archived))warnings.push('Selecciona una cuenta de destino activa.');
  if(own&&a&&b&&a.id===b.id)warnings.push('El origen y el destino no pueden ser la misma cuenta.');
  if(!positive)warnings.push('Introduce un importe mayor que cero.');
  if(fx&&!validRate)warnings.push('La tasa de conversión debe ser positiva.');
  if(manual&&!(receive>0&&Number.isFinite(receive)))warnings.push('Indica el importe recibido válido según el comprobante.');
  if(mode==='outgoing'&&!read(f,'payee').trim())warnings.push('Indica quién recibe la transferencia a terceros.');
  if(Number.isFinite(pct)&&(pct<0||pct>100))warnings.push('Revisa el porcentaje del impuesto.');
  if(!Number.isFinite(charges)||charges<0)warnings.push('Revisa impuestos y otros cargos de la operación.');
  const before=a?currentBalance(a):NaN;
  const destBefore=b?currentBalance(b):NaN;
  const canBalances=safe&&Number.isFinite(before)&&Number.isFinite(total)&&positive&&!warnings.length;
  let html='<header><strong>'+ (own?'Transferencia entre tus cuentas':'Transferencia a terceros') +'</strong><small>VISTA PREVIA</small></header>';
  html+='<div class="v381-transfer-kind">'+(own?'No es un ingreso ni un gasto. Solo los cargos reales se clasifican como egreso.':'El dinero sale hacia un tercero; este flujo registra un gasto clasificado, no un movimiento entre dos cuentas propias.')+'</div>';
  html+='<div class="v381-transfer-route"><div><small>ORIGEN</small><strong>'+escape(a?.name||'Selecciona cuenta')+'</strong><span>'+escape(ac)+'</span></div><div class="v381-transfer-arrow">→</div><div><small>'+(own?'DESTINO':'BENEFICIARIO')+'</small><strong>'+escape(own?(b?.name||'Selecciona cuenta'):(read(f,'payee')||'Indica beneficiario'))+'</strong><span>'+escape(own?bc:'Externo')+'</span></div></div>';
  html+='<div class="v381-transfer-numbers"><div><small>Sale del origen</small><strong>'+cash(total,ac)+'</strong></div><div class="v381-receive"><small>'+(own?'Recibe el destino':'Importe transferido')+'</small><strong>'+cash(own?receive:amount,own?bc:ac)+'</strong></div></div>';
  html+='<div class="v381-transfer-rows">';
  html+=line('Capital enviado',cash(amount,ac));
  if(fx)html+=line('Tasa aplicada',validRate?'RD$'+rate.toFixed(4)+' / US$1':'Pendiente');
  if(own&&fx)html+=line(manual?'Importe recibido indicado':'Recibido calculado',cash(receive,bc));
  html+=line('Cargos e impuestos',cash(charges,ac));
  if(canBalances)html+=line('Saldo origen actual → estimado',cash(before,ac)+' → '+cash(before-total,ac));
  if(canBalances&&own&&Number.isFinite(destBefore)&&Number.isFinite(receive))html+=line('Saldo destino actual → estimado',cash(destBefore,bc)+' → '+cash(destBefore+receive,bc));
  html+='</div>';
  if(warnings.length)html+='<div class="v381-warning" role="status">'+escape(warnings[0])+'</div>';
  if(edit)html+='<p class="v381-transfer-note">Estás editando una operación anterior. Los saldos se recalcularán al guardar, sin crear una segunda transferencia.</p>';
  else if(!safeDate(f))html+='<p class="v381-transfer-note">Fecha histórica: no se muestra un saldo final porque hay que recalcular los movimientos posteriores.</p>';
  else html+='<p class="v381-transfer-note">Saldos mostrados únicamente como simulación. No se modifica ninguna cuenta hasta confirmar el registro.</p>';
  box.innerHTML=html;
  f.dataset.v381Error=warnings[0]||'';
 }
 function attach(f){
  const mode=detect(f);if(!mode||f.dataset.v381Attached==='1')return;
  f.dataset.v381Attached='1';f.dataset.v381Transfer=mode;
  const pane=document.createElement('section');pane.className='v381-transfer-preview';pane.setAttribute('aria-label','Vista previa de transferencia y sus efectos');pane.setAttribute('aria-live','polite');
  const target=f.querySelector('#guidedReceipt')||f.querySelector('.flow-receipt')||f.querySelector('.form-grid');
  if(target&&target!==f.querySelector('.form-grid'))target.insertAdjacentElement('afterend',pane);
  else(f.querySelector('.form-grid')||f).appendChild(pane);
  const update=()=>render(f,pane);
  f.addEventListener('input',()=>queueMicrotask(update));
  f.addEventListener('change',()=>queueMicrotask(update));
  // Preflight at capture: preserve native save handler and the review layer on valid input.
  f.addEventListener('submit',e=>{
    update();const error=f.dataset.v381Error;
    if(!error)return;
    e.preventDefault();e.stopImmediatePropagation();
    if(typeof toast==='function')toast(error);
    let field='amount';
    if(/origen/.test(error))field='accountId';
    else if(/destino|misma cuenta/.test(error))field='toAccountId';
    else if(/tasa/.test(error))field='fxRate';
    else if(/recibido/.test(error))field='targetAmount';
    else if(/quién|beneficiario/.test(error))field='payee';
    // Old assistants can hide inactive steps. Don't forcibly manipulate their state.
    f.elements.namedItem(field)?.focus?.();
  },true);
  update();
 }
 function enhanceReview(){
  const review=root.querySelector('.v349-review-screen');if(!review||review.dataset.v381TransferReview==='yes')return;
  const source=root.querySelector('form#transactionForm[data-v381-transfer]');if(!source)return;
  const info=source.querySelector('.v381-transfer-preview');if(!info)return;
  const route=info.querySelector('.v381-transfer-route');const numbers=info.querySelector('.v381-transfer-numbers');
  const where=review.querySelector('.v353-breakdowns');if(!where)return;
  const result=document.createElement('section');result.className='v381-review-card';
  const title=document.createElement('strong');title.textContent='Origen, destino e impacto';
  const desc=document.createElement('p');desc.textContent=(route?.innerText||route?.textContent||'').replace(/\s+/g,' ').trim();
  const amounts=document.createElement('p');amounts.textContent=(numbers?.innerText||numbers?.textContent||'').replace(/\s+/g,' ').trim();
  const caveat=document.createElement('p');caveat.textContent=source.dataset.v381Transfer==='own'?'Mover fondos propios no constituye ingreso ni gasto; únicamente los cargos reales se contabilizan como egreso.':'Este envío a terceros es un gasto, no una transferencia entre cuentas propias.';
  result.append(title,desc,amounts,caveat);where.prepend(result);
  review.dataset.v381TransferReview='yes';
 }
 let scheduled=false;function scan(){if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;root.querySelectorAll('form#transactionForm').forEach(attach);enhanceReview();});}
 // Registered before the universal review listener: invalid transfer forms cannot reach review.
 window.addEventListener('submit',e=>{
   const f=e.target;if(!f||f.id!=='transactionForm'||!detect(f))return;
   const pane=f.querySelector('.v381-transfer-preview');if(!pane)return;
   render(f,pane);
   const error=f.dataset.v381Error;
   if(!error)return;
   e.preventDefault();e.stopImmediatePropagation();
   if(typeof toast==='function')toast(error);
   const field=/origen/.test(error)?'accountId':/destino|misma cuenta/.test(error)?'toAccountId':/tasa/.test(error)?'fxRate':/recibido/.test(error)?'targetAmount':/quién|beneficiario/.test(error)?'payee':'amount';
   f.elements.namedItem(field)?.focus?.();
 },true);
 new MutationObserver(scan).observe(root,{subtree:true,childList:true});scan();
})();
;
/* ==== script: v382-card-payment-controller ==== */
(function(){
 'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 const read=(f,k)=>{const el=f.elements.namedItem(k);return el&&typeof el.value==='string'?el.value:''};
 const numeric=v=>{if(v===''||v==null)return NaN;const n=Number(v);return Number.isFinite(n)?n:NaN};
 const rounded=v=>Math.round((v+Number.EPSILON)*100)/100;
 const currency=(n,c)=>Number.isFinite(n)?(n<0?'-':'')+(c==='USD'?'US$':'RD$')+Math.abs(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';
 const esc=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
 const isCardPay=f=>f?.id==='transactionForm'&&(f.dataset.mode==='cardpay'||read(f,'flowMode')==='cardpay');
 const currentDate=()=>typeof today==='function'?today():'';
 function model(f){
   const c=typeof card==='function'?card(read(f,'cardId')):null;
   const a=typeof account==='function'?account(read(f,'accountId')):null;
   const debtCurrency=read(f,'currency')||'DOP',sourceCurrency=a?.currency||'DOP';
   const st=c&&typeof cardStatus==='function'?cardStatus(c,debtCurrency):null;
   const debt=st?Number(st.debt):NaN, billed=st?Number(st.billed):NaN;
   const amount=numeric(read(f,'amount'));
   const mode=read(f,'cardPaymentMode')||'cut';
   const fx=sourceCurrency!==debtCurrency;
   const rate=numeric(read(f,'paymentFxRate'));
   const manual=fx&&read(f,'actualDebitMode')==='manual';
   const expected=Number.isFinite(amount)&&(!fx||(Number.isFinite(rate)&&rate>0))?
       rounded(fx?(debtCurrency==='USD'?amount*rate:amount/rate):amount):NaN;
   const debit=manual?numeric(read(f,'sourceAmount')):expected;
   const ch=read(f,'paymentChannel')||'presencial';
   const eligible=a&&typeof isTaxableBankPayment==='function'?isTaxableBankPayment(a,ch,false,false):false;
   const taxable=eligible&&read(f,'paymentTaxable')==='yes';
   const pct=taxable?(typeof cardPaymentSettingsTaxPct==='function'?cardPaymentSettingsTaxPct():numeric(read(f,'paymentTaxPct'))):0;
   const tax=Number.isFinite(debit)&&Number.isFinite(pct)?rounded(debit*pct/100):NaN;
   const fee=numeric(read(f,'paymentFee'));
   const charges=Number.isFinite(tax)&&Number.isFinite(fee)?rounded(tax+fee):NaN;
   const debitTotal=Number.isFinite(debit)&&Number.isFinite(charges)?rounded(debit+charges):NaN;
   const editing=!!f.dataset.id;
   const todayRecord=!editing&&read(f,'date')===currentDate();
   const sourceBalance=a&&typeof getAccountBalance==='function'?Number(getAccountBalance(a)):NaN;
   const reasons=[];
   if(!c||c.archived)reasons.push('Selecciona una tarjeta activa.');
   if(!a||a.archived)reasons.push('Selecciona una cuenta de pago activa.');
   if(!['DOP','USD'].includes(debtCurrency))reasons.push('Selecciona RD$ o US$ para el saldo de tarjeta.');
   if(!(Number.isFinite(amount)&&amount>0))reasons.push('El importe del pago debe ser mayor que cero.');
   if(!['cut','total','custom'].includes(mode))reasons.push('Selecciona una modalidad de pago válida.');
   if(fx&&!(Number.isFinite(rate)&&rate>0))reasons.push('Indica una tasa de cambio positiva.');
   if(manual&&!(Number.isFinite(debit)&&debit>0))reasons.push('Indica el débito exacto positivo del comprobante.');
   if(a?.kind==='cash'&&ch==='internet_banking')reasons.push('No puedes utilizar Internet Banking desde efectivo.');
   if(taxable&&!(Number.isFinite(pct)&&pct>=0&&pct<=100))reasons.push('Revisa el porcentaje del impuesto.');
   if(!(Number.isFinite(fee)&&fee>=0))reasons.push('Revisa las comisiones del pago.');
   if(!(Number.isFinite(debitTotal)&&debitTotal>0))reasons.push('El débito total debe ser positivo y estar calculado.');
   // Avoid silently generating card credit balances. A bank credit in excess of debt
   // is a separate adjustment operation, not a normal payment from this assistant.
   if(!editing&&Number.isFinite(debt)&&Number.isFinite(amount)&&amount>debt+.01)reasons.push('El abono supera la deuda registrada. Revisa el importe o concilia el saldo bancario.');
   if(!editing&&Number.isFinite(debt)&&debt<=.005)reasons.push('Esta moneda no tiene deuda registrada para pagar.');
   if(!editing&&mode==='cut'&&Number.isFinite(billed)&&billed<=.005)reasons.push('No hay saldo facturado al corte. Selecciona pago total o un monto específico.');
   return {c,a,st,debt,billed,amount,mode,fx,rate,manual,debit,fee,tax,charges,debitTotal,pct,taxable,sourceCurrency,debtCurrency,editing,todayRecord,sourceBalance,reasons};
 }
 function render(f,pane){
   if(!pane.isConnected)return;
   const x=model(f),line=(k,v)=>'<div><span>'+esc(k)+'</span><strong>'+esc(v)+'</strong></div>';
   const canEstimate=x.todayRecord&&!x.reasons.length&&Number.isFinite(x.sourceBalance)&&Number.isFinite(x.debt);
   let html='<header class="v382-pay-head"><h3>Pago de tarjeta</h3><span>IMPACTO ANTES DE GUARDAR</span></header>';
   html+='<div class="v382-pay-route"><div><small>SALE DE</small><strong>'+esc(x.a?.name||'Cuenta por seleccionar')+'</strong><em>'+esc(x.sourceCurrency)+'</em></div><div class="v382-pay-arrow">→</div><div><small>SE ABONA A</small><strong>'+esc(x.c?.name||'Tarjeta por seleccionar')+'</strong><em>'+esc(x.debtCurrency)+'</em></div></div>';
   html+='<div class="v382-pay-numbers"><div><small>Reduce deuda de tarjeta</small><strong>'+currency(x.amount,x.debtCurrency)+'</strong></div><div class="v382-pay-positive"><small>Sale de la cuenta (con cargos)</small><strong>'+currency(x.debitTotal,x.sourceCurrency)+'</strong></div></div>';
   html+='<div class="v382-pay-breakdown">';
   html+=line('Deuda registrada',currency(x.debt,x.debtCurrency));
   html+=line('Saldo facturado al corte',currency(x.billed,x.debtCurrency));
   html+=line('Tipo de pago',({cut:'Al corte',total:'Total',custom:'Monto específico'})[x.mode]||'—');
   if(x.fx)html+=line('Tipo de cambio',Number.isFinite(x.rate)&&x.rate>0?'RD$ '+x.rate.toFixed(4)+' por US$1':'Pendiente');
   if(x.fx)html+=line(x.manual?'Débito exacto declarado':'Débito equivalente',currency(x.debit,x.sourceCurrency));
   html+=line('Impuesto bancario',currency(x.tax,x.sourceCurrency));
   html+=line('Otros cargos',currency(x.fee,x.sourceCurrency));
   if(canEstimate){
    html+=line('Deuda después del pago',currency(Math.max(0,rounded(x.debt-x.amount)),x.debtCurrency));
    html+=line('Cuenta: antes → estimado',currency(x.sourceBalance,x.sourceCurrency)+' → '+currency(rounded(x.sourceBalance-x.debitTotal),x.sourceCurrency));
   }
   html+='</div>';
   if(x.reasons.length)html+='<div class="v382-pay-warning" role="status">'+esc(x.reasons[0])+'</div>';
   if(x.editing)html+='<p class="v382-pay-note">Edición: los saldos deben recalcularse con los movimientos posteriores. No se simula un nuevo pago ni se crea otro registro.</p>';
   else if(!x.todayRecord)html+='<p class="v382-pay-note">Pago con fecha histórica: se recalculará el historial. No se anticipan saldos de hoy.</p>';
   else html+='<p class="v382-pay-note">Este pago reduce una deuda existente; solo los impuestos y las comisiones reales cuentan como gasto. Vista previa informativa: nada cambia hasta confirmar.</p>';
   pane.innerHTML=html;
   f.dataset.v382PaymentError=x.reasons[0]||'';
 }
 function attach(f){
   if(!isCardPay(f)||f.dataset.v382PayAttached==='yes')return;
   f.dataset.v382PayAttached='yes';
   const pane=document.createElement('section');pane.className='v382-card-payment-preview';pane.setAttribute('aria-label','Impacto del pago en cuenta y tarjeta');pane.setAttribute('aria-live','polite');
   const receipt=f.querySelector('#guidedReceipt');
   if(receipt)receipt.insertAdjacentElement('afterend',pane);
   else (f.querySelector('.studio-fields')||f.querySelector('.form-grid')||f).appendChild(pane);
   const update=()=>render(f,pane);
   f.addEventListener('input',()=>queueMicrotask(update));
   f.addEventListener('change',()=>queueMicrotask(update));
   update();
 }
 function review(){
   const page=root.querySelector('.v349-review-screen:not([data-v382-pay-review])');if(!page)return;
   const form=root.querySelector('form#transactionForm[data-v382-pay-attached="yes"]');if(!form||!isCardPay(form))return;
   const x=model(form),where=page.querySelector('.v353-breakdowns');if(!where)return;
   const card=document.createElement('section');card.className='v382-review-card';
   const title=document.createElement('strong');title.textContent='Efecto financiero de este pago';
   const route=document.createElement('p');route.textContent=(x.a?.name||'Cuenta')+' → '+(x.c?.name||'Tarjeta')+' · '+x.debtCurrency;
   const amount=document.createElement('p');amount.className='v382-review-highlight';amount.textContent='Deuda que se reduce: '+currency(x.amount,x.debtCurrency)+' · Débito total: '+currency(x.debitTotal,x.sourceCurrency);
   const note=document.createElement('p');note.textContent='El principal pagado no es un gasto nuevo. Los cargos bancarios sí se registran como gasto. Valida estos valores antes de guardar.';
   card.append(title,route,amount,note);where.prepend(card);page.dataset.v382PayReview='yes';
 }
 let scheduled=false;
 function scan(){if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;root.querySelectorAll('form#transactionForm').forEach(attach);review();});}
 // Attach before the universal review listener: reject invalid payments at capture phase.
 window.addEventListener('submit',e=>{
   const f=e.target;if(!isCardPay(f))return;
   const pane=f.querySelector('.v382-card-payment-preview');if(!pane)return;
   render(f,pane);
   const err=f.dataset.v382PaymentError;if(!err)return;
   e.preventDefault();e.stopImmediatePropagation();
   if(typeof toast==='function')toast(err);
   if(f.classList.contains('studio-form')&&typeof studioShowStep==='function'){
     studioShowStep(f,1,{force:true});
   }
   const fld=/tarjeta|deuda/.test(err)?'cardId':/cuenta|efectivo/.test(err)?'accountId':/tasa/.test(err)?'paymentFxRate':/débito/.test(err)?'sourceAmount':'amount';
   f.elements.namedItem(fld)?.focus?.();
 },true);
 new MutationObserver(scan).observe(root,{subtree:true,childList:true});scan();
})();
;
/* ==== script: v349-register-experience-script ==== */
(()=>{'use strict';
  /* Only presentation and confirmation review. Never write data here. */
  const eligible=new Set(['transactionForm','recurringPaymentConfirmForm','rewardReceivedForm','manualBenefitForm','benefitLedgerForm','personalPaymentForm','annualFeeForm','v144CashbackForm']);
  let pendingReview=null;
  // V393: fingerprint the values shown at review time; never approve a changed form.
  const snapshot=form=>{
    const fd=new FormData(form), pairs=[];
    for(const [key,value] of fd.entries())pairs.push([key,typeof value==='string'?value:(value?.name||'archivo')]);
    return JSON.stringify(pairs);
  };
  let confirmationBusy=false;

  const val=(form,name)=>{const field=form.elements?.namedItem(name);if(!field)return '';if(typeof field.value==='string'){if(field.tagName==='SELECT')return field.selectedOptions?.[0]?.textContent?.trim()||field.value;return field.value.trim()}if(field.length){const chosen=[...field].find(x=>x.checked);return chosen?.value||''}return ''};
  const raw=(form,name)=>{const el=form.elements?.namedItem(name);return el&&typeof el.value==='string'?el.value.trim():''};
  
  function isRelevant(form){return form instanceof HTMLFormElement&&!!form.closest('#modal-root')&&(eligible.has(form.id)||form.classList.contains('other-studio-form')||form.dataset.v83Loan==='yes')}
  
  
  function dismiss(restore=true){const node=document.querySelector('#modal-root .v349-review-screen');node?.remove();if(pendingReview){const original=pendingReview.form.closest('.modal');original?.removeAttribute('aria-hidden');if(restore&&pendingReview.submitter?.isConnected)pendingReview.submitter.focus();pendingReview=null}}
  
  /* V614: El guardado directo no añade un segundo listener de submit.
     La capa de revisión ya no intercepta; validación y persistencia pertenecen
     enteramente al controlador contable que funciona tanto en web como en móvil. */
  function decorate(){
    const root=document.getElementById('modal-root');if(!root)return;
    for(const dialog of root.querySelectorAll('.modal')){
      const form=dialog.querySelector('form');if(!form||!isRelevant(form)||dialog.classList.contains('v349-register-dialog'))continue;
      dialog.classList.add('v349-register-dialog');
      // Keep the existing flow fields and buttons; only refine the visual rhythm.
      form.classList.add('v349-register-flow');
      // Legacy selectors can out-rank theme rules on selected studio labels.
      // An inline *visual-only* override prevents white tiles in Black mode.
      if((document.body.classList.contains('theme-black')||document.body.classList.contains('theme-dark'))&&!form.classList.contains('v700-express')){
        for(const label of form.querySelectorAll('label:has(select),label:has(input:not([type=radio]):not([type=checkbox]))')){
          label.style.setProperty('background','#111','important');
          label.style.setProperty('background-image','none','important');
          label.style.setProperty('color','#f5f5f5','important');
          label.style.setProperty('border-color','#303030','important');
        }
      }
      const footer=form.querySelector('.form-foot button[type=submit]');
      if(footer && !footer.dataset.v349Label){
        const original=footer.textContent.trim();
        footer.dataset.v349Label=original;
        // Preservar el botón de registro establecido por la vista y no renombrarlo a «Continuar».
        footer.dataset.v349Direct='yes';
      }
    }
  }
  let scheduled=false;
  const schedule=()=>{if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;decorate()})};
  const boot=()=>{const root=document.getElementById('modal-root');if(!root)return;new MutationObserver(schedule).observe(root,{childList:true,subtree:false});decorate()};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
;
/* ==== script: v351-register-structural-components ==== */
(()=>{'use strict';
  const root=()=>document.getElementById('modal-root');
  const icons={transfer:'<path d="M4 8h16m-4-4 4 4-4 4M20 16H4m4-4-4 4 4 4"/>',money:'<rect x="3" y="6" width="18" height="12" rx="2"/><circle cx="12" cy="12" r="2"/>',card:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',list:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8m-8 4h8m-8 4h5"/>',category:'<path d="m3 12 9-9 9 9-9 9z"/><circle cx="12" cy="12" r="2"/>'};
  function kind(title){const t=title.toLocaleLowerCase('es');if(/origen|destino|transfer|entre cuentas/.test(t))return 'transfer';if(/tarjeta|pagar desde|pago/.test(t))return 'card';if(/fecha/.test(t))return 'calendar';if(/categ|clasific|en qué|gastaste/.test(t))return 'category';if(/importe|saldo|cuenta|dinero/.test(t))return 'money';return 'list'}
  function decorate(dialog){if(dialog.dataset.v351Prepared==='1')return;
    const form=dialog.querySelector('form');if(!form||!dialog.classList.contains('v349-register-dialog'))return;
    dialog.dataset.v351Prepared='1';dialog.classList.add('v351-structured');
    for(const section of form.querySelectorAll('.v134-section')){
      const heading=section.querySelector(':scope > .v134-section-heading');if(!heading||heading.closest('.v351-section-top'))continue;
      const title=heading.querySelector('strong')?.textContent||'';
      const top=document.createElement('div');top.className='v351-section-top';
      const icon=document.createElement('span');icon.className='v351-section-icon';icon.setAttribute('aria-hidden','true');
      const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.innerHTML=icons[kind(title)];icon.appendChild(svg);
      section.insertBefore(top,heading);top.append(icon,heading);
    }
    // A real shared progress component. It does not replace any step logic or financial inputs.
    const existing=form.querySelector('.mqr-detail-amount,.v134-detail-stage,.studio-stepper,.v83-loan-pay-nav');
    if(!existing&&form.querySelector('.v134-section')&&!form.querySelector('.v351-form-step')){
      const band=document.createElement('div');band.className='v351-form-step';band.setAttribute('aria-label','Detalles del registro');
      const left=document.createElement('div');left.className='v351-form-step-left';
      const label=document.createElement('span');label.className='v351-form-step-label';label.textContent='DETALLES DEL REGISTRO';
      const bars=document.createElement('span');bars.className='v351-form-step-bars';bars.setAttribute('aria-hidden','true');for(let i=0;i<3;i++)bars.appendChild(document.createElement('i'));
      left.append(label,bars);band.appendChild(left);
      const amount=form.elements.namedItem('amount');
      if(amount&&typeof amount.value==='string'){
        const number=document.createElement('strong');number.className='v351-form-step-amount';
        const sync=()=>{const value=Number(amount.value);number.textContent=Number.isFinite(value)?'RD$ '+new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(value):'RD$ —'};
        amount.addEventListener('input',sync);sync();band.appendChild(number);
      }
      form.insertBefore(band,form.querySelector('.v134-section'));
    }
  }
  let pending=false;
  function scan(){pending=false;root()?.querySelectorAll('.v349-register-dialog').forEach(decorate)}
  function schedule(){if(!pending){pending=true;queueMicrotask(scan)}}
  function boot(){const r=root();if(!r)return;new MutationObserver(schedule).observe(r,{childList:true,subtree:true});schedule()}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
;
/* ==== script: v377-runtime-polish ==== */
(function v377RuntimePolish(){
  'use strict';
  const moneyPattern=/^(RD\$|US\$)-(\d[\d,.]*)$/;
  const selectors=[
    'strong','b','.kpi-value','.v58-main-value','.v58-kpi-value','.v244-product-value strong',
    '.v187-hero-primary strong','.v187-hero-sides strong','.v360-pressure-details-head>strong',
    '.v349-review-amount strong','.v349-review-row strong','.v12-patrimony-line strong','.v12-patrimony-net strong'
  ].join(',');
  function normalizeMoney(root){
    (root.querySelectorAll?root.querySelectorAll(selectors):[]).forEach(el=>{
      if(!el || el.children.length) return;
      const txt=(el.textContent||'').trim();
      const m=txt.match(moneyPattern);
      if(m) el.textContent='-'+m[1]+m[2];
    });
  }
  function applyPageHints(){
    const main=document.querySelector('main.main');
    if(!main) return;
    document.body.classList.toggle('v377-mobile-world', window.innerWidth<=790);
    const hasDock=!!document.querySelector('.vive-mobile-dock');
    document.body.classList.toggle('v377-has-dock', hasDock);
    const switchTabs=document.querySelectorAll('.module-switch-tabs,.inner-menu-tabs,.v248-budget-tabs');
    switchTabs.forEach(tab=>tab.setAttribute('data-v377-scroll','1'));
  }
  function patch(root=document){
    normalizeMoney(root);
    applyPageHints();
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>patch(document),{once:true});
  else patch(document);
  const root=document.getElementById('app')||document.body;
  const modalRoot=document.getElementById('modal-root')||document.body;
  const obs=new MutationObserver(muts=>{
    const touched=[];
    muts.forEach(m=>{m.addedNodes && m.addedNodes.forEach(n=>{if(n.nodeType===1) touched.push(n);});});
    if(!touched.length){patch(document);return;}
    touched.forEach(n=>patch(n));
    patch(document);
  });
  obs.observe(root,{childList:true,subtree:true});
  if(modalRoot!==root) obs.observe(modalRoot,{childList:true,subtree:true});
  window.addEventListener('resize',()=>patch(document),{passive:true});
})();
;
/* ==== script: v378-register-personalization ==== */
(()=>{'use strict';
  // Specific visual onboarding for each existing registered form. Inputs and submit handlers are untouched.
  const specs={
    bankForm:['banks','Institución','Identifica una entidad y su perfil sin duplicarla.','⌂'],
    accountForm:['banks','Cuenta y efectivo','Banco, moneda y saldo inicial; detalles avanzados opcionales.','▣'],
    cashWalletForm:['banks','Efectivo','Dinero físico en RD$ o US$, separado de las cuentas bancarias.','▣'],
    cardForm:['cards','Tarjeta de crédito','Límites, ciclo y deuda separados por moneda.','▤'],
    loanForm:['loans','Contrato de préstamo','Condiciones, cuotas y verificación antes del registro.','≋'],
    certificateForm:['investments','Certificado financiero','Capital, tasa, vencimiento y tratamiento contable.','◈'],
    categoryForm:['catalog','Catálogo','Clasifica ingresos y gastos sin alterar movimientos previos.','▦'],
    budgetForm:['catalog','Presupuesto','Límite por categoría y período.','▥'],
    personalLoanForm:['relations','Acuerdo entre personas','Una sola obligación con historial de abonos.','⇄'],
    personalPaymentForm:['relations','Abono entre personas','Reduce el saldo del acuerdo sin duplicar ingresos o egresos.','⇄'],
    v56ContactForm:['relations','Contacto','Persona para acuerdos y obligaciones.','♧'],
    v56LoanForm:['relations','Acuerdo entre personas','Registra si el dinero ya está contabilizado.','⇄'],
    v40BenefitForm:['benefits','Beneficio','Beneficios informativos, separados del efectivo.','✧'],
    manualBenefitForm:['benefits','Beneficio recibido','Cashback confirmado o beneficio no monetario.','✧'],
    benefitLedgerForm:['benefits','Recompensas','Puntos y millas sin impacto automático en efectivo.','✧'],
    benefitRuleForm:['benefits','Regla de beneficio','Define elegibilidad sin inventar acreditaciones.','✧'],
    annualFeeForm:['benefits','Anualidad real','Solo registra el cargo cuando efectivamente se cobra.','✧'],
    rewardReceivedForm:['benefits','Cashback acreditado','Distingue abono en tarjeta de depósito en cuenta.','✧'],
    perkUsageForm:['benefits','Beneficio utilizado','Valor informativo que no aumenta tu efectivo.','✧'],
    v144CashbackForm:['benefits','Cashback','Acreditación real o pendiente de confirmar.','✧'],
    v144CostForm:['benefits','Costo de tarjeta','Evita registrar un costo o una anualidad dos veces.','✧'],
    v144SettleForm:['adjustments','Conciliación de costo','Vincula un pago ya realizado sin otra salida.','✓'],
    recurringPaymentConfirmForm:['recurring','Servicio recurrente','Confirma fecha, fuente de pago y estado.','◷'],
    transactionForm:['operations','Movimiento','Revisa categoría, origen, destino y saldo afectado.','↔'],
    v56ContactEditForm:['relations','Contacto','Mantén la información de la persona vinculada.','♧']
  };
  const specialSpecs={refund:['adjustments','Devolución de compra','El reintegro reduce deuda o devuelve fondos; no es ingreso nuevo.','↶'],adjustment:['adjustments','Conciliar saldo','Ajuste documentado, sin crear ingresos o gastos ficticios.','≒'],benefit:['benefits','Beneficio recibido','Elige la tarjeta y el tipo de acreditación.','✧'],loan:['loans','Pago de préstamo','Cuota, capital e intereses se distinguen al revisar.','≋']};
  const escapeText=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function decorate(){
    const root=document.getElementById('modal-root');if(!root)return;
    for(const dialog of root.querySelectorAll('.modal')){
      const form=dialog.querySelector('form');if(!form)continue;
      const conf=specs[form.id] || specialSpecs[form.dataset.special] || null;
      if(!conf)continue;
      const [group,title,desc,symbol]=conf;
      dialog.classList.add('v378-group-'+group,'v378-form-'+(form.id||form.dataset.special));
      if(form.dataset.v378Decorated==='1')continue;
      form.dataset.v378Decorated='1';
      // Do not add section to guided wizards; they have their own step header.
      if(form.classList.contains('v87-loan-wizard')||form.classList.contains('v86-loan-wizard')||form.classList.contains('fastx-form')||form.classList.contains('mqr-detail-form')||form.classList.contains('other-studio-form'))continue;
      const grid=form.querySelector(':scope > .form-grid');if(!grid)continue;
      const card=document.createElement('div');card.className='v378-form-identity';card.setAttribute('role','note');
      card.innerHTML='<span class="v378-form-symbol" aria-hidden="true">'+escapeText(symbol)+'</span><div><strong>'+escapeText(title)+'</strong><small>'+escapeText(desc)+'</small></div>';
      grid.prepend(card);
    }
  }
  function boot(){const root=document.getElementById('modal-root');if(!root)return;decorate();let queued=false;
    const obs=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;decorate()})});
    obs.observe(root,{childList:true,subtree:true});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
;
/* ==== script: v383-loan-controller ==== */
(function(){
 'use strict';
 // V951: sin este puente, loan/account eran inaccesibles aquí y TODO abono quedaba bloqueado con «Selecciona un préstamo activo».
 const core=window.__viveCore||{};
 const loan=core.loan,account=core.account,loanAccounting=core.loanAccounting,xconvert=core.xconvert,isTaxableBankPayment=core.isTaxableBankPayment,today=core.today,toast=core.toast;
 const currency=(n,c)=> (c==='USD'?'US$':'RD$')+new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Math.abs(Number(n)||0));
 const escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
 const numValue=(f,name)=>{const field=f.elements.namedItem(name);return field&&field.value.trim()!==''?Number(field.value):NaN};
 const str=(f,name)=>String(f.elements.namedItem(name)?.value||'');
 const round=n=>Math.round((Number(n)+Number.EPSILON)*100)/100;
 function inspect(f){
  const l=typeof loan==='function'?loan(str(f,'loanId')):null;
  const a=typeof account==='function'?account(str(f,'accountId')):null;
  const mode=str(f,'loanPaymentMode')==='bank'?'bank':'normal';
  const kind=str(f,'paymentKind')==='extra'?'extra':'regular';
  const total=numValue(f,'amount'), principal=numValue(f,'principal'), interest=numValue(f,'interest'), insurance=numValue(f,'insurance'), fee=numValue(f,'fee');
  const beforeApp=l&&typeof loanAccounting==='function'?Number(loanAccounting(l).balance):NaN;
  const beforeBank=numValue(f,'bankBalanceBefore');
  const before=mode==='bank'?beforeBank:beforeApp;
  const sourceNum=numValue(f,'sourceAmount');
  const sameCurrency=!!a&&!!l&&a.currency===l.currency;
  // The app engine computes fallback FX. Show it only if available from the existing function.
  let debit=Number.isFinite(sourceNum)&&sourceNum>0?sourceNum:NaN;
  if(sameCurrency)debit=total;
  else if(l&&a&&Number.isFinite(total)&&typeof xconvert==='function'){
   try{if(!(debit>0))debit=xconvert(total,l.currency,a.currency)}catch(_){debit=NaN}
  }
  const percentage=str(f,'paymentTaxable')==='yes'?numValue(f,'paymentTaxPct'):0;
  const taxApplies=!!a&&typeof isTaxableBankPayment==='function'&&isTaxableBankPayment(a,str(f,'paymentChannel'))&&str(f,'paymentTaxable')==='yes';
  const tax=taxApplies&&Number.isFinite(debit)&&Number.isFinite(percentage)?round(debit*percentage/100):0;
  const hasDate=str(f,'date');
  const current=typeof today==='function'?today():new Date().toISOString().slice(0,10);
  const editing=!!f.dataset.id;
  const newToday=!editing&&hasDate===current;
  const errors=[];
  if(!l||l.archived)errors.push('Selecciona un préstamo activo.');
  if(!a||a.archived)errors.push('Selecciona una cuenta de pago activa.');
  if(!(total>0)||!Number.isFinite(total))errors.push('Introduce cuánto vas a pagar.');
  const parts=[principal,interest,insurance,fee];
  if(parts.some(v=>!Number.isFinite(v)||v<0))errors.push('Revisa capital, interés, seguro y comisiones: deben ser valores válidos no negativos.');
  else if(Number.isFinite(total)&&Math.abs(round(parts.reduce((s,v)=>s+v,0))-total)>.025)errors.push('El desglose debe sumar exactamente el total que vas a pagar.');
  if(kind==='extra'&&mode==='bank')errors.push('El abono extraordinario debe utilizar la modalidad normal; la conciliación es para cuotas ordinarias.');
  if(mode==='bank'&&(!Number.isFinite(beforeBank)||beforeBank<0||l&&beforeBank>Number(l.principal)+.01))errors.push('Indica el saldo de capital del banco antes del pago, sin intereses futuros.');
  if(Number.isFinite(before)&&Number.isFinite(principal)&&principal>before+.01)errors.push('El capital abonado supera el capital pendiente del préstamo.');
  if(a&&l&&!sameCurrency&&!(debit>0&&Number.isFinite(debit)))errors.push('Verifica el importe de la cuenta de origen y la conversión de moneda.');
  if(Number.isFinite(percentage)&&(percentage<0||percentage>100))errors.push('La tasa de impuesto debe estar entre 0 y 100 %.');
  if(kind==='regular'&&!str(f,'installmentPeriod'))errors.push('Selecciona el vencimiento de la cuota.');
  return {l,a,mode,kind,total,principal,interest,insurance,fee,beforeApp,beforeBank,before,after:round(Math.max(0,before-(Number.isFinite(principal)?principal:0))),debit,tax,percentage,hasDate,newToday,editing,errors};
 }
 function line(k,v){return '<div class="v383-loan-line"><span>'+escape(k)+'</span><strong>'+escape(v)+'</strong></div>'}
 function preview(x){
  const c=x.l?.currency||'DOP',ac=x.a?.currency||c;
  let html='<header><div><small>vive el hoy · préstamo</small><h3>Tu pago, antes de confirmar</h3></div><span class="v383-loan-mode">'+(x.kind==='extra'?'Abono al capital':x.mode==='bank'?'Conciliación bancaria':'Cuota ordinaria')+'</span></header>';
  html+='<p class="v383-loan-intro">'+escape(x.l?.name||'Selecciona un préstamo')+' · '+escape(x.a?.name||'Elige la cuenta de origen')+'</p>';
  html+='<div class="v383-loan-figures"><div><small>Capital pendiente antes</small><strong>'+ (Number.isFinite(x.before)?currency(x.before,c):'Por confirmar')+'</strong></div><div class="v383-loan-future"><small>Capital después del abono</small><strong>'+(x.errors.length||!Number.isFinite(x.after)?'Por confirmar':currency(x.after,c))+'</strong></div></div>';
  html+='<div class="v383-loan-lines">';
  html+=line('Total del pago',currency(x.total,c));
  html+=line('A capital',currency(x.principal,c));
  html+=line('Intereses',currency(x.interest,c));
  html+=line('Seguro',currency(x.insurance,c));
  html+=line('Comisiones',currency(x.fee,c));
  if(x.mode==='bank'&&Number.isFinite(x.beforeBank)&&Number.isFinite(x.beforeApp))html+=line('Diferencia de capital con la app',currency(Math.abs(x.beforeBank-x.beforeApp),c)+(x.beforeBank>=x.beforeApp?' · banco mayor':' · banco menor'));
  if(x.a&&x.l&&ac!==c)html+=line('Débito estimado en '+ac,Number.isFinite(x.debit)?currency(x.debit,ac):'Pendiente de conversión');
  if(x.tax>0)html+=line('Impuesto bancario',currency(x.tax,ac));
  html+=line('Total que sale de la cuenta',Number.isFinite(x.debit)?currency(x.debit+x.tax,ac):'Pendiente');
  html+='</div>';
  if(x.errors.length)html+='<p class="v383-loan-notice" role="status">'+escape(x.errors[0])+'</p>';
  else if(x.editing)html+='<p class="v383-loan-notice ok">Estás corrigiendo un pago existente: se recalculará su historial, sin crear otra cuota.</p>';
  else if(!x.newToday)html+='<p class="v383-loan-notice ok">Fecha histórica: estos importes no representan un saldo actual definitivo. Se recalculará la deuda al registrar.</p>';
  else html+='<p class="v383-loan-notice ok">El capital reduce deuda; solo intereses, seguro, comisiones e impuestos son costos. No se genera un segundo gasto por pagar capital.</p>';
  return html;
 }
 function render(f){
  const box=f.querySelector('.v383-loan-impact');if(!box)return;
  const x=inspect(f);box.innerHTML=preview(x);f.dataset.v383Error=x.errors[0]||'';
 }
 function install(f){
  if(!f||f.dataset.v383LoanAttached==='1'||str(f,'type')!=='loan_payment')return;
  f.dataset.v383LoanAttached='1';
  const box=document.createElement('section');box.className='v383-loan-impact';box.setAttribute('aria-label','Resumen del pago de préstamo');box.setAttribute('aria-live','polite');
  const right=f.querySelector('.other-studio-right');const breakDown=f.querySelector('#v49PaymentBreakdown');
  const body=f.querySelector('.other-studio-content');
  if(body){const fold=body.querySelector('.other-studio-fold');if(fold)fold.insertAdjacentElement('beforebegin',box);else body.appendChild(box)}
  else if(right){if(breakDown&&breakDown.parentElement===right)breakDown.insertAdjacentElement('beforebegin',box);else right.prepend(box)}
  else(f.querySelector('#v49PaymentBreakdown')||f.querySelector('.form-grid')||f).insertAdjacentElement('beforebegin',box);
  const modes=f.querySelector('.v359-mode-picker');
  if(modes){const quick=document.createElement('div');quick.className='v383-loan-quick';quick.innerHTML='<button type="button" data-v383-action="regular">Cuota ordinaria</button><button type="button" data-v383-action="extra">Abonar al capital</button>';modes.insertAdjacentElement('afterend',quick);
    quick.addEventListener('click',e=>{
      const btn=e.target.closest('[data-v383-action]');if(!btn)return;
      const k=btn.dataset.v383Action==='extra'?'extra':'regular';const field=f.elements.namedItem('paymentKind');if(!field)return;
      if(k==='extra'&&f.elements.namedItem('loanPaymentMode')){f.elements.loanPaymentMode.value='normal';if(typeof v359LoanRefresh==='function')v359LoanRefresh(f,'mode')}
      field.value=k;field.dispatchEvent(new Event('change',{bubbles:true}));
      if(k==='extra')for(const name of ['interest','insurance','fee']){const el=f.elements.namedItem(name);if(el){el.value='0';el.dispatchEvent(new Event('input',{bubbles:true}))}}
      queueMicrotask(()=>render(f));
    });
  }
  const sync=()=>queueMicrotask(()=>render(f));f.addEventListener('input',sync);f.addEventListener('change',sync);
  render(f);
 }
 function active(){const f=document.querySelector('#modal-root #transactionForm');if(f&&str(f,'type')==='loan_payment')install(f)}
 // Existing modal implementation may reparent fields after opening. Install after those wrappers settle.
 const root=document.getElementById('modal-root');if(root){new MutationObserver(()=>queueMicrotask(active)).observe(root,{childList:true,subtree:false});queueMicrotask(active)}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',active,{once:true});
 // This capture handler runs before buttons advance to the final step; review only opens for valid operations.
 window.addEventListener('click',e=>{
  const button=e.target.closest?.('button');if(!button)return;
  const f=document.querySelector('#modal-root #transactionForm[data-v383-loan-attached="yes"]');if(!f)return;
  if(!button.closest('#modal-root'))return;
  const next=button.matches('[data-v83-pay-next]');
  const submit=button.matches('button[type="submit"],.v349-confirm');
  if(!next&&!submit)return;
  // The navigation from data step to breakdown is always permitted; check before final confirmation.
  const selected=f.querySelector('.v83-loan-pay-nav button.selected');
  if(next && (!selected||selected.dataset.v83LoanPayStep!=='1'))return;
  render(f);const warning=f.dataset.v383Error;
  if(!warning)return;
  e.preventDefault();e.stopImmediatePropagation();
  if(typeof toast==='function')toast(warning);
  const panel=f.querySelector('.v383-loan-impact');panel?.scrollIntoView({block:'nearest',behavior:'smooth'});
 },true);
 // If a save is triggered programmatically, stop it in the capture phase before the accounting handler.
 window.addEventListener('submit',e=>{
  const f=e.target;if(f.id!=='transactionForm'||f.dataset.v383LoanAttached!=='1')return;
  render(f);const warning=f.dataset.v383Error;
  if(warning){e.preventDefault();e.stopImmediatePropagation();if(typeof toast==='function')toast(warning)}
 },true);
})();
;
/* ==== script: v384-bank-account-experience ==== */
(function(){
 'use strict';
 const escape=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const val=(f,n)=>String(f.elements.namedItem(n)?.value??'').trim();
 const field=(f,n)=>f.elements.namedItem(n);
 const number=(f,n)=>{const raw=val(f,n);return raw===''?NaN:Number(raw)};
 const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLocaleLowerCase('es');
 const cash=(n,c)=>{const a=Number(n);if(!Number.isFinite(a))return 'Por indicar';return (a<0?'−':'')+(c==='USD'?'US$':'RD$')+new Intl.NumberFormat('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Math.abs(a));};
 const banks=()=>Array.isArray(db?.banks)?db.banks:[];
 const accounts=()=>Array.isArray(db?.accounts)?db.accounts:[];
 const getBank=id=>banks().find(b=>b.id===id);
 const getAccount=id=>accounts().find(a=>a.id===id);
 const hasHistory=id=>Array.isArray(db?.transactions)&&db.transactions.some(t=>t.accountId===id||t.toAccountId===id);
 const validDate=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(new Date(v+'T12:00:00').getTime())&&new Date(v+'T12:00:00').toISOString().slice(0,10)===v;
 function elements(f){return {name:val(f,'name'),bankId:val(f,'bankId'),kind:val(f,'kind'),currency:val(f,'currency'),opening:number(f,'opening'),opened:val(f,'opened'),last4:val(f,'last4'),annualRate:number(f,'annualRate')};}
 function inspect(f){
  const id=f.dataset.id||'';const existing=f.id==='bankForm'?getBank(id):getAccount(id);
  const name=val(f,'name');const errors=[];let details={id,existing,name,errors};
  if(f.id==='bankForm'){
   const kind=val(f,'kind');const scope=f.querySelector('[name="scope"]:checked')?.value||val(f,'scope')||'personal';
   if(!name)errors.push('Indica el nombre de la institución.');
   if(name.length>80)errors.push('El nombre debe tener 80 caracteres o menos.');
   if(banks().some(b=>b.id!==id&&normalize(b.name)===normalize(name)))errors.push('Ya existe una institución con ese nombre; puedes abrirla o editarla.');
   if(!kind)errors.push('Selecciona el tipo de institución.');
   if(!['personal','negocio'].includes(scope))errors.push('Selecciona un perfil de uso válido.');
   const linked={accounts:accounts().filter(a=>a.bankId===id).length,cards:(db.cards||[]).filter(c=>c.bankId===id).length,loans:(db.loans||[]).filter(l=>l.bankId===id).length,certificates:(db.certificates||[]).filter(c=>c.bankId===id).length};
   return {...details,kind,scope,linked};
  }
  const data=elements(f);const institution=getBank(data.bankId);const hist=!!id&&hasHistory(id);
  if(!name)errors.push('Indica el nombre de la cuenta.');
  if(name.length>80)errors.push('El nombre no puede superar 80 caracteres.');
  if(!institution||institution.archived)errors.push('Selecciona una institución financiera activa.');
  else if(typeof v40IsFinancial==='function'&&!v40IsFinancial(institution))errors.push('Las cuentas bancarias deben vincularse a una institución financiera.');
  if(!['savings','checking'].includes(data.kind))errors.push('Selecciona un tipo de cuenta válido.');
  if(!['DOP','USD'].includes(data.currency))errors.push('Selecciona pesos dominicanos o dólares.');
  if(!Number.isFinite(data.opening)||Math.abs(data.opening)>1e12)errors.push('El saldo inicial debe ser un importe válido.');
  if(!validDate(data.opened)||data.opened>today())errors.push('La fecha del saldo inicial no puede ser posterior a hoy.');
  if(!/^\d{0,4}$/.test(data.last4))errors.push('Los últimos dígitos deben contener hasta cuatro números.');
  if(!Number.isFinite(data.annualRate)||data.annualRate<0||data.annualRate>100)errors.push('La tasa anual debe estar entre 0 y 100 %.');
  if(hist&&existing&&existing.currency!==data.currency)errors.push('La moneda no se puede cambiar porque la cuenta tiene movimientos. Crea otra cuenta para una moneda distinta.');
  if(hist&&existing&&existing.bankId!==data.bankId)errors.push('Esta cuenta tiene movimientos: no la traslades a otro banco, porque alteraría el historial.');
  if(hist&&existing&&existing.opened!==data.opened)errors.push('La fecha del saldo inicial no se puede modificar después de registrar movimientos.');
  const duplicate=accounts().some(a=>a.id!==id&&a.kind!=='cash'&&a.bankId===data.bankId&&normalize(a.name)===normalize(name)&&a.currency===data.currency);
  if(duplicate)errors.push('Ya existe una cuenta con ese nombre y moneda en esta institución.');
  return {...details,...data,institution,hist};
 }
 function badge(t,tone=''){return '<span class="v384-detail-chip"'+(tone?' data-tone="'+tone+'"':'')+'>'+escape(t)+'</span>'}
 function line(label,value){return '<div class="v384-preview-row"><span>'+escape(label)+'</span><strong>'+escape(value)+'</strong></div>'}
 
 function header(f,x){
  const bankForm=f.id==='bankForm';let label=bankForm?'INSTITUCIONES':'CUENTAS BANCARIAS';
  let title=bankForm?(x.id?'Editar institución':'Nueva institución'):(x.id?'Editar cuenta':'Nueva cuenta');
  let intro=bankForm?'Identidad institucional, perfil de uso y productos vinculados.':'Saldo de apertura, institución y moneda. Sin movimientos ficticios.';
  const icon=bankForm?'⌂':'▣';
  let chips=bankForm?
   [badge(x.kind||'Tipo por elegir'),badge(x.scope==='negocio'?'Negocio':'Personal'),x.id?badge('Edición segura','positive'):badge('Nueva relación','positive')]:
   [badge(x.currency==='USD'?'Dólares · US$':'Pesos · RD$'),badge(x.kind==='checking'?'Corriente':'Ahorros'),x.hist?badge('Historial protegido','warning'):badge('Saldo de apertura','positive')];
  return '<div class="v384-intro"><div class="v384-intro-top"><div class="v384-emblem" aria-hidden="true">'+icon+'</div><div><span class="v384-intro-eyebrow">vive el hoy · '+label+'</span><h3>'+escape(title)+'</h3></div></div><p>'+escape(intro)+'</p><div class="v384-detail-chiprow">'+chips.join('')+'</div></div>';
 }
 function preview(f,x){
  let html='';
  if(f.id==='bankForm'){
   let linked=x.linked||{accounts:0,cards:0,loans:0,certificates:0};let total=linked.accounts+linked.cards+linked.loans+linked.certificates;
   html='<div class="v384-preview-heading"><strong>Resumen de la institución</strong><small>Identidad</small></div>';
   html+=line('Nombre',x.name||'Por indicar');
   html+=line('Clasificación',x.kind||'Por indicar');
   html+=line('Perfil de uso',x.scope==='negocio'?'Negocio':'Personal');
   if(x.id){html+=line('Productos vinculados',String(total));html+=line('Cuentas · tarjetas · préstamos · certificados',`${linked.accounts} · ${linked.cards} · ${linked.loans} · ${linked.certificates}`)}
   html+='<p class="v384-notice">'+(x.id?'Editar el nombre o el perfil conserva los vínculos de los productos existentes.':'Al guardar se crea la identidad de la institución; no se crean cuentas ni saldos.')+'</p>';
  }else{
   html='<div class="v384-preview-heading"><strong>Cómo se registrará tu cuenta</strong><small>'+(x.id?'Edición':'Apertura')+'</small></div>';
   html+='<div class="v384-money-figure"><small>'+(x.id?'Saldo inicial registrado':'Saldo inicial de apertura')+'</small><strong>'+cash(x.opening,x.currency)+'</strong></div>';
   html+=line('Institución',x.institution?.name||'Por seleccionar');
   html+=line('Tipo y moneda',(x.kind==='checking'?'Cuenta corriente':'Cuenta de ahorros')+' · '+(x.currency||'DOP'));
   html+=line('Fecha del saldo inicial',validDate(x.opened)?x.opened:'Por indicar');
   if(x.id&&x.existing){
    const current=typeof getAccountBalance==='function'?getAccountBalance(x.existing):NaN;
    html+=line('Saldo actual registrado',cash(current,x.existing.currency));
    if(x.hist)html+='<p class="v384-notice warn">Esta cuenta tiene movimientos: cambiar su saldo de apertura puede recalcular todo su historial. Confirma el importe con tu estado de cuenta.</p>';
    else html+='<p class="v384-notice">Sin movimientos asociados todavía. El saldo inicial es una referencia, no un ingreso nuevo.</p>';
   }else html+='<p class="v384-notice">El saldo inicial define el punto de partida de la cuenta: no crea una transacción de ingreso ni un depósito adicional.</p>';
  }
  if(x.errors.length)html+='<p class="v384-notice critical" role="status">'+escape(x.errors[0])+'</p>';
  return html;
 }
 function paint(f){
  const x=inspect(f);const intro=f.querySelector('.v384-intro'),box=f.querySelector('.v384-inline-preview');
  if(intro)intro.outerHTML=header(f,x);
  if(box)box.innerHTML=preview(f,x);
  f.dataset.v384Error=x.errors[0]||'';
  // Feedback only; existing form submit handler remains the single writer.
  const save=f.querySelector('.form-foot button[type="submit"]');
  if(save){save.setAttribute('aria-describedby','v384-'+f.id+'-preview');save.setAttribute('aria-invalid',x.errors.length?'true':'false')}
 }
 function decorate(f){
  if(!f||f.dataset.v384Ready==='1')return;
  f.dataset.v384Ready='1';
  const grid=f.querySelector('.form-grid');if(!grid)return;
  const intro=document.createElement('div');intro.className='v384-intro';
  const preview=document.createElement('section');preview.id='v384-'+f.id+'-preview';preview.className='v384-inline-preview';preview.setAttribute('aria-label',f.id==='bankForm'?'Resumen institucional':'Resumen de apertura de cuenta');
  preview.setAttribute('aria-live','polite');
  grid.prepend(intro);grid.append(preview);
  const redraw=()=>paint(f);f.addEventListener('input',redraw);f.addEventListener('change',redraw);
  paint(f);
 }
 const root=document.getElementById('modal-root');
 const attach=()=>{if(!root)return;for(const f of root.querySelectorAll('#bankForm,#accountForm'))decorate(f)};
 if(root){const mo=new MutationObserver(()=>attach());mo.observe(root,{childList:true,subtree:false});attach()}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',attach,{once:true});
 document.addEventListener('submit',e=>{
  const f=e.target;if(!f||!['bankForm','accountForm'].includes(f.id))return;
  const x=inspect(f);paint(f);
  if(x.errors.length){e.preventDefault();e.stopImmediatePropagation();
   const warning=x.errors[0];if(typeof toast==='function')toast(warning);
   f.querySelector('.v384-inline-preview')?.scrollIntoView({block:'nearest',behavior:'smooth'});
  }
 },true);
})();
;
/* ==== script: v385-certificate-controller ==== */
(function(){
 'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 const esc=x=>String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const field=(f,n)=>f.elements.namedItem(n);
 const val=(f,n)=>String(field(f,n)?.value??'');
 const cash=(n,c)=> (c==='USD'?'US$':'RD$')+(Number(n)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
 const numVal=(f,n)=>Number(val(f,n));
 const rows=(name,x)=>'<div class="v385-cert-row"><span>'+esc(name)+'</span><strong>'+esc(x)+'</strong></div>';
 function inspect(f){
  const id=f.dataset.id||'',prior=id&&typeof certificate==='function'?certificate(id):null;
  const b=typeof bank==='function'?bank(val(f,'bankId')):null;
  const cur=val(f,'currency'),principal=numVal(f,'principal'),rate=numVal(f,'rate'),tax=numVal(f,'taxPct');
  const start=val(f,'startDate'),end=val(f,'maturityDate'),mode=val(f,'capitalMode');
  const payout=val(f,'payoutFrequency'),errors=[];
  const operations=prior&&Array.isArray(db?.transactions)?db.transactions.filter(t=>t.certificateId===id):[];
  if(!val(f,'name').trim())errors.push('Escribe un nombre para el certificado.');
  if(!b||b.archived)errors.push('Selecciona una institución financiera activa.');
  if(!['DOP','USD'].includes(cur))errors.push('Selecciona DOP o USD.');
  if(!Number.isFinite(principal)||principal<=0)errors.push('Introduce un capital mayor que cero.');
  if(!Number.isFinite(rate)||rate<0||rate>100)errors.push('Revisa la tasa anual.');
  if(!Number.isFinite(tax)||tax<0||tax>100)errors.push('La retención debe estar entre 0 % y 100 %.');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end)||end<=start)errors.push('El vencimiento debe ser posterior a la constitución.');
  if(start>today())errors.push('La constitución no puede tener fecha futura.');
  if(prior&&operations.length&&(prior.bankId!==val(f,'bankId')||prior.currency!==cur||Math.abs(Number(prior.principal)-principal)>.005||(prior.capitalMode||'already')!==mode||prior.startDate!==start||prior.maturityDate!==end))errors.push('Este certificado ya tiene operaciones. No cambies institución, moneda, capital, modalidad de constitución ni fechas.');
  const validDates=/^\d{4}-\d{2}-\d{2}$/.test(start)&&/^\d{4}-\d{2}-\d{2}$/.test(end)&&end>start;
  const days=validDates?Math.max(0,Math.round((Date.parse(end+'T12:00:00Z')-Date.parse(start+'T12:00:00Z'))/86400000)):0;
  const gross=Number.isFinite(principal*rate)?Math.max(0,principal)*Math.max(0,rate)*days/36500:0;
  const reten=gross*Math.max(0,Number.isFinite(tax)?tax:0)/100;
  const confirmed=operations.filter(t=>t.type==='income').reduce((z,t)=>z+Number(t.amount||0),0);
  const funding=operations.filter(t=>t.type==='certificate_funding').reduce((z,t)=>z+Number(t.amount||0),0);
  const redeems=operations.filter(t=>t.type==='certificate_redemption').reduce((z,t)=>z+Number(t.amount||0),0);
  return {id,prior,b,cur,principal,rate,tax,start,end,mode,payout,days,gross,reten,confirmed,funding,redeems,operations,errors};
 }
 function preview(x){
  const active=x.mode==='pending'?Math.max(0,x.funding-x.redeems):Math.max(0,x.principal-x.redeems);
  const estimated=x.gross-x.reten;
  const underfund=x.mode==='pending'&&x.funding<x.principal-.005;
  const realProjection=x.prior&&typeof certProjection==='function'?certProjection(x.prior):null;
  return '<header><strong>Resumen de la inversión</strong><small>'+(x.prior?'EDITANDO':'NUEVO')+'</small></header>'+
   '<div class="v385-cert-capital"><small>CAPITAL PACTADO</small><strong>'+cash(x.principal,x.cur)+'</strong></div>'+
   '<div class="v385-cert-pairs">'+
     '<div class="v385-cert-pair"><small>Rendimiento bruto orientativo</small><strong>'+cash(x.gross,x.cur)+'</strong></div>'+
     '<div class="v385-cert-pair"><small>Rendimiento neto orientativo</small><strong>'+cash(estimated,x.cur)+'</strong></div>'+
   '</div>'+
   rows('Institución emisora',x.b?.name||'Selecciona una institución')+
   rows('Plazo contractual',x.days+' días')+
   rows('Tasa y retención',x.rate.toFixed(3)+' % anual · '+x.tax.toFixed(2)+' % retención')+
   rows('Cobro de intereses',({monthly:'Mensual',quarterly:'Trimestral',maturity:'Al vencimiento',other:'Según contrato'})[x.payout]||'Sin definir')+
   (x.prior?rows('Capital vigente según movimientos',cash(active,x.cur))+rows('Intereses efectivamente registrados',cash(x.confirmed,x.cur)):'')+
   (x.prior&&realProjection?rows('Estimación sobre movimientos reales',cash(realProjection.net,x.cur)):'')+
   (underfund?'<div class="v385-cert-note warn">Capital pendiente de transferir: no se aumenta el efectivo ni se considera ingreso hasta registrar una operación real.</div>':'')+
   '<div class="v385-cert-note '+(x.mode==='pending'?'warn':'')+'">'+(x.mode==='pending'?'PENDIENTE DE CONSTITUCIÓN: crea el certificado ahora y registra después la salida desde la cuenta, una sola vez.':'YA CONSTITUIDO: el capital consta invertido en el saldo inicial. No lo vuelvas a descontar de una cuenta.')+'</div>'+
   '<div class="v385-cert-note">El rendimiento utiliza interés simple orientativo, base de 365 días. No equivale a una promesa del banco, no incorpora capitalizaciones y no se registra como ingreso hasta su cobro efectivo. El cobro real se registra aparte por el importe neto acreditado.</div>'+
   (x.operations.length?'<div class="v385-cert-note warn">Existen '+x.operations.length+' operaciones vinculadas. Se protegen las condiciones contractuales que afectan su historial.</div>':'')+
   (x.errors.length?'<div class="v385-cert-note error" role="alert">'+esc(x.errors[0])+'</div>':'');
 }
 function paint(f){if(!f.isConnected)return;const x=inspect(f);const intro=f.querySelector('.v385-cert-intro');
   if(intro)intro.innerHTML='<span class="eyebrow">vive el hoy · CERTIFICADOS FINANCIEROS</span><h3>'+(x.prior?'Edita tu inversión':'Una inversión con vencimiento claro')+'</h3><p>Configura capital, tasa, retención y vencimiento. El dinero invertido y los intereses cobrados permanecen separados del efectivo.</p>';
   const pane=f.querySelector('.v385-cert-preview');if(pane)pane.innerHTML=preview(x);
 }
 function setup(){const f=root.querySelector('#certificateForm');if(!f||f.dataset.v385Ready)return;
  f.dataset.v385Ready='1';const grid=f.querySelector('.form-grid');if(!grid)return;
  const intro=document.createElement('section');intro.className='v385-cert-intro';grid.prepend(intro);
  const pane=document.createElement('section');pane.className='v385-cert-preview';pane.setAttribute('aria-label','Vista previa financiera del certificado');pane.setAttribute('aria-live','polite');grid.append(pane);
  const onChange=()=>paint(f);f.addEventListener('input',onChange);f.addEventListener('change',onChange);paint(f);
 }
 window.v385CertificateSetup=setup;
 const mo=new MutationObserver(()=>setup());mo.observe(root,{childList:true,subtree:false});setup();
 document.addEventListener('submit',e=>{
  const f=e.target;if(f?.id!=='certificateForm')return;
  const x=inspect(f);paint(f);
  if(x.errors.length){e.preventDefault();e.stopImmediatePropagation();if(typeof toast==='function')toast(x.errors[0]);f.querySelector('.v385-cert-preview')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
 },true);
})();
;
/* ==== script: v386-recurring-controller ==== */
(function(){
 'use strict';
 const hooks=window.__f360RecurringVisualAdapter;
 const {account,card,bank,prettyDate,today}=hooks||{};
 const moneyText=(n,c)=>`${c==='USD'?'US$':'RD$'}${Math.max(0,Number(n)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
 const read=(f,key)=>String(f.elements.namedItem(key)?.value??'');
 const safe=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
 const validDay=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s+'T12:00:00Z'));
 const sourceOf=(value)=>{const [k,id]=String(value).split(':');return k==='account'?account(id):k==='card'?card(id):null;};
 function inspect(f){
  const current=hooks?.readState();
  const id=f.dataset.id||'',old=id?current?.recurring?.find(x=>x.id===id):null;
  const name=read(f,'name').trim(),amount=Number(read(f,'amount')),
   currency=read(f,'currency'),source=read(f,'source'),cycle=read(f,'frequency'),nextDue=read(f,'nextDue'),mode=read(f,'postingMode'),active=read(f,'active');
  const [kind]=source.split(':'),s=sourceOf(source),errors=[];
  if(!name)errors.push('Indica el nombre del servicio.');
  if(!Number.isFinite(amount)||amount<=0)errors.push('El importe por cobro debe ser mayor que cero.');
  if(!['DOP','USD'].includes(currency))errors.push('Selecciona una moneda válida.');
  if(!s||s.archived||!['account','card'].includes(kind)||bank(s.bankId)?.archived)errors.push('Selecciona una cuenta o tarjeta activa como fuente.');
  if(kind==='account'&&s&&s.currency!==currency)errors.push('La moneda debe coincidir con la cuenta de pago.');
  if(!['weekly','monthly','quarterly','annual'].includes(cycle))errors.push('Selecciona una periodicidad válida.');
  if(!validDay(nextDue))errors.push('Indica el próximo vencimiento válido.');
  if(mode==='auto'&&validDay(nextDue)&&nextDue<today())errors.push('El próximo vencimiento automático no puede estar en el pasado.');
  const ratio={weekly:52/12,monthly:1,quarterly:1/3,annual:1/12}[cycle]||1;
  const monthly=Number.isFinite(amount)?amount*ratio:0;
  const already=id?(current?.transactions||[]).filter(t=>t.recurringId===id&&['expense','card_charge'].includes(t.type)):[];
  const paid=already.length,latest=already.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0];
  const duplicate=id&&(current?.transactions||[]).some(t=>t.scheduleKey===`recurring:${id}:${nextDue}`);
  const warning=duplicate?'El vencimiento seleccionado ya tiene un movimiento asociado. Revisa la agenda antes de confirmar otro cobro.':mode==='auto'?'El modo automático registra un asiento estimado al procesar el vencimiento dentro de la app; no paga al proveedor.':'El registro manual solo crea una obligación prevista. No descuenta dinero hasta registrar el pago.';
  return {id,old,name,amount,currency,source,cycle,nextDue,mode,active,kind,s,monthly,paid,latest,warning,errors};
 }
 function setup(){
  const f=document.getElementById('recurringForm');if(!f||f.dataset.v386Ready)return;
  f.dataset.v386Ready='1';
  const grid=f.querySelector('.form-grid');if(!grid)return;
  const panel=document.createElement('section');panel.className='v386-rec-summary';panel.setAttribute('aria-label','Resumen y validación del servicio');
  panel.innerHTML='<header><span class="v386-rec-kicker">SERVICIOS · PROGRAMACIÓN</span><strong>Antes de guardar</strong></header><div class="v386-rec-hero"><small>Importe del siguiente cobro</small><strong data-r386="amount">RD$0.00</strong></div><div class="v386-rec-stats"><div class="v386-rec-stat"><small>Costo mensual equivalente</small><strong data-r386="monthly">RD$0.00</strong></div><div class="v386-rec-stat"><small>Próximo vencimiento</small><strong data-r386="date">Sin fecha</strong></div><div class="v386-rec-stat"><small>Fuente de pago</small><strong data-r386="source">Por seleccionar</strong></div><div class="v386-rec-stat"><small>Historial de este servicio</small><strong data-r386="history">Nuevo compromiso</strong></div></div><div class="v386-rec-note" data-r386="message" role="status" aria-live="polite">Guardarlo no realiza ningún cargo bancario.</div>';
  const layout=grid.querySelector('.v147-rec-shell');
  if(layout)layout.insertAdjacentElement('afterend',panel);else grid.append(panel);
  function update(){
   if(!f.isConnected)return;const x=inspect(f);
   const out=(id,value)=>{const node=panel.querySelector(`[data-r386="${id}"]`);if(node)node.textContent=value};
   out('amount',moneyText(x.amount,x.currency));out('monthly',moneyText(x.monthly,x.currency));
   out('date',validDay(x.nextDue)?prettyDate(x.nextDue):'Sin fecha');
   out('source',x.s?`${x.s.name} · ${x.kind==='card'?'Tarjeta':'Cuenta'}`:'Por seleccionar');
   out('history',x.paid?`${x.paid} cargo${x.paid===1?'':'s'} · último ${prettyDate(x.latest.date)}`:'Sin cargos registrados');
   const message=panel.querySelector('[data-r386="message"]');
   message.textContent=x.errors.length?x.errors[0]:x.warning;
   message.dataset.state=x.errors.length?'error':x.mode==='auto'||x.warning.startsWith('El vencimiento')?'warning':'info';
  }
  f.addEventListener('input',update);
  f.addEventListener('change',update);
  f.addEventListener('click',ev=>{if(ev.target.closest('[data-v147-frequency],[data-v45-payfreq],[data-v147-preset]'))queueMicrotask(update);});
  update();
 }
 hooks?.wrapRenderer(prior=>function(id){prior(id);queueMicrotask(setup);});
 window.v386ValidateRecurringForm=function(ev){
  const f=ev.target;if(f?.id!=='recurringForm')return;
  const x=inspect(f);
  if(!x.errors.length)return;
  ev.preventDefault();ev.stopImmediatePropagation();
  const err=f.querySelector('#formError')||document.getElementById('formError');
  if(err){err.textContent=x.errors[0];err.style.display='block';}
  else if(typeof showError==='function')showError(x.errors[0]);
  f.querySelector('.v386-rec-summary')?.scrollIntoView({block:'nearest',behavior:'smooth'});
 };
})();
;
/* ==== script: v387-services-web-behavior ==== */
/* Scoped desktop redesign; reuses original service cards/actions and dynamic values. */
(function(){
 'use strict';
 const hooks=window.__f360RecurringVisualAdapter;
 const state={category:'all',search:'',status:'all',frequency:'all',sort:'next'};
 let raf=0;
 const esc=(value)=>String(value??'').toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const safeString=value=>String(value??'');
 function sourceName(r){
  const src=safeString(r.source);
  if(!src)return 'Sin método asociado';
  const parts=src.split(':');
  if(parts.length!==2)return 'Método configurado';
  if(parts[0]==='account'){
   const a=(hooks.readState().accounts||[]).find(x=>String(x.id)===parts[1]);
   return a?'Cuenta · '+safeString(a.name):'Cuenta no disponible';
  }
  if(parts[0]==='card'){
   const c=(hooks.readState().cards||[]).find(x=>String(x.id)===parts[1]);
   return c?'Tarjeta · '+safeString(c.name):'Tarjeta no disponible';
  }
  return 'Método configurado';
 }
 const $=(tag,cls,content)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(content!==undefined)el.textContent=content;return el};
 function reconcile(){
  if(window.innerWidth<791||hooks?.currentPage()!=='recurring')return;
  const root=document.querySelector('#page .v26-internal[data-module="recurring"]');
  if(!root)return;
  const kpi=root.querySelector('.v264-subs-kpi'), grid=root.querySelector('.v46-subscriptions-grid'),panel=root.querySelector('.v46-subs-panel');
  if(!grid||!panel||!kpi)return;
  root.classList.add('v387-services-web');
  const kpiGrid=kpi.querySelector('.v264-kpi-grid');
  if(kpiGrid&&!kpiGrid.querySelector('.v387-active-kpi')){
   const active=(hooks.readState().recurring||[]).filter(r=>r&&!r.archived&&r.active!==false).length;
   const k=$('article','v264-kpi-card v387-active-kpi');
   k.append($('small','', 'SERVICIOS ACTIVOS'),$('strong','',String(active)),$('span','','Programados'));
   kpiGrid.append(k);
  }
  const all=(hooks.readState().recurring||[]).filter(r=>r);
  const cards=new Map([...grid.querySelectorAll('.v46-subscription-card[data-v149-rec-id]')].map(el=>[el.getAttribute('data-v149-rec-id'),el]));
  const head=panel.querySelector('.v46-subs-head');
  if(head){const h=head.querySelector('h3');if(h)h.textContent='Servicios y suscripciones';}
  if(!panel.querySelector('.v387-toolbar')){
   const toolbar=$('div','v387-toolbar');
   const search=$('label','v387-search');search.innerHTML='<svg width="16" height="16" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/></svg>';
   const input=$('input');input.type='search';input.placeholder='Buscar un servicio';input.setAttribute('aria-label','Buscar servicio');input.value=state.search;
   input.addEventListener('input',()=>{state.search=input.value;draw()});search.append(input);
   const controls=$('div','v387-controls');
   const makeSelect=(label,options,field)=>{const select=$('select');select.setAttribute('aria-label',label);options.forEach(([val,text])=>{const opt=$('option');opt.value=val;opt.textContent=text;select.append(opt)});select.value=state[field];select.addEventListener('change',()=>{state[field]=select.value;draw()});return select};
   controls.append(makeSelect('Estado',[['all','Todos los estados'],['active','Activas'],['paused','Pausadas']],'status'));
   controls.append(makeSelect('Frecuencia',[['all','Todas las frecuencias'],['monthly','Mensual'],['weekly','Semanal'],['quarterly','Trimestral'],['annual','Anual']],'frequency'));
   controls.append(makeSelect('Ordenar',[['next','Próximo cobro'],['name','Nombre A–Z'],['amount','Importe mayor'],['category','Categoría']],'sort'));
   toolbar.append(search,controls);
   const categories=$('nav','v387-categories');categories.setAttribute('aria-label','Filtrar por categoría');
   const count=$('div','v387-summary-line');
   panel.insertBefore(toolbar,grid);panel.insertBefore(categories,grid);panel.insertBefore(count,grid);
  }
  // DOM cards are moved, not cloned: data-act and data-id stay attached to the original event handlers.
  const catalog=all.map(r=>({r,card:cards.get(String(r.id))})).filter(x=>x.card);
  const chips=panel.querySelector('.v387-categories');
  const categories=[...new Set(catalog.map(x=>safeString(x.r.category||'Otros').trim()||'Otros'))].sort((a,b)=>a.localeCompare(b,'es'));
  if(state.category!=='all'&&!categories.includes(state.category))state.category='all';
  chips.replaceChildren();
  const chip=(name,value,count)=>{
   const btn=$('button','v387-cat');btn.type='button';btn.setAttribute('aria-pressed',String(state.category===value));
   btn.append(document.createTextNode(name+' '),$('b','',String(count)));
   btn.addEventListener('click',()=>{state.category=value;draw()});chips.append(btn);
  };
  chip('Todas','all',catalog.length);categories.forEach(category=>chip(category,category,catalog.filter(x=>(x.r.category||'Otros')===category).length));
  function draw(){
   const query=esc(state.search.trim());
   let shown=catalog.filter(({r})=>(state.category==='all'||(r.category||'Otros')===state.category)
    &&(state.status==='all'||(state.status==='active'?(r.active!==false):(r.active===false)))
    &&(state.frequency==='all'||r.frequency===state.frequency)
    &&(!query||esc([r.name,r.category,r.subcategory,r.frequency,sourceName(r)].join(' ')).includes(query)));
   shown.sort((a,b)=>{
    const ar=a.r,br=b.r;
    if(state.sort==='name')return safeString(ar.name).localeCompare(safeString(br.name),'es');
    if(state.sort==='amount')return Number(br.amount||0)-Number(ar.amount||0);
    if(state.sort==='category')return safeString(ar.category).localeCompare(safeString(br.category),'es')||safeString(ar.name).localeCompare(safeString(br.name),'es');
    return safeString(ar.nextDue||'9999').localeCompare(safeString(br.nextDue||'9999'))||safeString(ar.name).localeCompare(safeString(br.name),'es');
   });
   panel.querySelector('.v387-summary-line').replaceChildren($('span','',shown.length+' de '+catalog.length+' servicios'),$('span','','Agrupados por categoría'));
   grid.replaceChildren();grid.classList.add('v387-grouped');
   if(!shown.length){grid.append($('div','v387-empty','No hay servicios para esta selección. Prueba con otros filtros.'));return;}
   const names=[...new Set(shown.map(x=>safeString(x.r.category||'Otros').trim()||'Otros'))].sort((a,b)=>a.localeCompare(b,'es'));
   names.forEach(name=>{
    const group=$('section','v387-group');
    const title=$('header','v387-group-head');const tally=shown.filter(x=>(x.r.category||'Otros')===name).length;
    title.append($('strong','',name),$('small','',tally+' '+(tally===1?'servicio':'servicios')));
    const items=$('div','v387-group-items');
    shown.filter(x=>(x.r.category||'Otros')===name).forEach(({r,card})=>{
     card.querySelector('.v387-pay-source')?.remove();
     const details=card.querySelector('.v46-sub-card-next');
     if(details)details.append($('span','v387-pay-source',sourceName(r)));
     items.append(card);
    });group.append(title,items);grid.append(group);
   });
  }
  draw();
 }
 function schedule(){if(raf)return;raf=requestAnimationFrame(()=>{raf=0;try{reconcile()}catch(err){console.warn('Servicios V387:',err)}})}
 hooks?.wrapMainRenderer(original=>function(...args){const result=original.apply(this,args);schedule();return result});
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
 window.addEventListener('resize',schedule,{passive:true});
})();
;
/* ==== script: v391-registration-interaction ==== */
(()=>{'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 const names={transactionForm:'Movimiento',accountForm:'Cuenta',cardForm:'Tarjeta',loanForm:'Préstamo',certificateForm:'Certificado',personalLoanForm:'Acuerdo',personalPaymentForm:'Abono',recurringForm:'Servicio',annualFeeForm:'Anualidad',rewardReceivedForm:'Beneficio',benefitLedgerForm:'Beneficio',manualBenefitForm:'Beneficio',v144CashbackForm:'Cashback',bankForm:'Institución',categoryForm:'Categoría',budgetForm:'Presupuesto',cashWalletForm:'Efectivo'};
 const escape=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let processing=false;
 function decorate(){
  if(processing)return;processing=true;
  try{
   for(const modal of root.querySelectorAll('.modal.v204-form-dialog')){
    if(modal.dataset.v391Ready==='1')continue;
    const form=modal.querySelector(':scope > form');if(!form)continue;
    const formName=names[form.id]||'Registro';
    modal.dataset.v391Ready='1';modal.classList.add('v391-form-shell');
    const head=modal.querySelector(':scope > .modal-head');
    // Barra de etapas decorativa eliminada; se mantienen encabezado y validaciones.
    const error=form.querySelector('#formError');if(error){error.setAttribute('role','alert');error.setAttribute('aria-live','polite');}
    // Preserve native validation and all original financial submit handlers.
    form.addEventListener('invalid',e=>{const field=e.target;if(!(field instanceof HTMLElement))return;const details=field.closest('details');if(details)details.open=true;field.setAttribute('aria-invalid','true');},true);
    form.addEventListener('input',e=>{const field=e.target;if(field instanceof HTMLElement&&field.matches('input,select,textarea')&&field.checkValidity())field.removeAttribute('aria-invalid')});
    form.addEventListener('change',e=>{const field=e.target;if(field instanceof HTMLElement&&field.matches('input,select,textarea')&&field.checkValidity())field.removeAttribute('aria-invalid')});
   }
  }finally{processing=false;}
 }
 decorate();
 let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;decorate();})});observer.observe(root,{childList:true,subtree:true});
})();
;
