/* ==== script: f836-form-simplification ==== */
(()=>{'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 let pending=false;
 const names={cashback:'Cashback recibido',discount:'Descuento recibido',points:'Puntos recibidos',other:'Beneficio recibido'};
 function prepareBenefit(f){
  if(f.dataset.f836Prepared==='1')return;
  const type=f.elements.namedItem('kind'),concept=f.elements.namedItem('name'),date=f.elements.namedItem('date');
  if(!type||!concept||!date)return;
  f.dataset.f836Prepared='1';
  /* Retain required native fields. Concept comes from the chosen benefit type;
     on edit, don't overwrite the user's historical description. */
  const savedConcept=concept.value;
  const edited=!!f.elements.namedItem('entryId')?.value;
  const sync=()=>{
   if(!edited && (!concept.value||Object.values(names).includes(concept.value)))concept.value=names[type.value]||names.other;
  };
  type.addEventListener('change',sync);sync();
  for(const el of [concept,date]){
    const label=el.closest('label');if(label){label.classList.add('f836-hidden-field');}
  }
  /* Keep the date value supplied by the original form (today on a new
     entry, original date on an edit). Do not silently change past records. */
  const fold=f.querySelector('.other-studio-fold');if(fold){fold.open=false;fold.hidden=true;}
  const impact=f.querySelector('.v785-benefit-preview');
  if(impact){impact.hidden=false;}
  /* Don't hide destination: it is necessary when cashback is credited to a bank account. */
 }
 function prepareLoan(f){
  if(f.dataset.f836Prepared==='1')return;
  const content=f.querySelector('.other-studio-content'),loan=f.elements.namedItem('loanId');
  if(!content||!loan)return;
  f.dataset.f836Prepared='1';
  const core=loan.closest('.other-studio-fields');
  const summary=f.querySelector('.f834-loan-summary');
  /* A compact overview follows the loan selection and payment type. The
     detailed financial preview remains available in its collapsible section. */
  if(summary&&core){core.after(summary);}
  const details=f.querySelector('.f835-details');if(details)details.open=false;
 }
 function run(){pending=false;for(const f of root.querySelectorAll('form.other-studio-form[data-financial-layout]')){
  if(f.dataset.special==='benefit')prepareBenefit(f);
  if(f.dataset.special==='loan')prepareLoan(f);
 }}
 new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(run)}}).observe(root,{subtree:true,childList:true});run();
window.__v866Runners.f836=run;
})();
;
/* ==== script: f837-loan-premium-flow ==== */
(()=>{'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 let scheduled=false;
 function setup(f){
  if(f.dataset.f837Flow)return;
  const loan=f.elements.namedItem('loanId'), account=f.elements.namedItem('accountId');
  const amount=f.elements.namedItem('amount'), payKind=f.querySelector('.financial-payment-type');
  const core=loan?.closest('.other-studio-fields'), amountCard=f.querySelector('.other-studio-amount');
  if(!core||!loan||!payKind||!amountCard||!account)return;
  f.dataset.f837Flow='1';
  const loanLabel=loan.closest('label'),accountLabel=account.closest('label');
  const layout=document.createElement('section');layout.className='f837-flow';
  core.prepend(layout);
  for(const el of [loanLabel,payKind,amountCard])if(el)layout.appendChild(el);
  const lines=document.createElement('section');lines.className='f837-payment-summary';lines.setAttribute('aria-label','Desglose del pago');
  lines.innerHTML='<div class="f837-pay-line"><span>Capital</span><strong data-f837="principal">—</strong></div><div class="f837-pay-line"><span>Intereses</span><strong data-f837="interest">—</strong></div><div class="f837-pay-line"><span>Seguro y comisiones</span><strong data-f837="fees">—</strong></div>';
  layout.appendChild(lines);
  if(accountLabel){accountLabel.classList.add('f837-account');layout.appendChild(accountLabel)}
  const extra=document.createElement('details');extra.className='f837-options';
  extra.innerHTML='<summary>Fecha, vencimiento y canal de pago ▾</summary>';
  for(const key of ['paymentChannel','date','installmentPeriod']){
   const field=f.elements.namedItem(key)?.closest('label');if(field)extra.appendChild(field);
  }
  layout.appendChild(extra);
  const nf=new Intl.NumberFormat('es-DO',{minimumFractionDigits:2,maximumFractionDigits:2});
  function update(){
   const raw=String(loan.options[loan.selectedIndex]?.textContent||'');
   const ccy=/\bUSD\b|US\$/i.test(raw)?'US$':'RD$';
   const fmt=(key)=>{let n=Number(f.elements.namedItem(key)?.value);return Number.isFinite(n)&&n>=0?ccy+nf.format(n):'—'};
   lines.querySelector('[data-f837="principal"]').textContent=fmt('principal');
   lines.querySelector('[data-f837="interest"]').textContent=fmt('interest');
   const fees=Number(f.elements.namedItem('insurance')?.value||0)+Number(f.elements.namedItem('fee')?.value||0);
   lines.querySelector('[data-f837="fees"]').textContent=Number.isFinite(fees)?ccy+nf.format(fees):'—';
  }
  f.addEventListener('change',update);f.addEventListener('input',update);update();
 }
 function run(){scheduled=false;for(const f of root.querySelectorAll('form.other-studio-form[data-special="loan"]'))setup(f)}
 new MutationObserver(()=>{if(!scheduled){scheduled=true;requestAnimationFrame(run)}}).observe(root,{subtree:true,childList:true});run();
window.__v866Runners.f837=run;
})();
