 const head=form.querySelector('.financial-header-copy p');if(head)head.textContent='Registra tus beneficios y aprovecha más';
 // V864: Un solo encabezado, mismo orden de Devolución de compra.
 // Conserva el botón de cierre nativo (y, por tanto, su manejador real).
 const header=form.querySelector('.other-studio-header');
 if(header&&!header.querySelector('.v864-topbar')){
   const close=header.querySelector('.other-studio-close');
   const art=header.querySelector('.v785-hero-icon');
   const copy=header.querySelector('.financial-header-copy');
   if(close&&art&&copy){
     header.querySelector('.v844-back')?.remove();
     const topbar=document.createElement('div');topbar.className='v864-topbar';
     const back=document.createElement('button');back.type='button';back.className='v864-back';
     back.setAttribute('aria-label','Volver a Otras gestiones');
     back.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 18 9 12l6-6"/><path d="M9 12h11"/></svg><span>Otras gestiones</span>';
     back.addEventListener('click',()=>{
       // Navegación original de la referencia Devolución de compra.
       const nav=document.createElement('button');nav.type='button';nav.dataset.act='newTransaction';
       nav.hidden=true;form.appendChild(nav);nav.click();nav.remove();
     });
     close.classList.add('v864-close');
     const heroHead=document.createElement('div');heroHead.className='v864-hero';
     const iconWrap=document.createElement('div');iconWrap.className='v864-hero-icon';iconWrap.append(art);
     heroHead.append(iconWrap,copy);
     topbar.append(back,close);
     header.replaceChildren(topbar,heroHead);
     // El grid inline de versiones previas se reemplaza exclusivamente aquí.
     header.style.setProperty('display','block','important');
     header.style.setProperty('grid-template-columns','none','important');
     header.style.setProperty('height','auto','important');
     header.style.setProperty('min-height','0','important');
     header.style.setProperty('padding','0','important');
     header.style.setProperty('margin','0 0 13px','important');
   }
 }
 const small=hero.querySelector('small');if(small)small.textContent='Beneficio por registrar';
 const giftEl=hero.querySelector('.f834-gift');if(giftEl)giftEl.innerHTML=gift;
 for(const btn of kinds.querySelectorAll('button[data-kind]')){const node=btn.querySelector('.f834-kind-icon');if(node&&choices[btn.dataset.kind])node.innerHTML=choices[btn.dataset.kind];}
 const amt=form.querySelector('.other-studio-amount');if(amt){const lab=amt.querySelector(':scope>span');if(lab)lab.textContent='Monto recibido';}
 const input=amt?.querySelector('input[name=amount]');
