 loan.addEventListener('change',updateSymbol);updateSymbol();
 // Conservar selección actual al entrar, y evitar pérdida de estado en los pasos.
 f.querySelectorAll('.v83-loan-pay-nav button').forEach(b=>b.setAttribute('aria-label',b.textContent.trim()));
