/* ==== script: v872-registrar-navigation-canonical ==== */
(()=>{'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 const svg='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 18 9 12l6-6"/><path d="M9 12h11"/></svg>';
 let queued=false;
 function mountBenefit(form){
   if(!form.classList.contains('v844-reference')||form.dataset.v844Benefit!=='1')return;
   const header=form.querySelector('.other-studio-header');if(!header)return;
   const top=header.querySelector('.v864-topbar');if(!top)return;
   let back=top.querySelector('.v864-back');
   if(!back){back=document.createElement('button');back.type='button';back.className='v864-back';back.innerHTML=svg+'<span>Otras gestiones</span>';top.prepend(back);}
   back.setAttribute('aria-label','Volver a Otras gestiones');
   const close=top.querySelector('.other-studio-close');if(close)close.setAttribute('aria-label','Cerrar Beneficios bancarios');
 }
 function mountLoan(form){
   if(form.dataset.v865Prepared!=='1')return;
   const header=form.querySelector('.other-studio-header');if(!header)return;
   let bar=header.querySelector('.v871-loan-topbar');
   if(!bar){
     const close=header.querySelector('.other-studio-close');
     const icon=header.querySelector('.v785-hero-icon');
     const copy=header.querySelector('.financial-header-copy');
     if(!close||!icon||!copy)return;
     let back=header.querySelector('.v844-back');
     if(!back){back=document.createElement('button');back.type='button';back.className='v844-back';header.prepend(back);}
     back.classList.add('v871-loan-back');
     back.innerHTML=svg+'<span>Otras gestiones</span>';
     back.setAttribute('aria-label','Volver a Otras gestiones');
     close.classList.add('v871-loan-close');close.setAttribute('aria-label','Cerrar Abonar a un préstamo');
     bar=document.createElement('div');bar.className='v871-loan-topbar';
     const hero=document.createElement('div');hero.className='v871-loan-hero';
     bar.append(back,close);hero.append(icon,copy);header.replaceChildren(bar,hero);
     header.style.removeProperty('grid-template-columns');header.style.removeProperty('height');
     header.style.setProperty('display','block','important');
     for(const node of [back,close,icon,copy])for(const key of ['grid-area','grid-column','grid-row'])node.style.removeProperty(key);
   }
 }
 function run(){queued=false;for(const form of root.querySelectorAll('form.other-studio-form[data-special]')){
  const kind=form.dataset.special;
  if(kind==='benefit')mountBenefit(form);
  if(kind==='loan')mountLoan(form);
  // One navigation control per operation, taking the route already owned by V872.
  // No parallel navigation bar and no close X in these six mobile operations.
  if(window.matchMedia('(max-width:790px)').matches&&!form.dataset.vopNavCompact){
   const back=form.querySelector('.v861-back,.v855-back,.v864-back,.v871-loan-back,.v844-back');
   if(back){
    back.classList.add('vop-circular-back');
    back.innerHTML=svg;
    back.setAttribute('aria-label','Regresar a Registrar · Otras gestiones');
    back.setAttribute('title','Regresar');
    form.dataset.vopNavCompact='1';
    const header=back.closest('.other-studio-header');
    form.querySelectorAll('.v861-x,.v855-close,.v864-close,.v871-loan-close,.other-studio-close,.v857-close')
     .forEach(node=>node.remove());
    // Earlier navigation bar has no remaining purpose.
    form.querySelector('.v857-headrow')?.remove();
    if(form.dataset.special==='adjustment'){
     const submit=form.querySelector('.form-foot button[type="submit"]');
     if(submit)submit.textContent='✓ Confirmar ajuste';
    }
   }
  }
  const shell=form.querySelector('.other-studio-shell');if(shell&&!form.dataset.v871Mounted){
    form.dataset.v871Mounted='1';
    shell.setAttribute('role','region');shell.setAttribute('aria-label','Contenido de '+({benefit:'Beneficios bancarios',loan:'Abonar a un préstamo',refund:'Devolución de compra',adjustment:'Conciliar un saldo'}[kind]||'operación'));
    shell.setAttribute('tabindex','-1');
  }
 }}
 function requestRun(){if(!queued){queued=true;requestAnimationFrame(run);}}
 /* Capture BEFORE old handlers: a single navigation route; no double click and no closing-only back button. */
 root.addEventListener('click',function(event){
  const back=event.target.closest?.('.v861-back,.v855-back,.v854-back,.v857-back,.v864-back,.v871-loan-back,.v844-back');
  if(!back)return;
  const form=back.closest('form.other-studio-form[data-special]');if(!form)return;
  event.preventDefault();event.stopImmediatePropagation();
  const trigger=document.createElement('button');trigger.type='button';trigger.dataset.act='newTransaction';trigger.hidden=true;
  form.appendChild(trigger);try{trigger.click()}finally{trigger.remove()}
  /* Ensure the assistant is on the requested Otros group, not the previous group. */
  const assistant=root.querySelector('.v235-register-dialog');
  if(assistant){
    const other=assistant.querySelector('[data-act="registrationGroup"][data-id="other"]');
    if(other&&!other.classList.contains('selected'))other.click();
    const title=assistant.querySelector('.vr-workspace-head h3');
    if(title&&title.textContent.trim()!=='Gestiones avanzadas')requestAnimationFrame(()=>{root.querySelector('.v235-register-dialog [data-act="registrationGroup"][data-id="other"]')?.click()});
  }
 },true);
 const obs=new MutationObserver(requestRun);obs.observe(root,{childList:true,subtree:true});run();
 window.__v866Runners.v871=run;
})();
;
